  chapters = {
    ["ages-past"] = { "Les Âges passés", "L'histoire du monde, des Titans à la dernière guerre, telle que la racontent les vieux livres de ses bibliothèques." },
    ["alterac"] = { "Montagnes d'Alterac", "Un royaume déchu dans les neiges, Dalaran au bord du lac, et une vallée que deux peuples se disputent." },
    ["arathi"] = { "Hautes-terres Arathies", "Le berceau des royaumes humains, tombé en ruine et toujours disputé." },
    ["ashenvale"] = { "Orneval", "L'antique forêt des elfes de la nuit, et les haches des orcs à sa lisière." },
    ["azshara"] = { "Azshara", "La terre de la reine, au bord de la mer qui l'a engloutie." },
    ["badlands"] = { "Terres ingrates", "Un désert rouge de canyons, et sous lui la chambre forte des titans, Uldaman." },
    ["barrens"] = { "Les Tarides", "La grande savane sèche au cœur de Kalimdor, et tous ceux qui se la disputent." },
    ["blackrock-mountain"] = { "Mont Rochenoire", "La montagne du seigneur du Feu, et la guerre qui s'y livre." },
    ["blasted-lands"] = { "Terres foudroyées", "Le désert rouge autour de la Porte des ténèbres." },
    ["burning-steppes"] = { "Steppes ardentes", "La plaine de cendres au sud de la montagne, là où s'étendaient jadis les Carmines." },
    ["callings"] = { "Les Vocations", "Les voies des armes, de la foi et de la magie qu'un voyageur peut suivre, et d'où chacune d'elles vient." },
    ["darkshore"] = { "Sombrivage", "Une longue côte brumeuse semée de ruines elfiques, face à l'Arbre-Monde par-delà les eaux." },
    ["deadwind-pass"] = { "Défilé de Deuillevent", "La vallée morte du dernier Gardien." },
    ["desolace"] = { "Désolace", "Un pays gris et mort, de centaures, d'ossements et de démons." },
    ["dun-morogh"] = { "Dun Morogh et Forgefer", "Les vallées enneigées autour de Forgefer, berceau du clan Bronzebeard." },
    ["durotar"] = { "Durotar et Orgrimmar", "La terre rouge que Thrall a donnée à son peuple, et la cité qui porte le nom du chef de guerre qui les a libérés." },
    ["duskwood"] = { "Bois de la Pénombre", "Une forêt où la nuit ne finit jamais tout à fait, et où les morts ne restent pas en terre." },
    ["dustwallow"] = { "Marécage d'Âprefange", "La cité insulaire de dame Proudmoore, un marais plein de dragons, et une auberge qui a brûlé." },
    ["eastern-plaguelands"] = { "Maleterres de l'est", "Les anciennes Terres de l'Est, Stratholme, et la nécropole dans le ciel." },
    ["elwynn"] = { "Forêt d'Elwynn et Hurlevent", "Le cœur du royaume humain : sa forêt, ses fermes et la cité blanche rebâtie sur ses cendres." },
    ["felwood"] = { "Gangrebois", "La forêt empoisonnée, où l'on trouva le crâne de Gul'dan." },
    ["feralas"] = { "Feralas", "Des arbres géants, des ogres, et les ruines des Bien-nés." },
    ["hillsbrad"] = { "Contreforts de Hautebrande", "De vertes collines où vivants et Réprouvés se disputent chaque ferme." },
    ["hinterlands"] = { "Les Hinterlands", "Les collines sauvages des nains Wildhammer, où se dressent aussi des temples trolls." },
    ["loch-modan"] = { "Loch Modan", "Le pays du lac à l'est de Forgefer, où un barrage retient les eaux sous le regard de rois de pierre." },
    ["moonglade"] = { "Reflet-de-Lune", "La vallée sacrée des druides." },
    ["mulgore"] = { "Mulgore et Thunder Bluff", "Les vertes plaines des taurens, et la cité sur les mesas." },
    ["peoples"] = { "Peuples et puissances", "Les peuples, ordres et factions qu'un voyageur rencontre en bien des contrées, réunis en un seul endroit." },
    ["redridge"] = { "Les Carmines", "Des collines rouges, un lac paisible et une ville assiégée par le nord." },
    ["searing-gorge"] = { "Gorge des Vents brûlants", "Le versant nord calciné de la montagne, et la grande fosse des Sombrefer." },
    ["shen-dralas"] = { "Shen'dralas", "Le pays maudit de la Vallée des Ossements, où les centaures ont trouvé les morts." },
    ["silithus"] = { "Silithus", "Le désert des insectes, le Mur du scarabée, et ce qui dort derrière." },
    ["silverpine"] = { "Forêt des Pins argentés", "Des pins gris entre les Réprouvés et la porte close de Gilnéas." },
    ["stonetalon"] = { "Les Serres-Rocheuses", "De hauts pics et de vieilles forêts, qui brûlent sous les scies des gobelins." },
    ["stranglethorn"] = { "Vallée de Strangleronce", "La jungle de l'ancien empire troll, où pirates, chasseurs et gobelins font fortune." },
    ["swamp-of-sorrows"] = { "Marais des Chagrins", "Un pays noyé de brume et de fange, et un temple englouti pour ses péchés." },
    ["tanaris"] = { "Tanaris", "Le grand désert du sud, et les portes des guetteurs." },
    ["teldrassil"] = { "Teldrassil et Darnassus", "Le nouvel Arbre-Monde des elfes de la nuit, et la cité nichée dans sa cime." },
    ["thousand-needles"] = { "Mille pointes", "Un canyon d'aiguilles de pierre, et une étendue de sel où gobelins et gnomes font la course." },
    ["tirisfal"] = { "Clairières de Tirisfal et Fossoyeuse", "Le cœur de Lordaeron déchu, et les Réprouvés qui règnent sous sa capitale en ruine." },
    ["ungoro-crater"] = { "Cratère d'Un'Goro", "Un monde perdu au fond d'un cratère, et ses mystérieux cristaux." },
    ["western-plaguelands"] = { "Maleterres de l'ouest", "Le cœur mort de Lordaeron, là où la peste a commencé." },
    ["westfall"] = { "Marche de l'Ouest", "Le grenier de Hurlevent, tombé en poussière et aux mains des bandits." },
    ["wetlands"] = { "Les Paluns", "Les marais entre Khaz Modan et Arathi, où les routes des nains débouchent sur de vieilles guerres." },
    ["winterspring"] = { "Berceau-de-l'Hiver", "La neige, les gobelins, et la malédiction des Bien-nés." },
    ["zephras-isle"] = { "Île de Zéphras", "L'île volante des éolides, dans le Mur-Céleste." },
  },
  -- the game's own texts, by their English titles: each text's pages, and
  -- the start of its English first page (to tell apart those sharing a title)
  books = {
    ["A Bloodstained Envelope"] = { { ids = { "i22930" }, first = "myemilyafewshortdaysagow", pages = { "Ma chère Emily,\n\nIl y a à peine quelques jours que sur ordre du roi, nous avons levé le camp pour quitter cet endroit perdu et rentrer chez nous. J'avais le cœur léger malgré la désolation environnante, car je savais qu'au bout de la marche glacée jusqu'au rivage et du long et pénible voyage, je trouverais le réconfort de vos bras.\n\nAujourd'hui, nous sommes arrivés sur la côte pour constater que nos bateaux, notre seul moyen de retour, n'étaient plus que des coques carbonisées. Nous ne pouvons plus rentrer et notre seule alternative est de traverser le cœur de cet épouvantable désert.\n\nJe suis allé jusqu'à l'extrême bout du monde pour votre sécurité, Emily... et je regrette à présent de tout mon être de ne pas être resté en Lordaeron avec vous.\n\nJe ne cesse à chaque instant de penser à vous. Vous êtes mon réconfort sur cette terre gelée, la seule parcelle de chaleur que rien ni personne ne peut m'enlever.\n\nMaxwell" } } },
    ["A Bloodstained Journal Page"] = { { ids = { "i939" }, first = "downwardspiralofdespairf", pages = { "...en bas d'une spirale de désespoir. Tout d'abord elle se moque de moi puis la voilà fiancée ! Cette indélicate créature s'est prétendue amoureuse alors qu'elle ne souhaitait que me faire du mal. Un tourbillon noir croît chaque minute au plus profond de ma poitrine. Le sang que je verserai n'est rien en comparaison des larmes que j'ai pleurées..." } } },
    ["A Careworn Note"] = { { ids = { "i22945" }, first = "dearestameliatonightihav", pages = { "Ma chère Amelia,\n\nCette nuit, j'ai vu des choses qui me hanteront jusqu'à la fin des temps.\n\nStratholme est la proie des flammes et nous en sommes responsables.\n\nNotre prince nous a conduit dans les rues, ce soir, nous a ordonné de forcer les portes des maisons et de tuer les habitants dans leur sommeil. Selon le seigneur Arthas, ils étaient contaminés par le Fléau, et nous devions les tuer avant qu'ils ne nous tuent.\n\nCe fut un vrai massacre. Des centaines de personnes sont mortes en silence, passées au fil de l'épée par leurs protecteurs. Je n'ai pas pu le supporter, je me suis enfui.\n\nJe suis peut-être un déserteur, mais je ne peux commettre de telles atrocités. Je voyais ton visage et celui de nos enfants sur les traits des agonisants. Si refuser d'obéir à ces ordres signifie que je suis un traître, qu'il en soit ainsi.\n\nJ'espère que je trouverai mon chemin pour te rejoindre, mais les routes ne sont pas sûres. Embrasse bien les enfants pour moi.\n\nJames" } } },
    ["A Clue to Sander's Treasure"] = { { ids = { "i1358" }, first = "goodworkmateynowyeneedto", pages = { "Bon travail, matelot ! Maintenant il va falloir cingler vers l'est. A l'est, vers le haut des falaises, à l'est vers la route. Cherchez les ruines des vieilles cheminées, au bord de la route. Là, vous trouverez un vieux tonneau qui contient l'indice suivant." } } },
    ["A Crumpled Missive"] = { { ids = { "i22944" }, first = "helianaivargusyetlivedes", pages = { "Heliana,\n\nJe suis au regret de vous annoncer que contrairement à vos vœux, je suis encore en vie. Je déteste me traîner dans cette campagne boueuse avec une armure ridicule.\n\nNos ordres nous ont conduit vers Andorhal pour aller chercher du blé, ou un autre truc stupide de ce genre. Je me moque des réserves de nourriture d'Andorhal, ce trou perdu. Toute cette histoire d'engagement dans l'armée est grotesque.\n\nSoyez bien sûre, tante Heliana, que je reviendrais chercher votre héritage. Même si je devais être grièvement blessé et abandonné sans nourriture, je trouverais toujours dans votre contrariété la force de continuer.\n\nVargus" } } },
    ["A Dusty Unsent Letter"] = { { ids = { "i889" }, first = "tothehonorableheadmaster", pages = { "À l'honorable Maître Crillian,\n\nCher ancien maître, je vous écris pour vous informer de ce que devient votre apprenti. Suivant vos conseils, j'ai décidé d'augmenter mes connaissances et ma sagesse en voyageant loin des frontières de notre bien-aimée Stormwind. Mes voyages m'ont fait découvrir bien des lieux, mais j'ai finalement décidé de m'établir dans la magnifique ville de Ruisselune. Les champs qui entourent la marche de l'Ouest sont plus beaux encore tandis que l'époque de la moisson approche.", "À peine arrivé, j'ai commencé à enseigner aux enfants des fermes voisines. Les leçons se sont si bien déroulées que le maire m'a demandé de diriger une école. La construction du bâtiment a déjà commencé ! Des Pins argentés à Stormwind, et maintenant Ruisselune, qui aurait pensé que j'aurais exploré de si larges portions d'Azeroth !\n\nMeilleures salutations,\n\nStalvan Mistmantle" } } },
    ["A Faded Journal Page"] = { { ids = { "i921" }, first = "moststrangeanduncontroll", pages = { "...sentiment étrange et incontrôlable. Jamais je n'avais ressenti cela. J'aidais Giles dans sa leçon d'Histoire, et je voyais Tilloa, par la fenêtre, s'occuper du jardin. Quelques instants après, elle est entrée, elle a placé un bégonia écarlate dans ma paume ouverte et elle m'a souri de telle manière que mon coeur s'est mis à trembler dans ma poitrine..." } } },
    ["A Letter to Grelin Whitebeard"] = { { ids = { "i2188" }, first = "grelinmytimeisshortandma", pages = { "Grelin,\n\nJ'ai peu de temps et bien des affaires à régler, et j'espère que votre enquête sur les trolls ne me causera pas de soucis supplémentaires. Je vous autorise donc à utiliser mon autorité dans l'affaire des trolls de la façon que vous estimerez nécessaire, surtout si vous pouvez régler l'affaire rapidement.\n\nMagni Bronzebeard" } } },
    ["A Mysterious Message"] = { { ids = { "i1381" }, first = "blacknailstheseaawaitsus", pages = { "Blacknails--\n\nLa mer nous attend. Nous avons besoin de vos fournitures venant du Nord. Prenez tout : chaque poteau, chaque baquet. On a besoin de métal. Une cargaison devait venir de BB mais on l'attend toujours. Venez à moi, Blacknails. Envoyez vos fournitures directement à la \"grange\" cette fois. Plus de temps à perdre.\n\n--VanCleef" } } },
    ["A Ragged Page"] = { { ids = { "i22946" }, first = "samlaaswefollowourlordar", pages = { "Samla,\n\nNous suivons le seigneur Arthas vers le nord, encore et encore, et mon cœur s'alourdit de jour en jour.  La Lumière resplendissait autrefois sur le jeune paladin, mais je sens aujourd'hui que son esprit s'obscurcit. Son zèle est terni par de sombres ruminations, un cauchemar dans son âme que je ne peux deviner…\n\nNous allons bientôt débarquer  dans les steppes gelées. Alors qu'un grand nombre de ses hommes tombent malades à cause du froid et des batailles qu'ils mènent contre des bêtes putrides, Arthas nous a affirmé que ce qu'il cherchait dans les glaces changera le cours de la bataille. Mais ses paroles ne m'ont pas réconforté... Le sourire sinistre figé sur ses lèvres dédaigneuses après son discours m'a glacé plus profondément que ne l'aurait fait n'importe quel blizzard.\n\nPrie pour nous, Samla, et prie pour notre monde.\n\nTorgal" } } },
    ["A Short Note"] = { { ids = { "i9329" }, first = "curgleihavebeeneagerlyaw", pages = { "Curgle,\n\nj'attends avec impatience votre nouvelle invention. J'ai hâte de l'utiliser pour alimenter mes études.\n\nVeuillez la confier à mon messager.\n\nMeilleurs sentiments,\n\nDaryn Lightwind" } } },
    ["A Smudged Document"] = { { ids = { "i22948" }, first = "dearpamelatomorrowwemake", pages = { "Ma chère Pamela,\n\nDemain, nous livrerons enfin bataille à Andorhal, et j'ai bien peur que ce soit la dernière lettre que je puisse t'envoyer, mon amour. Les morts-vivants ne se fatiguent jamais, et nous ne sommes que de pauvres êtres humains. Nous ne pourrons pas tenir contre eux. Mais ne te fais pas trop de souci, car même si nous sommes certains de périr, nous gardons espoir. La Lumière vaincra !\n\nEt, mon cœur, je trouve un grand réconfort en sachant que lorsque ces sombres terreurs emporteront nos murs et nous écraseront sous leur nombre, mes dernières pensées ne seront pas tournées vers la mort. Je penserai à toi dans mes bras, et je connaîtrai enfin la paix.\n\nChristoph" } } },
    ["A Torn Journal Page"] = { { ids = { "i916" }, first = "gilestheboyseemsabitramb", pages = { "...Giles, le garçon, semble un peu dissipé et ne sera pas facile à éduquer. Mais la fille aînée, Tilloa, semble exceptionnellement brillante. Je ne peux m'empêcher de constater aussi combien elle est belle. Elle est presque une femme désormais. Il paraît que Monseigneur a arrangé son mariage pour l'année prochaine. Mais je m'éloigne du sujet. Cette semaine, je vais accompagner la famille à leur résidence d'été, près du Camp de bûcherons du Val d'est en Elwynn, non loin des Carmines. Je vous donnerai plus de nouvelles depuis là-bas." } } },
    ["A Torn Letter"] = { { ids = { "i22932" }, first = "reubeniwritethisletterkn", pages = { "Reuben,\n\nJ'écris cette lettre en sachant que tu ne la liras peut-être jamais. Mais je ne peux pas rester les bras croisés, en écoutant les bruits sourds qui ébranlent constamment les murs d'Hearthglen. Les morts-vivants assiègent notre village sans interrompre un instant leurs assauts, et nous avons été chargés de défendre les villageois jusqu'à l'arrivée des renforts.\n\nJe me suis cassé la jambe lors de la dernière charge, et je dois rester assis, inutile, l'épée au côté au cas où nos défenses seraient débordées. On n'entend aucun bavardage… seuls les bruits des combats et de la mort. L'air empeste la peur.\n\nLe prince Arthas est là, combattant sur le front avec les hommes. Sans lui, nous serions tombés depuis longtemps. Son amour pour cette terre et ses habitants est contagieux, jambe cassée ou pas, je ne peux pas rester ici. Chaque épée est nécessaire. J'espère que tu liras cette lettre en des temps meilleurs.\n\nTon ami,\nLeagrem" } } },
    ["A Treatise on Military Ranks"] = { { ids = { "o179706", "i18664" }, first = "atreatiseonmilitaryranks", pages = { "TRAITE DES GRADES MILITAIRES\n\nVous trouverez ici les\n\ngrades militaires de\n\nl'Alliance, suivies par les\n\ninformations équivalentes\n\ndont nous disposons\n\nconcernant les races\n\nde la Horde. Chaque\n\nliste comporte deux\n\nsections, officiers et hommes de troupe. Les grades sont cités du plus élevé au moins élevé.  Longue vie à l'Alliance !", "GRADES D'OFFICIER DE L'ALLIANCE\n\nPart 1\n\n Connétable\n\n Grand maréchal\n\n Maréchal\n\n Commandant\n\n Lieutenant-commandant", "GRADES D'OFFICIER DE L'ALLIANCE\n\nPart 2\n\nChevalier-champion\n\n Chevalier-capitaine\n\nChevalier-lieutenant\n\nChevalier", "GRADES DES RECRUES DE L'ALLIANCE\n\nSergent-major\n\n Sergent-chef\n\nSergent\n\nCaporal\n\nSoldat", "GRADES D'OFFICIER DE LA HORDE\n\nPart 1\n\n Grand seigneur de guerre\n\n Seigneur de guerre\n\nGénéral\n\nLieutenant-général\n\nChampion", "GRADES D'OFFICIER DE LA HORDE\n\nPart 2\n\nCenturion\n\nLégionnaire\n\nGarde de sang\n\nGarde de pierre", "GRADES DES RECRUES DE LA HORDE\n\nAdjudant\n\n Sergent-chef\n\nSergent\n\nGrunt\n\nEclaireur" } } },
    ["Acolyte's Note"] = { { ids = { "i205184" }, first = "gakin", pages = { "<Le texte de la page est en grande partie maculé de sang, mais on peut distinguer un nom.>\n\nGakin" } }, { ids = { "i208224" }, first = "carendin", pages = { "<Le texte de la page est en grande partie maculé de sang, mais on peut distinguer un nom.>\n\nCarendin" } } },
    ["Admiral Barean Westwind"] = { { ids = { "o175772" }, first = "admiralbareanwestwindgra", pages = { "Amiral Barean Westwind\nGrand amiral de la Flotte écarlate\nCitoyen de Kul'Tiras\nPorté disparu au large des côtes glacées de Northrend" } } },
    ["Admiral Proudmoore's Orders"] = { { ids = { "i4883" }, first = "officialordersforthekult", pages = { "Ordres officiels pour la flotte de Kul Tiras\n\nMoi, amiral Proudmoore, je mènerai le premier débarquement sur les rivages de Kalimdor.\n\nLe lieutenant Benedict commandera en mon absence. Toutes les affaires militaires locales de Kul Tiras seront placées sous son autorité. Si je ne donne pas de nouvelles du donjon de Tiragarde dans les 12 mois, le lieutenant Benedict conduira la seconde vague destinée à s'emparer des lieux.", "En attendant, j'envoie le lieutenant Alverold en mission d'exploration autour du continent de Kalimdor. Ses forces doivent accomplir leur mission et nous rejoindre au donjon de Tiragarde.\n\nIl est prévu que la mission du lieutenant Alverold dure quelques temps. Les nouvelles terres semblent vastes et dangereuses. Mais si le malheur me poursuit ou s'abat sur Benedict, les troupes d'Alverold reprendront le donjon.\n\nNous enverrons vague après vague jusqu'à ce que la forteresse soit nôtre !\n\n--Amiral Proudmoore" } } },
    ["Advisor Emerson's Instructions"] = { { ids = { "i285356" }, first = "greetingsasaguestoftheal", pages = { "Salutations,\n\nEn tant qu'hôte de l'Alliance, vous avez reçu l'autorisation d'arpenter librement l'ensemble de ses terres.\n\nCe document vous servira de guide pour vous aider à rejoindre les autres villes membres de notre alliance.", "Votre première étape devrait être Forgefer, que vous pouvez rejoindre en empruntant la merveille technologique que constitue le tram des profondeurs.\n\nVous trouverez l'entrée du tram dans le quartier des Nains, ici à Hurlevent, juste au sud-ouest du donjon. Le tram vous transportera en toute sécurité au cœur de Forgefer.\n\nDès votre arrivée, n'hésitez pas à explorer la ville et à localiser le Grand Bricoleur Mekkanivelle et le roi Magni Barbe-de-Bronze, qui se situent respectivement dans Brikabrok et dans la Grande forge. Présentez-vous comme émissaire des Éolides et ils vous feront bon accueil.", "The city of Darnassus can be found across the sea, off the coast of northern Kalimdor. The city itself rests at the top of the great tree, Teldrassil.\n\nThe safest route for you currently is via the harbor on the west side of Stormwind. Take the ship departing from the southernmost dock to the port of Auberdine.\n\nUpon arriving, proceed to the north side of the Auberdine docks and take the ship there to Ru'theran Village. This village contains a magical transporter that will take you into the city itself.\n\nExplore Darnassus and seek out Tyrande Whisperwind, the High Priestess of Elune.", "Après avoir fait la connaissance des autres dirigeants de l'Alliance, le seigneur Fordragon a demandé à ce que vous le rejoigniez au donjon.\n\nJe vous souhaite bonne chance dans vos voyages, Éolide." } } },
    ["Advisor Nazgrel's Instructions"] = { { ids = { "i285357" }, first = "elfasaguestofthehordethe", pages = { "Elfe,\n\nEn tant qu'hôte de la Horde, le chef de guerre vous a accordé l'autorisation d'arpenter librement l'ensemble de notre territoire.\n\nUtilisez ce guide pour trouver votre chemin sur nos terres.", "Dans cette salle même, vous trouverez Vol'jin, de la tribu des Sombrelances.\n\nLes Trolls sombrelances sont des alliés solides des Orcs. Nos liens ont été scellés dans le sang et la chaleur des combats, au cours de notre exode des royaumes humains à l'est.\n\nTraitez-le avec égards et il en fera de même. Lui manquer de respect… serait une mauvaise idée.", "Ensuite, je vous conseille de revenir à Mulgore et de chercher Cairne Sabot-de-sang, aux Pitons-du-Tonnerre.\n\nCairne est le chef de la tribu taurène des Sabot-de-sang et c'est par sa seule grâce que votre peuple et le Cercle terrestre ont reçu la permission de s'établir à Mulgore.\n\nVous connaissez sûrement déjà la route vers les Pitons-du-Tonnerre. Allez voir le maître de vol au centre d'Orgrimmar et prenez une wyverne de monte jusqu'aux Pitons-du-Tonnerre. Vous trouverez Cairne sur le plateau central, juste à l'est du grand totem qui sert de nid aux wyvernes de la ville.", "Nos alliés Réprouvés résident dans la région connue sous le nom de clairières de Tirisfal, sur le continent est. Vous trouverez Fossoyeuse loin sous les ruines d'une cité autrefois appelée Lordaeron.\n\nPour vous rendre à Tirisfal, sortez de la ville par la grande porte sud et dirigez-vous vers la tour des zeppelins.\n\nEmbarquez à bord du zeppelin qui s'amarre sur le côté sud de la tour. Une fois que vous aurez franchi l'océan, vous arriverez dans le village de Brill. De là, marchez simplement vers le nord jusqu'aux ruines de Lordaeron.\n\nTrouvez l'ascenseur et empruntez-le pour descendre dans les profondeurs de Fossoyeuse et trouver la Dame noire dans le quartier royal.\n\nAttention cependant, vous pourriez trouver la capitale des Réprouvés pour le moins… déstabilisante." } } },
    ["Aegwynn and the Dragon Hunt"] = { { ids = { "o175738" }, first = "asthepoliticsandrivalrie", pages = { "Les rivalités entre les sept nations humaines ne cessaient jamais. Malgré tout, la lignée des Gardiens continuait à monter la garde contre le chaos. Il y eut bien des Gardiens au fil des années, mais un seul détenait à chaque fois les pouvoirs magiques de Tirisfal. L'un des derniers Gardiens se distingua particulièrement dans la lutte contre les ombres.", "Aegwynn, une fière jeune fille humaine, gagna le soutien de l'Ordre et reçut le manteau du Gardien. Aegwynn travailla vigoureusement à chasser et éliminer les démons où qu'ils se trouvaient, mais remettait sans cesse en cause l'autorité des hommes qui constituaient le Conseil de Tirisfal.", "Cette femme de guerre croyait que les anciens elfes et les hommes âgés qui constituaient le Conseil étaient trop rigides et pas assez clairvoyants pour prendre la décision de mettre fin une fois pour toutes au conflit contre le chaos. Impatientée par les palabres et les débats, elle voulut prouver qu'elle valait ses pairs et ses maîtres. Elle prit souvent le parti de l'audace contre celui de la raison dans des situations cruciales.", "Tandis que grandissait sa maîtrise des pouvoirs cosmiques de Tirisfal, Aegwynn apprit que de puissants démons agissaient dans le continent glacé de Northrend. Aegwynn partit pour le nord lointain et traqua les démons dans les montagnes. Là, elle vit que les démons chassaient l'une des dernières tribus de dragons et s'emparaient de la magie naturelle de ces antiques créatures.", "Les puissants dragons, qui avaient fui l'avancée progressive des sociétés mortelles, ne parvenaient pas à prendre l'avantage sur la magie noire de la Légion. Aegwynn affronta les démons, et avec l'aide des nobles dragons, les élimina. Mais, au moment où le dernier démon était banni du monde des mortels, une grande tempête se déclencha dans le nord.", "Un immense visage noir apparut dans le ciel au-dessus de Northrend. Sargeras, le roi démon et seigneur de la Légion ardente, apparut devant Aegwynn, vibrant d'énergie infernale. Il affirma à la jeune Gardienne que l'ère de Tirisfal touchait à sa fin et que le monde allait bientôt succomber sous les coups de la Légion.", "La fière Aegwynn, se croyant de taille à affronter le dieu menaçant, déchaîna ses pouvoirs contre l'avatar de Sargeras. Avec une déconcertante facilité, Aegwynn battit le seigneur démon et parvint à détruire son apparence physique. Craignant que l'esprit de Sargeras ne subsiste, Aegwynn enferma l'enveloppe en ruines de son corps dans l'un des anciens halls de Kalimdor qui avait été précipité au fond de la mer au moment de l'effondrement du Puits d'éternité.", "Aegwynn ne sut jamais qu'elle avait exactement suivi le plan de Sargeras. Elle avait malgré elle scellé le destin du monde mortel, car Sargeras, au moment de sa mort physique, avait transféré son esprit dans le corps affaibli d'Aegwynn. Sans se révéler à la jeune Gardienne, Sargeras allait rester calfeutré dans les recoins sombres de son âme pendant des années." } } },
    ["Aftermath of the Second War"] = { { ids = { "o21581" }, first = "thedevastatingsecondwara", pages = { "La Deuxième Guerre contre la horde des orcs, particulièrement brutale, laissa l'Alliance de Lordaeron dans un état de choc et de désarroi. Les orcs assoiffés de sang, sous la conduite de leur puissant chef Orgrim Doomhammer, parvinrent jusqu'aux terres naines de Khaz Modan, et réussirent à dévaster bien des provinces centrales de Lordaeron. Dans leur lancée, les orcs ravagèrent même le royaume éloigné des elfes, Quel'Thalas, avant d'être enfin arrêtés.", "Les armées de l'Alliance, conduites par le seigneur Anduin Lothar, Uther Lightbringer dit le Porteur de Lumière et l'amiral Daelin Proudmoore, repoussèrent les orcs au sud vers les terres ravagées d'Azeroth, le premier royaume que l'attaque meurtrière des orcs avait mis à feu et à sang.\n\nLes forces de l'Alliance dirigées par messire Lothar parvinrent à repousser les clans de Doomhammer hors de Lordaeron jusque dans les terres d'Azeroth, contrôlées par les orcs. Les forces de Lothar investirent la citadelle volcanique du pic Blackrock et assiégèrent ses défenses.", "Dans un ultime effort, Doomhammer et ses lieutenants tentèrent une charge audacieuse depuis le Pic et se heurtèrent aux paladins de Lothar, au centre des Steppes ardentes. Doomhammer et Lothar s'affrontèrent dans un combat de titans qui les laissa l'un et l'autre blessés et exsangues. Doomhammer parvint à vaincre Lothar, mais la mort du grand héros n'eut pas le résultat escompté par le chef des orcs.", "Turalyon, le lieutenant le plus fidèle de Lothar, ramassa le bouclier ensanglanté de Lothar et rallia les hommes pour lancer une contre-attaque cruelle. Sous les étendards en lambeaux de Lordaeron et d'Azeroth, les troupes de Turalyon massacrèrent la plupart des forces restantes de Doomhammer dans une bataille glorieuse, mais terrible.", "Les orcs survivants n'eurent d'autre choix que de fuir vers le dernier bastion de puissance de leur race : la Porte des ténèbres.\n\nTuralyon et ses guerriers chassèrent les derniers orcs à travers les nauséabonds marais des Chagrins, jusqu'aux viles Terres foudroyées où se trouvait la Porte des ténèbres. Là, au pied du gigantesque portail, la Horde décimée et l'Alliance épuisée s'affrontèrent dans ce qui devait être la dernière et la plus sanglante des batailles de la Deuxième Guerre.", "Noyés sous le nombre et rendus fous par leur soif de sang, les orcs s'effondrèrent devant l'ire de l'Alliance. Doomhammer fut capturé et escorté jusqu'à Lordaeron tandis que les clans démembrés étaient faits prisonniers et menés au nord, à Lordaeron." } } },
    ["Alliance Military Ranks"] = { { ids = { "o179735" }, first = "alliancemilitaryranksoff", pages = { "GRADES MILITAIRES DE L'ALLIANCE\n\nOFFICIERS\n\nConnétable\n\nGrand Maréchal\n\nMaréchal\n\nCommandant\n\nLieutenant-commandant\n\nChevalier-champion\n\nChevalier-capitaine\n\nChevalier-lieutenant\n\nChevalier\n\nRECRUES\n\nSergent-Major\n\nSergent-chef\n\nSergent\n\nCaporal\n\nSoldat" } } },
    ["Altar of Zanza"] = { { ids = { "o180367" }, first = "wecalluponyouzanzaofzuld", pages = { "Viens à nous, Zanza de Zuldazar.\n\nBénis ceux qui te demandent de l'aide, loa Zanza. Bénis ceux qui cherchent à s'allier avec le peuple\nzandalarien.\n\nAide-nous dans cette heure de péril. Aide-nous, loa. Donne-nous le pouvoir d'abattre nos ennemis. Donne-nous le pouvoir de vaincre une nouvelle fois le Dieu sanglant." } } },
    ["An Exotic Cookbook"] = { { ids = { "i5428" }, first = "getoneoreightmanhitmanha", pages = { "1. Trouver un homme ou huit\n2. Taper fort l'homme\n3. Taper l'homme plus fort\n4. Mettre l'homme dans le feu\n5. Manger l'homme" } } },
    ["An Undelivered Letter"] = { { ids = { "i910" }, first = "dearnoblesirwordofyourne", pages = { "Monseigneur,\n\nJ'ai entendu dire que vous cherchiez un précepteur pour vos enfants, ici, à Goldshire, où je me suis établi à l'auberge de la Fierté du lion. En raison des tristes événements qui agitent la région, j'ai été contraint d'abandonner ma position de directeur de l'école de Ruisselune. Veuillez considérer avec bienveillance ma candidature au poste que vous cherchez à pourvoir. Le maître de l'académie Crillian vous fournira si besoin toutes les recommandations voulues.", "Je viendrai vous rencontrer en personne lorsque la saison des pluies sera achevée et que les routes permettront le déplacement.\n\nJe demeure en attendant votre dévoué\n\nStalvan Mistmantle des Pins argentés" } } },
    ["Ancient Inscription"] = { { ids = { "o19025" }, first = "theshrineofmelthandrisma", pages = { "L'Autel de Mel'Thandris\n\n\"Que la lumière d'Elune brille éternellement sur cette vallée et illumine les voies de la forêt comme elle l'a fait depuis des temps immémoriaux.\"" } } },
    ["Ancient Tablet"] = { { ids = { "i9242" }, first = "themalletofzulfarraktocr", pages = { "Le Maillet de Zul'Farrak\n\nPour créer le Maillet de Zul'Farrak, il faut voyager jusqu'à l'autel de Zul et obtenir le maillet sacré d'un Gardien troll.\n\nEnsuite, il faut apporter le maillet sacré à l'autel au sommet de la ville troll de Jintha'alor.\n\nUtiliser le maillet sacré à l'autel l'imprégnera de puissance et le transformera en Maillet de Zul'Farrak." } } },
    ["Annals of Darrowshire"] = { { ids = { "i12900" }, first = "theannalsofdarrowshireda", pages = { "Les Annales de Darrowshire\n\nDarrowshire, dont le nom vient du lac Darrowmere situé à l'ouest, est un village coincé dans les contreforts sud de Lordaeron. Connu pour ses habitants humbles et travailleurs, Darrowshire est resté au second plan de l'histoire de Lordaeron jusqu'à la Deuxième Guerre.\n\nDes héros émergèrent durant cette guerre. Et des héros périrent.", "La bataille de Darrowshire\n\nLa bataille de Darrowshire se déroula au milieu de la Deuxième Guerre, quand les forces du Fléau se déchaînèrent contre Lordaeron. Darrowshire fut coupé du gros des forces de l'Alliance, mais la ville fut défendue par une compagnie de troupes, un contingent de paladins de la Main d'argent, et un groupe fidèle d'une milice locale menée par le capitaine Joseph Redpath.", "Les assauts du Fléau sur Darrowshire furent d'abord peu importants. De petits groupes de squelettes et de cadavres en maraude erraient autour du village avant d'être repoussés.\n\nMais le Fléau ne fut pas découragé par la ténacité des défenseurs et réagit en conséquence. Une seconde vague d'attaques suivit bientôt. Des champions parmi les goules, serviteurs du seigneur-goule Horgus, descendirent des collines en hurlant et assiégèrent les défenseurs de Darrowshire.", "Les Défenseurs ont commencé à faiblir, mais des paladins sont venus à leur secours, des disciples de la Main d'argent. Leur chef, Davil Crokford, était originaire de Darrowshire. Il est venu avec ses disciples quand il a entendu parler de l'attaque. Avec les Défenseurs, ils ont repoussé les serviteurs d'Horgus.\n\nQuand Horgus lui-même a pris part à la bataille, il a rencontré Davil. Pendant plusieurs minutes, ils se sont battus et finalement Davil a été victorieux. Malheureusement, après avoir battu le seigneur-goule, il a succombé à une blessure mortelle.", "La bataille s'est poursuivie et le capitaine Redpath a mené sa milice avec bravoure. Elle aurait gagné si le capitaine n'avait pas été corrompu par le chevalier de la mort Marduk le Noir.\n\nAu milieu du combat, Marduk s'est dirigé vers Redpath, et avec de la magie noire il a arraché l'esprit de Redpath, le remplaçant par l'ombre maléfique du brave capitaine.", "Le capitaine Redpath, corrompu, fut à l'origine de la trahison des défenseurs de Darrowshire envers leurs alliés, ainsi que du massacre de ces derniers. Puis les défenseurs se tournèrent vers la ville de Darrowshire et tuèrent tous ceux qui se cachaient dans leur maison.\n\nLe reste de l'armée du Fléau, accompagné de l'esprit corrompu du capitaine Redpath, quitta ensuite le village ravagé de Darrowshire et se rua sur Lordaeron, accroissant ainsi les douleurs et les morts de la Deuxième Guerre." } } },
    ["Another Clue to Sander's Treasure"] = { { ids = { "i1361" }, first = "nowfromthisherebarrelfac", pages = { "À partir de ce tonneau, tournez-vous vers le nord. Marchez droit comme une bande de cadets qui va au réfectoire, jusqu'à ce que vous voyiez la cruche vide, à côté du moulin à vent solitaire, sur les falaises. Si vous farfouillez autour de cette cruche, vous pourrez bien trouver ce que vous cherchez." } } },
    ["Arathor and the Troll Wars"] = { { ids = { "o175734" }, first = "asthehighelvesfoughtfort", pages = { "Tandis que les hauts-elfes se battaient pour leur survie contre le furieux assaut des trolls, les humains éparpillés de Lordaeron luttaient pour consolider la position de leurs propres tribus. Ces dernières s'attaquaient sauvagement, sans projet d'unification ni souci d'honneur.", "Pourtant, une tribu, les Arathi, comprit que la menace des trolls devenait trop grave pour être ignorée. Les Arathi espéraient soumettre toutes les tribus pour pouvoir présenter un front uni contre les guerriers trolls.", "Pendant six ans, les Arathi remportèrent sur les autres tribus victoire sur victoire, offrant à chaque fois la paix et l'égalité au peuple conquis. Ils gagnèrent ainsi la loyauté de ceux qu'ils avaient vaincus. Au bout du compte, la tribu Arathi parvint à inclure un grand nombre de peuples disparates, et les rangs de son armée prirent une considérable ampleur.", "Pensant pouvoir repousser les trolls ou même les solitaires elfes en cas de besoin, les seigneurs de guerre Arathi décidèrent de construire une puissante ville fortifiée dans le sud de Lordaeron. La cité-état prit le nom de Strom et devint la capitale de la nation Arathi, Arathor. Tandis qu'Arathor prospérait, les humains de tout le continent émigrèrent vers le sud pour bénéficier de la protection et de la sécurité de Strom.", "Unies sous une bannière unique, les tribus humaines développèrent une culture solide et tournée vers l'avenir. Thoradin, le roi d'Arathor, savait que les mystérieux elfes des terres du Nord étaient constamment assiégés par les trolls, mais ne voulut pas risquer la sécurité de son peuple en se lançant à l'aide de ces étrangers mystérieux. Pendant des mois, des rumeurs sur la défaite des elfes parvinrent du Nord. C'est seulement lorsque des ambassadeurs épuisés mandés par Quel'Thalas atteignirent Strom que Thoradin réalisa la puissance que représentaient les trolls.", "Les elfes informèrent Thoradin que les armées des trolls étaient immenses et qu'une fois Quel'Thalas détruite, elles se tourneraient contre les régions du Sud. Les elfes, désespérés, ardemment désireux de trouver une aide militaire, acceptèrent sans rechigner d'enseigner à quelques humains les secrets de la magie en échange d'un soutien contre les trolls.", "Thoradin, qui n'avait pas confiance dans la magie, accepta par nécessité d'aider les elfes en difficulté. Presque immédiatement, des sorciers elfes arrivèrent à Arathor et commencèrent à instruire un groupe d'humains.", "Les elfes virent que, malgré la maladresse des humains dans la manipulation de la magie, ils possédaient pour elle une affinité naturelle. Une centaine d'humains apprit les bases de la magie elfique : pas plus qu'il n'était strictement nécessaire pour combattre les trolls. Convaincus que leurs disciples humains étaient prêts à les aider dans leur lutte, les elfes quittèrent Strom et partirent vers le nord avec les puissantes armées du roi Thoradin.", "Les armées unies des elfes et des humains se heurtèrent aux innombrables trolls au pied des Montagnes d'Alterac. La bataille dura plusieurs jours, mais les armées inépuisables d'Arathor ne cédèrent jamais un pouce de terrain devant les assauts des trolls. Les seigneurs elfes pensèrent venu le temps d'utiliser leur magie contre l'ennemi.", "Les cent magi humains et les innombrables sorciers des elfes appelèrent la fureur et le feu du ciel sur les armées des trolls. Les flammes élémentaires empêchèrent les trolls de régénérer leurs blessures et les consumèrent de l'intérieur.", "Les trolls se débandèrent et s'enfuirent. Les armées de Thoradin les poursuivirent et éliminèrent tous les soldats. Les trolls n'allaient jamais se remettre de cette défaite, et le monde ne vit plus jamais les trolls s'unir en une grande nation. Sachant que Quel'Thalas était sauvée de la destruction, les elfes firent acte d'allégeance et d'amitié à la nation d'Arathor et à la lignée du roi Thoradin. Les humains et les elfes allaient vivre en paix pendant les années à venir." } } },
    ["Archaic Rune"] = { { ids = { "i282400" }, first = "youalreadyfeltthecallofs", pages = { "Vous avez déjà ressenti l'appel de forces supérieures ? Eh bien, c'est l'appel des éléments. Nous, les Nains, avons un lien fort avec la terre, mais avec le bon entraînement, vous pourrez apprendre à parler avec tous les éléments. Les élémentaires sont exigeants, mais je suis ici pour vous guider et vous apprendre à communiquer avec eux. Venez me trouver à Courbenclume et je vous entraînerai à écouter les éléments et à les faire vous écouter.\n\n– Teo Martel-tempête, maître des chamans" } } },
    ["Archbishop Alonsus Faol"] = { { ids = { "o177199" }, first = "archbishopalonsusfaolben", pages = { "Archevêque Alonsus Faol\n\nBienveillant protecteur de l'Eglise de la Lumière.\n\nBien qu'il ait commencé son excellent travail à Stratholme, Lordaeron, l'archevêque Faol se montra un ami continu du peuple de Stormwind. Dans les heures sombres qui suivirent la Deuxième Guerre, il aida à réformer la Fraternité de Northshire et leva des fonds pour rebâtir la cité de Stormwind.\n\nCette cathédrale n'est pas seulement un bastion de la Sainte Lumière, mais aussi un mémorial de son esprit noble et de sa générosité." } } },
    ["Archimonde's Return and the Flight to Kalimdor"] = { { ids = { "o175758" }, first = "oncekelthuzadwaswholeaga", pages = { "Une fois Kel'Thuzad rétabli, Arthas mena le Fléau vers le sud, en direction de Dalaran. Là, la Liche souhaitait obtenir le puissant livre de sorts de Medivh et l'utiliser pour invoquer Archimonde. Ce dernier pourrait alors préparer l'invasion finale de la Légion. Même les magiciens du Kirin Tor ne purent empêcher les forces d'Arthas de voler le livre de Medivh et Kel'Thuzad eut bientôt tout ce dont il avait besoin pour lancer le sort.", "Après dix millénaires, le puissant démon Archimonde et son hôte émergèrent de nouveau dans le monde d'Azeroth. Mais Dalaran n'était pas leur ultime destination. Commandés par Kil'jaeden lui-même, Archimonde et ses démons suivirent le Fléau mort-vivant à Kalimdor, dans le but de détruire Nordrassil, l'Arbre-monde.", "Au milieu de ce chaos, un mystérieux prophète solitaire apparut pour guider les races mortelles. Ce n'était autre que Medivh, le dernier Gardien miraculeusement revenu de l'Au-delà pour trouver la rédemption de ses crimes passés. Medivh enseigna à la Horde et à l'Alliance les dangers qui se profilaient et les pressa de s'allier.", "Mais il dut traiter séparément les orcs et les humains, lassés par des années de guerre. Il utilisa la prophétie et le mensonge pour les mener au-delà des mers dans les terres légendaires de Kalimdor. Les orcs et les humains rencontrèrent vite la civilisation longtemps recluse des Kaldorei.", "Les orcs, menés par Thrall, souffrirent une série de revers au cours de leur voyage à travers Kalimdor. Ils se lièrent d'amitié avec Cairne Bloodhoof et ses puissants guerriers taurens, mais beaucoup d'orcs succombèrent à la soif de sang qui les avait corrompus pendant des années. Le plus grand lieutenant de Thrall, Grom Hellscream, trahit même la Horde en se livrant à ses plus bas instincts.", "Tandis que Hellscream et ses loyaux guerriers Warsong avançaient dans les forêts d'Ashenvale, ils se heurtèrent aux anciennes Sentinelles des elfes de la nuit. Certain que les orcs avaient renoué avec leurs pulsions guerrières, le demi-dieu Cénarius apparut pour repousser Hellscream et ses orcs. Mais Hellscream et ses troupes, emplis de haine et de rage surnaturelles, parvinrent à tuer Cénarius et à corrompre les vieilles forêts.", "Finalement, Hellscream racheta son honneur en aidant Thrall à battre Mannoroth, le seigneur démon qui avait le premier corrompu les orcs avec son sang porteur de rage et de haine. Mannoroth éliminé, la malédiction des orcs fut levée.", "Tandis que Medivh travaillait à convaincre les orcs et les humains de s'allier, les elfes de la nuit combattirent la Légion selon leurs propres méthodes. Tyrande Whisperwind, la grande prêtresse immortelle des Sentinelles, combattit avec l'énergie du désespoir pour empêcher les démons et les morts-vivants de submerger les forêts d'Ashenvale. Tyrande réalisa qu'elle avait besoin d'aide. Elle alla donc éveiller les druides elfes de leur sommeil millénaire.", "Appelant son amour de toujours, Malfurion Stormrage, Tyrande parvint à galvaniser ses défenses et à repousser la Légion. Avec l'aide de Malfurion, elle fit se lever la nature elle-même pour vaincre la Légion et le Fléau.", "En cherchant d'autres druides à éveiller, Malfurion trouva l'ancienne prison où il avait enchaîné son frère Illidan. Convaincu qu'Illidan l'aiderait contre la Légion, Tyrande le libéra. Illidan les aida bien pendant un temps, mais s'écarta finalement pour s'occuper de ses propres affaires.", "Les elfes de la nuit s'unirent pour combattre la Légion ardente avec une extrême détermination. La Légion n'avait jamais cessé de vouloir accéder au Puits d'éternité, depuis longtemps source de la vitalité de l'Arbre-monde et coeur du royaume des elfes de la nuit. Si leur assaut contre l'Arbre réussissait, les démons parviendraient à disloquer le monde." } } },
    ["Archmage Khadgar of the Kirin Tor"] = { { ids = { "o25333" }, first = "archmagekhadgarofthekiri", pages = { "Archimage Khadgar du Kirin Tor\n\nAncien apprenti de Medivh. Commandant suprême de l'expédition de l'Alliance qui a marché sur le monde des orcs, Draenor. Présumé mort.\n\nNul ne s'est avec plus d'altruisme plongé dans l'étude de la magie et du combat. Nous sommes avec toi, audacieux guerrier, où que tu sois.\n\n- Antonidas - Archimage de Dalaran" } } },
    ["Arellas Fireleaf"] = { { ids = { "o175771" }, first = "arellasfireleafhighwizar", pages = { "Arellas Fireleaf\nGrand mage de la Croisade écarlate\nCitoyen de Quel'Thalas\nEnfermé dans un combat éternel avec le nécromancien Diesalven" } } },
    ["Baelog's Journal"] = { { ids = { "o123463" }, first = "ihavefoundamethodtoenter", pages = { "J'ai trouvé un moyen d'entrer dans la chambre de Khaz'mul !\n\nPrenez le Médaillon de Gni'kiv dans mon coffre.\n\nBattez le trogg Revelosh dans la chambre placée avant la salle de la carte et récupérez la Hampe de Tsol.\n\nAssemblez le médaillon et la hampe pour former le Bâton de Prehistoria.\n\nUtilisez ce bâton dans la salle de la carte pour déverrouiller la porte de la Chambre de Khaz'mul.\n\nFaites tout ceci et la chambre sera à vous !\n-Baelog" } } },
    ["Bath'rah's Parchment"] = { { ids = { "i6929" }, first = "belowyouwillfindthatwhic", pages = { "Vous trouverez plus bas ce qu'il me manque pour lancer le sort d'invocation du grand Cyclonien. Que la chance soit avec vous.\n\n--Bath'rah la Vigie des vents", "Vietérule :\n\nVous pouvez trouver cette plante dans la nature ou sur les Fane-lianes du marécage d'Âprefange. Ses vertus sont nécessaires pour attirer en ce monde l'essence de vie des Cycloniens.", "Défenses de Bloodscalp :\n\nLes défenses des trolls de Strangleronce sont d'une rare qualité. La dépravation des Bloodscalp est concentrée dans leurs défenses. Broyées en poudre, elles libèrent leur pouvoir maléfique.", "Essence d'exil :\n\nCette essence s'obtient en combinant les trois charmes des élémentaires exilés des hautes-terres d'Arathi. Rassemblez les Charmes ardents, les Charmes de tonnerre et les Charmes armoriés, puis placez-en huit de chaque dans mon chaudron.\n\nÀ partir des charmes, vous obtiendrez l'essence d'exil." } } },
    ["Beginnings of the Undead Threat"] = { { ids = { "i5861" }, first = "theundeadsbeginningsupon", pages = { "L'avènement des morts-vivants n'est pas lié à la corruption du prince Arthas. Il date de bien avant cet événement. Les événements qui provoquèrent la chute de Lordaeron débutèrent bien avant cette époque. Tout commença avec les clans orcs et la Légion ardente.", "Les clans orcs, riches d'une noble culture chamanique vieille de plusieurs millénaires, ne savaient rien de la corruption ni de la déliquescence spirituelle. Mais les sinistres agents de la Légion ardente cherchaient à les transformer en une armée invincible et meurtrière. Rusé, le démon Kil'jaeden, second chef de la Légion, voulait les réduire en esclavage et les utiliser au sein de la Légion ardente pour mener à bien ses desseins de conquête.", "Kil'jaeden se présenta au plus respecté des chefs orcs, un puissant chaman du nom de Ner'zhul. Il lui promit la connaissance et des pouvoirs magiques inouïs s'il consentait à un pacte avec le démon qui ferait des clans les esclaves de la Légion ardente. Ce pacte, en plus de leur destin, scellait celui du monde.", "Au fil du temps, Ner'zhul réalisa quel destin la Légion ardente réservait aux clans. Il défia Kil'jaeden et refusa d'aider plus avant. Furieux de la méfiance du chaman, Kil'jaeden trouva un nouvel apprenti désireux de conduire les orcs sur les chemins du néant. Ce nouvel esclave n'était autre que le protégé de Ner'zhul, l'infâme Gul'dan.", "C'est Gul'dan qui fut responsable du déclin du chamanisme au sein des clans. Il convainquit les clans en leur promettant la puissance et le contrôle de leurs ennemis. Avec l'aide de Kil'jaeden, Gul'dan se mit à manipuler les clans. Les orcs, race noble, devinrent des sauvages sans cervelle et corrompus. L'ajout de sang démoniaque dans leur corps transforma les orcs en créatures impitoyables et barbares.", "Bien que Kil'jaeden ait corrompu Gul'dan après son échec avec Ner'zhul, Kil'jaeden haïssait le chaman et était bien décidé à lui faire respecter le pacte qu'il avait passé. Kil'jaeden captura Ner'zhul et se mit à le torturer lentement. Tandis que Ner'zhul implorait qu'on le laisse mourir, Kil'jaeden rappela à Ner'zhul qu'ils étaient toujours liés par leur pacte. Kil'jaeden tua l'orc, mais physiquement seulement. Kil'jaeden s'empara de l'esprit du chaman orc avant qu'il trouve son chemin vers le Néant distordu.", "Kil'jaeden plaça l'esprit de Ner'zhul dans un bloc de glace récupéré dans le Néant distordu. Alors qu'il était piégé dans la glace, il le contraint à absorber plus de pouvoir. La perte de son enveloppe charnelle et la découverte de pouvoirs si incroyables mit fin à la transformation qui s'effectuait en Ner'zhul.", "Kil'jaeden renvoya la prison glacée de Ner'zhul dans le monde d'Azeroth. Elle s'écrasa sur le continent de Northrend et marqua l'avènement du mal dans notre monde. Ner'zhul avait disparu à jamais, à sa place se dressait un trône de glace et de haine. Le chaman respecté était devenu une créature très puissante, le roi-liche.", "Kil'jaeden ne faisait pas confiance au roi-liche. Il envoya ses seigneurs de l'effroi pour le surveiller et veiller à ce que le roi-liche exécute ses ordres. Les serviteurs vampiriques volèrent jusqu'à Azeroth, attirés par la destruction et le pouvoir libéré par le roi-liche et l'espoir d'assister au génocide de toutes les races de la planète.", "Une dizaine d'années s'écoulèrent. Pendant ce temps, le roi-liche utilisa ses vastes pouvoirs pour asservir les esprits des créatures de Northrend, à qui il ordonna d'ériger une grande citadelle autour de son trône. Quand tout le Northrend fut sous sa domination, le roi-liche sut qu'il devait commencer à infiltrer Lordaeron. Piégé dans son trône de glace, l'ancien chaman orc se mit à rechercher de nouveaux esprits à contrôler et à manipuler. Son appel retentit à travers les continents.", "Les actions du roi-liche ne passèrent pas inaperçues et furent remarquées par un petit groupe d'individus puissants. Parmi eux, il y avait l'archimage Kel'Thuzad, un membre puissant du gouvernement de Dalaran, le Kirin Tor. Ses recherches en magie violaient toutes les lois en vigueur concernant l'apprentissage de la sorcellerie. Kel'Thuzad quitta le Kirin Tor et tout ce qui le rattachait à des schémas de pensée conventionnels et jura d'apprendre tout ce qu'il pourrait à propos du roi-liche.", "Ils passèrent un pacte. Kel'Thuzad reçut l'immortalité et d'immenses pouvoirs en échange de son allégeance au roi-liche. La première tâche de Kel'Thuzad fut d'utiliser sa fortune et son influence pour fonder le culte des damnés dans Lordaeron. Le culte promit l'égalité et la vie éternelle à tous ses membres s'ils juraient fidélité à Ner'zhul, le dieu du culte.", "Ner'zhul créa des objets destinés à répandre la peste dans les civilisations humaines de Lordaeron. Il les confia à Kel'Thuzad et ordonna au sorcier de les éparpiller sur les terres. Les serviteurs du culte devaient défendre les reliques à tout prix.", "Une fois en place, la peste imprégna la terre et se répandit parmi la population ignorante. Sous la surveillance de Kel'Thuzad, l'armée du roi-liche grandit rapidement et prit le contrôle de vastes territoires. Cette armée fut bientôt connue sous le nom de Fléau. Son seul but était d'éradiquer toute l'humanité de la surface d'Azeroth." } } },
    ["Bel'dugur's Note"] = { { ids = { "i4650" }, first = "thestarofxilyehanogreina", pages = { "L'Étoile de Xil'yeh\n\nUn ogre d'Alterac, Grel'borg l'Avare, fut le dernier possesseur connu de cette gemme qui, dit-on, donne à celui qui la détient la possibilité de communiquer avec d'autres mondes. D'après nos sources, Grelborg erre dans les ruines d'Alterac, au cœur des montagnes d'Alterac, fouillant les décombres à la recherche d'autres reliques.", "La Main de Dagun\n\nDagun est une créature des profondeurs, adorée par les murlocs du marécage d'Âprefange Ils l'attirent à la surface avec un varech spécial, enchanté par leurs chamans. Chassez les murlocs, trouvez leur varech enchanté, puis placez-le sur l'autel des murlocs. Dagun viendra, et vous l'attendrez.\n\nJe veux cette main.", "Le Coeur de l'héritage\n\nLes anciens textes disent que celui qui possède le Coeur de l'héritage n'a plus à craindre la tombe. C'est peut-être vrai, car l'actuel possesseur du Coeur, le troll Mogh, est connu sous le nom de Mogh l'immortel. Sorcier-docteur de la tribu des Skullsplitter, Mogh se trouve à Strangleronce dans les ruines de Zul'Mamwe.", "Rapportez-moi ces objets, l'Etoile, la Main et le Coeur, et je vous donnerai un exemplaire du Sommaire de Yagyin.\n\n-Le Conservateur" } } },
    ["Belamoore's Research Journal"] = { { ids = { "i3711" }, first = "kegandarkmarleaderofthes", pages = { "Kegan Darkmar, chef d'un petit groupe de morts-vivants qui est venu à nous à la recherche d'un asile contre leurs \"frères\", a ébranlé nos certitudes concernant son espèce. Peut-être que sa peau pourrit et que son sang ne coule plus dans ses veines, mais il agit noblement et semble se préoccuper davantage de ses camarades que de lui-même.\n\nIl y a vraiment en lui une humanité qui fait défaut, je dois le confesser, à certains humains qui m'entourent.", "Pourquoi est-ce que j'explique tout cela ? Pour donner du poids aux mots que je vais écrire, car ils viennent directement des lèvres de Kegan et j'ai bon espoir que mes collègues, en lisant mon journal, sauront pourquoi je crois ce qu'il a dit :\n\n\"Ce qu'il reste des Dieux très anciens demeure toujours dans les profondeurs du monde. De nouvelles forces cherchent à s'assujettir cette puissance, et ceux qui y parviendront disposeront d'une arme terrible contre leurs ennemis.\"", "C'est ce que Kegan a dit en me tendant son pendentif de pierre de sang, et il y avait de la peur et comme une sorte de respect dans ses yeux. Et lorsque ses mains ont touché les miennes, elles ont frémi, comme s'il était réticent à m'abandonner le pendentif. Une vague de répulsion m'a envahie, mais j'ignore toujours aujourd'hui si c'est à cause de sa chair morte contre la mienne ou à cause du pendentif lui-même.\n\nCar j'ai senti un pouvoir en lui. Un pouvoir enfoui, caché, affamé. Avide de s'échapper.", "Bien que mes collègues de Dalaran aient hésité à étudier les pierres de sang, préférant mettre Kegan et ses compagnons en quarantaine avec tout ce qu'ils portaient sur eux, la sincérité de Kegan m'a contrainte à entamer l'étude de son pendentif.", "Je souhaitais vérifier si ce type de pierre possèdait des propriétés magiques et faire comprendre à mes collègues que si nous, les sorciers de Dalaran, ne souhaitions pas exploiter la puissance des pierres de sang, nous devions au moins en apprendre les propriétés, car nos ennemis pourraient un jour les utiliser contre nous.\n\nMes études ont donc commencé.", "J'ai commencé mes tests dans l'idée que la pierre de sang était un morceau de roc, comme le quartz ou l'obsidienne. J'ai donc lancé une série de procédures pour déterminer : quels minéraux étaient contenus dans la pierre de sang, quelles forces étaient appliquées pour produire la couleur et la résistance, et les autres caractéristiques propres aux rochers et aux minerais. Mais, à ma plus grande frustration, le pendentif n'a pas réagi aux procédures comme du minerai normal.", "En fait, il a souvent réagi de façon contraire à ce que j'espérais. C'était comme si le pendentif essayait délibérément de tromper mes expériences.\n\nComme s'il pensait, comme s'il vivait.\n\nEn colère mais pas découragée, je suis partie ensuite de l'idée que la pierre de sang n'était pas un morceau inerte de rocher, mais une chose vivante.\n\nJ'ai échoué de nouveau.", "Aucun de mes nouveaux tests ne m'a apporté de révélation sur les origines de la pierre de sang. La seule énigme que j'ai résolue à l'époque, c'était que la pierre de sang n'était ni vivante, ni morte !\n\nMais c'est alors, au bord de l'échec, que j'ai fait une percée. Mon dernier test impliquait un vase de verre dont le bord était un peu ébréché. Après avoir terminé, sans que le test ne m'apprenne rien, une fois de plus, j'ai commencé à nettoyer mon matériel et je me suis coupée sur le vase.", "La coupure n'était pas profonde mais saignait tout de même abondamment. Avant que je ne puisse bander mon doigt, une bonne partie de mon sang avait jailli sur le plan de travail.\n\nTandis que je nettoyais, j'ai constaté quelque chose d'étrange…", "Le sang qui avait coulé près du pendentif de pierre de sang avançait doucement vers le bijou, comme si la gravité s'inclinait vers la pierre de sang. Le sang qui touchait le pendentif semblait disparaître et la couleur rouge de la pierre devenait plus profonde au fur et à mesure que le sang était bu.", "Après avoir vu cela, j'ai senti ma tête s'alléger, soit à cause de ma récente blessure (mais je ne pensais pas avoir perdu tant de sang), soit parce qu'après toutes ces frustrations, j'avais découvert une propriété de la pierre de sang. Je me suis assise et me suis mise à réfléchir. Pensées et questions s'agitaient dans ma tête, me donnant le vertige et menaçant de me faire tomber à terre.\n\nEst-ce que les pierres de sang boivent du sang ? Ont-elles soif de sang ? Sont-elles attirées par le sang ?", "Ou sont-elles faites de sang ? Mais alors, le sang de qui ? Le mien ? Celui d'un humain ? D'un animal ?\n\nOu peut-être la pierre de sang est-elle le sang de quelque chose d'inconnu, la chose que Kegan avait à la fois l'air de craindre et de respecter en me remettant son pendentif ?\n\nC'est la question à laquelle il faut répondre. Voilà la clé.", "Le feu s'est rallumé en moi et j'ai repris mes expériences. Cette fois, je ne suis partie d'aucun a priori, j'ai réalisé méthodiquement tous les tests à ma disposition. Cela a considérablement augmenté les efforts nécessaires, mais a accru les chances de faire une découverte.\n\nEt bien que mon labo soit exigu et que je n'aie pas d'assistant, j'ai découvert une autre qualité étrange de la pierre de sang.", "En plus du sang, des forces élémentaires sont mêlées dans la pierre. Le feu, l'eau, la foudre et la pierre sont mélangés au sang (mais une fois encore, au sang de quoi ?) et bien que le mélange soit inerte extérieurement, toutes ces forces semblent s'affronter à l'intérieur. Cette extraordinaire substance soulevait tant d'autres questions !", "Mais pour répondre à ces questions, d'autres études, d'autres expériences sont nécessaires. J'ai peur que le camp d'internement de Lordamere ne puisse fournir la main-d'oeuvre ni le matériel requis pour cette tâche. Alors j'ai envoyé le pendentif de pierre de sang à Dalaran avec des instructions détaillées sur la manière de le tester, pour leur éviter mes frustrations initiales.", "Tandis que j'attendais les résultats des tests, j'ai passé du temps à parler avec Kegan. Je n'ai cessé de l'interroger sur ce qu'il savait des pierres de sang, mais il ne m'a rien dit de plus que le jour où il m'a donné son pendentif. Et il n'a guère parlé du temps qu'il a passé au sein des \"Réprouvés\" (c'est le nom qu'il donne à son clan de morts-vivants).", "Mais Kegan avait grande envie de parler d'autres sujets, notamment son enfance à Lordaeron avant sa chute.\n\nIl a encore beaucoup d'affection pour ce royaume perdu, même s'il est aujourd'hui en ruines, disparu.\n\nMa sympathie croissante pour Kegan m'a fait patienter le temps que les résultats des tests me reviennent.", "Mais après des semaines sans réponse, ma patience a commencé à faiblir, et après avoir pris mes renseignements à Dalaran, j'ai appris que la pierre de sang n'avait jamais atteint mes collègues. Mon messager a disparu en chemin et le pendentif avec lui !\n\nCe sont de bien graves nouvelles, car bien que Kegan et ses compagnons aient d'autres spécimens de pierres de sang, j'ai peur que le pendentif perdu ne tombe entre de mauvaises mains.", "J'ai envoyé un autre messager à Dalaran, et j'ai appris qu'ils cherchent toujours le pendentif, dans les ruines qui entourent notre sphère protégée.\n\nJ'espère qu'il n'est pas trop tard." } } },
    ["Berard's Journal"] = { { ids = { "i3255" }, first = "throughstudyofvariousfos", pages = { "A travers l'étude de différentes créatures fossilisées, j'ai déduit que dans les temps anciens, une grande peste a ravagé les eaux du lac Lordamere. Quelle en fut la cause ? Nous ne le saurons peut-être jamais. Mais le taux de contamination paraît très élevé à en juger par la forte concentration de restes présents partout dans le lit du lac.", "Dans un effort pour comprendre le passé, j'ai commencé à examiner les créatures du présent dans l'espoir de trouver la chaînon manquant de ce mystère. Les furtifs et les rampants du lac sont des bêtes anciennes qui habitent les îles au centre du lac Lordamere. Une certaine mousse pousse sur leur corps qui évoque fortement certains éléments trouvés sur les fossiles. D'autres recherches sont nécessaires avant que je ne puisse émettre une hypothèse.", "En cherchant à récupérer des échantillons de mousse, je suis arrivé sur les lieux d'un sanglant combat. Le clan murloc des Ailerons noirs a été assiégé par des gnolls en maraude. Le champ de bataille était jonché de cadavres de gnolls et de murlocs. En passant à côté du corps déchiqueté d'un murloc, j'ai repéré une étrange tumeur durcie sortant de la blessure. En étudiant la tumeur, il est devenu clair qu'elle présentait des caractéristiques proches de celles de la mousse que je cherchais à récupérer. C'est malheureusement la seule tumeur que j'ai trouvée." } } },
    ["Beyond the Dark Portal"] = { { ids = { "o21582" }, first = "onlyafewmonthsafternethe", pages = { "Quelques mois seulement après l'achèvement de Rempart-du-Néant, les énergies de la Porte des ténèbres se confondirent pour ouvrir un nouveau chemin vers Draenor. Les clans orcs rescapés, sous la conduite d'un chaman âgé, Ner'zhul, se ruèrent de nouveau dans Azeroth. Les orcs étaient décidés à voler des objets magiques capables d'augmenter les pouvoirs de Ner'zhul, afin d'ouvrir de nouveaux portails dans Draenor. Ils pensaient pouvoir fuir ainsi, à jamais, leur monde maudit.", "Convaincu que Ner'zhul planifiait une nouvelle offensive contre l'Alliance, le roi Terenas de Lordaeron envoya ses armées à Draenor pour mettre fin, une fois pour toutes, à la menace des orcs. Conduits par Khadgar et le général Turalyon, les forces de l'Alliance se heurtèrent aux orcs sur les terres calcinées. Même avec l'aide du Forestier elfe Alleria, du nain Kurdran et du vétéran Danath, Khadgar ne parvint pas à empêcher Ner'zhul d'ouvrir ses portails vers d'autres mondes.", "Les puissantes tempêtes magiques déclenchées par les énergies convergentes des portails commencèrent à déchiqueter les terres déjà ravagées. Ner'zhul, suivi de ses serviteurs les plus précieux, parvint à s'échapper à travers l'un des portails tandis que Khadgar luttait désespérément pour repousser les autres orcs vers Azeroth. Comprenant qu'ils allaient se retrouver prisonniers d'un monde à l'agonie, Khadgar et ses compagnons décidèrent héroïquement de détruire la Porte des ténèbres. Ainsi, Azeroth serait épargné par l'effondrement violent de Draenor.", "Selon toutes les chroniques, les héros parvinrent à détruire la Porte et à sauver Azeroth. Mais nul ne sait s'ils échappèrent à la destruction de Draenor." } } },
    ["Blackrat's Note"] = { { ids = { "i208205" }, first = "ivegotthegoodsillbehidin", pages = { "J'ai la marchandise. Je me cacherai près du refuge de Brumepins, à côté du vieux bateau. Si vous envoyez l'un de vos gars pour la récupérer, assurez-vous qu'il ne soit pas visible !\n\n- Ratnoir" } } },
    ["Blood-Stained Letter"] = { { ids = { "i251522" }, first = "mydearesttabithahowstran", pages = { "Ma très chère Tabitha,\n\nComme il est étrange de prédire ma propre mort. J'écris cette note car j'ignore à quelle heure mon sort sera scellé. C'est bien loin de remplacer de vrais adieux, je le sais. Te quitter ainsi est une grande douleur et ma plume a bien du mal à l'exprimer.\n\nChaque jour, au réveil, je retrouve le chagrin dont j'ai échoué à te protéger. Je suis désolé de ne pas avoir pu sauver notre cher petit, et d'avoir laissé le deuil me mener dans un piège auquel je ne peux plus échapper.\n\nTu es ma confidente et l'amour de ma vie, une vie qui n'aurait pas compté autant sans ta présence. Chaque semaine, quand je pénètre dans les ruines de notre fière cité, je crains que ce soit la dernière fois, et je remercie à chaque fois la providence en sachant que c'est auprès de toi que je rentrerai.\n\nJe prie pour que nous soyons réunis, ne serait-ce qu'un instant." } } },
    ["Bloodsail Orders"] = { { ids = { "i3921" }, first = "bloodsailorderspayattent", pages = { "Ordres de la Voile sanglante\n\nPrêtez une grande attention à ces mots, camarades, car on n'a pas le droit à l'erreur à Baie-du-Butin.\n\nJ'ai envoyé le Vieux bourré reconnaître le nord et je lui ai dit d'attendre notre signal.\n\nL'Heureuse Demoiselle va jeter l'ancre au cap sud pour gérer l'intendance. Le capitaine Stillwater, le petit nabot, doit préparer son équipage à embarquer le butin. Je suis sûr que le vieux Brutus sera à la hauteur.", "Je veux que le capitaine Keelhaul amène le Courant aux rivages du sud-est. Nous enverrons son équipage à pied au signal.\n\nSalthoof peut emmener les hommes. Je veux qu'on ait à l'oeil Revilgaz et Seahorn. Vous pouvez les envoyer par cent brasses de fond si ça vous amuse.\n\nVous avez pour mission de récupérer tout ce qui peut être de quelque utilité pour notre projet avec VanCleef dans les Mortemines.", "Je donnerai l'ordre de tir à Ironpatch. Le barrage d'artillerie empêchera tout navire de Flots noirs d'entrer dans le port ou d'en sortir.\n\nQuand le \"Voile cramoisi\" aura déchargé ses canons, je le mènerai près du \"Courant\" en soutien et je lui donnerai les réserves nécessaires.\n\nUne fois que Salthoof et ses gamins auront incendié la ville et que tout le monde sera à son poste, nous ferons voile et offrirons une dernière bordée à la côte pour faire bonne mesure.\n\n--Amiral Firallon" } } },
    ["Bloodstained Journal"] = { { ids = { "i7668" }, first = "onlyportionsofthejournal", pages = { "Quelques passages de ce journal recouvert de taches de sang sont encore lisibles).\n\nUldaman, Jour 3\n\nJe ne peux pas croire à quel point j'ai été stupide. Aveuglé, je n'ai pas su percer à jour ces filous de nains Ombreforge. Mes blessures se referment lentement, je suis sûrement empoisonné. Néanmoins je dois continuer à avancer...\n\n...Et pour ne rien arranger, le collier que les gnomes m'ont fabriqué a été brisé ! Trois des plus grosses gemmes serties dedans ont disparu. Je dois les retrouver, sans elles le collier n'a plus de pouvoirs...", "Uldaman, Jour 4\n\n...Le premier indice s'est révélé de lui-même dans les profondeurs d'Uldaman. L'un des troggs les plus sauvages que j'aie jamais vus brandissait un grand saphir, qui irait parfaitement dans le collier. J'ai entendu l'un des nains Ombreforge dire le nom de la bête : Grimlok. Mais difficile d'arracher le saphir à cette brute...", "Uldaman, 5ème jour\n\n...le trogg, s'emparant de la topaze que détenaient ses \"frères\" morts, s'engage dans la caverne annexe, près de l'entrée du hall...\n\n...il place rapidement la topaze dans une grande et superbe urne au fond de la chambre...\n\n...bon sang, des nains ! Trois de surcroît ! En fait, ils se sont barricadés pour combattre les troggs. Essayer de s'approcher d'eux serait un suicide, surtout dans mon état, ces ignobles troggs pourraient me massacrer. Une fois que j'aurai la troisième gemme, je pourrai...\"", "Uldaman, Jour 6\n\n…si faim. Je n'ai plus de provisions et même du pain moisi serait un festin… Mes yeux ont cru voir un steak juteux à la place d'une tête de trogg...", "Uldaman, Jour 7\n\n...une dernière chance de rattraper mes erreurs. Je crois que le rubis se trouve dans la dernière place forte tenue par les nains. Les combats qui les opposent aux troggs pour la gemme sont incessants. C'est comme si ces vils nains l'avaient cachée quelque part. Dans tous les cas, je dois me décider à agir. Peut-être qu'une course effrénée vers l'extérieur serait le meilleur choix..." } } },
    ["Bloody Missive"] = { { ids = { "i219929" }, first = "ourspiestellusthatsiandt", pages = { "Nos espions nous apprennent que le SI:7 et la Main d'argent ont mordu à l'hameçon, et votre cible devrait se diriger vers vous. Découvrez ce qu'ils savent, puis veillez à vous en débarrasser discrètement, hors de la ville de préférence. Ces fouineurs doivent mourir et nos biens doivent nous revenir, par tous les moyens nécessaires. N'échouez pas." } } },
    ["Bloody Note"] = { { ids = { "i254871" }, first = "theculthitusbysurprisera", pages = { "The cult hit us by surprise. Raani never saw it coming and Arvensus took a sword to the gut. For my part, I took a lightning bolt to the chest and blacked out. They never bothered to finish me off... I guess they assumed my wounds would do me in. When it's all said and done, I suspect they might.", "Dès que les affrontements ont pris fin, ils ont commencé à monter de grandes caisses de pierres de vent jusqu'au sommet de la tour. Leur cheffe, une sorte de prêtre, a parlé d'un rituel.\n\nJ'écris cette note dans l'éventualité où je ne parviendrais pas à rentrer à Shen'dar pour prévenir Aonda. Il se trame quelque chose, ici. Quelque chose de terrible.", "If anyone finds this, please, do your best to stop them. There were only a few left at the tower when I scribbled this note and crawled away.\n\nAlso, try and get Raani's lucky feather from his body. He liked to tell tall tales about how he plucked it from some kind of firebird and I think he'd want to make sure that it made its way back home.\n\nIf you are also able to retrieve Arvensus Shadowsong's family signet from his body, please do so. High Elder Shadowsong is his uncle and he would want it to be returned to the family." } } },
    ["Blue Punch Card"] = { { ids = { "i9282" }, first = "donotletthisinformationf", pages = { "Ne PAS laisser ces données tomber entre des mains ennemies !\n\n01001100 01100101 00100000 01110010 01101111 01101001 00100000 01100100 01100101 01110011 00100000 01100111 01101110 01101111 01101101 01100101 01110011 00100000 01110000 01101111 01110010 01110100 01100101 00100000 01110101 01101110 00100000 01110011 01110100 01110010 01101001 01101110 01100111 00100000 01100100 00100111 01100101 01101100 01100110 01100101 00100000 01100100 01100101 00100000 01101100 01100001 00100000 01101110 01110101 01101001 01110100" } } },
    ["Bolvar's Decree"] = { { ids = { "i11368" }, first = "solomonthecarrierofthisd", pages = { "Solomon,\n\nLe porteur de ce décret a reçu le statut officiel d'adjoint en exercice des forces de Stormwind. Vous pouvez l'utiliser pour trouver la preuve de l'alliance entre les dragons noirs et les orcs Blackrock. Si une telle preuve était trouvée, cet adjoint devrait me la rapporter à Stormwind, et je donnerais l'ordre aux forces militaires de se porter au secours de Lakeshire.\n\nSalutations,\n\nSeigneur Bolvar Fordragon" } } },
    ["Bonegrip's Note"] = { { ids = { "i4649" }, first = "thestarofxilyehgrelborgt", pages = { "L'Étoile de Xil'yeh\n\nGrel'borg l'Avare a l'Étoile. C'est un ogre cupide qui passe ses journées dans les montagnes d'Alterac, au coeur des ruines d'Alterac, à chercher des babioles. La majeure partie de sa collection est sans intérêt, mais un des objets, l'Étoile de Xil'yeh, a des capacités intéressantes.", "La Main de Dagun\n\nDes textes anciens affirment que les griffes de Dagun sécrètent un poison qui non seulement tue sa proie, mais la fait muter en quelque chose d'autre, en un membre des vieilles races. Sa valeur est évidente pour nous.\n\nDagun vit dans la mer profonde, mais il est régulièrement attiré à la surface par une tribu de murlocs Aileron boueux du le marécage d'Âprefange. Leurs oracles l'invoquent avec du varech enchanté. Si vous tuez assez d'oracles, vous trouverez le varech. Placez-le ensuite sur l'autel des murlocs et Dagun apparaîtra.", "Le Coeur de l'héritage\n\nMogh l'Immortel est un sorcier-docteur troll de Strangleronce. Il possède le Coeur de l'héritage, qui a réputation d'éloigner la mort de ceux qui savent découvrir son secret. Vous trouverez Mogh dans les ruines de Zul'Mamwe. Battez-le, si vous pouvez, et apportez-moi le Coeur de l'héritage.", "Apportez-moi ces trois objets, l'Etoile, la Main et le Coeur, et le Sommaire de Yagyin sera à vous.\n\n-G.B." } } },
    ["Book from Sven's Farm"] = { { ids = { "i2161" }, first = "theterrorofthesepastfeww", pages = { "La terreur des dernières semaines est plus que je n'en peux supporter. Mais je pense qu'en écrivant ce que j'ai vu, je pourrai trouver quelque réconfort. C'est le seul que je puisse espérer en ces temps obscurs.", "Tout a commencé avec la découverte de cette maudite Faux au Destin de Roland. Avant la Faux, il n'y avait rien de plus terrible ici que dans la vallée de Northshire.\n\nMais depuis que j'ai trouvé la hampe de la Faux dans un tas de déchets de la mine et que, malédiction sur moi, je l'en ai extirpée, le Destin de Roland est devenu un lieu de mort impie !", "Après l'exhumation de la Faux, ils ont surgi de partout, sortant de trous à nos pieds, tombant d'escarpements au-dessus de nos têtes. La moitié de nos hommes sont tombés dans ces premières minutes de panique. Les autres ont essayé de fuir. Moi aussi. Tout en courant, j'ai vu nombre de nos frères se faire déchiqueter, et j'ai entendu bien des cris sombrer dans le silence après un hoquet.", "J'ignore comment j'ai survécu cette nuit-là. J'ai toujours été prudent, toujours rapide à fuir les plaies et les bosses. On me traite de froussard depuis toujours. C'est peut-être ce fort instinct de conservation qui m'a sauvé...\n\nOu peut-être est-ce la Hampe que j'ai arrachée aux décombres. Ce ne peut être la Faux elle-même, je l'ai perdue dans ma course éperdue. Mais si c'est moi qui ai ramené les worgens dans le bois de la Pénombre, peut-être m'ont-ils fait la grâce de me laisser survivre. Qu'ils soient maudits !", "Après avoir fui le Destin de Roland, je me suis caché dans une grange appartenant à un homme du nom de Sven. J'ai passé quelques jours dans la grange et une telle horreur me possédait que je n'ai jamais signalé ma présence à Sven ni à sa famille. Mais de ce que j'ai vu depuis ma cachette, j'ai compris que ces fermiers étaient d'honnêtes gens. Si j'étais sorti de mon recoin, je crois qu'ils m'auraient offert l'hospitalité, mais je ne suis pas d'un naturel confiant. Surtout depuis ce choc dans la mine.\n\nAlors je suis resté caché.", "<Le reste du livre est vierge>" } } },
    ["Brazier of Invocation: User's Manual"] = { { ids = { "i22344" }, first = "brazierofinvocationusers", pages = { "LE BRASERO D'INVOCATION : MODE D'EMPLOI\n\nOù trouver des lieux hantés\n\nINTRODUCTION\n\nCes pages vous expliqueront où trouver les âmes et les esprits déchus des personnes impliquées dans l'incident de l'amulette du seigneur Valthalak. Bien que vous ayez déjà sauvé mes anciens compagnons, je soupçonne que les échos répugnants du mal qui a corrompu leurs esprits résonnent toujours dans ces lieux hantés. Tel est le pouvoir maléfique de l'esprit du seigneur Valthalak.\n\nLe brasero peut aussi servir à invoquer le seigneur Valthalak mais comme vous avez déjà pu vous en rendre compte, il vaut mieux faire preuve de prudence à ce propos.", "INTRODUCTION, suite...\n\nLe brasero lui-même fonctionne comme le brasero de signal. Placez-le aux alentours de l'un des cinq lieux hantés et il invoquera l'esprit des morts.\n\nAccessoirement et parce que je sais que cela vous intéresse, la bannière de provocation peut être utilisée d'une manière similaire dans l'arène des profondeurs de Blackrock. À votre prochaine visite, et si possible à toutes les suivantes, infligez donc à Theldren et à ses brutes une bonne leçon de ma part.\n\nSi vous voulez en apprendre davantage, continuez à lire.", "ISALIEN\n\nElfe de la nuit, prêtresse de la Lune.\n\nLorsque Isalien décida de quitter la compagnie, elle avait l'intention de se rendre en pèlerinage à Hache-tripes, l'antique cité en ruine que les elfes connaissaient naguère sous le nom d'Eldre'Thalas. Il s'y trouve encore une bibliothèque, un sanctuaire consacré au savoir, que quelques elfes de la nuit ont réussi à préserver. Elle comptait trouver des réponses concernant à la fois le passé de son peuple et les morceaux de l'amulette. Notez qu'elle était très amie avec Falrin Treeshaper.", "ISALIEN, suite...\n\nMalheureusement, au moment où elle entrait dans la ville, elle fut victime d'Alzzin le Modeleur et de ses séides. Son hippogryphe apprivoisé, Empyréen, succomba également. Isalien tomba et ne se releva pas. Il est peut-être préférable qu'elle ne soit pas parvenue à découvrir les secrets de la magie maléfique dont le seigneur Valthalak s'était servi pour enfermer une partie de son essence dans l'amulette.\n\nLa salle découverte où réside Alzzin est l'un des lieux hantés.", "MOR GRAYHOOF\n\nDruide tauren, il fut le premier à succomber.\n\nMor Grayhoof était l'un des plus vaillants compagnons au sein de la Lame ardente. Tragiquement, il a été la première victime des séides maléfiques du seigneur Valthalak.\n\nLorsque nous avons fui la colère de Valthalak, nous étions poursuivis par une véritable armée d'assassins et de traqueurs spectraux. Notre départ du pic Blackrock fut passablement désordonné. Hélas, au cours du trajet, Mor perdit pied. À moins que quelqu'un ne l'ait poussé…Quoi qu'il en soit, il tomba dans les ténèbres de la partie inférieure du pic.", "MOR GRAYHOOF, suite...\n\nPlus tard, nous avons découvert que Mor avait survécu à sa chute. Hélas, mon vieil ami a connu une fin affreuse. Il fut capturé par les trolls de Tazz'Alaor. Peu après, alors que le maître de guerre Voone était en train de le torturer, il fut achevé par un groupe d'assassins au service de Valthalak.\n\nSi vous souhaitez consulter l'écho de l'esprit de Mor Grayhoof, la chambre du maître de guerre Voone est l'un des lieux hantés.", "JARIEN ET SOTHOS\n\nUne fratrie d'aspirants à la Croisade écarlate\n\nJarien et Sothos étaient parmi les gens les plus intolérants que j'aie croisés. Mais ils étaient des combattants exceptionnels, et issus d'une famille riche. Pour ces raisons Anthion, le chef de la Lame voilée, les tolérait.\n\nIls ont fini par se laisser séduire par les enseignements et la philosophie de la Croisade écarlate. Ils avaient toujours fait preuve de beaucoup de zèle dans l'extermination des créatures du Fléau qui croisaient notre chemin, et nous soupçonnions leur famille d'avoir des liens avec cette organisation.", "JARIEN ET SOTHOS, suite...\n\nIls se retrouvèrent donc confrontés aux épreuves réservées à ceux qui souhaitent rejoindre la Croisade. Ils convoitaient le titre de chevalier, ce qui apparemment requiert des épreuves plus compliquées. Nous avons su plus tard que Sothos avait échoué. Jarien refusa de l'admettre, et soutint que son frère devait la rejoindre parmi les chevaliers. Pour cette raison, le Grand croisé Dathrohan finit par les tuer tous les deux au milieu de ses appartements.\n\nPour cette raison, le Trône cramoisi, au cœur du Bastion écarlate de Stratholme, est un autre lieu hanté.", "KORMOK\n\nOgre nécromancien bicéphale\n\nQue dire de Kormok ? C'était un ogre bicéphale, de la variété qui lance des sorts, mais il n'était pas mauvais bougre. Il nous a rejoints quand nous l'avons capturé au cours d'un boulot dans les Steppes ardentes. L'affaire a dégénéré, il nous a aidé à nous en tirer, et il a fini par devenir l'un des principaux mages de la compagnie.\n\nBizarrement, ses deux têtes se comportaient de manière complètement différente. La première était joviale et pas futée, l'autre était matoise et calculatrice, avec un regard mort vaguement effrayant.", "KORMOK, suite...\n\nAu cours de nos voyages, Kormok découvrit le versant nécromantique de la magie. Malheureusement, sa tête effrayante avait un don pour ces pratiques. Elle y prenait un plaisir pervers, surtout lorsqu'elle parvenait à faire apparaître les esprits exilés de l'île de la Purification pour les asservir.\n\nAprès la dissolution de la compagnie, Kormok entra à la Scholomance pour « s'instruire ». Les assassins spectraux n'eurent aucun mal à pénétrer dans l'école. Ils le tuèrent aux pieds de son nouveau maître, Ras Murmegivre.\n\nLa chambre de Ras Murmegivre est l'un des lieux hantés où il est possible d'utiliser le brasero.", "LE SEIGNEUR VALTHALAK\n\nNoble draconique et ancien général du pic Blackrock\n\nAvant le général Drakkisath, il y avait le seigneur Valthalak, un démoniste d'une puissance immense. La direction du pic change assez souvent, et malheureusement pour nous, nous avons été impliqués dans les derniers bouleversements.\n\nNous avons été engagés par un sorcier-contrebandier des environs de Baie-du-Butin, Gremnik Rizzlesprang, pour voler le livre de sorts de Valthalak. Nous ne savons pas s'il voulait l'étudier, le vendre ou les deux, cela n'a plus d'importance. Nous avons infiltré le sommet du pic et nous avons tué Valthalak dans son repaire. C'est là que ça s'est gâté.", "LE SEIGNEUR VALTHALAK, suite...\n\nNous ignorions que le seigneur Valthalak était passé maître dans la manipulation des âmes. Sinon, nous n'aurions pas pris ce boulot. Mais nous l'avons accepté, et ce fut notre dernier.\n\nNous venions de prendre son livre de sorts au cadavre de Valthalak lorsque Kormok a senti quelque chose à propos de son amulette. Il a insisté pour qu'elle devienne sa part du butin. Nous nous sommes disputés, et nous avons bien failli en venir aux mains. Nous ne savions pas que l'amulette renfermait une bonne part de l'esprit de Valthalak. Nous l'avons découvert plus tard, dans la douleur.", "LE SEIGNEUR VALTHALAK, suite...\n\nAvant de fuir, poursuivis par le fantôme de Valthalak et une armée d'assassins spectraux, nous avons divisé l'amulette en plusieurs morceaux. Notre dispute sur l'amulette avait attiré l'attention des défenseurs restants du pic !\n\nNous sommes presque tous sortis du pic, et nous avons cru que nous étions à l'abri. Mais même de l'au-delà, Valthalak nous envoyait ses sbires, où que nous nous cachions. La Lame voilée a éclaté peu après cette mission et nous sommes devenus des cibles encore plus faciles.\n\nComme vous le savez certainement, la résidence du seigneur Valthalak, qui est aujourd'hui la chambre de la Bête dans le pic Blackrock, est le dernier des lieux hantés." } } },
    ["Brock's List"] = { { ids = { "i16310" }, first = "belowistheliststudentswh", pages = { "Voici la liste des étudiants qui ont obtenu une Etoile de platine à l'Ecole des mines de Brock, ce qui leur vaut un Pic de mineur honoraire :\n\nMelia Stoneshaker\nBardin Ironband\nUmi Togglevolt\nRumi Togglevolt\nVorel Steelspire" } } },
    ["Call to Arms Announcement"] = { { ids = { "i22595" }, first = "toallablebodiedmenandwom", pages = { "À tous ceux en état de porter les armes :\n\nLe Fléau est de retour et nous devons oublier nos différends pour faire face à cette menace. L'Aube d'argent ne refusera aucun de ceux qui souhaitent prendre les armes pour lutter contre le Fléau.\n\nLa mobilisation pour la défense de nos contrées s'effectue à la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est. Ensemble, nous vaincrons.\n\nLe gardien des registres\nL'Aube d'argent" } } },
    ["Calor's Note"] = { { ids = { "i2113" }, first = "mastercarevinthebearerof", pages = { "Maître Carevin,\n\nLe porteur de cette note s'est montré digne de la Lumière, capable de battre les morts-vivants et les démons qui infestent les abords du bois de la Pénombre, et désire rejoindre la famille Carevin dans sa lutte pour la Lumière.\n\nJe vous suggère donc de confier d'autres tâches à ce guerrier de la Lumière, comme enquêter sur certains membres de la communauté qui sont suspectés d'être traîtres à la Lumière.\n\nBien amicalement,\nCalor" } } },
    ["Captain's Documents"] = { { ids = { "i5882" }, first = "thebleedingsparrowmanife", pages = { "Le Moineau sanglant : Manifeste\n\n(20) tonneaux de rhum. Destination : Theramore\n(50) sacs de farine. Destination : Theramore\n(2) caisses d'assortiments d'outils gnomes. Destination : Ratchet\n(30) rouleaux de tissu en coton. Destination : Theramore\n(4) caisses d'épices. Destination : Theramore\n(3) passagers. Destination : Theramore", "Capitaine,\n\nJe vous souhaite bonne chance dans vos voyages. Malheureusement, la bonne fortune n'était pas avec nous lors de notre première tentative d'enlèvement.\n\nLorsque votre groupe a pris contact avec la cible dans les tunnels de Stormwind/Ironforge, ils n'ont trouvé qu'un leurre. Il semble qu'il était plus sage que nous le pensions.\n\nMais le second plan est déjà enclenché. Les agents Defias sont prêts à intercepter la cible quand elle approchera de Theramore. Bientôt Stormwind sentira notre étau autour de son cou.\n\n-M" } } },
    ["Certificate of Thievery"] = { { ids = { "i7907" }, first = "thebearerofthiscertifica", pages = { "Le porteur de ce certificat a droit au respect et à la considération que mérite tout chapardeur et larron de première classe." } } },
    ["Charge of the Dragonflights"] = { { ids = { "o175726" }, first = "satisfiedthatthesmallwor", pages = { "Contents que le petit monde ait été ordonné et que leur travail soit accompli, les Titans se préparèrent à quitter Azeroth. Mais, avant de partir, ils décidèrent de donner aux plus grandes espèces nouvelles du monde le pouvoir de surveiller Kalimdor contre toute menace possible. A cette époque, il y avait de nombreuses tribus de dragons.", "Il existait cinq tribus qui avaient la main-mise sur leurs frères. Ce sont ces cinq tribus que les Titans choisirent pour contrôler le monde. Les plus grands membres du Panthéon donnèrent une partie de leur pouvoir au chef de chaque tribu. Ces dragons majestueux, dont les noms suivent, prirent le nom de Grands Aspects, ou Aspects dragons.", "Aman'Thul, le Haut-père du Panthéon, concéda une partie de sa puissance cosmique au massif dragon de bronze, Nozdormu. Le Haut-père donna pouvoir à Nozdormu de garder le temps lui-même et de guider les chemins toujours instables de la destinée. Le stoïque et honorable Nozdormu prit le nom d'Eternel.", "Eonar, le Titan responsable de la vie, donna une portion de sa puissance au léviathan rouge, Alexstrasza. Alexstrasza fut désormais connue comme la Lieuse de vie et elle travailla à sauvegarder les créatures vivantes du monde. En raison de sa sagesse sans bornes et de son infinie compassion pour toutes les espèces vivantes, Alexstrasza fut couronnée reine des dragons et reçut la tutelle de son espèce.", "Eonar bénit également la jeune soeur d'Alexstrasza, le souple dragon vert Ysera, qui put désormais influencer la nature. Ysera tomba en une transe éternelle, liée au Rêve de la Création. Connue sous le nom de Rêveuse, elle surveillait la croissance de la nature depuis son royaume foisonnant, le Rêve d'émeraude.", "Norgannon, le Titan gardien des traditions et de la magie, donna au dragon bleu Malygos une partie de ses vastes pouvoirs. Malygos, désormais Tisseur de sorts, devint le gardien de la magie et des arcanes cachées.", "Khaz'goroth, le Titan qui forgeait les mondes, transmit un peu de sa grande puissance à la Wyrme noire, Neltharion. Avec son grand coeur, Neltharion, qui prit le nom de Gardien du monde, reçut toute puissance sur la terre et les vastes espaces du monde. Il personnifia la force du monde et devint le plus ardent soutien d'Alexstrasza.", "Ainsi nantis de différents pouvoirs, les cinq Aspects furent chargés de la défense du monde en l'absence des Titans. Les dragons étant prêts à défendre leur création, les Titans quittèrent Azeroth pour toujours. Malheureusement pour eux, et pour le petit monde qu'ils venaient de façonner, Sargeras finirait un jour ou l'autre par découvrir son existence..." } } },
    ["Charred Note"] = { { ids = { "i205864" }, first = "adaimpleasedtohearisland", pages = { "<La page est calcinée en plusieurs endroits, comme si quelqu'un avait tenté de la brûler en toute hâte. Une partie de ce qui reste est lisible.>\n\nAda,\n\nJe suis heureux d'entendre -------- île sur la rive assombrie. ----- Un de nos agents ------------ mot de passe ----\n\n« Quand une bougie s'éteint, une autre s'allume. »\n\n– Mitchells" } } },
    ["Civil War in the Plaguelands"] = { { ids = { "o175761" }, first = "nerzhulthelichkingknewth", pages = { "Ner'zhul, le roi-liche, savait que ses heures étaient comptées. Emprisonné dans le Trône de glace, il suspecta que Kil'jaeden allait envoyer ses agents pour le détruire. Les dégâts causés par le sort d'Illidan avaient rompu le Trône de glace : le roi-liche perdait chaque jour de son pouvoir. Désireux de se préserver, il appela son plus grand serviteur mortel à ses côtés : le chevalier de la mort, le prince Arthas.", "Bien que ses pouvoirs fussent diminués par la faiblesse du roi-liche, Arthas s'était impliqué dans la guerre civile de Lordaeron. La moitié des forces des morts-vivants, menée par la banshee Sylvanas Windrunner, avait préparé un coup d'état pour prendre le contrôle de l'empire mort-vivant. Arthas, appelé par le roi-liche, dut laisser le Fléau aux mains de son lieutenant, Kel'Thuzad, alors que la guerre s'étendait sur les Maleterres.", "Finalement, Sylvanas et ses morts-vivants rebelles (connus sous le nom de Réprouvés) s'emparèrent de la capitale en ruines de Lordaeron. Ils construisirent leur propre bastion sous la cité délabrée et jurèrent de vaincre le Fléau et de repousser Kel'Thuzad et ses serviteurs loin de la région.", "Affaibli, mais déterminé à sauver son maître, Arthas rejoignit Northrend et découvrit que les nagas d'Illidan et les elfes de sang l'attendaient. Avec ses alliés nérubiens, Arthas tâcha d'atteindre avant les forces d'Illidan le glacier de la Couronne de glace pour y défendre son trône." } } },
    ["Cliffwatcher Longhorn Report"] = { { ids = { "i13507" }, first = "natakaalliswellinthousan", pages = { "Nataka, tout va bien à Mille pointes. Les centaures sont tout au plus un peu agaçants... Parfois ils attaquent, rien qui ressemble à une véritable menace. Mais il paraît que les clans de centaures s'unissent.\n\nNous avons toujours redouté qu'une telle race fasse taire ses différends... J'essaie de ne pas m'arrêter à ces pensées... Rien n'est capable de pénétrer la haine pure qu'ils ont, même les uns pour les autres.\n\n-Garde-falaise Longhorn" } } },
    ["Cloth Request"] = { { ids = { "i2724" }, first = "totheschneidersgooddayit", pages = { "Aux Schneider,\n\nSalutations. J'espère que les affaires vont bien. Dans le quartier commerçant, c'est l'explosion.\n\nNous avons grand besoin de tricots, car nos stocks sont vides. Veuillez nous envoyer le chargement habituel dès que vous le pourrez.\n\nJe vous souhaite bonne fortune et j'espère que les études de votre fils Thurman progressent bien,\n\n--Harlan Bagley" } } },
    ["Compendium of the Fallen"] = { { ids = { "i5535" }, first = "withkelthuzadssuccessinl", pages = { "Après le succès de Kel'Thuzad à Lordaeron, le roi-liche termina ses préparatifs avant de se lancer à l'assaut de la civilisation humaine. Il créa des objets transportables, appelés chaudrons de peste, pour diffuser son énergie pestilentielle. Ner'zhul ordonna à Kel'Thuzad de transporter ces chaudrons à Lordaeron où ils seraient cachés dans des villages voués au culte.", "Les chaudrons, protégés par les membres loyaux du culte, agiront comme des générateurs de peste qui contamineront les fermes et les villes du nord de Lordaeron.\n\nLe plan du roi-liche se déroula à la perfection. Beaucoup de villages du Nord furent contaminés presque immédiatement. Comme pour le Northrend, les citoyens contaminés moururent et devinrent les esclaves du roi-liche.", "Les membres du culte, aux ordres de Kel'Thuzad, étaient pressés de mourir et de revenir à la vie pour servir leur seigneur ténébreux. Ils exultaient à l'idée de devenir immortels. Tandis que la peste se répandait, de plus en plus de zombies affluaient des terres du Nord. Kel'Thuzad observait l'armée sans cesse grandissante du roi-liche et la nomma le Fléau. Dans peu de temps, cette armée marcherait sur les portes de Lordaeron... Et éliminerait l'humanité de la surface de ce monde." } } },
    ["Confidential Message"] = { { ids = { "i210967" }, first = "brotheresolonshouldyoune", pages = { "Frère Esolon,\n\nSi vous avez besoin d'accéder au reliquaire, j'ai caché une clé dans le cimetière. Elle se trouve dans un coffret de pierre, sous le sol du mausolée nord.\n\nUn mécanisme permet de soulever le coffret. Pour l'activer, vous devez vous asseoir sur les deux bancs situés entre les paires de statues, de part et d'autre du cimetière.\n\nMerci de garder ces informations strictement confidentielles.\n\nBénédictions,\nFrère Seramus" } } },
    ["Consecrated Letter"] = { { ids = { "i9570" }, first = "ihopethisletterfindsyouw", pages = { "J'espère que vous allez bien, $C. Je le dis avec fierté, car peu peuvent se targuer d'une telle foi, mais ils font également partie de l'élite vraie des protecteurs d'Azeroth.\n\nSouvenez-vous toujours et avant tout que votre devoir est de vous battre contre ceux qui veulent blesser notre monde et corrompre nos foyers.\n\nJ'ai reçu toute autorité pour vous former. Quand vous le voudrez, venez me voir à l'Abbaye de Northshire.\n\n-Frère Sammuel, Maître des paladins" } } },
    ["Consecrated Rune"] = { { ids = { "i9563" }, first = "somefearourkindmorethand", pages = { "Certains nous craignent plus encore que les dragons. D'autres nous envient davantage que les forgerons les plus habiles. Certains se divertissent de notre foi. D'autres sont jaloux de nous voir si bien tenir la bière. Mais en tout état de cause, $C, vous faites partie de l'élite des protecteurs d'Azeroth. La Sainte Lumière nous donne notre force et nous lui donnons la nôtre.\n\nJe vous en dirai plus quand vous connaîtrez mieux ces terres. Vous me trouverez à Anvilmar, au-dessus de la Vallée.\n\n-Bromos Grummner, Maître des paladins" } } },
    ["Consecrated Scroll"] = { { ids = { "i282423" }, first = "welcomebackiunderstandal", pages = { "Bon retour parmi nous, $N.\n\nJe ne comprends que trop bien le choc que l'on peut ressentir dans la situation où vous vous trouvez. Vous avez survécu jusqu'à maintenant, et c'est ce qui vous distingue des autres paladins récemment ressuscités.\n\nL'aspect le plus difficile de votre nouvelle vie sera de redécouvrir ce que vous avez perdu… et de supporter la douleur que cela vous causera.\n\nVenez me parler au Glas et je vous aiderai à trouver la détermination nécessaire pour faire vos premiers pas.\n\n– Aramis Mainmartel, maître des paladins" } } },
    ["Control Console Operating Manual"] = { { ids = { "i5088" }, first = "thesamophlangecontrolcon", pages = { "La console de contrôle du samophlange peut être utilisée pour réguler automatiquement les flux de carburant, de gaz, de liquides, et tout ce qui est lié aux machines. Une fois la configuration en place, tout devrait fonctionner avec un minimum de maintenance.\n\nListe sommaire des éléments de la console de contrôle (de la gauche vers la droite)\n\nI. Levier d'alimentation principal\n\nPermet de faire fonctionner le samophlange. Le mécanisme de contrôle ne se désengage pas automatiquement quand le levier est en position off. Cela initie seulement", "le processus de refroidissement. Il faut ensuite une à deux minutes (en fonction de la situation) pour que l'appareil s'éteigne.\n\nREMARQUE IMPORTANTE : le levier d'alimentation principal ne peut être contrôlé que lorsque les trois valves de contrôle de la machine ont été désengagées. Ces valves peuvent être désactivées dans n'importe quel ordre.\n\nLa première est la VALVE DE CONTRÔLE PRINCIPALE, qui se trouve à la base de la grande cheminée verticale. Ensuite, la VALVE DE CONTRÔLE DU CARBURANT se trouve sur le grand tuyau qui va des réservoirs", "de carburant (il devrait y en avoir trois) à la cheminée. Enfin, la VALVE DE RÉGLAGE se trouve sur le plus court des deux grands réservoirs cylindriques sur le bord de la cheminée.\n\nII. Jauges de carburant\n\nAffichent la pression actuelle dans les réservoirs de carburant principal, secondaire et tertiaire.\n\nIII. Jauge de flux\n\nAffiche l'état actuel du flux dans le système.", "IV. Contrôles du flux\n\nPermettent d'augmenter ou de baisser le taux du flux. Contrôlé automatiquement par le mécanisme de contrôle du samophlange.\n\nV. Jauge de température\n\nAffiche la température de fonctionnement de tout le système." } } },
    ["Covert Ops Plans: Alpha & Beta"] = { { ids = { "i5737" }, first = "okayyoushouldhaveyourngc", pages = { "Bon, les détonateurs et les explosifs NG-5 doivent être prêts à fonctionner. Je les ai marqués pour vous... Le bleu est pour la scierie. Le rouge pour la mine des Cisailles.\n\nJ'y suis allé en reconnaissance et vous ne devriez pas avoir de problème à aller placer les explosifs et à ressortir avant de les faire exploser avec le détonateur.\n\nSouvenez-vous, le but est de faire diversion. Eloignez-vous des chariots avant que les gobelins ne viennent voir ce qui s'est passé et faufilez-vous discrètement derrière eux pour entrer.", "Surtout faites attention. Le Nitromirglyceronium peut vous réduire en poussière. J'ai enfermé le liquide dans des tubes en cuivre, il devrait rester stable et sans danger.\n\nJ'ai utilisé le parchemin que Collin vous avait donné sur les boîtes des détonateurs. Ils enverront un message silencieux aux explosifs NG-5 une fois que vous les aurez placés. J'ai utilisé un mécanisme Stalthwargon simple pour être sûr que la conductivité est optimale et que l'écoulement de la Nitroglycérine entre les fluides différentiels est meilleur que la moyenne.", "Avant que je ne rentre dans les détails de mon plan, laissez-moi vous expliquer où vous devrez placer les explosifs.\n\nPlan Alpha - la scierie :\nIl y a un chariot à l'extérieur en face de la scierie (c'est au nord-est du site de déboisement et de stockage de bois). Je pense que les plans d'ingénierie sont dans la scierie.\n\nPour placer la charge, allez derrière le chariot. Une fois qu'elle est placée, éloignez-vous au plus vite.", "Lorsque vous êtes prêt, appuyez sur le détonateur.\n\nJe me suis assuré que le signal serait bon en utilisant des bobines de cuivre et d'argent avec une antenne melthusienne déployée sur le boîtier. Ça devrait fonctionner à bonne distance. Méfiez-vous des gobelins. Ils n'apprécieront pas de vous trouver à cet endroit.\n\nAu fait, des fois que vous n'ayez pas compris, éloignez-vous du chariot avant de le faire exploser... Ça fait mal.", "Plan Bêta - Mine des Cisailles :\n\nJ'ai vu les gobelins utiliser un autre chariot d'explosifs au nord de l'entrée de la mine. Je pense que cet endroit conviendra très bien pour y placer la charge d'explosif NG-5 (rouge). Après avoir placé la charge à l'arrière du chariot, éloignez-vous et appuyez sur le bouton.\n\nSi les gobelins ne viennent pas voir ce qui s'est passé, c'est que la montagne leur est tombée sur la tête.", "Les lettres de la KapitalRisk sont à l'extérieur de la mine... Sur certaines des caisses au niveau inférieur, je crois.\n\nBonne chance, et souvenez-vous...\n\nExplosif bleu : la scierie\nExplosif rouge : la mine\n\nEt détruisez cette lettre une fois la mission accomplie. D'ailleurs, je devrais peut-être penser à trouver un moyen pour que ces lettres se détruisent toutes seules, une fois qu'elles sont lues. Ce n'est pas bête, ça..." } } },
    ["Crate of Horseshoes"] = { { ids = { "i1284" }, first = "anoteisattachedtothecrat", pages = { "Une note est attachée à la caisse. Elle dit :\n\nVerner - Désolé d'apprendre que les Carmines connaissent de telles difficultés. Voici les fers à cheval que vous avez demandés. Veuillez me payer 100 pièces d'argent lorsque vous le pourrez.\"\n\n\"Vous pouvez si vous préférez me payer en écailles ventrales de jeunes dragons noirs (il paraît que ces dragons sont nombreux dans les Carmines). Comme nous sommes amis, 4 écailles suffiront. Tous mes remerciements --Argus\"" } } },
    ["Crude Map"] = { { ids = { "i21037" }, first = "", pages = { "" } } },
    ["Crumpled Note"] = { { ids = { "i4100" }, first = "fleeingfromthezanzilinth", pages = { "Fuir les Zanzil dans ce bateau pourrissant semblait sage sur le moment, mais je commence à me dire que la mort aurait été un destin plus favorable.\n\nJe pensais que mes ancêtres m'avaient fait une faveur en me permettant d'échapper à leur colère. Mais je commence à me demander quelle sagesse je vais acquérir si je survis à mon emprisonnement." } }, { ids = { "i282419" }, first = "youvegotagoodswordarmand", pages = { "$N, j'ai remarqué que vous avez un bon bras armé.\n\nC'est le bazar sur l'île de Zéphras, ça ne fait aucun doute. Nos guerriers et guerrières shen'dorei devront être au meilleur de leur forme si nous voulons survivre à ce qui nous attend. Il est temps pour vous d'arrêter de jouer au petit soldat et de passer aux choses sérieuses.\n\nRetrouvez-moi dans la base de la tour de guet de Thendal. Je vais vous entraîner correctement.\n\n– Maître-lame Ren, maîtresse des guerriers" } } },
    ["Crystal Pylon User's Manual"] = { { ids = { "i11482" }, first = "crystalpylonusersmanuala", pages = { "MANUEL D'UTILISATION DES PYLÔNES DE CRISTAL\n\n \"Guide pour récupérer et utiliser les cristaux de puissance du cratère d'Un'Goro.\"\n\nChapitre 1 : Le pylône du nord\n\nChapitre 2 : Le pylône de l'est\n\nChapitre 3 : Le pylône de l'ouest", "Chapitre 1 : LE PYLONE NORD\n\nLe Pylône\nnord accepte\nles cristaux\njaunes, rouges\net verts.\n\nLe Pylône se focalise sur l'énergie qui peut être créée en utilisant des cristaux jaunes comme source de puissance principale.", "Combinaisons du cristal Nord\n\nIl y a deux effets possibles : une combinaison produit des dégâts, l'autre les supprime.\n\nCHARGE CRISTALLINE : nécessite des cristaux rouges et jaunes.\nCela produit une explosion violente.\n\nRESTAURATION CRISTALLINE : nécessite des cristaux jaunes et verts.\nVous fournit une aura de soins.", "DIAGRAMME DU PYLONE NORD", "Chapitre 2 : LE PYLONE EST\n\nLe Pylône\nest accepte\nles cristaux\nbleus, jaunes\net verts.\n\nLe Pylône se focalise sur l'énergie qui peut être créée en utilisant des cristaux bleus comme source de puissance principale.", "Combinaisons de cristal est\n\nIl y a deux effets possibles : l'un fournit un bonus d'esprit, l'autre crée un bouclier de dégâts.\n\nFORCE CRISTALLINE : nécessite des cristaux bleus et verts.\nVous fournit une amélioration de l'esprit.\n\nFLECHE CRISTALLINE : nécessite des cristaux bleus et jaunes.\nCrée un bouclier qui inflige des dégâts aux attaquants.", "DIAGRAMME DU PYLONE EST", "Chapitre 3 : LE PYLONE OUEST\n\nLe Pylône\nouest accepte\nles cristaux\nrouges, verts\net bleus.\n\nLe Pylône se focalise sur l'énergie qui peut être créée en utilisant des cristaux rouges comme source de puissance principale.", "Combinaisons de cristal ouest\n\nIl y a deux effets possibles : une combinaison améliore votre protection contre les dégâts, l'autre affaiblit les défenses de l'ennemi.\n\nGARDIEN CRISTALLIN : nécessite des cristaux rouges et verts.\nAméliore votre armure.\n\nFISSURES CRISTALLINES : nécessite des cristaux bleus et rouges.\nPeut réduire l'armure d'une cible spécifique.", "DIAGRAMME DU PYLONE OUEST" } } },
    ["Crystallized Note"] = { { ids = { "i10839" }, first = "towhomitmayconcernifyoua", pages = { "Aux intéressés :\n\n Si vous êtes en train de lire cette note, c'est que vous êtes dans l'un des deux endroits suivants :\n\n(1) Sur la péninsule sud d'Azshara.\n\n(2) Dans le ventre d'un géant des falaises.\n\nDans les deux cas, vous êtes en mauvaise posture.\n\nSachez que j'ai eu l'occasion de visiter les deux mais particulièrement le dernier comme le prouve cette lettre.", "Etre à l'intérieur du ventre d'un géant vous laisse du temps pour réfléchir.\n\nAlors que mon corps commence à se cristalliser, j'en suis venu à la conclusion qu'il y a peut-être suffisamment de héros dans ce monde. Si je réussis à m'en sortir, je tordrai le cou de cet orc !\n\n- Windan Shay" } }, { ids = { "i10840" }, first = "whatwasithinkingperhapsa", pages = { "A quoi est-ce que je pensais ?\n\nMais une autre question s'impose : pourquoi suis-je en train d'écrire une note alors que je suis emprisonné dans le ventre d'un géant ?\n\n Deux questions pertinentes pour lesquelles je n'ai pas de réponses immédiates...\n\nIl faut reconnaître que ma mission n'était pas des plus simples. Je suis parti à la recherche d'Azsharite, un cristal unique en Azshara du Sud. Ah, j'aurais pu devenir riche !\n\nBah ! Regardez-moi maintenant...", "Si jamais une quelconque forme de vie intelligente trouve cette note, elle doit se demander ceci : \"Pourquoi se risquer à chahuter avec des géants violents de neuf mètres de haut ?\"\n\n- Mook" } } },
    ["Cutty's Note"] = { { ids = { "i203723" }, first = "ivegotthegoodsillbehidin", pages = { "J'ai la marchandise. Je me cacherai en amont de la rivière du lac de Cristal, près du mur. Si vous envoyez un agent pour la récupérer, assurez-vous qu'il ne soit pas visible !\n\n– Cutty" } } },
    ["Damp Diary Page (Day 4)"] = { { ids = { "i6304" }, first = "diarydayihavebeenstrande", pages = { "Journal - Jour 4\n\nCela fait maintenant 4 jours que je me suis échoué sur l'île et que je suis seul perdu dans mes pensées. Les bananes sont très goûteuses, mais c'est une véritable partie d'escalade pour les atteindre. Lorsque je ne suis pas à la recherche de nourriture ou d'un abri contre les pluies diluviennes, je ne pense qu'à un hypothétique secours.\n\nJe ne caresserais pas un tel espoir si des caisses de bouteilles et de papiers ne s'étaient pas échouées sur le rivage. Quelle ironie quand je repense à tout ce temps passé sur ce navire, me plaignant d'être coincé à bord de ce rafiot avec tous ces Alchimistes et Scribes." } } },
    ["Damp Diary Page (Day 512)"] = { { ids = { "i6306" }, first = "diarydaythebananashavest", pages = { "Journal - Jour 512\n\nLes bananes ont commencé à me parler et j'ai appris beaucoup de choses concernant leur culture. J'ai cessé de détruire aveuglement leurs maisons et arrêté de consommer leurs rejetons. Je ne savais presque rien de la civilisation glorieuse que j'étais en train de détruire.\n\nD'un autre côté, je suis à cours de bouteilles et de papier. Lorsque j'ai vu pour la première fois ces énormes liasses de papier rejetées sur le rivage, j'ai cru que cette réserve serait inépuisable. Pauvre journal, ce sera bientôt la fin pour nous deux." } } },
    ["Damp Diary Page (Day 87)"] = { { ids = { "i6305" }, first = "thesemonthshavegivenmeti", pages = { "Ces derniers mois m'ont laissé du temps pour revoir mes vieilles croyances. L'Alliance ? La Horde ? Le Bien ? Le Mal ? Le sens de ces mots, jusqu'ici si clair, se brouille au fur et à mesure que mon regard se perd dans la mer.\n\nJe sais maintenant à quoi m'en tenir. Les bananes sont après moi.\n\nHaut perchées dans leur arbre, elles me fixent avec malveillance. Et la dernière que j'ai essayé de manger m'a presque étouffé ! Je pouvais presque l'entendre crier alors que je l'écrasai, à moitié mangée, sur les rochers.\n\nC'est la guerre et je la gagnerai." } } },
    ["Danath Trollbane"] = { { ids = { "o25332" }, first = "danathtrollbanemilitiaco", pages = { "Danath Trollbane\n\nCommandant de la milice de Stromgarde. Conseiller stratégique du général Turalyon. Commandant des forces attachées à l'expédition de l'Alliance qui a marché sur le monde des orcs de Draenor. Présumé mort.\n\nNous honorons ta mémoire, ô mon neveu, et ton sacrifice. Depuis la fondation de notre glorieux empire, le chemin de la grandeur a toujours été ouvert par le sang des héros.\n- Thoras Trollbane, seigneur de Stromgarde" } } },
    ["Dark Iron Script"] = { { ids = { "i6847" }, first = "dirtytroggsaresoeasytofo", pages = { "Les affreux troggs sont si simples à duper. La haine qu'ils vouent à notre espèce les rend plus faciles à manipuler. Je suis surpris qu'ils aient accepté la moindre alliance, mais nous représentons une telle menace pour eux... Du moins, pour le moment.\n\nUne fois les combats commencés, les deux camps seront affaiblis et à notre merci. Emparez-vous de la ferme qui se trouve au sud du lac d'Helm's Bed et attendez les ordres.\n\nIronforge sera à nous." } } },
    ["Dark Keeper Nameplate"] = { { ids = { "o164820" }, first = "vorfalkirongourdvorfalkw", pages = { "Vorfalk Irongourd\n\nVorfalk travaille dans les réserves du Sinistre dévoreur, et son sacrifice envers les Gardiens sombres va très loin.\n\nPuisse son esprit rester fort." } }, { ids = { "o164821" }, first = "bethekstormbrowbethekswa", pages = { "Bethek Stormbrow\n\nLes errances de Bethek l'ont emmené profondément dans Blackrock. Les secrets de la montagne l'ont attiré.\n\nQue jamais son esprit ne faillisse." } }, { ids = { "o164822" }, first = "uggelhammerhanduggelisas", pages = { "Uggel Hammerhand\n\nUggel est un sculpteur habile, et lorsqu'il ne porte pas le fardeau de la Clé noire, ses mains savent façonner de merveilleux objets au Hall des artisans." } }, { ids = { "o164823" }, first = "zimreldarktoothwhenthema", pages = { "Zimrel Darktooth\n\nLorsque la folie de la Clé noire s'empare de Zimrel, seuls les hurlements des mourants peuvent l'adoucir.\n\nEn récompense de son sacrifice, il aura toujours droit à une place dans les bancs de l'arène. Que nos sports sanglants sachent apaiser la rage de son coeur." } }, { ids = { "o164824" }, first = "ofgutstonefistthosefalle", pages = { "Ofgut Stonefist\n\nCeux qui sont tombés sous le marteau du garde noir Ofgut ne se comptent plus.\n\nLes soldats de la Garnison de l'ouest sont saisis de terreur lorsqu'il passe. Car qui, parmi eux, peut lire dans les yeux d'Ofgut et supporter les secrets de la Clé noire qui s'y trouvent ?" } }, { ids = { "o164825" }, first = "pelverdeepstompdarkkeepe", pages = { "Pelver Deepstomp\n\nLe Gardien noir Pelver est notre disciple le plus honoré. Il a porté la clé plus longtemps que quiconque, et cela lui a coûté cher. Lorsqu'il est appelé, il est gardé au Domicile.\n\nSon sacrifice est célébré et il restera longtemps dans nos coeurs. Il y restera longtemps après que les ténèbres se seront emparé de lui." } } },
    ["Deathstalker Report"] = { { ids = { "i3252" }, first = "deathstalkermissionrepor", pages = { "Rapport de mission des Traqueurs noirs\n\nAgents : Rane Yorick, Quinn Yorick, Erland McKree\n\nMission principale : faire une reconnaissance dans la région nord de la forêt des Pins argentés et déterminer le degré de menace représenté par la faune et par le Fléau.", "Les agents ont commencé leur exploration et ont découvert une présence significative de worgs. Il est recommandé que des équipes de chasse soient envoyées pour éliminer le problème.\n\nDes gnolls morts-vivants ont été trouvés dans la ferme de la région nommée le Champ des morts. La raison de leur présence en ces lieux est inconnue, mais leurs déplacements et leurs actes suggèrent une action militaire imminente. Au cours de nos observations, aucun chef n'a été repéré parmi les gnolls. On suppose qu'ils attendent l'arrivée d'un commandant ou de renforts.", "Durant leur progression, nos agents ont été retenus à la ferme d'Ivar. Ivar, la plupart de sa famille et ses travailleurs ont succombé au Fléau et sont devenus ses serviteurs.\n\nNos agents ont été attaqués et bien qu'ils aient réussi à vaincre leurs assaillants, certains d'entre eux ont été sérieusement blessés, notamment l'agent Quinn.", "Une position défensive a été adoptée dans la vieille maison d'Ivar, et tandis que Rane montait la garde, Erland a continué la reconnaissance.\n\nErland a alors été cloué dans un verger du Nord par des worgs et n'a réussi à s'échapper qu'avec l'aide d'un autre agent des Réprouvés. Cet agent est la personne qui apporte ce rapport.", "Il faut noter que le messager a été essentiel au succès de notre mission, mais a également battu Ivar l'Infect, secouru Erland et accepté de porter ce rapport.\n\nNous lui sommes très reconnaissants et nous recommandons au commandement de récompenser cette glorieuse conduite à hauteur de ce qu'elle mérite.\n\n-Traqueur noir Rane Yorick,\nChef de mission" } } },
    ["Decoded Tablet Transcription"] = { { ids = { "i20405" }, first = "dayourpilgrimageisoverwe", pages = { "Jour 1\nNotre  pèlerinage est terminé. Nous avons finalement rejoint Silithus, où nous devrons effectuer la prise de contact.  Nous sommes venus de bien des endroits différents pour mettre nos efforts en commun, et mener à bien cette entreprise monumentale.\n\nUne extraordinaire atmosphère de fébrilité règne parmi nous.  Demain, nous consacrerons toute notre énergie à la construction de ce qui nous permettra de communiquer avec EUX.\n\nDemain nous érigerons une pierre des vents !", "Jour 2\nL'emplacement de la Pierre des vents a été le sujet d'un grand débat. Même les plus sages d'entre nous sont incapables de déterminer avec une grande certitude l'endroit exact auquel se réfère la vieille prophétie.\n\nJe suis resté avec le groupe nord d'origine, et le temps prouvera indubitablement que nous avons raison. Soutenir que les lignes d'énergie se croisent à cet endroit selon des angles défavorables est idiot et naïf.\n\nNous avons déjà rassemblé tous les matériaux de construction qui nous sont nécessaires.", "Jour 15\nNotre dévouement a fini par porter ses fruits. Nous sommes le premier camp à avoir terminé la construction d'une pierre des vents. Si les autres imbéciles étaient restés avec nous, nous aurions achevé notre tâche en moins d'une semaine !\n\nDemain, nous commencerons les rituels qui invoqueront le baron Kazum en personne. Il a demandé d'être le premier à tester le système, et nous n'avons pas pu le contredire, car il s'emporte facilement.\n\nJe pense qu'il sera très content de nous." } } },
    ["Decoded Twilight Text"] = { { ids = { "i20541" }, first = "forimmediatedisseminationtoalltwilightshammermembersthes", pages = { "À diffuser immédiatement auprès de tous les membres du Marteau du crépuscule.\n\nLa traque du traître Ortell progresse à une allure plus que satisfaisante.  Nos éclaireurs ont pu réduire le champ des recherches à un réseau de cavernes dans la marche de l'Ouest.\n\nLa trahison d'Ortell ne sera pas pardonnée. Sa fuite représente un risque majeur pour la sécurité de notre organisation.\n\nTout individu qui se rendrait coupable de dissimulation d'informations concernant le lieu où se trouve Ortell subira un châtiment exemplaire.\n\n-Seigneur du crépuscule Everun" } }, { ids = { "i20545" }, first = "forimmediatedisseminationtoalltwilighth", pages = { "À diffuser immédiatement auprès de tous les membres du Marteau du crépuscule.\n\nEn raison de la situation actuelle à Silithus, toute diffusion des textes du Vrai croyant devra être effectuée sous l'escorte de pas moins de quatre gardes armés du Marteau du crépuscule.\n\nTout membre qui contreviendrait à cette nouvelle directive sera puni sans délai.\n\n-Seigneur du crépuscule D'Sak" } }, { ids = { "i20552" }, first = "forimmediatedisseminationtoalltwilightshammermembersthef", pages = { "À diffuser immédiatement auprès de tous les membres du Marteau du crépuscule.\n\nLes informations suivantes décrivent l'utilisation des pierres des vents pour communiquer avec nos maîtres du Conseil abyssal.\n\nToute utilisation frivole des pierres des vents sera punie dans la douleur.\n\n-Gardien du crépuscule Havunth", "Les Templiers des abysses\n\nEn tant qu'initié, vous êtes autorisé à établir contact avec des Templiers des abysses pour des rituels de routine.  Souvenez-vous de toujours porter les vêtements appropriés lorsque vous utilisez les pierres des vents afin d'éviter d'activer nos enchantements défensifs.\n\nEn cas d'urgence, si aucun surveillant n'est présent, vous avez la permission d'invoquer un Templier des abysses.\n\nPour davantage de détails au sujet des rituels d'invocation concernés, consultez le Vrai Croyant du mois dernier.", "Les ducs des abysses\n\nSeuls les acolytes en possession d'un médaillon de statut sont autorisés à établir contact avec des ducs des abysses.  Un médaillon de statut doit être utilisé uniquement par la personne pour laquelle il a été issu à l'origine.\n\nLes membres du Marteau du crépuscule qui se rendraient coupables d'une communication inappropriée avec les ducs des abysses ou d'un usage non autorisé d'un médaillon de statut seront châtiés par moi en personne.", "Le Haut conseil des seigneurs des abysses\n\nSeuls les seigneurs des abysses sont autorisés à entrer en contact avec le prince Skaldrenox, le haut maréchal Trombe, le baron Kazum ou le seigneur Skwol.\n\nLes membres de faible rang du Marteau du crépuscule ne sont autorisés à initier toute forme de communication avec le Haut conseil en aucune circonstance.  Tous ceux qui ne lui appartiennent pas qui utiliseraient une pierre des vents de cette manière seront réduits en cendres sur le champ." } }, { ids = { "i20676" }, first = "thestateofthecultvolumei", pages = { "État du Culte, Volume 92\n\nC'est le cœur réjoui que je vous accueille, mes frères, car notre culte ne pourrait mieux se porter.  Nous sommes légion et nos objectifs n'ont jamais été plus prêts de leur aboutissement.\n\nDe nouvelles recrues continuent d'affluer.  Elles chantent les louanges de nos seigneurs à Sombrivage, elles s'inclinent dans l'allégresse dans la gorge des Vents brûlants, elles embrassent le serviteur de nos maîtres, Aku'mai, dans les Profondeurs de Brassenoire.  Je vous le dis, mes frères et sœurs, bientôt un essaim de fidèles recouvrira tout Azeroth !" } }, { ids = { "i20677" }, first = "stateofthecultvolumeitis", pages = { "État du Culte, Volume 127\n\nEn vérité, aujourd'hui est un jour heureux !  Nous avons été mis à l'épreuve à Silithus et nous avons réussi !\n\nLes nouvelles de la destruction de notre camp le plus au nord pourront troubler les cœurs de ceux qui manquent de foi, mais ce massacre ne doit pas être considéré comme une tragédie.  Non !", "Que notre sang soit versé par l'un des membres du Haut conseil abyssal est une bénédiction !  Nous devrions envier ceux de nos camarades qui sont tombés, car leurs esrpits demeurent à présent dans le ventre d'une bête des plus vertueuses !\n\nGloire aux Dieux très anciens !  Gloire à leurs serviteurs !  Gloire au Marteau du crépuscule !" } }, { ids = { "i20678" }, first = "stateofthecultvolumeoppo", pages = { "État du Culte, Volume 233\n\nUne nouvelle occasion pour nous, mes frères et sœurs!  Le Cercle cénarien, une vile secte d'adorateurs de la nature, envoie à présent ses agents contre nous.  Ils veulent probablement nous empêcher d'invoquer des pierres d'attraction rouges.  Nous ne le permettrons pas !\n\nLes pierres rouges sont d'une importance vitale pour nos nouveaux alliés.  Nous ne devons pas laisser les valets du Cercle cénarien parvenir à leurs fins.  Soyez fermes, mes fidèles amis.  Soyez fermes !" } }, { ids = { "i20679" }, first = "howdoweknowtheyloveussom", pages = { "Comment savons-nous qu'ils nous aiment ?\n\nCertains se demandent peut-être comment les Dieux très anciens et leurs serviteurs pourraient nous aimer.  Est-ce qu'ils ne nous tuent pas ?  Est-ce qu'ils ne nous causent pas à tous douleur et souffrances ?  Comment des êtres ayant un penchant si prononcé pour le mal pourraient-ils connaître l'amour dans leurs cœurs?\n\nLa réponse à cette question est très simple.  Si simple qu'il n'est pas nécessaire de la prononcer.", "La foi.  La foi est la source grâce à laquelle la joie de servir nous inonde.  La foi nous tiendra chaud lors des nuits les plus froides de Silithus.  La foi nous donnera la miséricorde de nos seigneurs quand la Fin des jours arrivera.\n\nLa foi nous sauvera." } } },
    ["Decorated Headstone"] = { { ids = { "o175933" }, first = "inlovingmemoryofjessemor", pages = { "En mémoire de notre cher Jesse Morales" } } },
    ["Decrypted Letter"] = { { ids = { "i3518" }, first = "greetingsmasterforgiveme", pages = { "Salutations, maître,\n\npardonnez-moi cette manière de vous envoyer un message. Mes mages de l'ombre d'Alterac sont plongés dans leur travail, ce qui me contraint à utiliser un messager étranger, choisi parmi nos nouveaux \"alliés\", pour vous apporter ce rapport. Mais j'ai codé cette lettre avec l'un de mes chiffres les plus ésotériques. Ces rustres n'y comprendront rien.", "Notre plan progresse bien. Comme je l'ai mentionné, nous avons fait alliance avec un groupe d'humains qui se fait appeler le Syndicat. Ses chefs sont les anciens nobles d'Alterac et ils rêvent de retrouver leur position.\n\nIls ont donc fait un marché avec nous. Ils le regretteront.", "Aujourd'hui, le Syndicat n'a guère de pouvoir sur ces terres, mais ils connaissent bien la région et ont assez d'hommes pour les tâches à venir. Avec une aide appropriée, je pense que le Syndicat régnera de nouveau sur Alterac.\n\nDe plus, nous avons poussé le Syndicat à se diriger vers la cité de Stromgarde dans les hautes-terres d'Arathi. La ville est un champ de bataille entre nos forces, les ogres et les humains de Stromgarde, mais nous pensons qu'avec une tactique habile nous posséderons cette grande cité.", "Quand cela sera fait, nous passerons à l'étape suivante de notre plan. Avec notre propre nation et une base puissante dans la région, nous préparerons la route pour le Troisième Ost.\n\nBientôt, les seigneurs de la Légion récompenseront notre travail en faisant pleuvoir le feu une fois de plus !", "Le Conseil a été sage de vous nommer à la tête de la Veille d'Argus, surveillant de leurs stratégies dans la terre des humains et des nains. Et je suis honoré d'exécuter vos volontés dans Alterac.\n\nAu nom de Sargeras,\n\nNagaz,\nHiérophante d'Argus" } } },
    ["Deepfury's Orders"] = { { ids = { "i4429" }, first = "bumblingfoolsmyplanscall", pages = { "Pauvres idiots !\n\nMon plan nécessitait que les deux ponts soient détruits simultanément. Et qu'avez-vous fait, avec vos cervelles spongieuses ? Vous n'avez fait que la moitié du travail et vous avez alerté toute l'Alliance de nos intentions. Mais quels idiots !\n\nIl vous reste une chance de vous racheter. Nous avons une cache d'explosifs dans les hautes-terres d'Arathi, non loin du pont.\n\nFinissez le travail si vous tenez à vos pitoyables existences !\n\n--Kam Deepfury" } } },
    ["Defias Docket"] = { { ids = { "i5947" }, first = "ourfirstplanhasalreadyfa", pages = { "Notre premier plan a déjà échoué !\n\nFist a réussi à modifier le tableau de service des hommes en faction dans le tunnel ce soir, mais à cause des efforts imprévus de certains citoyens de Stormwind, notre cible a pu s'enfuir avant que nous ne puissions l'attraper. Mais nous avions envisagé cette éventualité. Le plan 2 a été lancé et était déjà en bonne voie avant que nous tendions notre embuscade dans Stormwind.", "Le plan 2 est tout aussi simple, mais il requiert plus de patience de notre part. Notre homme dans Menethil a déjà été récompensé pour ses efforts et il a réussi avec brio. Nous ne devrions pas rencontrer de problèmes pour prendre notre cible une fois que nous serons en mer.", "Attendez-vous à ce que l'attaque ait lieu quelques miles avant leur destination. C'est là que nos alliés nous attendent. Je ne suis pas certain de ce qui nous a poussé à former une alliance avec ces créatures, mais je ne peux pas m'empêcher de penser que cela nous ligote. En définitive, ça n'a pas d'importance. Une fois la cible emprisonnée, nous serons en bonne voie pour reprendre Stormwind à ceux qui nous l'ont prise !" } } },
    ["Defias Script"] = { { ids = { "i6846" }, first = "theplanissetinmotiontake", pages = { "Notre plan est en train de se réaliser.\n\nPrenez cet ancien bastion de la foi, la Veillée des héros, pour en faire notre base, et nous commencerons à vous envoyer des renforts de la marche de l'Ouest, une fois que vous nous aurez fait savoir que le site a été préparé.\n\nCet endroit est quasiment oublié des citoyens et soldats de Stormwind et fera un avant-poste parfait pour lancer nos attaques.\n\nLes Defias reprendront Stormwind !\n\nJ'attends votre réponse." } } },
    ["Diary of Weavil"] = { { ids = { "i21130" }, first = "deardiarytodaymyarchenem", pages = { "Cher journal,\n\nAujourd'hui, mon ennemi juré, Narain Soothfancy, a tenté de déjouer mes plans en m'envoyant quelques sbires prendre sa place lors de l'exécution. De SON exécution. Tu imagines ?\n\nJe me suis donné un mal fou pour mettre au point un plan génial afin de l'attirer dans cette fichue hutte, et il me fait un coup pareil ? La barbe… je suis trop énervé pour écrire. À plus tard.", "Cher journal,\n\nQuand j'ai quitté ma cachette après avoir rédigé ma dernière note, j'étais dans une rage folle. Vraiment, vraiment furieux ! J'ai décidé de redessiner l'uniforme de mes sbires pour qu'il reflète mes souffrances intérieures. Je me sens un peu mieux, mais il me manque encore quelque chose. Je reviens…", "Cher journal,\n\nVoilà, je me sens beaucoup mieux. J'ai battu l'un de mes sbires jusqu'à ce qu'il pleure comme une petite fille.\n\nEuh… non, en fait, je me sens un peu mal à l'aise. Ah mais minute, je suis un génie du MAL ! Du mal, tu vois ? Je me déçois beaucoup. À plus.", "Cher journal,\n\\Je l'ai serré dans mes bras et je lui ai dit qu'il s'en sortait bien et qu'il devait continuer comme ça. Je me sens mieux. Mais ça reste entre nous, d'accord ?\n\nOù en étais-je ? Ah oui, NARAIN ! ARRGH !!! Je le hais. Quand nous étudiions au Bricolo-institut de Gnomeregan, ses résultats étaient si bons qu'il fallait redéfinir toutes les moyennes en fonction de lui.\n\nEt du coup, ils m'ont chassé de l'école parce que j'étais en dessous des nouvelles normes. En ce qui me concerne, Gnomeregan a eu ce qu'elle méritait !\n\nBon, ça suffit pour aujourd'hui. Bonne nuit, mon cher journal !", "Cher journal,\n\nJe dois veillir. J'ai complètement oublié ce que je te racontais à propos de Narain et de la manière dont il a triché. J'ai si furieux de voir un leurre déguisé en Narain que j'ai demandé à Numéro Deux de massacrer cet imbécile !\n\nAprès, j'ai couru jusqu'à ma machine volante et j'ai commencé à déchirer son livre bien-aimé, stupide et idiot sur le draconique. Quel prétentieux ! Qui le lit le draconique ? Je le hais tant !", "Cher journal,\n\nDésolé, je me suis endormi. J'étais fou de rage et je jetais les chapitres de ce livre stupide un peu partout. Quand j'ai vu un démon en dessous de moi, dans la gorge du Sombre murmure, j'ai décidé de faire une tornade magique avec le premier chapitre. Elle l'a déchiqueté en un million de petits morceaux ! Ça m'a soulagé. Magie + papier = rigolo.\n\nJ'étais tellement content que j'ai decidé de faire un tour dans les Royaumes de l'est. Mon premier arrêt a été pour le Cœur du Magma. Narain en parlait souvent… « Le Cœur du Magma ceci, Ragnaros cela… »", "Tu sais quoi ? S'il aime tant son fichu livre, il pourra toujours le reconstituer en allant au Cœur du Magma et en récupérant un chapitre dans un tas de cendres ! Ah !\n\nEt tant que j'étais dans le coin, je me suis dit que certains des techniciens baveux du labo de ce bon vieux Victor Nefarius auraient peut-être l'usage d'un peu de draconique. Et hop, sitôt dit, sitôt largué !", "C'était en train de devenir un passe-temps à part entière. Je prenais beaucoup de plaisir à découper ce fichu livre en morceaux !\n\nLes largages suivants ont été simples.\n\nUndercity, demeure des morts-vivants fétides et pestilentiels (mais aussi du meilleur chili du monde) en a eu un. Stormwind, capitale du fromage, un autre. Dis, cher journal, as-tu déjà pensé à mettre du fromage de Stormwind sur du chili d'Undercity ? HÉ HO ? Ce serait intéressant…", "J'étais fatigué, alors j'ai fait virer la machine volante, direction la maison, mais avant, j'ai fait deux autres arrêts. J'ai survolé le seigneur Kazzak et ses démons, à la Balafre impure (il a horreur de ça), et j'en ai glissé un autre dans le cheminée d'Onyxia.\n\nFatigué. Dodo." } } },
    ["Divined Scroll"] = { { ids = { "i5455" }, first = "anevilforcecreatedtheseh", pages = { "Une force maléfique a créé ceci,\nEn haut du Pic de Brume-funeste il est assis,\nIl rit de toi, de tes amis,\nSes élémentaires toujours en vie,\n\nBientôt tu affronteras sa magie,\nCar seule la mort mettra fin à sa furie." } } },
    ["Dorgar Stoenbrow"] = { { ids = { "o175773" }, first = "dorgarstoenbrowwarriorof", pages = { "Dorgar Stoenbrow\n\nGuerrier de la Croisade écarlate\n\nSeigneur des Cavernes rouges\n\nVu pour la dernière fois dans les montagnes d'Alterac" } } },
    ["Ebonlocke's Response to Solomon"] = { { ids = { "i1410" }, first = "yourhonoriregrettoinform", pages = { "Votre Honneur--\n\nJe regrette de devoir vous informer que les Veilleurs sont incapables de quitter leur poste de Darkshire en ce moment. Vous ignorez peut-être que Stormwind ne fournit plus de soutien militaire dans cette région. Les Veilleurs ont été formés et entraînés par le peuple de la forêt dans le but de défendre Darkshire en l'absence de Stormwind. Sans les Veilleurs, la ville tomberait. Je vous souhaite bonne chance.\n\n--Seigneur Ello Ebonlocke" } } },
    ["Eliza's Tombstone"] = { { ids = { "o37" }, first = "elizabelovedwifemaytheea", pages = { "Eliza\n\nChère épouse, puisse la terre apaiser votre faim." } } },
    ["Empires' Fall"] = { { ids = { "o175855" }, first = "asidefromtheirshadowyori", pages = { "Bien que leurs origines restent obscures, il est clair que les elfes de la nuit apparurent peu après la découverte du Puits d'éternité. En dépit des tentatives des trolls pour les empêcher d'étendre leurs territoires, les elfes de la nuit bâtirent un puissant empire qui s'étendit rapidement en Kalimdor. Maîtrisant des magies puissantes dont les trolls superstitieux n'avaient jamais rêvé jusque-là, les elfes de la nuit n'eurent pas de mal à accomplir ce que les Aqir n'avaient pu faire : renverser les deux plus puissants empires du monde.", "Les elfes de la nuit brisèrent systématiquement les défenses et les chaînes de ravitaillement des trolls. Ces derniers, incapables de contrer la magie destructrice des elfes, finirent par s'effondrer. Les elfes de la nuit se montrèrent aussi rusés et assoiffés de sang que les trolls, s'attirant le mépris et la haine éternels de ceux-ci. Les empires Gurubashi et Amani se disloquèrent en quelques années.", "Finalement, les elfes de la nuit furent brûlés par les feux d'arcanes qu'ils cherchaient à contrôler. Leur utilisation sans mesure de la magie attira dans le monde la Légion ardente. Les démons écrasèrent la plus grosse partie de la civilisation des elfes. Bien qu'aucun document n'indique que la Légion ait attaqué les civilisations des trolls, il est vraisemblable que les combats aient ravagé tout le continent.", "A la fin de ce terrible conflit, connu sous le nom de Guerre des Anciens, le Puits d'éternité explosa. L'onde de choc ébranla la terre de Kalimdor. Le centre du continent s'enfonça dans la mer, laissant de petits archipels de continents isolés.", "Des restes non négligeables des empires Amani et Gurubashi existent toujours aujourd'hui dans les terres de Quel'Thalas et de Strangleronce. Les royaumes Azj'Aqir d'Azjol-Nerub et d'Ahn'Qiraj ont également survécu dans Northrend et Tanaris.\n\nLes deux civilisations des trolls ont reculé devant les grandes destructions qui ont marqué le monde où elles étaient nées. Les trolls ont rebâti leurs cités ravagées et se sont efforcés de retrouver une partie de leur ancienne puissance." } } },
    ["Encrypted Letter"] = { { ids = { "i9555" }, first = "neverbeenmoreproudtobepa", pages = { "Je n'ai jamais été aussi fier de travailler dans ce commerce que lors de ces dernières années. Le besoin en assassins, espions et éclaireurs n'a jamais été aussi important. Vous pourriez penser que les périodes de guerre entraînent une forte demande, mais curieusement, elles ne sont pas aussi rentables que des temps comme les nôtres, quand la paix commence à se détériorer.\n\nJ'ai entendu dire que vous cherchiez à apprendre quelques trucs. Quand vous aurez le temps, venez me voir près des écuries derrière l'abbaye.\n\n-Jorik Kerridan, maître des voleurs" } } },
    ["Encrypted Memorandum"] = { { ids = { "i9558" }, first = "youwereexpectingthistobe", pages = { "Vous vous attendiez à une note normale de votre roi ou je ne sais qui, pas vrai ? Disons que je sais deux ou trois choses sur l'art des faussaires et je voulais m'assurer que vous alliez recevoir ce message. Je ne peux pas me permettre d'attirer l'attention sur moi !\n\nJe me suis introduit dans Anvilmar, vous me trouverez près de la fosse à feu. Quand vous le pourrez, venez me voir. Je veux juste vous rencontrer pendant que nous le pouvons encore.\n\n-Solm Hargrin, Maître des voleurs" } } },
    ["Encrypted Parchment"] = { { ids = { "i9560" }, first = "isendgreetingsiwaslostin", pages = { "Je vous transmets mes salutations, $N. J'étais perdu dans mes pensées, quand il m'est venu à l'esprit que j'avais besoin de vous écrire.\n\nBeaucoup d'entre nous, dans notre culture, louent nos chamans car ils sont nos chefs spirituels, comme notre grand Chef de guerre. D'autres pensent que l'épée et la hache sont des activités plus nobles, mais n'oubliez jamais que les batailles, et même les guerres, sont gagnées à l'aide de compétences plus spécialisées. C'est de cela dont je souhaite vous entretenir, $N. Retrouvez-moi au fond de l'Antre dans la Vallée des épreuves.\n\n-Rwag, Maître des voleurs" } } },
    ["Encrypted Rune"] = { { ids = { "i9550" }, first = "brothersisterihopethisru", pages = { "$gFrère:Soeur;, j'espère que cette rune vous trouvera en bonne forme. Je voulais prendre un moment pour vous faire savoir que je suis à Anvilmar, au-dessus de la vallée des Frigères.\n\nJe sais qu'il est vital que nous restions soudés et en ces temps de troubles, il est plus important que jamais que nous soyons rassemblés. Venez me voir quand vous aurez le temps.\n\n-Solm Hargrin, Maître des voleurs" } } },
    ["Encrypted Scroll"] = { { ids = { "i9559" }, first = "takecarenottoignoremywor", pages = { "Prenez garde à ne pas ignorer mes paroles, $N. Voici venue l'heure des subterfuges et des mensonges parmi toutes les nations... même dans notre chère Undercity. Tous ceux qui sont loyaux à Sylvanas travaillent pour construire une nouvelle ère, une ère où les Réprouvés auront le pouvoir. Et même si nous ne possédons pas de compétences magiques, et que nous ne défendons pas nos frontières par les armes, nous avons tout de même un rôle à jouer.\n\nVenez me trouver dans l'auberge du Glas. Nous parlerons davantage.\n\n-David Trias, Maître des voleurs" } } },
    ["Encrypted Sigil"] = { { ids = { "i9551" }, first = "saelahmyfriendihopethiss", pages = { "Sael'ah, j'espère que ce message vous trouvera en pleine forme. On m'a demandé de vous offrir mes services. Je suis moi aussi à Sombrevallon, dans le Grand arbre d'Aldrassil, et je voulais vous faire savoir que si vous avez besoin d'une formation plus poussée, vous pouvez venir me voir.\n\nEn ces temps difficiles, je crois prudent que ceux qui ont l'ombre pour vocation restent proches les uns des autres. Comment, sans cela, pourrions-nous protéger Teldrassil et notre manière de vivre ?\n\nVous me trouverez quand vous en aurez besoin.\n\n-Frahun Shadewhisper, Maître des voleurs" } } },
    ["Encrypted Tablet"] = { { ids = { "i9554" }, first = "greetingsbrothersisterth", pages = { "Salut, $gmon frère:ma soeur;. La Main brisée vous fait part de son respect et espère que vous trouvez la Vallée assez confortable pour y déployer votre commerce. C'est une période d'essai pour vous, pensez bien que vous serez sous surveillance permanente.\n\nIl est de mon devoir d'estimer vos compétences, puis d'informer la Main lorsque l'heure sera venue pour vous d'affronter des défis plus importants.\n\nLorsque vous vous en sentirez capable, venez me trouver au fin fond de l'Antre. Je vous attendrai là-bas.\n\n-Rwag, Maître des voleurs" } } },
    ["Etched Note"] = { { ids = { "o174746" }, first = "thisanvilisthepropertyof", pages = { "Cette enclume est la propriété de Jordan Stilwell. NE PAS utiliser !\n\n- Jordan" } }, { ids = { "i9565" }, first = "mightywarriorsdefendourh", pages = { "De puissants guerriers défendent notre foyer. Nos chamans guident nos esprits et nous montrent le passé de nos ancêtres. Nos druides nous aident à comprendre la volonté de la Terre-mère.\n\nMais vous êtes un de nos chasseurs, et nos chasseurs apprennent de nombreux aspects de nos traditions et les mélangent. Vous comprendrez que vous représentez le coeur de notre peuple, une partie des nôtres vous demandera de les guider, de les protéger. Mon devoir est de m'assurer que vous pourrez assumer ce rôle. Vous me trouverez au Camp Narache.\n\n-Lanka Farshot, Maître des chasseurs" } } },
    ["Etched Parchment"] = { { ids = { "i9553" }, first = "yabeingoodhandsnowmonjen", pages = { "Vous êtes entre de bonnes mains à présent. Jen'shan sait que vous voulez apprendre les voies du chasseur, et elle est prête à vous y aider... Si vous voulez l'entendre.\n\nVenez me voir dans la Vallée des épreuves. Jen'shan commencera votre formation et vous montrera les arcanes du métier de chasseur.\n\n-Jen'shan, Maître des chasseurs" } } },
    ["Etched Rune"] = { { ids = { "i9566" }, first = "tamerofbeastsmastermarsk", pages = { "Dompteur des bêtes, maître du tir, pisteur confirmé : que peut-on accomplir de plus en une seule vie ? Toutes ces choses, une fois combinées, demandent de l'intelligence et de la patience.\n\nLa voie du chasseur n'est pas facile, c'est certain. Vous aurez besoin de beaucoup d'entraînement si vous voulez vous aligner avec le plus mauvais de nos tireurs d'élite. Mais c'est pour cela que je suis ici.\n\nVous me trouverez dans Anvilmar, au-dessus de la vallée des Frigères. J'attendrai.\n\n-Thorgas Grimson, Maître des chasseurs" } } },
    ["Etched Sigil"] = { { ids = { "i9567" }, first = "eluneiswithyouthewindwhi", pages = { "Elune soit avec vous, $N. Les vents me murmurent bien des choses, et j'ai plaisir à pouvoir former la prochaine génération de chasseurs.\n\nD'après ce que j'ai entendu, vous êtes proche d'Aldrassil. Je vous rencontrerai dans le Grand arbre quand vous en aurez le temps.\n\nNos aînés m'ont demandé de m'assurer que les nouveaux chasseurs soient formés de façon appropriée, car les temps sont durs. Vous êtes encore novice, vous devriez venir me voir. Jusque là, portez-vous bien.\n\n-Ayanna Everstride, Maître des chasseurs" } } },
    ["Etched Tablet"] = { { ids = { "i9564" }, first = "itbegoodtohearthatoneofj", pages = { "Je vois avec plaisir un proche de Jen'shan venir dans la Vallée pour y améliorer ses aptitudes. Jen'shan a hâte d'y participer !\n\nJe n'ai pas besoin de vous rappeler ce qu'il faut de ruse et de force à un chasseur, vous le savez déjà. La tâche de Jen'shan sera d'augmenter cette ruse, cette force.\n\nVous trouverez Jen'shan dans la Vallée des épreuves. Elle vous guidera bien. Elle vous apprendra à dompter les plus grandes bêtes, entre autres choses.\n\n-Jen'shan, Maître des chasseurs" } } },
    ["Exile of the High Elves"] = { { ids = { "o175731" }, first = "asthecenturiespassedthen", pages = { "Au fur et à mesure que les siècles s'écoulaient, la nouvelle société des elfes de la nuit devint forte et s'étendit à travers les forêts désormais connues sous le nom d'Ashenvale. Bien des créatures et des espèces qui abondaient avant la Grande Fracture, comme les furbolgs et les hurans, réapparurent et se multiplièrent. Sous la conduite bienveillante des druides, les elfes de la nuit connurent une période sans précédent de paix et de tranquillité.", "Cependant, de nombreux survivants parmi les anciens Bien-nés ne trouvaient pas le repos. Comme Illidan auparavant, ils souffraient du manque occasionné par la perte de leur magie. Ils furent tentés, une fois encore, d'utiliser les énergies du Puits d'éternité et de renouer avec leurs pratiques magiques. Dath'Remar, le chef impudent et brusque des Bien-nés, commença à moquer publiquement les druides. Il les traitait de lâches parce qu'ils refusaient d'utiliser la magie qui leur appartenait de droit.", "Malfurion et les druides repoussèrent les arguments de Dath'Remar et prévinrent les Bien-nés que tout usage de la magie serait puni de mort. Dans leur insolence, Dath'Remar et ses compagnons lâchèrent une terrible tempête magique sur Ashenvale dans une tentative désespérée pour convaincre les druides d'abroger la loi.", "Les druides, incapables de se résoudre à tuer tant des leurs, décidèrent d'ostraciser les Bien-nés. Dath'Remar et ses compagnons, contents d'être enfin débarrassés de leurs cousins conservateurs, embarquèrent dans des navires spécialement conçus et prirent les mers. Personne ne savait ce qui les attendait de l'autre côté du furieux Maelström, mais ils avaient hâte d'établir leur propre foyer où ils pourraient pratiquer impunément leur chère magie.", "Les Bien-nés, ou 'Quel'dorei' selon l'appellation ancienne d'Azshara, finirent par aborder sur une terre à l'est que les hommes appelleraient un jour Lordaeron. Ils décidèrent de construire leur propre royaume magique, Quel'Thalas, et rejetèrent l'adoration de la lune et la vie nocturne qui avaient jusque là soudé les elfes. On ne les connut plus désormais que sous le nom de hauts-elfes." } } },
    ["Extended Annals of Darrowshire"] = { { ids = { "i13202" }, first = "theannalsofdarrowshireda", pages = { "Les Annales de Darrowshire\n\nDarrowshire, dont le nom vient du lac Darrowmere situé à l'ouest, est un village coincé dans les contreforts sud de Lordaeron. Connu pour ses habitants humbles et travailleurs, Darrowshire est resté au second plan de l'histoire de Lordaeron jusqu'à la Deuxième Guerre.\n\nDes héros émergèrent durant cette guerre. Et des héros périrent.", "La bataille de Darrowshire\n\nLa bataille de Darrowshire se déroula au milieu de la Deuxième Guerre, quand les forces du Fléau se déchaînèrent contre Lordaeron. Darrowshire fut coupé du gros des forces de l'Alliance, mais la ville fut défendue par une compagnie de troupes, un contingent de paladins de la Main d'argent, et un groupe fidèle d'une milice locale menée par le capitaine Joseph Redpath.", "Les assauts du Fléau sur Darrowshire furent d'abord peu importants. De petits groupes de squelettes et de cadavres en maraude erraient autour du village avant d'être repoussés.\n\nMais le Fléau sentit probablement la ténacité des défenseurs et réagit en conséquence : une seconde vague d'attaques suivit peu après. Des champions parmi les goules, serviteurs du seigneur-goule Horgus, descendirent des collines en hurlant et assiégèrent les défenseurs de Darrowshire.", "Les Défenseurs ont commencé à faiblir, mais des paladins sont venus à leur secours, des disciples de la Main d'argent. Leur chef, Davil Crokford, est originaire de Darrowshire. Il est venu avec ses disciples quand il a entendu parler de l'attaque. Avec les Défenseurs, ils ont repoussé les serviteurs d'Horgus.\n\nQuand Horgus lui-même a pris part à la bataille, il a rencontré Davil. Pendant plusieurs minutes, ils se sont battus et finalement Davil a été victorieux. Malheureusement, après avoir battu le seigneur-goule, il a succombé à une blessure mortelle.", "La bataille s'est poursuivie et le capitaine Redpath a mené sa milice avec bravoure. Et elle aurait gagné si le capitaine n'avait pas été corrompu par le chevalier de la mort Marduk le Noir.\n\nAu milieu du combat, Marduk s'est dirigé vers Redpath, et avec de la magie noire il a arraché l'esprit de Redpath, le remplaçant par l'ombre maléfique du brave capitaine.", "Le capitaine Redpath, corrompu, fut à l'origine de la trahison des défenseurs de Darrowshire envers leurs alliés, ainsi que du massacre de ces derniers. Puis les défenseurs se tournèrent vers la ville de Darrowshire et tuèrent tous ceux qui se cachaient dans leur maison.\n\nLe reste de l'armée du Fléau, accompagné de l'esprit corrompu du capitaine Redpath, quitta ensuite le village ravagé de Darrowshire et se rua sur Lordaeron, accroissant ainsi les douleurs et les morts de la Deuxième Guerre.", "Le Destin d'Horgus le Ravageur\n\nHorgus le Ravageur tomba lors de la bataille de Darrowshire. Mais le mal qui vivait en lui ne disparut pas avec lui. Les forces du Fléau victorieuses prirent son crâne sur le champ de bataille de Darrowshire et le transportèrent avec elles pour répandre la terreur parmi les vivants qu'elles croisaient.\n\nQuelques jours plus tard, la compagnie du Fléau qui possédait la tête fut vaincue par les paladins de la Main d'argent. La tête d'Horgus fut immergée dans le lac de Noirbois.", "Le Destin de Marduk le Noir\n\nMarduk a survécu à la Deuxième Guerre. Lui et son épée sont responsables de nombreuses morts et de beaucoup de douleur. Bien que Marduk soit encore en vie, son épée a été perdue dans une bataille près de la Croisée de Corin. Un capitaine nain a fracassé l'épée sur son bouclier enchanté, poussant ainsi Marduk à fuir le champ de bataille, ce qui permit à l'Alliance de remporter la victoire.\n\nL'épée de Marduk s'est enfoncée dans la terre et l'a corrompue, formant une gorge désormais connue sous le nom de Balafre infecte.", "Le Destin de Davil Lightforge\n\nDavil Lightforge est mort à la Bataille de Darrowshire, mais sa bravoure a inspiré toute l'Alliance durant la guerre.\n\nSon livre, son libram de paladin, fut retrouvé par les troupes de la Croisade écarlate. Il se trouve désormais dans l'hôtel de ville de Hearthglen, contrôlée par la Croisade, et il est souvent lu par les croisés désireux de s'inspirer de la force de Davil.", "Le Destin de Joseph Redpath\n\nJoseph Redpath fut tué durant la bataille de Darrowshire. Son esprit fut corrompu et prit une nouvelle forme, et cette créature répandit un grand mal à Lordaeron.\n\nA la Flétrissure de Gahrron, à l'est d'Andorhal, Redpath fut finalement vaincu par les forces de l'Alliance. Son bouclier se trouve toujours près de la grange de la ferme maudite, et les sbires du Fléau sont toujours attirés par son souvenir.", "Le Destin de Carlin Redpath\n\nFrère du capitaine Joseph Redpath, Carlin est tombé durant la bataille de Darrowshire. Bien que grièvement blessé, il ne mourut pas.\n\nQuelques jours après la bataille, les agents de l'Aube d'argent ont trouvé Carlin en train d'errer, assoiffé et fiévreux, près de la Croisée de Corin. Ils l'ont soigné et l'ont transporté à la Chapelle de l'Espoir de Lumière.\n\nPour les remercier de leur charité, Carlin a rejoint les rangs de l'Aube d'argent. Désormais, il cherche à se venger du Fléau." } } },
    ["Faded Photograph"] = { { ids = { "i11108" }, first = "", pages = { "" } } },
    ["Fel Tracker Owner's Manual"] = { { ids = { "i10832" }, first = "theconjuringofthebeastto", pages = { "L'invocation de la créature :\n\nPour invoquer un gangrechien traqueur, vous devez utiliser l'Orbe corrompu fourni.\n\nNotes :\n\nLe gangrechien traqueur invoqué n'apparaîtra que pour trente minutes dans ce monde.\n\nLe gangrechien traqueur invoqué ne fera que vous assister dans votre quête de formations d'Azsharite.\n\nLe gangrechien traqueur conjuré NE FERA PAS ce qui suit : faire des farces, attaquer n'importe quoi, aider quoi que ce soit, danser, détruire des êtres magiques.\n\nPage suivante s'il vous plaît...", "Contrôler la créature :\n\nLe gangrechien traqueur n'obéit qu'aux rugissements bestiaux. Afin d'amener votre gangrechien traqueur à suivre la piste des formations d'Azsharite, vous devez rugir avec vigueur ! (Ciblez le gangrechien traqueur et /rugir).\n\nLorsque le gangrechien traqueur localise une formation, il court sans prêter attention aux entités qui l'entourent. Vous n'aurez pas besoin de protéger le gangrechien traqueur mais il vaut mieux rester près de lui pour ne pas le perdre.", "Se défaire de la créature :\n\nAu bout de trente minutes, la bête retournera chez elle dans le Néant.\n\nNote :\n\nDans son excitation, la bête PEUT tomber d'une falaise ou d'une montagne. Ne pleurez pas la perte d'un gangrechien traqueur, invoquez-en un autre." } } },
    ["Fellari Swiftarrow"] = { { ids = { "o175774" }, first = "fellariswiftarrowrangerc", pages = { "Fellari Swiftarrow\nCapitaine des forestiers de la Croisade écarlate\nOriginaire de Quel'Thalas\nPortée disparue dans les forêts des Pins argentés" } } },
    ["Ferren Marcus"] = { { ids = { "o175775" }, first = "ferrenmarcushighabbotoft", pages = { "Ferren Marcus\n\nGrand abbé du monastère Écarlate\n\nOriginaire de Stratholme\n\nTué en défendant le monastère Écarlate lors du premier assaut de l'été" } } },
    ["Field Guide"] = { { ids = { "i213563" }, first = "arbortarantulaorderarane", pages = { "Tarentule arborescente\n\nOrdre : Araneae\nClimat : tropical\n\nConstruit son nid dans le bois mort et pourrissant. On la trouve souvent sur les zones d'exploitation forestière, car ces tarentules aiment s'installer dans les souches fraîchement coupées.", "Pique-chair\n\nOrdre : Scorpiones\nClimat : aride\n\nComme son nom l'indique, ce scorpion pique et dévore la chair sur les ossements d'autres animaux. C'est un charognard qui se nourrit de préférence sur de grandes carcasses.", "Charançon des foins\n\nOrdre : Coleoptera\nClimat : tempéré\n\nUne menace terrible sous sa petite carapace. Un seul de ces charançons peut dévorer une botte de foin entière en moins d'une heure. Les invasions sont rares, et le plus souvent signalées au nord des royaumes de l'Est." } } },
    ["Final Clue to Sander's Treasure"] = { { ids = { "i1362" }, first = "nowthatyefoundmeolwhiske", pages = { "Maintenant que vous avez trouvé la vieille cruche de whisky, vous êtes presque au trésor ! Tournez-vous vers l'ouest et descendez vers le rivage. Ne vous arrêtez pas au bord de l'eau, continuez ! Nagez vers l'ouest jusqu'à l'île où se trouve mon coffre au trésor !" } } },
    ["Fishing Tournament!"] = { { ids = { "i19978" }, first = "stranglethornfishingtour", pages = { "Concours de pêche à Strangleronce!\n\n Dimanche après-midi de 14 h à 16 h !\n\nBaladez-vous le long de la côte de Strangleronce et guettez les bancs de courbines qui apparaîtront le long de la côte ! Envoyez votre flotteur dans le banc, et vous prendrez des poissons inhabituels au lieu des variétés normales de Strangleronce. Le premier à pêcher quarante courbines et à se présenter au maître de pêche Bassbait, à Baie-du-Butin, recevra un prix !\n\nMême si vous n'êtes pas le premier à prendre quarante courbines, vous pouvez toujours vous présenter pour les revendre. Et puis, il existe aussi des poissons spéciaux, pour lesquels il y a des récompenses particulières !" } } },
    ["Fizzle Brassbolts' Letter"] = { { ids = { "i5827" }, first = "goodmartekiminajamandine", pages = { "Mon bon Martek,\n\nj'ai des soucis et j'ai besoin de votre aide.\n\nMon frère et moi-même sommes en train de construire un char de course et nous avons besoin de pistons solides. Je ne trouve rien qui soit assez résistant. Rien n'est à la hauteur des performances de notre nouveau char. Le moteur casse sans arrêt !\n\nVous êtes un expert de la forge du métal. Vous devez nous aider. Vous êtes le seul à pouvoir le faire.", "Voici les caractéristiques du piston :\n\nLongueur : 32 LM\nLargeur : 12 LM\nPoids : 23,5 GGM à 25,5 GGM\nConduction : 70 CO\nPuissance de découpage : 98 ou plus\nTaux de combobulation : \"super robuste\" ou plus\n\nAu cas où vous auriez oublié les mesures gnomes :\nLM = largeur des moustaches\nGGM = gramme grosso modo\nCO = courbure des orteils" } } },
    ["Fizzlefuse's Shopping List"] = { { ids = { "i239246" }, first = "dearfuturemedontforgetth", pages = { "Chère moi du futur, n'oublie pas le pain, cette fois.\n\n– 8 litres de lait glacé, – 20 morceaux de cheddars affinés (les rats n'arrêtent pas de le manger), – 1 gâteau au chocolat délicieux, – ou plutôt 2 gâteaux, – 4 gobelets de carburant de fusée gobelin, – 2 tubes en thorium, – 1 altérateur de vrai-argent, – <l'encre a bavé, la ligne est illisible>\n– 2 gyrochronatomes." } } },
    ["Folded Parchment"] = { { ids = { "i282420" }, first = "greetingssincetheelement", pages = { "Salutations, $N.\n\nDepuis la disparition des esprits élémentaires du vent, Zéphras se trouve au bord d'un précipice mortel. Les oiseaux, les bêtes et même les racines sous nos pieds nous appellent à l'aide.\n\nRetrouvez-moi au rez-de-chaussée du grand arbre de Thendal. Je vais vous conseiller et vous entraîner dans les arts druidiques.\n\n– Xyton Vent-argent, maître des druides" } } },
    ["Fool's Stout Report"] = { { ids = { "i5807" }, first = "mrfizzlebubthebeverageyo", pages = { "M. Fizzlebub,\n\nLe breuvage que vous avez confié à mon associé a eu beaucoup de succès. En plus d'être une boisson forte et qui trouble l'esprit, elle semble engendrer une certaine accoutumance. Je suis sûr que ceux qui y ont goûté en voudront plus.\n\nNous vous sommes redevables, Crank.\n\nEt je vous invite à venir aux Salines ou à envoyer quelqu'un de confiance pour profiter des nouvelles opportunités dont nous disposons là-bas.\n\n--Kravel" } } },
    ["For the Light!"] = { { ids = { "i20009" }, first = "hisnamebroughtlighttodar", pages = { "Son nom apporta la Lumière dans les ténèbres d'Azeroth.\n\nSa valeur renversa les murs de la souffrance.\n\nLa Main d'argent n'aurait pu accomplir plus grand bienfait\n\nque donner au monde le chevalier qui se sacrifia.", "La renommée n'était pas ce qu'il cherchait,\n\nni le pouvoir sur son peuple.\n\nIl choisit plutôt de lutter pour Lordaeron\n\ndans l'espoir que les siens n'auraient plus à se battre.", "L'histoire tragique de ce chevalier si saint\n\njamais ne se terminera par sa terrible mort.\n\nNous l'honorons, et lui rendons grâce !\n\nUther connaîtra toujours la gloire et la Lumière !" } } },
    ["Foreboding Plans"] = { { ids = { "i3718" }, first = "theywouldhavelifeeternal", pages = { "L. F. a ordonné que les attaques s'intensifient contre les imbéciles de l'Alliance. Ci-dessous, vous trouverez une liste des matériels nécessaires pour une importante mission contre Southshore :\n\nrations de voyage d'une semaine pour 20 hommes\n20 tenues de chevaliers noirs\n20 nouvelles paires de chaussures\n25 nouvelles épées\n30 couteaux de lancer\n20 masques noirs\n10 fioles d'huile inflammable\n50 doses de poison paralysant\n5 uniformes de gardes de Southshore volés, si possible\n100 pièces d'argent\n\n--Baron V.\nIntendant" } } },
    ["Forestlord and the first Druids"] = { { ids = { "o177205" }, first = "intimethechildcenariusgr", pages = { "En temps voulu, l'enfant, Cénarius, grandit jusqu'à atteindre la taille de son père. Frère des arbres et des étoiles, le grand chasseur parcourut tous les lieux du monde, chantant les mélopées harmonieuses de l'aube. Toutes les créatures s'inclinaient devant sa grâce et sa beauté. Nul n'était plus rusé que le fils de la lune et du cerf blanc.", "Enfin, Cénarius devint l'ami des Shu'halo et leur enseigna les mystères du monde. Les enfants de la terre le considéraient comme un frère et jurèrent de l'aider à maintenir les champs de la vie et à préserver les créatures de leur grande Terre-mère.", "Cénarius apprit aux enfants de la terre à parler aux plantes et aux arbres. Les Shu'halo devinrent des druides et, grâce à la magie, bercèrent la terre de leurs soins. Pendant des générations, les Shu'halo chassèrent avec Cénarius et gardèrent le monde à l'abri des ombres qui grouillaient sous sa surface." } } },
    ["Fossilized Egg"] = { { ids = { "o175680" }, first = "foundintheswelteringwast", pages = { "Cet oeuf que l'on trouve dans les terres écrasées de chaleur du désert de Tanaris reste un mystère pour les écologistes modernes. Les tests de datation suggèrent que l'oeuf pourrait être vieux de mille ans. Bien que certains éléments évoquent une structure insectoïde, sa véritable origine est difficile à cerner. Les espèces qui pondent ce type d'oeufs ne sont toujours pas connues." } } },
    ["From the Desk of Lord Victor Nefarius"] = { { ids = { "i21142" }, first = "towhomitmayconcernhowilo", pages = { "À qui de droit,\n\nComme j'aime ces petits jeux auxquels nous nous livrons.\n\nSi vous lisez cette lettre, je ne peux qu'en conclure que vous êtes $gparvenu:parvenue;, par miracle ou intervention divine, à me vaincre. Absurde, je sais, mais l'histoire de ce monde a connu des événements plus étranges encore.", "Comme pour toute chose dans la vie, ce triste récit a son heureux revers de tragédie, de chaos et de mal. Vous m'avez certes tué, mais avec tant de lenteur et de désordre que j'ai eu tout le loisir d'écrire cette lettre APRÈS avoir détruit votre unique espoir de sauver ce monde. La poudre de cristal rouge broyé est tout ce qui reste de votre fragment de sceptre.", "Profitez bien des pièces d'armure Némésis et Hurlorage que vous trouverez peut-être dans mon trésor. Croyez-moi lorsque je vous le dis : je prends un immense plaisir à savoir que j'ai accompli ce dont mon père était incapable...\n\nSincèrement,\n\nSeigneur Victor Nefarius\n\"Nefarian\"" } } },
    ["Furen's Instructions"] = { { ids = { "i6842" }, first = "inthefollowingpagesyoull", pages = { "Dans les pages suivantes, vous trouverez la liste des matériaux nécessaires pour construire une armure en acier trempé. Bonne chance, guerrier.\n\n-Furen Longbeard", "Crocs d'araignée brûlés :\n\nLe minerai d'incendicite, que l'on trouve dans une grotte à proximité du rocher de Thelgen, a brûlé les araignées qui vivaient là.\n\nLe venin de leurs crocs, devenu bouillant, réagit avec les crocs eux-mêmes pour donner une substance extrêmement dure.", "Cornes carbonisées :\n\nDe même que pour les crocs d'araignée brûlés, les cornes carbonisées des chimères qui vivent dans le Val calciné, dans les Serres-Rocheuses de Kalimdor, sont d'une qualité très prisée.\n\nBien battues et traitées comme il convient, elles deviennent très résistantes aux tensions physiques.", "Corne galvanisée :\n\nLa robustesse de cette rarissime corne galvanisée est l'élément indispensable pour réaliser cette pièce d'armure. Il faut donc que vous vous en procuriez une.\n\nVous la trouverez sur la matriarche chimère, qui est rare, dans le Val calciné.", "Fiole de phlogiston :\n\nLa dernière étape pour réaliser cette armure nécessite une forge d'une très haute température. Pour faire chauffer la forge suffisamment, il me faut une fiole de phlogiston.\n\nLa seule créature qui fabrique cette substance est Roogug, le légendaire huran, et il ne la cédera pas sans combattre. Roogug habite dans les profondeurs du Kraal de Tranchebauge, au sud des Tarides." } } },
    ["Furlbrow's Deed"] = { { ids = { "i1971" }, first = "thisisadeedtoanexpanseof", pages = { "Ceci est un acte notarié traitant d'une extension immobilière dans la région de la marche de l'Ouest. Il confère à la personne désignée la propriété de la zone considérée ainsi que les objets produits et les bâtiments construits dans ses limites.\n\nLe document est signé par :\n\n    Theodore Furlbrow\n    Verna Furlbrow", "[Les mots ci-dessous ont été rapidement griffonnés au revers de l'acte]\n\nNous avons fait pression sur Furlbrow et avons récupéré son titre de propriété, en pensant que ça pourrait vous être utile si vous vouliez en faire un pour chez vous. Les Furlbrow ne nous causeront pas de problèmes. La dernière fois que je les ai vus, ils étaient coincés sur la route de la marche de l'Ouest avec un chariot brisé." } } },
    ["General Turalyon"] = { { ids = { "o25330" }, first = "generalturalyonformerlie", pages = { "Général Turalyon\n\nAncien lieutenant du seigneur Anduin Lothar. Chevalier de la Main d'argent. Général en chef de l'Alliance attaché à l'expédition de l'Alliance qui a marché sur le monde des orcs de Draenor. Présumé mort.\n\nEsarus thar no'Darador' - Par le sang et l'honneur nous servons.\nTu étais la main de la justice et de la vertu, vieil ami. Ton nom sera honoré à jamais.\n\n- Seigneur Uther Lightbringer - Chevalier de la Main d'argent" } } },
    ["Geru Strider"] = { { ids = { "o175682" }, first = "thelargestoftheplainstri", pages = { "Le plus grand des trotteurs des plaines, le Geru, est rare. On ne le rencontre qu'exceptionnellement." } } },
    ["Glowing Recall Crystal"] = { { ids = { "i282416" }, first = "thehighorderhasbeenwatch", pages = { "<As you touch the glowing crystal a draft of wind stirs around you, carrying the faint hint of spoken words.>\n\nThe High Order has been watching you, $N, and we see great promise in your abilities.\n\nThe Wind Spirits have left Zephras Isle, and now more than ever, promising mages like yourself are needed. If our people are to find the self-reliance to survive this crisis, we must use our knowledge of the arcane to uncover the secrets of this realm.\n\nSeek me out in Thendal Village, on the ground floor of the great tree. We will begin your training in earnest.\n\n-Dorii Brightwhisper, Mage Trainer" } } },
    ["Glyphic Letter"] = { { ids = { "i9571" }, first = "therearefourrulestomagic", pages = { "Il y a quatre lois de la magie :\n\n   La Magie est puissante.\n   La Magie corrompt.\n   La Magie est une drogue.\n   La Magie attire les habitants du Néant distordu vers ceux qui manient les arcanes.\n\nCes règles existeront toujours. Ces règles gouverneront votre destinée si vous choisissez de poursuivre plus avant la voie de la magie.\n\nSi vous êtes assez stupide pour ignorer cet avertissement, alors venez me parler dans l'Aile de la Bibliothèque de l'abbaye à Northshire. Je vous attendrai en haut.\n\n-Khelden Bremen, Maître des mages" } } },
    ["Glyphic Memorandum"] = { { ids = { "i9573" }, first = "tonewstudentsofthearcane", pages = { "Pour : Les nouveaux étudiants des Arcanes :\nVous devez chercher le gnome Marryk Nurribit et y suivre son enseignement jusqu'à ce que vous soyez appelés à venir aider notre peuple à se trouver un nouveau foyer. Veuillez, sans angoisse excessive, vous préparer à des épreuves rigoureuses et une acclimatation difficile le temps de trouver un domicile, ou un compagnonnage avec les citoyens locaux.\n\nPosez toute question sur vos devoirs et capacités à Marrek Stromnur." } } },
    ["Glyphic Scroll"] = { { ids = { "i9574" }, first = "thecorruptionandevilthat", pages = { "La corruption et le mal, dont on dit qu'ils voyagent avec les arcanes, ne sont rien face à la douleur que nous avons déjà ressentie. Nous ne sommes plus des victimes, $N. Nous contrôlons désormais notre destin. Sylvanas nous a indiqué le chemin. Elle nous a prouvé que notre volonté nous appartient, que nous ne sommes plus les esclaves de ce maudit Arthas.\n\nTrouvez-moi dans l'église, je vous en dirai davantage... si tel est votre désir.\n\n- Isabella, Maître des mages" } } },
    ["Glyphic Tablet"] = { { ids = { "i9575" }, first = "welcometoyourawakeningmo", pages = { "Bienvenue à votre propre éveil ! Les secrets des arcanes sont à votre portée si vous avez la force de vous y affronter.\n\nVous trouverez Mai'ah lorsque vous le voudrez. Elle vous enseignera bien des choses sur la magie et les sorts dont vous aurez besoin pour détruire ceux qui se dresseront contre vous.\n\nMai'ah se trouve dans la Vallée des épreuves. Allez, trouvez-la et vous gagnerez en force. Puis vous pourrez montrer aux autres mages de quelle manière la magie se soumet à votre volonté... Et pas le contraire." } } },
    ["Goblin Rumors"] = { { ids = { "i5804" }, first = "thegoblinnazzsteamboilis", pages = { "Nazz Steamboil est en réalité le fils d'un prince marchand gobelin (quel prince ? Cette information vaut de l'or).\n\nIl semble qu'il préfère dépenser l'argent familial plutôt que d'en gagner par lui-même. Il a dérobé une petite fortune à sa famille et est parti se cacher dans les Salines.\n\nSi son père savait où il était, il irait le chercher et le ramènerait à la maison... amputé d'un orteil pour son insolence." } } },
    ["Goodsteel Ledger"] = { { ids = { "i11727" }, first = "greetingsandsalutationsa", pages = { "Salutations, Aventuriers !\n\nMoi, Krinkle Goodsteel, j'ai besoin de ceux qui sont capables de prendre beaucoup de risques pour achever les tâches les plus ardues. En raison de mes nombreux devoirs et des charges que j'ai dû endosser, je m'assurerai que quiconque est assez brave pour rapporter cette liste d'objets intacts soit grassement récompensé.\n\nLa liste est contenue dans les pages suivantes...", "Manches dans des pattes de cristal solide -\n\nLes araignées verrières de la gorge des Vents brûlants sont constituées d'une matière incroyable qui ressemble à du cristal. Leurs pattes, si elles ne sont pas endommagées lorsqu'on les tue, s'avèrent d'excellents conducteurs, utilisés par mes compagnons dans plusieurs expériences.\n\nIl m'en faudrait plusieurs pour faire des tests. Comme chaque araignée a huit pattes, cela ne devrait pas poser de problèmes pour un guerrier vétéran ou un mage entraîné.", "Un paquet en retard -\n\nJ'ai engagé quelqu'un que je croyais un pilote fiable pour me rapporter un paquet de Theramore. Erreur de jugement. Le pilote a survécu, mais il a laissé derrière lui le zeppelin et sa cargaison pour sauver sa peau.\n\nJ'ai besoin de ce paquet. D'après ce que m'a dit Beezil, il s'est écrasé à l'ouest de la baie du marécage d'Âprefange. L'appareil s'est écrasé juste après avoir traversé les collines le long de la berge.\n\nHmmm... Il ne m'a jamais dit pourquoi il s'était écrasé.", "La Flamberge de Goodsteel -\n\nEnfin, je veux l'une de mes plus belles réalisations à ce jour. Cette flamberge était une épée incroyable que j'ai donnée à quelqu'un que je prenais pour un grand et honorable guerrier. Eh bien, il a été battu à plates coutures par un murloc nommé Jarquai. Ou quelque chose du genre.\n\nIl voyageait le long de la côte des marais des Chagrins quand il a soudain eu l'idée d'attaquer cette créature. Il a échoué et s'est enfui, mais il a laissé l'épée derrière lui et le murloc s'en est saisi.", "Trouvez ces objets et rapportez-les tous à Gadgetzan avec ce livre de compte. Je vous récompenserai." } } },
    ["Gordo's Report"] = { { ids = { "i286202" }, first = "appleyumyummepickflowers", pages = { "<Étonnamment, on peut distinguer du texte à peine lisible gravé sur la peau restante de la pomme.>\n\nPomme miam miam. Moi cueillir fleurs maintenant." } } },
    ["Gozwin's Mechanic's Log"] = { { ids = { "i277976" }, first = "mechanicslogthiscommissi", pages = { "Journal du mécanicien\n\n<Ce petit journal relié en cuir est couvert de taches d'huile et de graisse. On y trouve des croquis de dispositifs mécaniques tous annotés. Vous l'ouvrez à une page au hasard.>\n\nCette commande me fera vivre pendant des années, il faut juste que je trouve un moyen d'empêcher le neutralisateur d'oscillations de surchauffer ou de se réduire en copeaux lui-même. Il faut que j'installe une vortexification de l'excès de chaleur vers le noyau de combustion, mais je ne m'y suis pas encore mis, parce qu'il faudrait démonter tout le trotteur et ensuite tout le moteur.\n\nPage 17", "<Vous faites défiler et tombez sur un diagramme étalé sur deux pages.>\n\nModifications des systèmes d'armement\n\nTourelle de glace – Opérationnelle\nLance-flammes – Opérationnel\nGénérateur d'impulsions électriques – Opérationnel\nProjecteur de radiations – Opérationnel\nAutocanon – Opérationnel\nRayon découpeur laser – EXPÉRIMENTAL\nCanon sonique – EXPÉRIMENTAL\nRayon de phase – CONCEPT\n\nPage 34                                      Page 35", "À FAIRE\n\nPréparer l'équipement pour l'expédition de chasse\nMousquetons pour la ceinture de Grund\nRéparer le casque de soudure\nCarte pour maman\n\nPage 45" } } },
    ["Gramma Stonefield's Note"] = { { ids = { "i1252" }, first = "hellowilliamitsbeenyears", pages = { "Bonjour William,\n\nVoilà des années que nous n'avons pas parlé, et j'ai bon espoir que vous et votre frère vous portez bien, ainsi que vos affaires.\n\nJe dois vous demander une faveur, William. Pour faire court, mon petit-fils Tommy Joe s'est épris de la jeune Maybell Maclure. Et bien qu'ils s'adorent, nos familles, ma foi, nos familles s'affrontent depuis des années.", "Je crains que la guerre entre les Stonefield et les Maclure ne finisse par tuer l'amour naissant de Tommy Joe et de Maybell. En des temps comme ceux-ci, où les nouvelles sont noires et où la guerre menace, la jeunesse et l'amour doivent être protégés.\n\nJe vous demande donc une faveur : utilisez vos connaissances pour concocter une potion capable d'aider ces jeunes gens dans leur quête de vie commune.\n\nMerci, William. Et s'il vous plaît, lorsque le travail vous laissera quelque répit, venez nous rendre visite. Nous évoquerons le bon vieux temps.\n\n-Mildred" } } },
    ["Grand Admiral Daelin Proudmoore"] = { { ids = { "o177201" }, first = "commanderofthealliancefl", pages = { "Commandant des Flottes de l'Alliance\n\nAmi de Stormwind" } } },
    ["Grape Manifest"] = { { ids = { "i11125" }, first = "brothernealsmygrapesares", pages = { "Frère Neals,\n\nMes raisins sont sauvés ! $N, qui vous apporte ce manifeste, a réussi à braver l'adversité et à récupérer les raisins. Bien que les Défias continuent à sévir sur les berges de la rivière, presque toute ma récolte a été sauvée.\n\nVous pourrez ajouter bien des boisseaux à vos échoppes.\n\nQue la Lumière nous protège,\n-Milly Osworth" } } },
    ["Green Hills of Stranglethorn - Chapter I"] = { { ids = { "i2756" }, first = "ourfirstdaywentaswellaso", pages = { "Notre première journée s'est aussi bien déroulée qu'on pouvait l'espérer. Nous avons surtout oeuvré à préparer l'établissement d'un campement. J'ai repéré un emplacement idéal près d'une rivière. A en juger par les vieux quais abandonnés qui s'y trouvent, ce site a été habité naguère. Quant aux anciens habitants, le temps nous dira peut-être ce qu'ils sont devenus.", "Pour cette expédition, j'ai réuni Ajeck Rouack et sire S. J. Erlgadin, ainsi que mon fidèle serviteur Barnil Stonepot. J'ai combattu aux côtés du père d'Ajeck dans bien des batailles au service de l'Alliance. La voir grandir a été quelque chose de très particulier. Son père l'a bien formée dans les arts du maniement d'arme. Ses talents à l'arc me font demander si elle n'aurait pas du sang elfe.", "Sire S. J. Erlgadin est un aristocrate humain. Son père, le comte Erlgadin, était célèbre pour sa générosité. C'est le comte qui s'est battu pour améliorer les conditions de travail de la Guilde des Maçons pendant la reconstruction de Stormwind après la Deuxième Guerre.", "Dans les années qui suivirent, après la trahison par Stormwind de la Guilde des Maçons, sire Erlgadin devint aigri au sujet du rôle des nobles du royaume. Il ne souhaitait plus conserver la position que la lignée de son père lui réservait à la Maison des Nobles. Mais trêve de digressions. Le but de cette histoire n'est pas de jouer au traité de science politique ni à la biographie. C'est la narration de mes expériences de chasse dans les vertes vallées de Strangleronce.", "Nous nous sommes levés à l'aube. Barnil a commencé à préparer le repas du matin. J'ai constaté qu'Ajeck semblait distraite. La marche serait longue ce jour-là et la chasse s'annonçait dangereuse. Il était vital que chacun reste concentré. Mais Ajeck me semblait incapable de détacher ses yeux de Barnil qui nettoyait ses affaires dans la rivière.", "Alors que j'allais interroger Ajeck sur son manque d'intérêt pour la stratégie de ce jour de chasse, elle s'est précipitée vers son carquois, a sorti une flèche et a tiré en direction du pauvre Barnil. Mais ce n'est pas Barnil qu'Ajeck visait. Lorsque Barnil s'est écarté, bouche bée, un grand crocilisque des rivières flottait à la surface, la flèche d'Ajeck parfaitement plantée entre ses deux yeux.", "Nous sommes partis vers l'ouest, à travers la jungle épaisse. Marchant lentement et précautionneusement, nous avons cherché nos proies dans l'épaisse frondaison. La matinée s'est écoulée dans un silence frustré. Rien ne frémissait dans la vallée, pas même la brise. Au début de l'après-midi, nous étions fatigués et Barnil avait abandonné la démarche silencieuse du chasseur de proies. Il arpentait la région d'un pas lourd, faisant craquer les feuilles mortes et les brindilles.", "Au cours d'un de ces faux-pas, Erlgadin a posé lourdement la main sur l'épaule de Barnil. Ajeck et moi nous sommes lancés un regard, pensant qu'il voulait simplement tancer Barnil. Mais Erlgadin a fait un geste  lent de la tête vers un arbre mort, non loin. Deux yeux noirs nous fixaient au-dessus d'une gueule emplie de crocs acérés." } } },
    ["Green Hills of Stranglethorn - Chapter II"] = { { ids = { "i2757" }, first = "thebeastwasamalestrangle", pages = { "C'était un tigre de Strangleronce, un mâle. Avant que j'aie le temps de relever mon arme, Erlgadin a pointé son arbalète vers la bête et a fait feu. Le trait a manqué la tête et a mordu la bête dans le flanc gauche. Le tigre a fait une puérile tentative pour fuir, mais la blessure était trop grave. Il a oscillé quelques secondes et Barnil l'a achevé d'un coup de hache.", "La mise à mort a créé une atmosphère joviale parmi les membres de l'expédition. Barnil a servi de l'hydromel à tous. Mais la bonne humeur n'a pas duré. Alors que nous préparions le cadavre pour le rapporter au campement, nous avons été surpris par un horrible grognement. De toute ma vie je n'ai jamais rien entendu qui soit plus de nature à glacer le sang.", "Sur un précipice rocheux découpé par le soleil couchant, j'ai aperçu le plus gros félin que l'on puisse imaginer. J'ai tiré une salve maladroite avec mon arme, mais le félin n'a pas bougé. Il a grogné à nouveau, plus fort que la première fois, et il a disparu.\n\nNous avons rassemblé nos affaires et nous sommes rentrés au campement.", "J'avais promis à l'équipe que nous passerions le jour suivant à chasser des panthères, car leur fourrure est très chère à Azeroth. Cela est juste, vu le nombre de trappeurs et de chasseurs qui ont perdu la vie au service de l'Alliance.", "Ajeck et sire Erlgadin étaient désireux d'apprendre à chasser efficacement avec un fusil nain. J'ai conseillé aux deux humains de laisser leurs armes primitives au campement. Barnil et moi leur avons fourni des armes à feu parmi les meilleures d'Ironforge.", "Ce jour-là, nous nous sommes aventurés vers le sud, à la suite de traces de panthère fraîches. Nous sommes arrivés à un ravin traversé par un immense pont de corde. Je n'ai pu m'empêcher de penser aux descriptions de Brann sur la région, quand j'ai aperçu cette merveille surplombant le vide. On pense si souvent que les trolls sont une race primitive et sans éducation, mais en observant la parfaite construction du pont je ne pus m'empêcher d'admirer l'habileté avec laquelle les bâtisseurs trolls avaient vaincu cette difficulté apparemment insurmontable.", "Bien vite, Ajeck repéra les traces d'une panthère vers le sud-ouest. Nous avons avancé rapidement, les armes prêtes, avides de rencontrer notre proie. Un craquement de branchages a attiré notre attention. Il y avait quelque chose par là. Un coup d'oeil rapide à Barnil a confirmé mes suppositions. Barnil a lentement relevé son fusil. Cette proie n'était pas pour nous, mais pour nos compagnons humains. D'innombrables panthères avaient perdu la vie au bout de nos canons. C'était au tour des humains.", "Ajeck et sire Erlgadin restaient aux aguets, canon levé vers le feulement qui provenait de la frange mouvante des arbres. Le soleil de midi tapait dur sur nos épaules. Un mince filet de sueur coulait le long des tempes d'Erlgadin lorsqu'il a relevé le chien de son arme. Au cliquetis qui a retenti, la dense végétation s'est ouverte et une panthère noire, un spécimen magnifique, est entrée dans la clairière." } } },
    ["Green Hills of Stranglethorn - Chapter III"] = { { ids = { "i2758" }, first = "thehumanstrainedtheirsit", pages = { "Les humains ont pointé leur arme sur la panthère qui courait le long de la ligne des arbres. Les canons se déplaçaient en parallèles parfaites. Barnil m'a lancé un coup d'oeil pressant mais j'ai fait non de la tête. Cette chasse était pour les humains, pas pour Barnil ni pour moi. Sire Erlgadin a tiré, mais a manqué la cible. Il n'était visiblement pas préparé au violent recul de l'arme.", "Son arme a failli lui échapper des mains. Le canon a dévié et est venu se placer sous le fusil d'Ajeck. Ajeck a choisi ce moment précis pour tirer. Le coup est parti avec sa détonation caractéristique, mais dans la direction de la ligne d'arbres. Des oiseaux se sont envolés dans toutes les directions avec des cris plaintifs. Un filet de fumée s'est élevé de l'arbre qui avait été touché. Stupéfaits, nous avons vu une énorme branche tomber sur la panthère en pleine course, lui brisant la colonne vertébrale.", "Au fur et à mesure que les semaines passaient, notre stock de peaux de panthère et de tigre grandissait. Je décidai qu'il était temps pour l'expédition de se concentrer sur un nouveau défi : les raptors.\n\nLes humains, tout en appréciant l'expérience de Barnil et la mienne, décidèrent de ne pas se servir d'armes à feu. Ajeck se sentait plus à l'aise avec un arc et sire Erlgadin ne quittait jamais le camp sans une solide arbalète.", "Nous avons levé le camp à l'aube et sommes partis vers le sud en traversant les ruines de Tkashi. Barnil craignait qu'on ne rencontre des membres de la tribu Bloodscalp. J'ai rappelé à Barnil que les Bloodscalp se concentraient surtout sur la destruction de leurs rivaux, les Skullsplitter. Cela, bien sûr, n'a pas rassuré Barnil le moins du monde. Mais j'avais un fusil chargé, des munitions, et trois chasseurs expérimentés pour me réconforter contre la menace d'une embuscade.", "Je me suis déjà tenu devant un immense Infernal sur le champ de bataille, tandis que l'armée de la Légion ardente avançait de toutes les directions. Une bande de trolls sans chef est aussi inoffensive qu'un lapin dans les collines de Dun Morogh.\n\nNous avons traversé les ruines de Tkashi sans incident, au grand soulagement de Barnil. Le groupe s'est ensuite dirigé vers l'ouest, en direction de la Grande Mer, longeant les ruines de Zul'Kunda au sud. C'est alors que nous montions les escarpements du rivage que nous avons repéré notre premier raptor.", "La bête ne nous a pas entendu approcher. Tout ce qu'elle a reçu, c'est une balle entre les yeux. Sire Erlgadin a laissé échapper un cri de joie tandis qu'Ajeck me lançait un coup de tête approbateur. J'ai cherché ma pipe dans mon sac, pour célébrer cette victoire. Barnil a filé vers le haut de la colline pour retrouver le cadavre du raptor. J'ai regardé la bête morte avec la satisfaction qui accompagne chaque joli tir.", "Mais je n'ai pas profité longtemps de ce moment de gloire. Quand j'ai tourné les yeux vers l'horizon, j'ai vu plusieurs silhouettes apparaître au sommet de la colline, juste au-dessus du pauvre Barnil.\n\n*Fuyez, Barnil !* ai-je hurlé. Ajeck, sire Erlgadin et moi avons envoyé une salve de balles et de flèches vers les nouveaux raptors. Dans la confusion, nous en avons abattu un autre.", "Nos tirs mal ajustés ont suffi à couvrir la fuite de Barnil. Il a dévalé la colline pour nous rejoindre. Nous nous sommes précipités dans la jungle, entraînant derrière nous une meute de raptors flagellants.\n\nLes chasseurs étaient désormais les proies." } } },
    ["Green Hills of Stranglethorn - Chapter IV"] = { { ids = { "i2759" }, first = "iledthepartytowardthesea", pages = { "J'ai mené le groupe jusqu'à la mer, espérant que le rivage nous fournirait une protection contre les raptors. Dans notre hâte, nous sommes allés trop loin vers le Nord, jusqu'à un promontoire dangereusement escarpé. Erreur fatale. Ma faute. Nous nous sommes retrouvés bloqués sur une corniche, les raptors à quelques pas derrière nous.", "Je fis lentement un pas en avant, arme levée. J'avais conduit ces braves chasseurs à leur mort. J'étais prêt à mourir en tentant de les défendre. Les raptors flagellants sont particulièrement féroces, réputés pour leur inextinguible soif de sang. Ils étaient beaucoup plus nombreux que nous. Mais je n'allais pas les laisser me tuer ainsi que mes camarades sans verser d'abord un peu de leur sang.", "Ajeck et sire Erlgadin ont préparé leurs armes, un à chacun de mes côtés, nos dos tournés vers la mer. Barnil a laissé échapper un soupir et a levé sa hache. Les flagellants étaient presque sur nous. Ils avançaient moins vite. Ils traquaient leurs proies maintenant qu'ils savaient qu'ils nous avaient piégés.", "Et le miracle a eu lieu. Loin sur notre flanc, nous avons entendu le rugissement caractéristique et terrifiant du grand tigre blanc. Malgré leur nombre, les raptors ont fait demi-tour et se sont dispersés dans toutes les directions. Nous avons vu un bref éclair blanc : le tigre passait devant nous et se précipitait sur l'un des raptors. Inutile de donner des ordres : nous savions tous que l'heure de fuir avait sonné.", "Nous avons foncé jusqu'au campement, sans ralentir. Au cours de la nuit, assis silencieusement autour du feu de camp, nous avons médité sur l'étrange destin qui venait de nous sauver la vie. Tels sont les risques de la chasse. Nous jouons avec le destin. Chacun de nous, à un moment ou à un autre, rencontrera sa fin entre ses dents aiguisées. Le nain que je suis est simplement heureux que ce moment ne soit pas arrivé dans les vertes collines de Strangleronce." } } },
    ["Green Hills of Stranglethorn - Page 1"] = { { ids = { "i2725" }, first = "thegreenhillsofstranglet", pages = { "Les vertes collines de Strangleronce\n\nNotre première journée s'est aussi bien déroulée qu'on pouvait l'espérer. Nous avons surtout oeuvré à préparer l'établissement d'un campement. J'ai repéré un emplacement idéal près d'une rivière. A en juger par les vieux quais abandonnés qui s'y trouvent, ce site a été habité naguère. Quant aux anciens habitants, le temps nous dira peut-être ce qu'ils sont devenus." } } },
    ["Green Hills of Stranglethorn - Page 10"] = { { ids = { "i2734" }, first = "thekillbroughtaboutafest", pages = { "La mise à mort a créé une atmosphère joviale parmi les membres de l'expédition. Barnil a servi de l'hydromel à tous. Mais la bonne humeur n'a pas duré. Alors que nous préparions le cadavre pour le rapporter au campement, nous avons été surpris par un horrible grognement. De toute ma vie je n'ai jamais rien entendu qui soit plus de nature à glacer le sang." } } },
    ["Green Hills of Stranglethorn - Page 11"] = { { ids = { "i2735" }, first = "onarockyprecipiceabovesi", pages = { "Sur un précipice rocheux découpé par le soleil couchant, j'ai aperçu le plus gros félin que l'on puisse imaginer. J'ai tiré une salve maladroite avec mon arme, mais le félin n'a pas bougé. Il a grogné à nouveau, plus fort que la première fois, et il a disparu.\n\nNous avons rassemblé nos affaires et nous sommes rentrés au campement." } } },
    ["Green Hills of Stranglethorn - Page 14"] = { { ids = { "i2738" }, first = "onthisdayweventuredtothe", pages = { "Ce jour-là, nous nous sommes aventurés vers le sud, à la suite de traces de panthère fraîches. Nous sommes arrivés à un ravin traversé par un immense pont de corde. Je n'ai pu m'empêcher de penser aux descriptions de Brann sur la région, quand j'ai aperçu cette merveille surplombant le vide. On pense si souvent que les trolls sont une race primitive et sans éducation, mais en observant la parfaite construction du pont je ne pus m'empêcher d'admirer l'habileté avec laquelle les bâtisseurs trolls avaient vaincu cette difficulté apparemment insurmontable." } } },
    ["Green Hills of Stranglethorn - Page 16"] = { { ids = { "i2740" }, first = "bothajeckandsirerlgadins", pages = { "Ajeck et sire Erlgadin restaient aux aguets, canon levé vers les broussailles qui se hérissaient à la base de la frange mouvante des arbres. Le soleil de midi tapait dur sur nos épaules. Un mince filet de sueur coulait le long des tempes d'Erlgadin lorsqu'il a relevé le chien de son arme. Au cliquetis qui a retenti, la dense végétation s'est ouverte et une panthère noire, un spécimen magnifique, est entrée dans la clairière." } } },
    ["Green Hills of Stranglethorn - Page 18"] = { { ids = { "i2742" }, first = "hisguntossedbackviolentl", pages = { "Son arme a failli lui échapper des mains. Le canon a dévié et est venu se placer sous le fusil d'Ajeck. Ajeck a choisi ce moment précis pour tirer. Le coup est parti avec sa détonation caractéristique, mais dans la direction de la ligne d'arbres. Des oiseaux se sont envolés dans toutes les directions avec des cris plaintifs. Un filet de fumée s'est élevé de l'arbre qui avait été touché. Stupéfaits, nous avons vu une énorme branche tomber sur la panthère en pleine course, lui brisant la colonne vertébrale." } } },
    ["Green Hills of Stranglethorn - Page 20"] = { { ids = { "i2744" }, first = "wesetoutatfirstlighthead", pages = { "Nous avons levé le camp à l'aube et sommes partis vers le sud en traversant les ruines de Tkashi. Barnil craignait qu'on ne rencontre des membres de la tribu Bloodscalp. J'ai rappelé à Barnil que les Bloodscalp se concentraient surtout sur la destruction de leurs rivaux, les Skullsplitter. Cela, bien sûr, n'a pas rassuré Barnil le moins du monde. Mais j'avais un fusil chargé, des munitions, et trois chasseurs expérimentés pour me réconforter contre la menace d'une embuscade." } } },
    ["Green Hills of Stranglethorn - Page 21"] = { { ids = { "i2745" }, first = "ivestoodbeforeatoweringi", pages = { "Je me suis déjà tenu devant un immense Infernal sur le champ de bataille, tandis que l'armée de la Légion ardente avançait de toutes les directions. Une bande de trolls sans chef est aussi inoffensive qu'un lapin dans les collines de Dun Morogh.\n\nNous avons traversé les ruines de Tkashi sans incident, au grand soulagement de Barnil. Le groupe s'est ensuite dirigé vers l'ouest, en direction de la Grande Mer, longeant les ruines de Zul'Kunda au sud. C'est alors que nous montions les escarpements du rivage que nous avons repéré notre premier raptor." } } },
    ["Green Hills of Stranglethorn - Page 24"] = { { ids = { "i2748" }, first = "ourhastilyaimedshotswere", pages = { "Nos tirs mal ajustés ont suffi à couvrir la fuite de Barnil. Il a dévalé la colline pour nous rejoindre. Nous nous sommes précipités dans la jungle, entraînant derrière nous une meute de raptors flagellants.\n\nLes chasseurs étaient désormais les proies." } } },
    ["Green Hills of Stranglethorn - Page 25"] = { { ids = { "i2749" }, first = "iledthepartytowardthesea", pages = { "J'ai mené le groupe jusqu'à la mer, espérant que le rivage nous fournirait une protection contre les raptors. Dans notre hâte, nous sommes allés trop loin vers le nord, jusqu'à un promontoire dangereusement escarpé. Erreur fatale. Ma faute. Nous nous sommes retrouvés bloqués sur une corniche, les raptors à quelques pas derrière nous." } } },
    ["Green Hills of Stranglethorn - Page 26"] = { { ids = { "i2750" }, first = "isteppedslowlyforwardgun", pages = { "Je fis lentement un pas en avant, arme levée. J'avais conduit ces braves chasseurs à leur mort. J'étais prêt à mourir en tentant de les défendre. Les raptors flagellants sont particulièrement féroces, réputés pour leur inextinguible soif de sang. Ils étaient beaucoup plus nombreux que nous. Mais je n'allais pas les laisser me tuer ainsi que mes camarades sans d'abord verser un peu de leur sang." } } },
    ["Green Hills of Stranglethorn - Page 27"] = { { ids = { "i2751" }, first = "ajeckandsirerlgadinreadi", pages = { "Ajeck et sire Erlgadin ont préparé leurs armes, un à chacun de mes flancs, nos dos tournés vers la mer. Barnil a laissé échapper un soupir et a levé sa hache. Les flagellants étaient presque sur nous. Ils avançaient moins vite. Ils savaient que leurs proies étaient piégées." } } },
    ["Green Hills of Stranglethorn - Page 4"] = { { ids = { "i2728" }, first = "intheyearsthatfollowedaf", pages = { "Dans les années qui suivirent, après la trahison de la Guilde des Maçons par Stormwind, Erlgadin devint aigri au sujet du rôle des nobles du royaume. Il ne souhaitait plus conserver la position que la lignée de son père lui réservait à la Maison des Nobles.\n\nMais trêve de digressions. Le but de cette histoire n'est pas de jouer au traité de science politique ni à la biographie. C'est la narration de mes expériences de chasse dans les vertes vallées de Strangleronce." } } },
    ["Green Hills of Stranglethorn - Page 6"] = { { ids = { "i2730" }, first = "justasiwasabouttoquestio", pages = { "Alors que j'allais interroger Ajeck sur son manque d'intérêt pour la stratégie de ce jour de chasse, elle s'est précipitée vers son carquois, a sorti une flèche et a tiré en direction du pauvre Barnil. Mais ce n'est pas Barnil qu'Ajeck visait. Lorsque Barnil s'est écarté, bouche bée, un grand crocilisque des rivières flottait à la surface, la flèche d'Ajeck parfaitement plantée entre ses deux yeux." } } },
    ["Green Hills of Stranglethorn - Page 8"] = { { ids = { "i2732" }, first = "duringonesuchmissteperlg", pages = { "Au cours d'un de ces faux-pas, Erlgadin a posé lourdement la main sur l'épaule de Barnil. Ajeck et moi nous sommes lancé un regard, pensant qu'il voulait simplement tancer Barnil. Mais Erlgadin a fait un geste lent de la tête vers un arbre mort, non loin. Deux yeux noirs nous fixaient au-dessus d'une gueule emplie de crocs acérés." } } },
    ["Grelin Whitebeard's Journal"] = { { ids = { "i2004" }, first = "dayonetheapprenticeandih", pages = { "PREMIER JOUR\n\nL'apprenti et moi-même sommes arrivés aujourd'hui à la vallée des Frigères. Il ne s'est rien passé au cours de notre passage dans les grottes. Nous avons établi notre campement à bonne distance de la grotte où l'on dit que les trolls se sont installés.\n\nDEUXIÈME JOUR\n\nLes hurlements d'un satané loup m'ont tenu éveillé toute la nuit.\n\nJ'aurai un nouveau manteau en peau de loup dans quelques jours.\n\nLe gamin a eu maille à partir avec un trogg aujourd'hui, il y a eu un combat, et", "il a réussi à prendre l'avantage sur l'horrible brute, mais il a subi une méchante entaille au bras. Je devrai m'occuper des corvées pour un moment.\n\nTROISIÈME JOUR\n\nIl fait froid. Il a un peu neigé vers midi.\n\nQUATRIÈME JOUR\n\nLe gamin semble en meilleure forme aujourd'hui, alors nous sommes allés jeter un coup d'oeil sur les trolls. Des trolls Frostmane, selon moi, à en juger par les scarifications et la bimbeloterie qu'ils portent sur leur corps.", "CINQUIÈME JOUR\n\nJ'ai laissé le gamin veiller sur le camp et je me suis glissé dans la grotte pour y jeter un coup d'oeil. Les effectifs des trolls sont inquiétants. Les Montagnards devront être mobilisés en masse s'il faut nettoyer la grotte de l'invasion des trolls.\n\nJe me rends compte que je n'ai pas mentionné les troggs dernièrement. Ils se font plus nombreux dans la zone, mais ils sont si primitifs qu'ils ne représentent pas une vraie menace. Le temps confirmera ou non cette impression.", "Pas une goutte de bière depuis pratiquement une semaine.\n\nSIXIÈME JOUR\n\nIl fait de nouveau froid. Il neige. Trolls. Pas de bière.\n\nSEPTIÈME JOUR\n\nLa neige est si blanche,\nLe ciel si bleu,\nLes loups cherchent une revanche,\nC'est de la bière que je veux.\n\nHUITIÈME JOUR\n\nLes trolls ne sont peut-être pas le problème que nous pensions initialement. Ils sont", "nombreux mais mal armés et peu organisés. Une petite démonstration de force devrait suffire pour régler la question." } } },
    ["Grelin's Report"] = { { ids = { "i2619" }, first = "areportonthestateofthefr", pages = { "Rapport sur les trolls Frostmane dans la région de la vallée des Frigères\n\nPréparé par Grelin Whitebeard, Envoyé spécial du Sénat\n\nAprès avoir passé du temps à observer les mouvements des trolls Frostmane dans la région de la vallée des Frigères, je suis en mesure de dire qu'ils ne représentent pas une menace sérieuse pour les comptoirs des nains dans la zone. Bien plus, avec une petite aide de l'armée, la question pourrait rapidement être réglée. Avec le soutien des Montagnards déjà présents dans la", "vallée des Frigères et de mercenaires (payés par les fonds débloqués avant mon départ par le Sénat), je suis convaincu que le problème sera résolu rapidement.\n\nCette action a été autorisée par le roi Bronzebeard." } } },
    ["Gryshka's Letter"] = { { ids = { "i16307" }, first = "dearzarghthesteaksyousen", pages = { "Cher Zargh,\n\nLes steaks que vous avez envoyés sont excellents. Marbrés, bien épais et enrobés de graisse de sanglier. Je ne les aime pas autrement. Quand je les mangerai plus tard, je penserai à vous tandis que je rongerai les derniers os. Je fermerai mes yeux et je verrai vos mains puissantes et balafrées donner des coups de hache et de couteau...\n\nHa ! Ça me rappelle la fois où vous avez eu cet accident, et que vous avez perdu un doigt... Oh, Zargh ! En repensant à ce jour, je suis guillerette comme une petite fille.\n\nVous êtes si mignon lorsque vous saignez !\n\n-Gryshka" } } },
    ["Hallowed Letter"] = { { ids = { "i9548" }, first = "yourconnectiontotheworld", pages = { "Votre connexion avec le monde, et sa connexion avec vous, sont d'une importance vitale pour votre formation de prêtre. Sagesse et compassion vous permettront d'aider ceux qui en ont vraiment besoin. La précipitation et la maladresse causeront des désastres et affaibliront les autres.\n\nAu fur et à mesure que vous comprendrez ce que cela signifie, vous aurez besoin de nouvelles techniques et de nouveaux sorts pour vous aider. C'est là que mon rôle commence : venez me voir dans la bibliothèque de l'abbaye de Northshire quand vous penserez l'heure venue.\n\n-Prêtresse Anetta, Maître des prêtres" } } },
    ["Hallowed Rune"] = { { ids = { "i9556" }, first = "withtheholylightwarminou", pages = { "La Sainte Lumière nous soutient et nous faisons chaque jour de nouvelles découvertes. L'heure est à l'enthousiasme pour les enfants d'Ironforge. La Ligue des explorateurs avance chaque jour pour révéler les réponses à nos plus anciennes questions. Et aujourd'hui, vous rejoignez nos fidèles pour les aider au combat contre les troggs et les autres menaces qui rôdent à nos frontières.\n\nVenez me voir quand vous en aurez le temps. Je serai derrière Anvilmar, en haut de la colline.\n\n- Branstock Kahlder, Maître des prêtres" } } },
    ["Hallowed Scroll"] = { { ids = { "i9569" }, first = "feelblessedthatyourespir", pages = { "Réjouissez-vous que votre esprit n'ait pas été lâché dans le Néant, $N. Réjouissez-vous davantage que je vous pense apte à recevoir ce parchemin.\n\nLes gens que vous avez connus naguère, que vous avez aimés peut-être, ne sont plus. Vous devez apprendre à \"vivre\" avec cela jusqu'à la fin de votre vie... quelle qu'elle soit. Avant toutes choses, le vous suggère d'apprendre à l'accepter.\n\nSi vous pensez pouvoir affronter les épreuves à venir, venez me voir dans l'église du Glas.\n\n- Sombre clerc Duesten, Maître des prêtres" } } },
    ["Hallowed Sigil"] = { { ids = { "i9557" }, first = "ihopethissigilfindsyouwe", pages = { "J'espère que vous allez bien, $N. Les esprits m'annoncent votre venue et c'est pour cela que je vous écris vite. J'ai hâte de partager avec vous mon expérience et de vous guider vers les affaires importantes qui vous attendent hors de Teldrassil.\n\nAvec tout ce qui est survenu au cours des dernières années, nous pouvons faire beaucoup pour aider les autres races d'Azeroth. Venez me voir quand vous penserez l'heure venue, je serai à Aldrassil, au deuxième niveau.\n\n-Shanda, Maître des prêtres" } } },
    ["Hallowed Tablet"] = { { ids = { "i9561" }, first = "ahhopedaspiritshaveprote", pages = { "J'espère que la protection des esprits ne vous a pas été mesurée jusqu'à aujourd'hui. Vous avez bien des épreuves à affronter, mais je partagerai mon expérience avec vous quand vous le voudrez. A vous de voir quelle puissance vous voulez atteindre. Je ne pourrai vous guider que lorsque l'heure sera venue.\n\nPour certains, cela vient très vite. Pour d'autres... c'est plus lent. Mais ne vous inquiétez pas. Nous parlerons davantage quand vous serez là.\n\n-Ken'jai, Maître des prêtres" } } },
    ["Harthal Truesight"] = { { ids = { "o175776" }, first = "fellariswiftarrowrangerc", pages = { "Harthal Truesight\nSeigneur paladin de la Croisade écarlate\nCitoyen d'Azeroth - Chevalier de la Main d'argent\nPorté disparu après être entré dans la ville maudite de Stratholme" } } },
    ["Hatred of the Centaur"] = { { ids = { "o177209" }, first = "asthemistsofdawnfadedand", pages = { "Tandis que les brumes de l'Aube se dissipaient et que l'Âge de la mémoire avançait, le demi-dieu Cénarius partit à travers les champs du monde. Les Shu'halo (taurens) furent désolés de son départ et oublièrent les connaissances druidiques qu'ils tenaient de lui. Tandis que les générations se succédaient, ils oublièrent le langage des arbres et des animaux. Les sombres murmures des profondeurs du monde montèrent de nouveau jusqu'à leurs oreilles.", "Les enfants de la terre restèrent à distance des murmures démoniaques, mais une terrible malédiction tomba sur les tribus errantes. Des terres noires de l'ouest survint une horde de créatures sanguinaires : les centaures. Cannibales, destructeurs, les centaures s'abattirent comme une peste sur les Shu'halo. Les braves et les chasseurs luttèrent avec la bénédiction de la Terre-mère, mais les centaures semblaient invincibles.", "Les Shu'halo ont dû quitter leurs terres ancestrales et errent depuis, nomades, sur les plaines sans limite. L'espoir était censé renaître un jour, et les tribus dispersées des Shu'halo trouveraient alors un nouveau foyer dans les bras de la Terre-mère." } } },
    ["Here Lies King Terenas Menethil II"] = { { ids = { "o175659" }, first = "herelieskingterenasmenet", pages = { "Ici repose le roi Terenas Menethil II, le dernier vrai roi de Lordaeron.\n\nSes actes furent grands, son règne fut long, sa mort était impensable.\n\n     \"Que le père ne soit pas souillé par les actions du fils.\n     Que la couronne sanglante reste perdue et oubliée.\"" } } },
    ["Highborne Astrolabe"] = { { ids = { "o175686" }, first = "recoveredfromtheundersea", pages = { "Trouvée dans les ruines sous-marines de Suramar, cette astrolabe fonctionnelle a été forgée par les Bien-nés des elfes de la nuit il y a près de douze mille ans. Les Bien-nés, obsédés par la magie, l'occulte et l'astronomie, ont développé une série d'appareils ingénieux. Cet outil fournit des renseignements précieux sur le niveau scientifique des anciens elfes de la nuit." } } },
    ["Hildelve's Journal"] = { { ids = { "i3117" }, first = "daymytankisbrokenbutikno", pages = { "Jour 1\n\nMon char est cassé, mais je sais que le minerai de chiron est quelque part dans ces collines. J'ai dit à Hammerfoot de rester et de surveiller les chars.\n\nJe continue les recherches seul. Si je ne reviens pas, alors ce journal constitue mon dernier testament.\n\n-- pilote Buron Hildelve\nBrigade des sapeurs d'Ironforge", "Jour 2\n\nMes recherches continuent, mais toujours pas de minerai. Je me demande si Stonegear n'a pas lancé la rumeur sur ce minerai pour plaisanter. Si c'est le cas, il aura droit à une belle fissure crânienne quand je rentrerai au dépôt de Steelgrill !\n\nCette nuit, en préparant mon bivouac, j'ai entendu l'écho d'un grondement dans les canyons.\n\nCe n'est pas un loup. Un ours, peut-être...", "Jour 3\n\nLe grondement a continué toute la nuit et me suit aujourd'hui, je ne peux plus me concentrer sur la recherche de minerai. Je pense qu'un ours me suit !\n\nQu'il approche ! Je lui planterai mon piolet dans la tête !", "Jour 4\n\nMes provisions sont presque épuisées. J'ai toujours de la nourriture, mais je n'avais pas prévu de passer tant de temps éloigné de mon char et je n'ai que deux tonnelets de bière avec moi.\n\nJe n'ai pas fermé l'oeil au cours des deux dernières nuits, perturbé par le grognement permanent, et j'ai presque asséché mes tonnelets !\n\nIl va falloir que je retourne vers Hammerfoot et nos chars à vapeur dès demain. Je ne veux pas rester à errer dans les parages sans carburant.", "Jour 5\n\nCe maudit ours s'est enfin dévoilé ! Il m'a attaqué à midi, il a chargé vers moi par derrière en grondant.\n\nJe l'aurais senti venir s'il avait chargé dans le vent, car il empestait horriblement ! Les relents de sa fourrure et de son haleine ont presque suffi à me faire m'évanouir !\n\nJ'ai repoussé la créature mais elle a eu le temps de me broyer la jambe. Je ne peux plus bouger, je n'ai plus de bière et je n'ai trouvé aucun minerai. Malédiction !", "Jour 6\n\nL'ours n'est pas encore revenu, il a dû recevoir une bonne volée ! Mais j'entends toujours son grognement. Je crois qu'il attend que je meure !\n\nJ'ai une requête pour quiconque trouvera ce livre. Tuez cet ours galeux ! Tuez-le et rapportez le livre à mon ami Hammerfoot. Il voudra savoir ce qui s'est passé.\n\nEt prenez mon armure. Vous en aurez besoin contre Griffe galeuse !" } } },
    ["Hillsbrad Town Registry"] = { { ids = { "i3657" }, first = "hillsbradtownregistrywet", pages = { "Registre municipal d'Hillsbrad\n\nNous, les citoyens d'Hillsbrad, jurons solennellement foi et dévotion à l'Alliance maintenue par les grands monarques, le roi Magni Bronzebeard d'Ironforge et le roi Anduin Wrynn de Stormwind.\n\nIci repose le registre municipal pour le gouvernement de cette grande cité dans les collines des montagnes d'Alterac et pour le recensement de ceux qui ont acquitté leurs impôts à leurs rois et à la puissante Alliance.", "Magistrat Rutherford Burnside\nDettes réglées.\n\nForgeron Avery Verringtan\nDettes réglées.\n\nGreffier Horrace Whitesteed\nDettes réglées.\n\nConseiller Gillis\nDettes réglées.\n\nConseiller Hooks\nDettes réglées.\n\nFermier Getz\nDettes réglées.\n\nFermier Ray\nDettes en instance. Paiement en nature promis au moment de la moisson.\n\nFermier Lyion\nDettes en instance. Chassé des terres.", "Fermier Kalaba\nDettes en instance. Paiement en nature promis au moment de la moisson.\n\nCitoyen Wilkes\nDettes réglées.\n\nCitoyen Bonoan\nDettes réglées.\n\nMineur Wellty\nDettes en instance. Paiement dû lors de la prochaine livraison de minerai d'Azureload.\n\nMineur Sidney\nDettes en instance. Paiement dû lors de la prochaine livraison de minerai d'Azureload.\n\nMineur Hackett\nDettes en instance. Paiement dû lors de la prochaine livraison de minerai d' Azureload.", "Mineur Orwell\nDettes en instance. Paiement dû lors de la prochaine livraison de minerai d'Azureload.\n\nMineur Fitzgerald\nDettes en instance. Paiement dû lors de la prochaine livraison de minerai d'Azureload.\n\nCitoyen Netherand\nDettes réglées.\n\nCitoyen May\nDettes réglées.\n\nContremaître Bonds\nDettes en instance. Paiement dû lors de la prochaine livraison de minerai d'Azureload." } } },
    ["Holia Sunshield"] = { { ids = { "o175777" }, first = "holiasunshielddefenderof", pages = { "Holia Sunshield\n\nRempart de la Croisade écarlate\n\nTomba en abattant le seigneur de l'effroi Beltheris" } } },
    ["Hollee's Note"] = { { ids = { "i281243" }, first = "tarrelmybelovednotadaygo", pages = { "Mon bien-aimé Tarrel,\n\nIl n'y a pas un jour où je ne me perds pas à penser à tes tresses de bronze, ton rire tonitruant ou tes bras musculeux.\n\nTu dois venir me retrouver à Auberdine par le prochain bateau. Nous sommes faits l'un pour l'autre, au fond de toi, tu sais que c'est vrai !\n\nJe suis tienne si tu veux de moi,\n\nHollee" } } },
    ["Horatio Montgomery, M.D."] = { { ids = { "o124374" }, first = "inmemoryofmydearmentorho", pages = { "A la mémoire de mon cher mentor, Horatio M. Montgomery, guérisseur, professeur, ami.\n\n50 BTFT - 25 ATFT\n\n\"Le monde est plein de malades et de déprimés. C'est notre métier, en tant que guérisseurs, non, en tant qu'hommes et femmes de la médecine, de les soulager.'\"\n\n- Agrégé de sciences, Docteur, Grand maître fermier, Danseur extraordinaire, Ami des animaux" } } },
    ["Horde Catapult"] = { { ids = { "o175688" }, first = "thisremnantfromthesecond", pages = { "Ce vestige de la Deuxième Guerre nous rappelle combien la Horde fut près de conquérir la montagne d'Ironforge." } } },
    ["Horde Military Ranks"] = { { ids = { "o179741" }, first = "hordemilitaryranksoffice", pages = { "GRADES MILITAIRES DE LA HORDE\n\nOFFICIERS\n\nGrand seigneur de guerre\n\nSeigneur de guerre\n\nGénéral\n\nLieutenant-général\n\nChampion\n\nCenturion\n\nLégionnaire\n\nGarde de sang\n\nGarde de pierre\n\nRECRUES\n\nAdjudant\n\nSergent-chef\n\nSergent\n\nGrunt\n\nEclaireur" } } },
    ["Humming Recall Crystal"] = { { ids = { "i282418" }, first = "thewindshapershavebeenwa", pages = { "<Lorsque vous touchez le cristal brillant, un courant d'air serpente autour de vous, transportant le faible écho de quelques mots.>\n\nLes Sculpte-vents ont observé vos faits et gestes, et il est temps pour vous de passer à l'étape suivante de votre formation chamanique.\n\nLes esprits du vent ont disparu de l'île de Zéphras et il revient à nous de braver les dangers du plan élémentaire pour les ramener chez eux. Il n'existe pas de devoir plus sacré et notre survie en dépend.\n\nRetrouvez-moi à Thendal, près du centre-ville. Je vais vous entraîner.\n\n– Sculpte-vent Boro, maître des chamans" } } },
    ["Icecrown and the Frozen Throne"] = { { ids = { "o175749" }, first = "kiljaedencastnerzhulsicy", pages = { "Kil'jaeden renvoya la prison glacée de Ner'zhul dans le monde d'Azeroth. Le cristal dur traversa le ciel nocturne et s'écrasa au sol dans le désert arctique de Northrend avant de disparaître au plus profond du glacier de la Couronne de glace. Le cristal gelé, endommagé par cette brutale descente, prit l'aspect d'un trône, et l'esprit assoiffé de vengeance de Ner'zhul ne tarda pas à remuer à l'intérieur.", "Prisonnier du Trône de glace, Ner'zhul déploya son immense conscience des choses et atteignit les esprits des indigènes de Northrend. Avec une déconcertante facilité, il réduisit en esclavage les trolls des glaces et les violents wendigos, recouvrant de son ombre grandissante ces peuples vils. Il découvrit que ses pouvoirs psychiques étaient presque sans limite, et les utilisa pour créer une petite armée qu'il abrita dans les couloirs labyrinthiques de la Couronne de glace.", "Le roi-liche accroissait ainsi ses pouvoirs sous la surveillance permanente des seigneurs de l'effroi, lorsqu'il découvrit un petit campement humain aux confins du vaste royaume des dragons. Ner'zhul décida de tester sa puissance et sa peste mortelle sur les humains qui ne suspectaient rien.", "Ner'zhul envoya une vague de mort née dans les profondeurs du Trône de glace sur les terres arctiques. Contrôlant cette peste par la seule force de sa volonté, il la conduisit jusque dans les villages humains. En trois jours, tous les humains avaient péri. Presque aussitôt, les villageois morts se relevèrent sous la forme de cadavres zombifiés. Ner'zhul était capable de ressentir leur esprit et leurs pensées comme s'ils faisaient partie de lui.", "Cette cacophonie rugissant dans son esprit lui permit de croître encore en puissance, comme s'il se nourrissait de ces âmes. Il découvrit qu'il était très facile de contrôler les actions des zombies et d'en faire ce que bon lui semblait.", "Pendant les mois qui suivirent, Ner'zhul continua de faire des expériences avec sa peste mortelle en s'appropriant tous les habitants humains de Northrend. Son armée de morts-vivants grossissait chaque jour et il savait que l'heure de la confrontation véritable approchait." } } },
    ["Important Blackrock Documents"] = { { ids = { "i12562" }, first = "wyrmthalakihavebeengiven", pages = { "Wyrmthalak,\n\nj'ai reçu des ordres directs de votre maître, Nefarian. Je dois vous punir comme je le crois approprié si d'autres étrangers pénètrent dans la citadelle.\n\nN'oubliez pas qui commande, reptile.\n\nLe fils de Blackhand : Maître des épées et des combats. Le seul vrai Chef.\n\n-Rend" } } },
    ["In Loving Memory"] = { { ids = { "o181062" }, first = "anthonyraystark", pages = { "Anthony Ray Stark\n\n1961 - 2005" } } },
    ["Invar One-Arm"] = { { ids = { "o175778" }, first = "invaronearmthefirstchief", pages = { "Invar le Manchot\nPremier Chef des assassins de la Croisade écarlate\nCitoyen de Dalaran\nDisparu sur les rivages de Northrend" } } },
    ["Ironband's Progress Report"] = { { ids = { "i2637" }, first = "honorablecolleaguesandtr", pages = { "Estimés collègues et chercheurs de vérité\n\nLa fouille du site continue, mais elle est ralentie par les troggs que j'ai mentionnés dans mon dernier rapport. Je suis sûr que l'on peut s'occuper d'eux, même si certains de ces troggs sont plus agressifs que d'ordinaire.\n\nD'autres artefacts ont été exhumés dernièrement, mais dans tous les cas à l'exception d'un (dont je parlerai plus bas), les découvertes récentes ne sont pas du même intérêt que les précédentes.", "L'exception est la suivante : les idoles étrangement gravées que nous avons trouvées dernièrement (j'en ai communiqué une brève description dans mon dernier rapport) semblent affecter les troggs présents sur le site. Les marques sur la pierre les attirent, et certains troggs en deviennent fous furieux !\n\nD'autres études sont nécessaires avant qu'une conclusion ne soit atteinte en ce qui concerne ces idoles, mais j'ai bon espoir qu'elles révèlent un lien entre les troggs et les Titans.", "Enfin, je me dois de réitérer mes demandes de poudre. Mes stocks sont fort bas et cela fait peser un risque grave sur la réussite de ces fouilles. On m'a affirmé que de la poudre était en route, mais je n'ai toujours rien vu.\n\nSur quels délais dois-je compter ?\n\nRespectueusement,\nProspecteur Darteus Ironband" } } },
    ["Ironforge - the Awakening of the Dwarves"] = { { ids = { "o175736" }, first = "intheancienttimesafterth", pages = { "Aux temps anciens, après le départ des Titans loin d'Azeroth, leurs enfants, qu'on appelait les terrestres, continuèrent à façonner et à garder les confins du monde. Les terrestres ne se préoccupaient guère des espèces vivant en surface et ne souhaitaient que se plonger dans les profondeurs obscures de la terre.", "Lorsque le monde fut fissuré par l'implosion du Puits d'éternité, les terrestres en furent profondément affectés. Souffrant comme la terre elle-même, les terrestres perdirent une grande partie de leur identité et se scellèrent dans les chambres de pierre où ils avaient été créés. Uldaman, Uldum, Ulduar... Tels étaient les noms des anciennes villes des Titans où les terrestres avaient pris forme. Enfouis au plus profond du monde, les terrestres reposèrent en paix pendant presque huit mille ans.", "On ignore au juste ce qui les éveilla, mais les terrestres scellés dans Uldaman finirent par sortir de leur exil volontaire. Ces terrestres se rendirent compte qu'ils avaient beaucoup changé durant leur hibernation. Leur peau de pierre s'était adoucie jusqu'à devenir une peau fine et leurs pouvoirs sur la pierre et la terre s'étaient dissipés. Ils étaient devenus des créatures mortelles.", "Prenant le nom de nains, les derniers terrestres quittèrent les murs d'Uldaman et s'aventurèrent dans un monde qui s'éveillait. Toujours attirés par la sécurité des endroits souterrains, ils fondèrent un vaste royaume sous la plus haute montagne.", "Ils nommèrent leur terre Khaz Modan, ou \"Montagne de Khaz\", en l'honneur du Titan donneur de formes, Khaz'goroth. Pour bâtir un autel à la gloire du Titan leur père, les nains érigèrent une immense forge au coeur de la montagne. La ville qui s'étendait autour de la Forge prit désormais le nom d'Ironforge.", "Les nains, fascinés par nature par la taille des gemmes et des pierres, commencèrent à miner les montagnes environnantes à la recherche des précieuses ressources. Satisfaits de leur sort sous terre, les nains restèrent à l'écart de leurs voisins vivant à la surface." } } },
    ["Jitters' Completed Journal"] = { { ids = { "i2560" }, first = "myjournaltheterrorofthes", pages = { "Mon Journal\n\nLa terreur de ces dernières semaines est presque plus que je ne puis en supporter. Comment se fait-il qu'en rédigeant ces quelques mots je puisse en quelque sorte tenir la folie à distance ? C'est comme si je confessais mes fautes à quelque compagnon silencieux, ou libérais mes pensées torturées pour les confiner sur le papier.\n\nJ'ai commencé un journal avant celui-ci, mais il est resté à un endroit où je ne puis retourner. Je reprends donc tout du début. Mais du vrai début, cette fois-ci.", "Tout a commencé avec la découverte de cette maudite Faux au Destin de Roland. Avant la Faux, il n'y avait rien de plus terrible ici que dans la vallée de Northshire.\n\nMais depuis que j'ai trouvé la hampe de la Faux dans un tas de déchets de la mine et que, malédiction sur moi, je l'en ai extirpée, le Destin de Roland est devenu un lieu de mort impie !", "Si j'avais su ce qui allait se passer, je me serais coupé la main pour m'empêcher de récupérer ce morceau de bois gravé de runes. Je suis bourrelé de remords. J'ai toujours pensé que c'était le privilège des vieux. Je sais maintenant que ce ne sont pas les vieux, ce sont les sans-espoir, qui portent le fardeau du regret, incapables d'en débarrasser leurs misérables épaules.\n\nMais assez pleuré, je ne suis pas poète. Je dois continuer ma chronique...", "Après l'exhumation de la Faux, un changement s'est opéré dans la mine. La lumière a tremblé au bout de nos torches, et la force de nos voix a paru échapper à notre contrôle. Parfois le murmure d'un homme rugissait dans les tunnels, à en être assourdissant, parfois nos vociférations portaient à quelques pas seulement avant de s'évanouir dans l'air.\n\nEprouvant, certes, mais ces bizarreries ne sont rien en comparaison de ce qui nous a vraiment chassés de la mine. Les worgens.", "Ils ont surgi de partout, sortant de trous à nos pieds, tombant d'escarpements au-dessus de nos têtes. La moitié de nos hommes sont tombés dans ces premières minutes de panique. Les autres ont essayé de fuir. Moi aussi. Tout en courant, j'ai vu nombre de nos frères se faire déchiqueter, entendu bien des cris sombrer dans le silence après un gargouillis.\n\nPour autant que je sache, je suis le seul à en avoir réchappé.", "J'ignore comment j'ai survécu cette nuit-là. J'ai toujours été prudent, toujours rapide à fuir les plaies et les bosses. On me traite de froussard depuis toujours. C'est même pour ça qu'on m'a surnommé \"La Tremblote\". C'est peut-être ce fort instinct de conservation qui m'a sauvé...\n\nOu peut-être est-ce la Hampe que j'ai arrachée aux décombres. Ce ne peut-être la Faux elle-même, je l'ai perdue dans ma course éperdue. Mais si c'est moi qui ai ramené les worgens dans le bois de la Pénombre, peut-être m'ont-ils fait la grâce de me laisser survivre. Qu'ils soient maudits !", "Ou peut-être suis-je condamné à être le témoin des changements que j'ai attirés sur le bois de la Pénombre. Peut-être est-ce mon destin de voir les worgens déchirer cette terre en lambeaux et la plonger dans les ténèbres.\n\nSi tel est vraiment mon destin, alors il est double. Car les worgens ne sont pas la seule puissance à vouloir le bois de la Pénombre : les misérables du défilé de Deuillevent ont également leurs projets.\n\nCe sera le prochain chapitre de ma narration, et je souhaite que ce soit le dernier...", "Après avoir fui le Destin de Roland, je me suis caché dans une grange appartenant à un homme du nom de Sven. J'ai passé quelques jours dans la grange et une telle horreur me possédait que je n'ai jamais signalé ma présence à Sven ni à sa famille. Mais de ce que j'ai vu depuis ma cachette, j'ai compris que ces fermiers étaient d'honnêtes gens. Si j'étais sorti de mon recoin, je crois qu'ils m'auraient offert l'hospitalité, mais je ne suis pas d'un naturel confiant. Surtout depuis ce choc dans la mine.\n\nAlors je suis resté caché. Et cela a sauvé ma vie.", "Quelques jours après mon arrivée à la grange, Sven quitta sa ferme pour le Darkshire. Il embrassa sa femme et ses enfants et promit de revenir vite avec des jouets et des bonbons. Pauvre vieux ! Ce fut la dernière fois qu'il vit sa famille en un morceau.\n\nAu moins se sont-ils quittés heureux. Au moins sa femme a-t-elle été la première à mourir, sans devoir assister au meurtre de ses enfants. Mais je n'ai pas eu cette chance. J'ai vu ce qui s'est passé, et cela hantera mes rêves toute ma vie.", "Mes mains tremblent tandis que je bats le rappel des souvenirs de cette nuit, Sven au loin et sa famille seule face aux Cavaliers Noirs. Les regrets se saisissent à nouveau de moi, car j'aurais pu me dresser contre ces mécréants du défilé de Deuillevent. Mais c'est un faux regret. Tout rescapé d'une tragédie connaît les mêmes. Je le sais bien, si j'avais quitté ma cachette, j'aurais été tué aussi, mon corps dépecé, ses morceaux dispersés, mutilés, impossibles à reconnaître.", "Mais j'ai beau savoir que je ne pouvais rien faire pour empêcher ce massacre, un vrai regret me taraude : c'est moi qui ait attiré les Cavaliers Noirs jusqu'à la ferme de Sven. Non seulement ma découverte de la Faux a ouvert aux worgens la porte du bois de la Pénombre, mais elle a aussi attiré les Cavaliers jusqu'au défilé de Deuillevent.\n\nJe le sais parce que, juste avant de commencer leur boucherie, ils ont posé une question à la femme de Sven qui serrait ses enfants contre elle pour leur prodiguer le peu de réconfort qu'elle pouvait avant une mort certaine.", "\"La Faux d'Elune !\" hurla l'un des Cavaliers d'une voix dure et pourtant suraiguë, comme le feulement d'un fer de hache contre une pierre. Et il glapit le dernier mot, Elune, comme s'il butait dessus.\n\nLa panique s'est emparé de moi lorsque j'ai entendu cette voix, à cause de son timbre ignoble, et parce que... je savais de quelle Faux parlait le Cavalier. Ce ne pouvait être que l'objet maudit que j'avais arraché aux roches du Destin de Roland quelques jours plus tôt. C'est cela que cherchaient les Cavaliers Noirs !\n\nEt c'est cela qui scella le destin de la famille de Sven.", "J'ignore comment se nommait la femme de Sven, tant ils abusaient des \"chérie\", \"mon amour\" et autres \"maman\" dans la famille. Mais je voudrais le connaître. Je suis la mémoire vivante de ses gestes ce jour-là. Et bien qu'elle ne fût qu'une femme de fermier, je n'ai jamais vu quiconque se comporter avec plus de bravoure.\n\nBien sûr, elle ne savait rien de la Faux, mais quand elle a compris que les Cavaliers le cherchaient, un plan a germé dans sa tête.\n\nC'était audacieux et astucieux. Si seulement ça avait marché.", "\"La Faux ?\" a-t-elle dit d'une voix calme. \"Je sais tout, bien sûr. Comme tout le monde ici.\" Elle fixa les Cavaliers d'un regard posé et, si je n'avais pas su la vérité, j'aurais été convaincu qu'elle savait tout de la Faux.\n\nSon pari a fonctionné. Le Cavalier qui avait posé la question se pencha légèrement vers elle et a croassé : \"Où ?\"\n\n\"Je vais tous vous y conduire\", a-t-elle répondu, et une lueur d'espoir a dansé dans ses yeux.", "Mais c'est loin d'ici et mes enfants nous ralentiraient. Nous devons les laisser.\"\n\nSon plan était simple, mais ce sont les plans simples qui ont le plus de chances de fonctionner. Elle avait une chance d'éloigner les Cavaliers de la ferme. Elle n'avait aucun espoir pour sa propre vie mais ses enfants seraient sauvés. Il suffisait que les Cavaliers acceptent ses courageux mensonges.\n\nJe n'ai jamais été un adepte de la Lumière, mais j'ai prié pour la femme de Sven tandis qu'elle faisait face aux terribles Cavaliers.\n\n\"Par pitié\", ai-je prié. \"Faites qu'ils mordent à l'hameçon.\"", "Ils attendaient, immobiles, et elle soutenait leur regard avec calme. Soudain, un cavalier a levé la tête, comme s'il entendait un appel distant. Il a tiré d'une poche une petite gemme et a regardé dedans. Puis il a fait un geste avec la verroterie vers la femme de Sven. Une lumière a jailli du cavalier et s'est avancée vers la femme sous forme d'une main blanche. La fermière a regardé la lumière sans bouger, mais une nuance d'incertitude a fendillé son masque de confiance. Quand la main l'a atteinte, ses doigts se sont ouverts au-dessus de son crâne.\n\nPuis ils ont serré.", "La femme de Sven était comme pétrifiée et ses yeux se sont écarquillés. Ses lèvres se sont ouvertes pour pousser un cri, mais aucun son n'est sorti de sa bouche. Après quelques instants de cette torture, la main l'a relâchée et elle est tombée à genoux. Le Cavalier qui tenait la gemme se redressa sur sa selle et une voix forte retentit.\n\n\"Cette femme ment\", lâcha-t-il d'une façon qui hante encore mes cauchemars. \"Elle n'a pas vu la Faux.\"", "Après cela, les épaules du Cavalier se sont abaissées légèrement, comme si un esprit le quittait. Puis, de la voix stridente qu'il avait à son arrivée, il a prononcé ces derniers mots :\n\n\"Le Maître a parlé. Tuez-les.\"", "Je ne peux décrire ce qui s'est passé ensuite. C'est précis dans mon esprit, mais même mon âme misérable ne peut mettre par écrit les événements des terribles minutes qui suivirent.\n\nJe ne peux que dire que la famille de Sven est morte. Peu après, Sven est revenu sur les lieux de cette scène atroce. Il a éclaté d'une telle douleur que je n'ai pas eu le courage de me montrer. Et de peur qu'il ne me trouve, je me suis enfui de ma cachette dans la grange. J'ignore ce qu'il est advenu de Sven, mais je prie qu'un jour il trouve la paix.", "J'ai passé les quelques semaines suivantes à errer de lieu en lieu, toujours saisi par la peur des Cavaliers noirs. Je me trouve actuellement dans la ville abandonnée de Colline-aux-Corbeaux, caché, comme toujours. Je ne suis pas de taille à affronter la force qu'ils ont déployée contre la femme de Sven et je sais qu'ils fouillent toujours le bois de la Pénombre à la recherche de la Faux. Je ne l'ai plus, et j'en remercie la Lumière, car si je l'avais gardée, ils m'auraient trouvé. Même aujourd'hui, je sais au fond de moi qu'ils finiront par me trouver.\n\nJe suis si fatigué." } } },
    ["Jordan's Weapon Notes"] = { { ids = { "i6996" }, first = "beforeigoanyfurtherletme", pages = { "$N,\nAvant de continuer, laissez-moi vous remercier pour tout ce que vous avez fait pour ma femme et moi. Vous lui avez sauvé la vie et je ne pourrai jamais vous payer ma dette. Elle représente tout pour moi. Si elle était morte... Et bien, je ne sais pas ce que j'aurais fait.\n\nVoici la liste des choses que vous devez rassembler si vous voulez que je vous forge une arme sacrée. Je les ai mises dans l'ordre, de la plus simple à récupérer à la plus difficile, j'espère que ça vous aidera.", "Un peu de bon bois de chêne de blanchepierre - Avant qu'elles ne soient capturées, les mines sous Ruisselune dans la marche de l'Ouest ne manquaient pas de bois. On l'utilisait pour construire de grandes poutres et des outils à cause de sa résistance à la chaleur et à la pression.\n\nIl était transporté jusqu'ici par des bateaux. C'est un bois rare et suffisamment résistant pour être utilisé dans la construction d'armes. S'il en reste dans les mines, vous devrez le disputer aux gobelins.", "Minerai raffiné - Il y un nain dans Thelsamar, un forgeron qui m'entraîna jadis, il se nomme Bailor Stonehand. Il fait un alliage exceptionnel qui conviendrait parfaitement pour votre arme. J'espérais un arrivage d'alliage pendant que j'étais à Ironforge, mais je n'ai plus de nouvelles de mon maître.\n\nTrouvez-le et récupérez la marchandise. Et s'il n'est plus dans Loch Modan, je saurai au moins ce qui est arrivé à mon ancien Maître.", "Marteau de forge - Avant la venue de la Peste et la trahison d'Arthas, je vivais dans une ville nommée Bois-du-Bûcher au fond de la belle forêt des Pins argentés. La forêt n'est plus aussi magnifique qu'autrefois, et le donjon où j'ai appris les secrets de la forge a été corrompu il y a longtemps, submergé par des créatures incroyablement malfaisantes.\n\nLorsque ma femme et moi nous sommes échappés de ce qu'on appelle maintenant le donjon d'Ombrecroc, nous y avons laissé une partie de nos précieux biens.", "Notamment, le marteau de forge que mon père m'avait offert. J'en ai toujours douté, mais il ne cessait de répéter qu'il était enchanté. C'est le seul souvenir qu'il me reste de lui, maintenant qu'il a été tué par le Fléau.\n\nRapportez-moi mon marteau, $N, que je puisse m'en servir pour exprimer ma passion. S'il est vraiment enchanté, il nous sera à tous les deux utile.\n\nJe l'ai laissé dans l'écurie qui se trouve dans la première cour de la forteresse. À moins que les créatures qui y résident ne soient des forgerons, il doit toujours être là-bas, quelque part.", "Une gemme de Kor - D'après les contes que j'ai entendus, les gemmes sont utilisées par des lanceurs de sorts pour contenir l'énergie dont leur magie a besoin, ce qui la rend plus mortelle encore. Un elfe de la nuit que j'ai aidé, Thundris Windweaver, vous en dira plus si vous l'interrogez en mon nom. Je crois que l'une des énergies des gemmes peut servir à la création de votre arme.\n\nLorsque nous avons parlé pour la dernière fois, Thundris était à Auberdine, au fond de Sombrivage, la forêt corrompue qui longe la côte et la terre natale des elfes de la nuit." } } },
    ["Journal Page"] = { { ids = { "i5839" }, first = "itneverceasestoamazemeho", pages = { "J'ai toujours été surpris de voir comment il était simple de manipuler les gens en exploitant la haine qu'ils ont développée à l'encontre des autres races. Les orcs et les trolls furent les premiers, la haine qu'ils éprouvent pour l'Alliance en faisait des sujets privilégiés et attentifs au message de la Rive noire. Sont-ils au courant des desseins qu'ils servent ?\n\nCe paladin exaspérant, Delgren le Purificateur, a mis son nez dans nos affaires dans la forêt d'Ashenvale, pendant que son laquais, Balthule, espionnait ma tour en pensant que je n'étais au courant de rien. Delgren pense que nous représentons une menace", "mineure, comme tant d'autres cultes de la mort. Il n'a pas la moindre idée que nous sommes l'une des... branches du Conseil des ombres.\n\nQuand j'étais enfant, on m'a parlé d'un insecte dont la morsure était mortelle, bien qu'il soit de la taille d'une mouche, une tache à peine reconnaissable. Ce sont les choses que l'on néglige qui vous infligent les pires souffrances." } } },
    ["Kearnen's Journal"] = { { ids = { "i8046" }, first = "theguardsofthistowerseem", pages = { "Les gardes de cette tour me semblent répondre faiblement à mes attaques. Alors que j'explorais l'arrière de la tour, un patrouilleur m'a repéré et m'a attaqué. Je me suis facilement débarrassé de ce garde en combinant une saignée puis un garrot.\n\nJe me suis caché en attendant que son partenaire s'approche pour voir de quoi il retournait. Le patrouilleur commença à fouiller les buissons où j'avais tiré le corps. Je me suis placé derrière lui tout doucement, afin que mon embuscade soit un succès.", "Lorsque j'en ai eu l'opportunité, je lui ai enfoncé ma dague dans le dos ! Ses poumons cessèrent brusquement leur activité sous la force de l'attaque et son corps s'écroula avec un bruit sourd.\n\nLe coup fut si rapide et violent que le pauvre bougre n'a pas eu le temps de pousser un cri. Bizarrement, lorsque j'ai retiré la lame de son dos, une odeur fétide s'échappait du patrouilleur perforé.", "Il semble que ce que Klaven a enfermé dans le coffre ait des effets nocifs sur les habitants de la tour. Je pense que les autres gardes souffrent des mêmes faiblesses. Peut-être que Klaven lui-même en subit les conséquences.\n\nAgent Amber Kearnen\nAgent de terrain du SI:7, R8" } } },
    ["Kel'Thuzad and the Forming of the Scourge"] = { { ids = { "o175754" }, first = "therewereahandfulofpower", pages = { "Des individus puissants, un peu partout dans le monde, entendirent la convocation mentale du roi-liche. Le plus notable d'entre eux fut l'archimage Kel'Thuzad, de la nation magique de Dalaran. Kel'Thuzad, l'un des membres les plus anciens du Kirin Tor, le conseil suprême de Dalaran, était considéré comme un original depuis des années : ne désirait-il pas étudier les secrets interdits de la nécromancie ?", "Ayant appris tout ce qu'il pouvait sur le monde magique et ses merveilles, il était frustré par ce qu'il considérait être, chez ses pairs, un manque d'imagination et du conservatisme. En entendant les puissants appels de Northrend, l'archimage mit toute sa volonté à communiquer avec la voix mystérieuse. Convaincu que le Kirin Tor était trop immobiliste pour se saisir du pouvoir et de la connaissance des arts obscurs, il décida de se vouer à apprendre tout ce qu'il pourrait du puissant roi-liche.", "Laissant là sa fortune et sa prestigieuse position politique, Kel'Thuzad abandonna la manière de vivre du Kirin Tor et quitta Dalaran à jamais. Attiré par la voix persistante du roi-liche qui résonnait dans son cerveau, il vendit ses nombreux biens et mit sa fortune à l'abri. Voyageant seul sur des centaines de lieues, sur terre comme sur mer, il atteignit finalement les rivages glacés de Northrend.", "Désireux d'atteindre la Couronne de glace et d'offrir ses services au roi-liche, l'archimage traversa les ruines ravagées par la guerre d'Azjol-Nerub. Kel'Thuzad constata de visu l'étendue et la cruauté des pouvoirs de Ner'zhul. Il réalisa petit à petit que s'allier avec le mystérieux roi-liche serait sage, mais pourrait aussi s'avérer fructueux.", "Après de longs mois de marche dans les plaines désertiques et glacées, Kel'Thuzad atteignit finalement le glacier noir de la Couronne de glace. Il approcha bravement de la sombre citadelle de Ner'zhul et fut ébahi de voir les sentinelles mortes-vivantes s'écarter silencieusement pour le laisser passer, comme s'il était attendu.", "Kel'Thuzad descendit dans les profondeurs de la terre froide et trouva son chemin jusqu'au bas du glacier. Là, dans l'immense caverne de gel et d'ombres, il se prosterna devant le Trône de glace et offrit son âme au noir seigneur des morts.", "Le roi-liche se montra satisfait de sa nouvelle recrue. Il promit à Kel'Thuzad l'immortalité et un grand pouvoir en échange de sa loyauté et de son obéissance. Kel'Thuzad, désireux d'apprendre le savoir obscur, accepta sa première grande mission : retourner au monde des hommes et fonder une nouvelle religion qui adorerait le roi-liche comme un dieu.", "Pour aider l'archimage dans sa mission, Ner'zhul ne toucha pas à l'humanité de Kel'Thuzad. Le magicien, âgé mais toujours charismatique, utilisa ses pouvoirs d'illusion et de persuasion pour s'attirer la confiance des démunis et des laissés-pour-compte de Lordaeron. Leur attention captée, il leur offrit une vision nouvelle de ce que pourrait être la société, ainsi qu'une nouvelle idole à adorer.", "Kel'Thuzad retourna sous un déguisement à Lordaeron, et en l'espace de trois ans, il utilisa sa fortune et son intelligence pour fonder une fraternité clandestine d'hommes et de femmes à son image. La fraternité, qu'il appela Culte des damnés, promit à ses membres l'égalité sociale et la vie éternelle sur Azeroth en échange de leurs services et de leur obéissance à Ner'zhul.", "Au fil des mois, Kel'Thuzad trouva de nombreux volontaires enthousiastes pour son culte parmi les travailleurs épuisés et saignés à blanc de Lordaeron. Etrangement, le but de Kel'Thuzad fut atteint facilement : la foi des citoyens en la Lumière se transforma rapidement en culte des pouvoirs obscurs de Ner'zhul. Tandis que le Culte des damnés augmentait en taille et en influence, Kel'Thuzad continua de se cacher aux yeux des autorités de Lordaeron.", "Kel'Thuzad ayant réussi à Lordaeron, le roi-liche s'occupa des ultimes préparatifs de son assaut contre la civilisation humaine. Il enferma sa peste dans de nombreux artefacts portables nommés chaudrons du fléau, puis ordonna à Kel'Thuzad de transporter les chaudrons vers Lordaeron où ils seraient placés dans différents villages contrôlés par le culte.", "Les chaudrons, protégés par les adeptes fidèles du Culte, allaient devenir des générateurs de peste et la répandre dans les fermes et les villes du nord de Lordaeron.", "Le plan du roi-liche fonctionna parfaitement. De nombreux villages du nord de Lordaeron furent atteints presque immédiatement. Tout comme à Northrend, les citoyens contaminés moururent et se relevèrent sous la forme d'esclaves fidèles du roi-liche.", "Les adeptes conduits par Kel'Thuzad avaient hâte de mourir et de renaître au service de leur sombre maître. L'immortalité dans la mort les exaltait. Tandis que la peste prenait de l'ampleur, de plus en plus de zombies sauvages se dressaient dans les terres du Nord. Kel'Thuzad regarda l'armée croissante du roi-liche et lui donna le nom de Fléau, un fléau qui allait bientôt marcher sur Lordaeron... et éliminer l'humanité de la surface de la terre." } } },
    ["Keldara's Log"] = { { ids = { "i221017" }, first = "dayibelieveivediscovered", pages = { "Jour 14 :\n\nJe crois avoir découvert un moyen de défaire la corruption apportée ici par les satyres : une teinture brassée à partir de leur propre fléau !\n\nAvec des échantillons de la satyrienne des environs, on pourrait préparer un extrait qui protège d'une corruption totale grâce à une exposition à une dose plus faible. On pourrait presque y voir une sorte d'antivenin.\n\nJ'aimerais tester mon remède sur la faune locale, mais les bêtes d'ici sont trop agressives. Si seulement je pouvais les tranquilliser d'une manière ou d'une autre." } } },
    ["Khazgorm's Journal"] = { { ids = { "i5006" }, first = "theexcavationofbaelmodan", pages = { "L'Excavation de Bael Modan\n\nL'équipe de surveillance envoyée par la Ligue des explorateurs avait raison. Le sol contient des objets d'une valeur inestimable pour notre peuple. Il est certain que nous trouverons de nombreuses réponses en fouillant le sable et les pierres de Bael Modan.\n\nLa géologie de la région nécessite cependant d'être très prudent. La plupart des dépôts de sable se sont solidifiés sous l'effet de conditions climatiques difficiles et changeantes.", "La solution est cependant assez simple. En utilisant de la pulpe de bois en guise d'absorbant, nous pouvons combiner les traces de nitroglycérine avec du nitrate de sodium afin de développer une puissante charge explosive, capable de transpercer même les masses les plus denses.\n\nLe travail sera bruyant et causera des perturbations mais notre recherche est de loin plus importante que le confort de la population locale. En fait, nous avons déjà dû déplacer une bande d'hommes taureaux, qui se sont avérés être une nuisance.", "Le fait que nous ayons déjà rencontré des problèmes avec quelques éléments imprévisibles me laisse à penser que nous aurons sans doute besoin de l'aide de l'armée du roi. Non seulement l'excavation nécessite un soutien militaire, mais il me semble, autant que je puisse en juger, que l'emplacement de Bael Modan représente une importance stratégique pour l'Alliance, si on considère la situation politique instable.\n\nMais je m'égare. Il y a un travail énorme à accomplir sous la roche. J'ai passé trop de temps à écrire alors que j'aurais dû l'employer à creuser..." } } },
    ["Kil'jaeden and the Shadow Pact"] = { { ids = { "o175741" }, first = "aroundthetimeofmedivhsbi", pages = { "À l'époque de la naissance de Medivh, Kil'jaeden le Menteur était assis et ruminait parmi ses serviteurs dans le Néant distordu. Le seigneur démon, sous les ordres de son maître Sargeras, préparait la seconde invasion d'Azeroth par la Légion ardente.", "Cette fois-ci, aucune erreur ne serait autorisée. Kil'jaeden se dit qu'il avait besoin d'une nouvelle force pour affaiblir les défenses d'Azeroth avant que la Légion ne mette le pied sur le monde. Si les races mortelles, comme les elfes de la nuit et les dragons, étaient forcées de repousser une nouvelle menace, elles seraient trop affaiblies pour opposer une véritable résistance à l'arrivée de la Légion.", "C'est à cette époque que Kil'jaeden découvrit le monde luxuriant de Draenor qui flottait paisiblement dans le Grand Au-delà Sombre. Terre des orcs chamaniques et des paisibles draeneï, Draenor était aussi idyllique que vaste.", "Les nobles clans orcs régnaient sur les prairies et chassaient par sport, tandis que les curieux draeneï construisaient des villes grossières sur les monts et les pics du monde. Kil'jaeden savait que les citoyens de Draenor avaient un grand potentiel et pouvaient servir la Légion ardente si on les dirigeait de façon appropriée.", "Des deux races, Kil'jaeden comprit que les guerriers orcs étaient les plus sensibles à la corruption de la Légion. Il ensorcela le plus ancien des chamans orcs, Ner'zhul, de la même manière que Sargeras avait pris le contrôle de la reine Azshara par le passé. Utilisant ce chaman rusé comme conducteur, le démon répandit le goût du sang et la sauvagerie dans les clans des orcs.", "Rapidement, la race spirituelle était devenue un peuple assoiffé de sang. Kil'jaeden poussa Ner'zhul et son peuple à franchir la dernière étape : s'abandonner complètement à la recherche de la mort et de la guerre. Mais le vieux chaman, sentant que son peuple deviendrait à jamais esclave de la haine, résista aux ordres du démon.", "Frustré par la résistance de Ner'zhul, Kil'jaeden chercha un autre orc qui livrerait son peuple à la Légion. Rusé, le seigneur démon finit par trouver le disciple docile qu'il cherchait : l'ambitieux apprenti de Ner'zhul, Gul'dan. Kil'jaeden promit à Gul'dan une puissance sans borne en échange de son obéissance absolue.", "Le jeune orc devint l'avide étudiant de la magie démoniaque et devint le plus puissant démoniste mortel jamais connu. Il apprit à d'autres jeunes orcs les arts des arcanes et tenta d'éradiquer les traditions chamaniques des orcs. Gul'dan enseigna une nouvelle sorte de magie à ses frères, un terrible pouvoir qui empestait le mal.", "Kil'jaeden, cherchant à renforcer sa mainmise sur les orcs, aida Gul'dan à fonder le Conseil des ombres, une secte secrète qui manipulait les clans et diffusait l'utilisation de la magie démoniaque à travers Draenor. Comme de plus en plus d'orcs commençaient à maîtriser la magie des démonistes, les champs paisibles de Draenor commencèrent à s'assombrir. Avec le temps, les vastes prairies que les orcs avaient habitées pendant des générations disparurent pour laisser place à un sol rouge et nu. Les énergies démoniaques tuaient lentement le monde." } } },
    ["King Llane I of the House of Wrynn"] = { { ids = { "o177200" }, first = "kingllaneiofthehouseofwr", pages = { "Roi Llane Ier de la maison de Wrynn\n\nSuzerain de Stormwind\n\nDéfenseur d'Azeroth" } } },
    ["Klaven Mortwake's Journal"] = { { ids = { "i7908" }, first = "theventurecompanyitwould", pages = { "La KapitalRisk <texte illisible> Il semble que ces imbéciles ont presque réussi à anéantir toute l'opération en essayant de stabiliser la mixture.\n\n<plusieurs pages semblent avoir été déchirées. >", "Ce que j'ai remarqué, c'est que le résultat est extrêmement mortel. Imaginez si <texte illisible> Hahaha !", "Est-ce que je deviens fou ? Aujourd'hui j'ai coupé la tête de l'un de mes plus fidèles patrouilleurs afin d'avoir un meilleur aperçu de son âme. Alors que je regardais la trachée sectionnée, je me disais que je n'avais pas mangé depuis des jours !", "Mathias Shaw a envoyé un garçon de courses pour me tuer. <texte illisible>\n\\Il patrouille dehors maintenant. Pantins sans âme et sans vie.\n\nHahahah !", "VanCleef...<texte illisible>\n\nM'a fait appeler ? POUR QUI SE PREND-IL ? Je suis Klaven Mortwake ! Ce n'est pas un insecte qui va me dire ce que je dois faire !\n\n<les autres pages du livre ont disparu>" } } },
    ["Kodo Skin Scroll"] = { { ids = { "i5838" }, first = "tofacefrostmawyoumustent", pages = { "Pour faire face à Gueule-glacée, vous devez l'attirer avec la viande de sa proie favorite.\n\nRendez-vous dans les montagnes d'Alterac en Azeroth, et chassez un lion des montagnes massif. Tuez-le et rapportez sa carcasse à la Caverne stérile, un endroit sacré pour le wendigo bestial.\n\nPlacez la carcasse sur la Flamme d'Uzel et l'odeur de la viande en train de cuire se répandra.\n\nGueule-glacée ne tardera pas." } } },
    ["Kravel's Parts Order"] = { { ids = { "i5799" }, first = "ordernumbertkbuyerkravel", pages = { "NUMÉRO DE COMMANDE : \"45TK-3\nACHETEUR : Kravel Koalbeard\n\nFACTURE :\n\nRoue à rochet hydroélectrique (3)\nBoulons à répétition (50)\nTubes de cuivre diamètre 20 30\"(12)\nTabac à priser, marque Deepfury (1)\nPrisme de premier choix (3)\"" } } },
    ["Kravel's Scheme"] = { { ids = { "i5826" }, first = "mrfizzlebubthebearerofth", pages = { "M. Fizzlebub,\n\nLe porteur de cette lettre et moi-même avons un projet commercial auquel nous vous proposons de vous joindre.\n\nComme vous le savez, j'ai passé beaucoup de temps dans les Salines. Le projet évoqué concerne les courses qui s'y déroulent.\n\nSi vous participez aux courses, et plus particulièrement si parier sur ces courses vous intéresse, continuez la lecture de ce document. Je suis certain que votre connaissance de Strangleronce sera très utile pour notre plan.", "Les chariots explosifs qui disputent les courses des salines nécessitent des réglages et un entretien très pointus. Il n'est donc pas étrange d'apercevoir les équipages dans les environs.\n\nIls testent leurs véhicules régulièrement et font des réglages lorsqu'une modification est nécessaire. C'est le seul moyen de conserver les véhicules en très bon état et performants.\n\nDonc... Nous recherchons un moyen de distraire les équipages afin qu'ils relâchent leur vigilance sur les véhicules, sans entretien, ils seront vite hors compétition.", "Si nous pouvons décider quels chariots sont en bon état et lesquels ne le sont pas, inutile de vous expliquer que nous aurons un sérieux avantage.\n\nDonc, mon bon Fizzlebub, nous avons besoin de quelque chose qui pousserait les équipages des chariots à faire des erreurs.\n\nEst-ce que Strangleronce possède des plantes, des herbes ou une boisson que nous pourrions utiliser pour perturber l'esprit des gnomes et des gobelins ?\n\n--K. Koalbeard" } } },
    ["Kristof's Report"] = { { ids = { "i286201" }, first = "executorzyganditismyopin", pages = { "Executor Zygand,\n\nIt is my opinion that the Scourge we see further inland are not due to our defenses failing. I have witnessed our forces at the Bulwark and eastern waypoint for some time now, and it would take a veritable army to break through.\n\nRather, I suspect they are being newly created by some unseen enemy within our borders. I will continue to pull on this thread, in hopes that we may stop these occurrences at the source.\n\n--Kristof" } } },
    ["Kurdran Wildhammer"] = { { ids = { "o25329" }, first = "kurdranwildhammerrenowne", pages = { "Kurdran Wildhammer\n\nChasseur de dragons réputé. Maître des gryphons du Nid-de-l'Aigle. Commandant des chevaucheurs de gryphons attachés à l'expédition de l'Alliance qui a marché sur le monde des orcs, Draenor. Présumé mort.\n\nNous entendrons l'appel de Sky-Ree dans le vent. Nous entendrons le tonnerre de ton marteau résonner dans les montagnes. Chevauche hardiment dans l'après-vie, frère ! Les salles de nos ancêtres t'attendent.\n\n- Falstad Wildhammer - Seigneur du Nid-de-l'Aigle" } } },
    ["Lady Mara Fordragon"] = { { ids = { "o177202" }, first = "ladymarafordragonhighcle", pages = { "Dame Mara Fordragon\n\nGrande prêtresse de Stormwind\n\nProtectrice des réfugiés qui ont fui vers Lordaeron après la Première Guerre.\n\nElle fut la mère lumineuse de notre avenir. Puisse-t-elle reposer dans la Lumière." } } },
    ["Laird's Response"] = { { ids = { "i16263" }, first = "nessaitisgoodtohearfromy", pages = { "Nessa,\n\nquel bonheur d'avoir de vos nouvelles.\n\nLes ossements et les écailles que vous m'avez envoyés forment un incroyable ensemble ! Je n'avais jamais vu de poisson de cette taille. Les pêcheurs des Rut'theran doivent pouvoir récupérer sans mal une tonne de poissons chaque jour !\n\nJ'envie l'ampleur de leurs profits, mais quelque chose me trouble néanmoins. Notre nouvel Arbre monde pourra-t-il faire croître des poissons de cette taille ? Si c'est le cas, quels autres effets aura-t-il ?\n\nVoilà des questions à approfondir,\n-Laird" } } },
    ["Legacy of the Aspects"] = { { ids = { "i5860" }, first = "ihavedoneagreatdealofres", pages = { "J'ai mené de grandes recherches concernant les Aspects et leurs créateurs titanesques, plus qu'aucun homme ne peut en mener en toute une vie. Il y avait cinq Aspects lorsque les Titans quittèrent ce monde. C'étaient de puissants dragons dont la tâche consistait à protéger le monde d'Azeroth. Les récits les concernant sont nombreux et variés. Maintenant, encore, malgré toutes les informations que j'ai pu réunir, je suis convaincu qu'il reste tout à apprendre à propos de ces magnifiques créatures.", "La plupart des connaissances que je possède maintenant, je n'aurais pas pu les apprendre tout seul. C'est pour cela que je suis extrêmement reconnaissant aux elfes de la nuit. C'est grâce à eux que j'ai pu obtenir autant de détails. Suite à nos échanges, je suis de plus en plus intimement convaincu qu'au commencement ils étaient bien plus proches des Aspects que je ne le pensais. Mais leurs secrets sont si bien gardés que je ne peux rien affirmer.", "Les informations que j'ai réunies à propos des Aspects, je les laisse ici afin que d'autres puissent s'y référer à l'avenir. Je sais qu'elles seront utiles car les dragons sont destinés à jouer un rôle de plus en plus important au fur et à mesure que notre monde évolue.", "Alexstrasza :\nAlexstrasza, l'ancienne et puissante reine des dragons, était surnommée la Lieuse de vie par les Titans. Elle fut la première à être créée par les Titans pour protéger le monde lorsqu'ils le quittèrent. On raconte qu'elle a été témoin de la naissance de toutes les races qui virent le jour sur Azeroth. Sa noble silhouette, renommée pour son allure majestueuse, commandait à tous les draconiens.", "Des rumeurs chez les elfes de la nuit racontent qu'Alexstrasza et le demi-dieu Cénarius sont des amis proches et que c'est lui qui fit appel à elle lors de la première invasion de la Légion ardente.", "Ysera :\nYsera la Rêveuse représente le subconscient des mortels. Elle protège le Rêve d'émeraude. Bien qu'elle apprécie l'imagination, la création et l'ambition des races mortelles, elle et sa meute considèrent le monde réel comme une illusion. Ysera est l'une des plus puissantes et gracieuses créatures que les mortels puissent observer.", "Malygos :\nMalygos est connu sous le nom d'Intendant de la magie ou de Tisseur de sort. Sa forme naturelle n'est pas celle d'un dragon typique et on raconte qu'il peut en changer à volonté. On l'a rarement aperçu depuis qu'il a établi sa retraite loin au nord et il passe son temps sous la forme d'une créature insectoïde. Mais, lorsqu'il reprend sa forme de dragon, il commande à une meute de la couleur du ciel.", "Nozdormu :\nNozdormu est connu comme étant le Gardien du temps ou l'Éternel. Sa meute et lui sont de la couleur du bronze et font preuve d'une grande habileté dans tous les domaines. Nozdormu s'est toujours concentré sur la recherche d'objets du passé. Il ne se soucie guère des histoires des mortels, même si elles concernent les Aspects. L'indifférence qu'il témoigne vis-à-vis de la politique des autres races ne veut pas dire qu'il reste indifférent aux événements qui influencent le monde.", "Considérés comme les protecteurs, les dragons de bronze furent attirés par les zones civilisées. Le dragon et ses pairs sont très patients de nature et ils privilégient l'observation, puis l'action avec un plan bien pensé, plutôt que la précipitation. Nozdormu se dressera toujours pour protéger le cours du temps et les mortels s'ils sont menacés par de puissants ennemis.", "Neltharion :\nNeltharion, appelé le Gardien depuis sa création, était le dragon protecteur le plus loyal à Azeroth parmi tous les Aspects. Sa meute de dragons noirs était responsable de la création de toutes les montagnes et des autres excroissances terrestres, y compris les frontières naturelles entre les différents royaumes des races mortelles. Les événements qui le rendirent maléfique sont méconnus. Peut-être une influence externe ou une gangrène intérieure. Je me demande si les Dieux très anciens ne sont pas en partie responsables de ce changement de comportement.", "Le dragon noir subit une transformation complète qui marqua la fin de l'existence de Neltharion. Il devint à la place Aile de mort, une créature mauvaise et haineuse. Il n'était plus le Gardien et les elfes l'appelèrent Xaxas pour remplacer le nom que lui avaient donné les Titans. Aile de mort est l'incarnation du chaos et du mal, et sa soif de destruction est insatiable. Il est sans doute la première réapparition maléfique sur Azeroth depuis l'époque où les Dieux très anciens furent bannis." } } },
    ["Legends of the Gurubashi, Volume 3"] = { { ids = { "i3899" }, first = "legendsofthetrollsvolume", pages = { "LEGENDES DES TROLLS, VOLUME III\nLa Pierre des marées\n\nDe la main de\nl'archimage Ansirem Runeweaver\nDalaran\n\nINTRODUCTION\n\nL'ancien empire Gurubashi fut une source de bien des légendes étonnantes et fascinantes qui nous renseignent sur l'environnement de ses sujets, car l'examen de leurs croyances et de leurs pratiques sociales montre leur grand respect pour leur environnement naturel.\n\nJ'ai détaillé les", "aspects de leur culte des serpents dans les précédents volumes de cette étude, mais je vais aborder ici l'examen des rapports uniques et passionnants des trolls avec la mer.\n\nLA GRANDE MER\n\nL'empire Gurubashi était entouré d'océans sur trois frontières. Rien d'étonnant à ce que l'eau ait constitué un aspect important de leur société. Les trolls ont été capables de soumettre de larges pans de leur monde forestier, mais la mer leur a toujours posé problème. Elle était vaste, incommensurable, représentait", "sans doute un voisin déconcertant pour les puissants trolls.\n\nDe récentes découvertes suggèrent que les trolls ne se sentaient pas le désir d'explorer les terres situées au-delà de la Grande Mer. Bien que des espèces de trolls soient disséminées partout dans tout Azeroth, Khaz Modan et Lordaeron, on n'a guère trouvé de traces de leur civilisation dans les terres nouvellement découvertes de Kalimdor ni dans les îles des Mers du Sud. Cela démontre-t-il le désir des trolls", "de ne pas s'éloigner de leur territoire terrestre ou une incapacité à développer la technologie nécessaire à entreprendre un tel voyage ? Cela demande d'autres recherches, qui dépassent le cadre de mon étude.\n\nMais on peut difficilement ignorer une présence si large, et de nouvelles trouvailles dans les ruines de la vallée de Strangleronce montrent un aspect de leur relation avec la mer que nous ignorions jusque là.\n\nLA PIERRE DES MAREES\n\nDe récentes découvertes pendant les fouilles dans", "les ruines trolls de Strangleronce ont montré des références à un objet nommé la \"Pierre des marées\". De nombreux fragments des légendes des trolls peuvent être assemblés pour obtenir une image assez précise de la pierre et de son importance dans l'ancien empire Gurubashi.\n\nIl semble que la Pierre des marées ait permis à celui qui la portait de contrôler l'eau dans ses nombreuses formes (rivières, pluie, marées). En raison des histoires narrant le fonctionnement de la Pierre des marées, je pense qu'il s'agit", "en fait d'une manifestation physique des puissances du seigneur des Eaux, un puissant élémentaire des mers. De quelle manière cet objet permettait-il le contrôle du seigneur des Eaux et comment est-il tombé entre les mains des trolls, c'est une autre question qui dépasse mes connaissances.\n\nLE PORTEUR DES MARÉES\n\nComme l'eau sur les rivages, la Pierre des marées entrait dans le monde des trolls et en repartait, ne restant jamais entre les mains des trolls pour plus d'une génération à la suite.", "Dans les légendes des trolls, on dit que la première fois que la Pierre des marées est entrée dans l'empire Gurubashi, elle a été trouvée par un guerrier troll errant le long de la côte de Strangleronce. Il est tombé sur une mystérieuse pierre bleue dans laquelle des fibres d'un blanc laiteux flottaient. Intrigué par la pierre, le guerrier la prit avec lui et continua sa route.\n\nAu cours des semaines et des mois qui suivirent, le guerrier découvrit que la pierre lui conférait le contrôle de l'eau. Il pouvait invoquer des", "élémentaires d'eau, des créatures formées entièrement d'eau, égalant par là même les plus puissants mages du Kirin Tor.\n\nLe guerrier alla jusqu'à Zul'Gurub, au coeur de l'Empire, pour faire la démonstration de ses capacités nouvelles à l'Empereur. Il obtint facilement une audience après avoir démontré l'étendue de ses pouvoirs au centre de la capitale impériale. Ses pouvoirs éblouirent l'empereur Gurubashi, qui lui donna immédiatement une place d'honneur à la cour, surnommant le guerrier \"Porteur des marées\", de sorte que son vrai nom", "ne nous est plus connu.\n\nPendant des années, le Porteur des marées servit l'empire Gurubashi, invoquant ses élémentaires d'eau au combat et manipulant les flux aquatiques de la vallée de Strangleronce au profit de l'Empire. Mais alors que les années passaient, le Porteur des marées se fit plus solitaire, restant de longues périodes de temps loin de la cour.\n\nLe Porteur des marées cachait un secret aux yeux inquisiteurs de la Cour. Les capacités qui lui étaient conférées par la Pierre des marées étaient accompagnées d'une malédiction. Au fur et à mesure du passage du temps,", "le Porteur des marées s'effaçait. A chaque reflux de la marée, il disparaissait un peu plus, perdant sa forme corporelle progressivement. Sentant venir son agonie, il partit vers la plage où il avait trouvé la Pierre et disparut dans la mer.\n\nDes générations plus tard, la Pierre des marées réapparut sur les rivages de Strangleronce, et un autre Porteur des marées fut choisi tandis que les trolls rapportaient la Pierre à", "Zul'Gurub. Cela continua ainsi pendant des générations, la Pierre venant avec la marée et le Porteur disparaissant avec elle.\n\nDes histoires contemporaines sur la Pierre des marées se font jour de temps en temps, mais on se demande toujours pourquoi un objet d'une telle puissance apparaîtrait si régulièrement, et sur la volonté de qui." } } },
    ["Lethargy of the Orcs"] = { { ids = { "o175751" }, first = "monthspassedandmoreorcpr", pages = { "Au fil des mois, de plus en plus d'orcs furent envoyés dans les réserves. Les premières réserves étant saturées, l'Alliance dut en créer de nouvelles dans les plaines qui s'étendent au sud des montagnes d'Alterac. Pour entretenir ces réserves, le roi Terenas fut contraint d'imposer une nouvelle taxe aux nations de l'Alliance.", "Cet impôt, en plus des tensions politiques nées des disputes territoriales, fut à l'origine d'une importante dissension parmi les chefs de l'Alliance. Le pacte fragile qui rassemblait les nations humaines à l'heure du péril menaçait d'être rompu à tout instant.", "Alors que la politique commençait à reprendre le dessus, plusieurs des surveillants des réserves remarquèrent des changements inquiétants dans le caractère des orcs dont ils avaient la charge. Les orcs tentaient de moins en moins souvent de s'échapper des réserves et ils semblaient même perdre leur esprit combatif.", "Cela semblait difficile à croire, mais les orcs, que l'on tenait pour la race la plus agressive jamais vue sur Azeroth, étaient tombés dans une sorte de léthargie. Cette nouvelle surprenante pour les chefs de l'Alliance était beaucoup plus inquiétante pour les orcs eux-mêmes, dont la population fondait à vue d'oeil.", "Certains émirent l'hypothèse qu'une maladie, que ne pourraient contracter que les orcs, était à l'origine de cette léthargie. Mais l'archimage Antonidas de Dalaran proposa une hypothèse plus réaliste. En étudiant l'histoire des orcs, Antonidas découvrit qu'ils étaient tombés sous l'influence d'une puissance démoniaque depuis plusieurs générations.", "Il pensait que les orcs avaient été corrompus par les puissances démoniaques bien avant leur première tentative d'invasion d'Azeroth. Il était évident que des démons avaient corrompu le sang des orcs, ce qui leur conférait leur force, leur endurance et leur agressivité inhabituelles.", "Antonidas émit la théorie que la léthargie des orcs n'était pas une maladie, mais qu'elle était liée au fait que la corruption démoniaque qui les habitait depuis des générations commençait à disparaître.", "Les symptômes étaient évidents, mais Antonidas n'avait aucun remède à proposer. Plusieurs autres mages, ainsi que certains chefs de l'Alliance, estimèrent que trouver un remède serait peut-être même une idée imprudente. Continuant d'observer les orcs et leur mystérieuse condition, Antonidas finit par en conclure que le seul remède possible ne saurait être que spirituel." } } },
    ["Letter to Delgren"] = { { ids = { "i5354" }, first = "masterdelgrenitisasyoufe", pages = { "Maître Delgren,\n\nC'est ce que vous craigniez. Votre théorie sur la Tour d'Althalaxx s'avère vraie. Un culte se rassemble dans la Tour d'Althalaxx, comptant bien des démonistes et même un satyre. Ils ont pris le nom de Culte de la Rive noire. Je ne puis imaginer quels vils desseins les rassemblent, mais cela m'inquiète.\n\nVeuillez excuser le laconisme de cette missive, mais le danger rôde dans la forêt qui m'entoure et je dois décrire la situation en peu de mots. Je", "vous aurais remis ce message moi-même, mais je préfère rester où je suis, de peur de manquer un événement important.\n\nSi vous voulez en savoir plus sur mes observations concernant la Tour d'Althalaxx, le porteur de ce message m'a été d'une aide précieuse pendant mes recherches et je pense que l'on peut lui faire confiance.\n\nEn hâte,\nBalthule Shadowstrike" } } },
    ["Letter to Ello"] = { { ids = { "i1637" }, first = "thelettersonthisnoteseem", pages = { "Les lettres, sur cette note, semblent bouger et danser sur le papier. Il est impossible d'en tirer le moindre sens." } } },
    ["Letter to Jin'Zil"] = { { ids = { "i5594" }, first = "jinzilithasbeenawhilebut", pages = { "Jin'Zil,\n   Je ne vous ai plus donné de nouvelles depuis longtemps, mais j'ai pensé que vous souhaiteriez être informé que la dernière des Plumesang a été tuée. Ne me remerciez pas, la personne qui délivre ce message est l'assassin. Si vous le souhaitez, je peux vous faire livrer la tête de la harpie, une fois que la caravane aura terminé sa tournée dans les Tarides. Je sais que vous recherchez ce genre de choses pour exercer votre magie vaudou.\n   Prenez soin de vous, vieil ami.\n\n-Darsok Swiftdagger" } } },
    ["Letter to Jorgen"] = { { ids = { "i5948" }, first = "jorgenmyfearshavecometru", pages = { "Jorgen,\nMes craintes se confirment, ils se sont comportés d'une manière que je n'aurais jamais crue possible. Je n'aurais jamais pensé qu'ils viendraient si près.\n\nAidez le porteur de cette missive, et envoyez-les vers LUI. En toute honnêteté, je pense qu'il nous aidera en raison du sérieux de cette affaire. S'il ne s'agissait que d'une menace quelconque, il continuerait sans doute à nous ignorer, ainsi que les problèmes de notre belle cité.\n\nMerci, vieux pêcheur. Je suis à jamais votre débiteur.\n\nVotre ami,\n         DeLavey" } } },
    ["Lewis' Note"] = { { ids = { "i15998" }, first = "osricpleasefindbelowthel", pages = { "Osric,\n\nVeuillez trouver ci-dessous la liste des éléments dont nous avons besoin pour nos Armures :\n\n10 chemises de mailles\n20 heaumes\n30 pièces d'armure\n15 paires de bottes en mailles\n\nNous vous sommes, comme à notre habitude, redevables. Et si la marche de l'Ouest était jamais libérée des voleurs qui la menacent, cela apaiserait un peu ma gêne si je pouvais vous inviter dans ma maison pour un bon repas préparé avec la générosité qui a fait autrefois la réputation de ce pays.\n\n-Lewis\nIntendant, Colline des sentinelles" } } },
    ["Libram of Constitution"] = { { ids = { "i11733" }, first = "thepageshereincontainmem", pages = { "<Les pages sont couvertes d'antiques runes elfiques.>\n\nCe document retrace les évènements qui se sont produits lors de la collecte et de la création des composants nécessaires à la fabrication des arcanum mineurs.\n\nPourvu que nos ennemis n'aient jamais accès à cet ouvrage !\n\nPourvu que je vive pour revoir la pâle lueur de la lune inonder Quel'Thalas !\n\nPourvu que je meure pour la grâce de Kael'thas !\n\nPourvu que je tue pour la gloire d'Illidan !\n\nMaître Telmius Cherche-Rêve", "", "", "", "" } } },
    ["Libram of Focus"] = { { ids = { "i18333" }, first = "thepageshereincontainmem", pages = { "<Les pages sont couvertes d'antiques runes elfiques.>\n\nCe document retrace les évènements qui se sont produits lors de la collecte et de la création des composants nécessaires à la fabrication des arcanum majeurs.\n\nPourvu que nos ennemis n'aient jamais accès à cet ouvrage !\n\nPourvu que je vive pour revoir la pâle lueur de la lune inonder Quel'Thalas !\n\nPourvu que je meure pour la grâce de Kael'thas !\n\nPourvu que je tue pour la gloire d'Illidan !\n\nMaître Telmius Cherche-Rêve", "<Vous ne comprenez rien à ce qui est écrit sur ces pages.>" } } },
    ["Libram of Protection"] = { { ids = { "i18334" }, first = "thepageshereincontainmem", pages = { "<Les pages sont couvertes d'antiques runes elfiques.>\n\nCe document retrace les événements qui se sont produits lors de la collecte et de la création des composants nécessaires à la fabrication des arcanum majeurs.\n\nPourvu que nos ennemis n'aient jamais accès à cet ouvrage !\n\nPourvu que je vive pour revoir la pâle lueur de la lune inonder Quel'Thalas !\n\nPourvu que je meure pour la grâce de Kael'Thas !\n\nPourvu que je tue pour la gloire d'Illidan !\n\nMaître Kariel Winthalus", "<L'encre danse et se tord sur la page. Vous avez l'impression que le livre se moque de vous.>" } } },
    ["Libram of Rapidity"] = { { ids = { "i18332" }, first = "thepageshereincontainmem", pages = { "<Les pages sont couvertes d'antiques runes elfiques.>\n\nCe document retrace les évènements qui se sont produits lors de la collecte et de la création des composants nécessaires à la fabrication des arcanum majeurs.\n\nPourvu que nos ennemis n'aient jamais accès à cet ouvrage !\n\nPourvu que je vive pour revoir la pâle lueur de la lune inonder Quel'Thalas !\n\nPourvu que je meure pour la grâce de Kael'thas !\n\nPourvu que je tue pour la gloire d'Illidan !\n\nMaître Telmius Cherche-Rêve", "<Regarder ces pages vous inflige une violente douleur.>" } } },
    ["Libram of Resilience"] = { { ids = { "i11736" }, first = "thepageshereincontainmem", pages = { "<Les pages sont couvertes d'antiques runes elfiques.>\n\nCe document retrace les évènements qui se sont produits lors de la collecte et de la création des composants nécessaires à la fabrication des arcanum mineurs.\n\nPourvu que nos ennemis n'aient jamais accès à cet ouvrage !\n\nPourvu que je vive pour revoir la pâle lueur de la lune inonder Quel'Thalas !\n\nPourvu que je meure pour la grâce de Kael'thas !\n\nPourvu que je tue pour la gloire d'Illidan !\n\nMaître Telmius Cherche-Rêve", "", "", "" } } },
    ["Libram of Rumination"] = { { ids = { "i11732" }, first = "thepageshereincontainmem", pages = { "<Les pages sont couvertes d'anciennes runes elfiques.>\n\nCes pages contiennent les souvenirs des événements liés à la récupération et à la création des composants nécessaires à la réalisation des arcanum inférieurs.\n\nQue jamais nos ennemis ne trouvent l'accès à ces libram.\n\nPuissé-je vivre assez pour voir la lumière de la lune briller de nouveau sur Quel'Thalas.\n\nPuissé-je mourir pour le bien de Kael'thas.\n\nPuissé-je tuer pour la gloire d'Illidan.\n\n-Maître Kariel Winthalus", "", "", "" } } },
    ["Libram of Tenacity"] = { { ids = { "i11734" }, first = "thepageshereincontainmem", pages = { "<Les pages sont couvertes d'anciennes runes elfiques.>\n\nCes pages contiennent les souvenirs des événements liés à la récupération et à la création des composants nécessaires à la réalisation des arcanum inférieurs.\n\nQue jamais nos ennemis ne trouvent l'accès à ces libram.\n\nPuissé-je vivre assez pour voir la lumière de la lune briller de nouveau sur Quel'Thalas.\n\nPuissé-je mourir pour le bien de Kael'thas.\n\nPuissé-je tuer pour la gloire d'Illidan.\n\n-Maître Kariel Winthalus", "", "", "", "" } } },
    ["Libram of Voracity"] = { { ids = { "i11737" }, first = "thepageshereincontainmem", pages = { "<Les pages sont couvertes d'antiques runes elfiques.>\n\nCe document retrace les évènements qui se sont produits lors de la collecte et de la création des composants nécessaires à la fabrication des arcanum mineurs.\n\nPourvu que nos ennemis n'aient jamais accès à cet ouvrage !\n\nPourvu que je vive pour revoir la pâle lueur de la lune inonder Quel'Thalas !\n\nPourvu que je meure pour la grâce de Kael'thas !\n\nPourvu que je tue pour la gloire d'Illidan !\n\nMaître Telmius Cherche-Rêve", "", "", "", "" } } },
    ["List of Components"] = { { ids = { "i236002" }, first = "inordertonavigatethemagi", pages = { "Pour traverser les ténèbres magiques que vous avez rencontrées à la crypte, il nous faudra créer une source de magie puissante, capable de percer cette nuit contre nature. C'est une magie délicate, qui exige une liste de composants bien précise.", "Le premier composant est la flamme de vie. Une telle flamme est l'essence pure et ardente de la création et de la renaissance. On dit que les dragons rouges sont capables de produire une telle flamme, l'Aspect Alexstrasza elle-même étant à l'origine de cette magie au sein de son vol. Grim Batol pourrait être un bon point de départ.", "Le composant suivant est une branche d'ancien bois de fer. Les Anciens immortels des légendes, qui marchent, sont entièrement faits de ce matériau merveilleux, mais prélever assez de bois de fer serait sans doute fatal à l'une de ces majestueuses créatures.\n\nJ'ai entendu parler d'un Ancien corrompu qui rôderait dans le canyon de la Malechute, au sud-est d'Ashenvale. Peut-être pourriez-vous trouver cette pauvre créature et la délivrer de son tourment, ce qui nous permettrait aussi d'obtenir la branche de bois de fer dont nous avons besoin.", "Le dernier composant est un esprit pur et bienveillant, auquel la flamme donnera forme et qui accepte d'être lié à l'ancien bois de fer pour faire rempart contre les ténèbres.\n\nCe monde regorge d'esprits, bien sûr. Mais trouver le bon esprit pour cette tâche pourrait se révéler difficile. Il devrait être indépendant et obstiné, mais avoir grand besoin d'un but. La plupart des esprits sont distants et sans pensée, mais il arrive, rarement, d'en trouver un qui aspire à une vocation plus haute...", "D'autres membres de mon ordre, présents lors de la bataille finale du mont Hyjal, racontent l'affrontement décisif entre les esprits des anciens Kaldorei et le seigneur démon Archimonde. Je ne vois pas de but plus digne pour un esprit que la défense de notre monde, mais si longtemps après cette bataille fatidique, ceux qui s'attardent encore pourraient être en quête d'une nouvelle cause, digne et noble.\n\nOn dit que la gorge du Sombre murmure est hantée par de nombreux esprits de ce genre.\n\nUne fois que vous aurez rassemblé tout cela, nous combinerons ces matériaux pour créer une source de flammes magiques qui devrait, je l'espère, dissiper les ténèbres et vous permettre de pénétrer dans la crypte." } } },
    ["Lonebrow's Journal"] = { { ids = { "i5790" }, first = "dayonemyjourneyfromironf", pages = { "--Premier jour--\n\nMon périple m'a conduit depuis Ironforge à Kalimdor !\n\nLe Prospecteur Khazgorm de Bael Modan progresse bien. Il a aujourd'hui découvert un fossile que les érudits du site pensent être un fragment d'os d'un ancien dieu. Khazgorm est convaincu que ce fossile relève d'un mystère plus grand encore. Pendant qu'il supervise le site de fouilles, il m'a chargé de découvrir d'autres fossiles afin de comprendre toute l'histoire.\n\nMa tâche est d'aller vers le sud à la recherche de davantage d'indices.", "--Deuxième jour--\n\nLes Tarides sont vastes et étendues. Mon périple a été long et difficile et je n'ai rien pu glaner pour les archives de la Ligue des explorateurs.\n\nLe seul incident notable a eu lieu sur la Route de l'or. Au loin, j'ai remarqué d'étranges créatures. Elles semblaient être mi-cochon, mi-homme. Je me suis vite caché et j'ai laissé passer ces viles créatures. Quelle puanteur elles ont laissé derrière elles !", "--Troisième jour--\n\nQuelle découverte merveilleuse !\n\nEn me promenant aujourd'hui, j'ai trouvé quelque chose d'exceptionnel : les restes immenses de ce qui semble être une créature porcine. Son crâne imposant faisait plusieurs fois ma taille. Chacune de ses dents était plus haute qu'un nain. En raison de leur gigantisme, je pense que ces restes sont ceux de l'un des Dieux très anciens légendaires.", "Je me souviens d'une conférence que le Chef archéologue Greywhisker avait donnée il y a quelques temps, au quartier général de la Ligue des explorateurs à Ironforge. Ce vieux professeur mentionnait un tel dieu, un de ceux qui étaient vénérés par les étranges elfes de Darnassus pour son légendaire altruisme.--\n\\Ah...! Un instant. J'ai entendu grogner à l'extérieur de la tente. Sûrement un sanglier des chardons qui essaie de me voler une de mes pommes...", "--Jour 4--\n\nCapturé !\n\nJe dois... le noter... rapidement.\n\nAttaqué par des hommes sangliers de la tribu de Tranchebauge. Je crois qu'ils m'emmènent à ce qu'il reste de ce grand dieu sanglier déchu. À moins qu'ils ne contournent les grands fossiles et se dirigent directement vers l'ouest du crâne géant, de l'autre côté de la Route de l'or.", "Entraîné de force dans cet endroit infect et infesté de bosquets épineux appelé Kraal de Tranchebauge. Jeté dans une hutte grossière et retenu captif avec un elfe de la nuit en piteux état.\n\nJe n'ai rien pu garder à part ce journal, ma plume et ma montre de poche...\n\nQuelqu'un approche...", "--Jour 5--\n\nMon compagnon de cellule elfe de la nuit souffre de graves blessures. Les hommes sangliers l'ont fouetté à plusieurs reprises et je pense qu'il ne survivra pas, à moins qu'une équipe de secours n'arrive par miracle dans cet endroit redoutable. Il perd régulièrement connaissance. Quand il se réveille, je lui donne le peu d'eau que j'ai.", "La nuit dernière, il a pu parler pour la première fois. C'est un druide appelé Heralath. Il a été envoyé ici pour étudier les rumeurs sur le dieu sanglier déchu.\n\nD'une voix très faible, il m'a dit qu'il croyait que le crâne du grand sanglier se trouvait à l'endroit où le grand dieu sanglier Agamaggan est tombé en combattant la Légion ardente il y a plus de dix mille ans, durant la guerre des Anciens. Son corps massif s'est écrasé sur le sol et son sang s'est répandu dans la terre. Des ronciers torturés ont poussé là où son sang a coulé...", "Heralath et son peuple cherchent à découvrir la source de la corruption sur ce site. Agamaggan était considéré comme un dieu pur, m'a-t-il dit. La raison pour laquelle ces créatures immondes et ces épines nocives défigurent ce pays demeure un mystère.\n\nAvant que je n'arrive à obtenir de plus amples informations, Heralath sombra de nouveau dans un sommeil agité...", "--Jour 6--\n\nLa santé d'Heralath empire.\n\nSes yeux se sont ouverts une seule fois aujourd'hui. Il a parlé avec angoisse et tristesse mais son message était clair. Si je réussis à m'enfuir de cet enfer, ici au Kraal de Tranchebauge, je dois aller rapporter à Falfindel Waywarder à Thalanaar que Charlga Trancheflanc lève des troupes dans le sud des Tarides. Sa puissance augmente de jour en jour. Il faut arrêter la mégère avant que le fléau de la corruption ne s'étende depuis le Kraal.", "Pauvre Heralath, il est pâle comme la mort. Sa fièvre ne cesse d'augmenter de minute en minute. Pendant ce temps-là, les hommes sangliers préparent de grandes manoeuvres militaires. Si je ne tente pas de m'échapper bientôt, je risque de connaître le même sort que mon compagnon de cellule elfique.\n\nMon plan consiste à me faufiler à l'extérieur lorsque les hommes sangliers partiront à la chasse. Mes gardes sont paresseux et sont souvent endormis à leur poste.", "Une fois libéré du Kraal, j'irai à Mille pointes puis vers l'ouest jusqu'à Thalanaar qui se trouve à la frontière de la mystérieuse forêt de Feralas. Là-bas, je chercherai le druide Falfindel Waywarder.\n\nCe qui à l'origine était une simple tentative pour en savoir plus concernant le passé de mon peuple, est devenu quelque chose de bien plus important. L'avenir de l'Alliance repose entre mes mains..." } } },
    ["Longwalker Malah's Report"] = { { ids = { "i286104" }, first = "dayventurecoactivitycont", pages = { "Jour 1\n\nL'activité de la KapitalRisk continue d'être une source de préoccupation. Ses opérations de minage n'ont cessé de croître et j'ai entendu un nouveau son de grincement qui suggère qu'un nouvel appareillage terrifiant y a potentiellement été déchargé.\n\nJe ne les considère toutefois pas comme une véritable menace pour les Pitons-du-Tonnerre, mais si on les provoque, ils pourraient parvenir à organiser une attaque fructueuse sur Sabot-de-Sang depuis le sud.", "Jour 2\n\nJ'entends un son tonitruant de cavalcade se réverbérer sur les falaises à l'est, là où nos terres rencontrent les plaines des Tarides. Il peut s'agir d'un autre troupeau de zhévras ou de gazelles, voire d'un lézard-tonnerre enragé, mais ce bruit se poursuit tard dans la nuit, bien au-delà des heures d'activité de ces animaux.\n\nJe vous invite à enquêter plus avant, mais en vous tenant à bonne distance.", "Jour 3\n\nLes centaures ont envahi Mulgore ! Notre adversaire le plus vil et le plus ancien a osé pénétrer à nouveau sur ces plaines après que nous les en avions chassés. Que la fureur du grand chef s'abatte sur eux !\n\nJe dois savoir ce qu'ils ont en tête, afin de pouvoir contrer leurs plans plus efficacement. En gardant le silence, je pense pouvoir me rapprocher suffisamment pour entendre leurs conversations.\n\nIl semble qu'ils prévoient de…\n\n<Le reste du texte est couvert de sang.>" } } },
    ["Lorgalis Manuscript"] = { { ids = { "i5359" }, first = "ourworldbrimswithhistory", pages = { "Notre monde regorge d'événements historiques. L'histoire des races, nouvelles et anciennes. L'histoire des guerres depuis longtemps terminées et celle des conflits encore brûlants.\n\nL'histoire des dieux et leurs apparitions. Sans compter d'anciens dieux qui sommeillent dans les entrailles de la terre.\n\nJe parle des Dieux très anciens. Ceux qui habitèrent et façonnèrent Azeroth lorsque le monde était encore jeune.", "Les Dieux très anciens sont l'âme de notre monde. Dans chaque tempête, on peut entendre le rire hurlant de l'un d'entre eux. L'éclat de chaque feu sauvage prend sa source dans la chaleur de leur regard. Lorsque les Dieux très anciens se déplacent, la terre tremble et se brise, et tous les petits êtres se terrent et prient pour leur misérable vie.\n\nA juste titre, comme les flammes n'hésitent pas à brûler la main d'un enfant, les Dieux très anciens n'ont que faire des créatures qui leur sont inférieures. Au mieux nous sommes des pions. Au pire, des jouets.", "Ils furent les premiers maîtres de ce monde et ils régnèrent par la force et la terreur. Bien qu'ils soient désormais enchaînés et endormis, leurs serviteurs rôdent toujours dans ce monde et nous pauvres mortels ne pouvons égaler leur force.\n\nCeux qui essayèrent furent dévorés. Mais ceux qui surent rester à leur place et vénérer avec supplication les serviteurs des Dieux très anciens, ceux qui sacrifièrent leur âme et leur esprit... Ceux-la gagnèrent leur faveur.", "Aku'mai, princesse des profondeurs, sert les Dieux très anciens. Elle habite dans les profondeurs de Brassenoire et emplit ses cavernes de son ancestrale sagesse. Menée dans ces profondeurs par les anciens mortels, Aku'mai est un symbole de la divinité. Elle a hérité de la puissance et de la sauvagerie des Dieux très anciens et sa soif de pouvoir ne connaît pas de limites.\n\nUn culte lui est dédié. Elle est crainte et aimée.\n\n--Lorgalis" } } },
    ["Maggran's Reserve Letter"] = { { ids = { "i16189" }, first = "grishyourrequestforsomet", pages = { "Grish-\n\nVotre requête a été acceptée. Je vous envoie un guerrier tauren pour garder votre poste le temps que vous rendiez visite à votre famille. Revenez dans une semaine !\n\n-Maggran Earthbinder" } } },
    ["Magical Ledger"] = { { ids = { "i20949" }, first = "", pages = { "" } } },
    ["Manual of Engineering Disciplines"] = { { ids = { "i10789" }, first = "theengineeringdiscipline", pages = { "Les sciences de l'ingénierie\n\nAlors que l'on peut se demander quelle race fut la première à organiser les sciences de l'ingénierie sur Azeroth, il n'y a aucun doute quant aux races qui en sont les principales actrices : les gnomes et les gobelins. Leur passion de l'ingénierie a permis la création d'inventions fantastiques durant ce qui est indubitablement l'Age magique de l'invention. Par contre, cette passion a également exacerbé leur rivalité raciale. Cela se voit particulièrement dans leur choix divergent de disciplines.", "Ingénierie des gnomes\n\nLes gnomes en tant que race tendent à exceller dans la création d'objets qui servent à manipuler et à contrôler le monde autour d'eux. Alors qu'ils n'ont qu'une connaissance superficielle des explosifs et des armements, l'ingénierie des gnomes se concentre plutôt sur les objets qui permettent de faciliter la vie. C'est une discipline de possibilités théoriques réalisées grâce au savoir-faire gnome. Cependant, certaines possibilités ne sont jamais complètement réalisées.", "Ingénierie des gobelins\n\nPour une race qui se veut neutre dans presque tous les conflits, les gobelins ont été très actifs pour tirer profit de la science. Ils maîtrisent les applications pratiques de l'ingénierie, comme on peut le voir dans leurs créations d'explosifs, d'armes à feu et de machines. Les gobelins ingénieurs n'ont que peu d'intérêt dans la théorie de cette science. Leurs inventions ont la réputation de trop bien marcher. Timorés, s'abstenir.", "Etude de disciplines\n\nLes gnomes et les gobelins protègent leurs savoirs respectifs avec tant de suspicion qu'il est presque impossible d'avoir accès aux deux types de disciplines simultanément. Chaque race, quelles que soient les affiliations politiques, réserve sa discipline à ceux qui acceptent de renoncer à l'autre. Si un apprenti décide d'apprendre l'ingénierie des gnomes, par exemple, l'ingénierie des gobelins lui restera à jamais inconnue.", "Décisions définitives\n\nLe paragraphe précédent soulignait un point important concernant les deux disciplines d'ingénierie. Il est primordial pour la bonne conduite de vos études. S'engager dans l'une des disciplines signifie que toute la panoplie des disciplines adverses ne vous seront pas ouvertes. Alors que cet état de fait peut être décourageant pour un profane, un ingénieur initié comprendra que les gnomes et les gobelins tiennent à garder leurs secrets jalousement. Un peu de connaissance vaut mieux que rien.", "Citations\n\n\"Vous voulez apprendre l'ingénierie des gobelins ? Allez parler à l'un de leurs meilleurs ingénieurs. Je crois que son nom est 'Nubby Stumpfingers'. Ne cherchez même pas à savoir pourquoi.\"\n-- Ringo Tragediction, ingénieur gnome\n\n\"Vous pouvez dire ce que vous voulez sur nous, les gobelins, mais sachez une chose : NOUS AVONS DES EXPLOSIFS !\"\n-- Yazz Nitrospork, bombardier gobelin", "Encore des citations !\n\n\"Vous connaissez ce sentiment quand vous venez de finir de faire quelque chose et que vous le faites fonctionner pour la première fois. Vous éprouvez alors la joie et la puissance du créateur. Les gnomes n'éprouvent jamais cela.\"\n-- Nixx Sprocketspring, Maître-ingénieur gobelin de Gadgetzan\n\n\"L'ingénierie, c'est réaliser les rêves les plus fous !\"\n-- Rovis McCrankenspank, inventeur gnome" } } },
    ["Marshal McBride's Documents"] = { { ids = { "i745" }, first = "reportkoboldstheactivity", pages = { "RAPPORT : Les kobolds\n\nL'activité des kobolds s'est accrue dans les pourtours de la vallée de Northshire. Ils ont établi un campement au nord de l'abbaye et se rassemblent dans la mine d'Echo en nombre effrayant. J'ai fait prêter serment aux paladins, aux guerriers et aux habitants du cru pour qu'ils m'aident à éliminer cette vermine.\n\nTout se passe bien. Je donnerai plus de nouvelles quand la situation aura évolué.", "RAPPORT : Les voleurs\n\nPlus inquiétants que les kobolds, une bande humaine de voleurs a fait son apparition dans la vallée. Ils portent des foulards rouges et se désignent comme une confrérie. Une telle organisation peut apporter bien des ennuis, ici comme dans toute la forêt d'Elwynn.\n\nNous avons identifié un de leurs chefs, un certain Garrick Padfoot, et nous espérons le présenter prochainement à la justice.", "RAPPORT : Les loups\n\nOn signale des attaques d'animaux de plus en plus nombreuses dans le Northshire. Eagan pense que les loups de la vallée proviennent du bois de la Pénombre d'où ils ont été effrayés.\n\nLes loups chassent rarement les humains, mais rien que leur nombre provoque des incidents avec les fermiers. Et de nombreuses bêtes ont disparu.", "RECOMMANDATION :\n\nLe porteur de ces documents a été nommé Adjoint dans l'armée de Stormwind, ayant servi le Northshire avec dévouement et courage. Je ne doute pas que vous trouviez ses services utiles dans la forêt d'Elwynn.\n\nSigné :\n-Maréchal Douglas McBride,\nArmée de Stormwind, Northshire" } } },
    ["Maybell's Love Letter"] = { { ids = { "i1208" }, first = "tommyjoewitheachpassingh", pages = { "Tommy Joe -\n\nA chaque heure qui passe, mon coeur gémit de ton absence. Oh, si seulement nos familles pouvaient oublier les torts qu'elles se sont infligés et comprendre que le seul vrai crime est la haine. La haine consume, et je crains ces sombres heures où la haine fera bien d'autres victimes que nos deux seules familles.\n\nSi les nôtres comprenaient, nous pourrions au moins être ensemble. C'est ce jour que j'attends dans l'espérance et c'est pour lui que je survis.\n\nTon amour,\nMaybell" } } },
    ["Memories of Valor"] = { { ids = { "i281149" }, first = "memoriesofvalorarecounto", pages = { "Souvenirs des Valor\nUne chronique de la famille Valor et des services qu'elle a rendus à Colline-aux-Corbeaux\n\nAucune famille des royaumes de l'Est n'est plus remarquable que la famille Valor. Les exploits accomplis par ses membres au service de la population qu'ils avaient juré de protéger tiennent du miracle, et leur disparition est un drame pour tout Colline-aux-Corbeaux.\n\nJ'écris cette chronique pour rétablir la vérité, et montrer que Grant, Ira, Silvia et Merrick étaient des êtres d'exception. Que ces mots soient source de réconfort, car leur absence me peine profondément.", "Merrick Valor, Watcher of Darkshire\n\nMerrick was the youngest son of the Valor family. As he witnessed the corruption coming to his homeland, he chose to join The Watch in a desperate bid to protect his loved ones.\n\nWhile he was the most inexperienced member of his family, he quickly made a name for himself amongst the ranks of The Watchers. He had a knack for archery, and soon became one of the most staunch defenders of Darkshire.\n\nHis personal mission was to keep the roads safe, wary of the ever more hostile creatures coming to the forests.", "Silvia Valor, garde de Colline-aux-Corbeaux\n\nSilvia Valor était déjà une héroïne locale lorsqu'elle fut invitée à rejoindre les rangs de la Garde. S'il y avait bien une chose au monde qu'elle ne pouvait tolérer, c'était les opportunistes qui profitaient du malheur des gens.\n\nBandits, escrocs, fauteurs de troubles, tous connaissaient le même sort. Silvia passait au fil de l'épée quiconque tentait de semer le chaos dans sa contrée chérie. Il n'y avait donc rien d'étonnant qu'elle accède à un poste qui allait lui conférer l'autorité nécessaire pour appliquer son idéal de justice.\n\nÀ croire les récits, ce ne serait qu'en rendant son dernier soupir qu'elle aurait abandonné les fermes et foyers du bois de la Pénombre. Et cela reste encore à prouver.", "Ira Valor, Forest Stalker\n\nWhen Ira's father grew ill, she took it upon herself to gather food and supplies from the nearby forests. While resources were not in short supply, you were as likely to find food as you were to become it.\n\nOver the years, she adapted to the forests, preferring to spend her time within the dark woods rather than in Raven Hill. Travelers who got lost in the trees would tell stories of a shadow seemingly opening the way for them back to the road. There was no confirmations of who it was, but rumors spread quickly.\n\nIt's said that Ira is still in the woods offering a guiding hand to those who fall prey to the beasts within.", "Seigneur Grant Valor, patriarche de la famille Valor\n\nLe seigneur Grant, paix à son âme, était le summum de l'exceptionnalisme de l'Alliance. Un meneur né, ses choix avisés ont contribué à mener la population de Colline-aux-Corbeaux vers la prospérité. Lorsque les ténèbres ont commencé à envahir les bois, il fut le premier à rallier notre peuple.\n\nPour le seigneur Grant, aucun adversaire n'était plus abject que les morts-vivants. Il patrouillait en personne dans les cimetières du bois de la Pénombre pour contenir les hordes chancelantes. Le jour où les monstres lui infligèrent une grave blessure, toute la ville partagea sa souffrance.\n\nGrâce au dévouement de sa famille, il put reprendre ses fonctions, mais un mal tenace sembla l'affecter jusqu'à la fin de ses jours.", "Dame Cassandra Valor, épouse et mère aimante\n\nOn sait peu de choses au sujet de Cassandra, si ce n'est qu'elle aimait sa famille. Elle prit grand soin de braves enfants et d'un mari puissant, en amenant certains à s'imaginer qu'elle était la source de la grandeur de sa famille. Des louanges qu'elle démentait toujours avec grâce.\n\nSi elle ne doit rester dans les mémoires que pour une unique raison, n'oublions jamais qu'elle a toujours œuvré pour le bien de sa famille." } } },
    ["Merrin's Letter"] = { { ids = { "i2639" }, first = "mydearesttarrelexcusethe", pages = { "Tarrel -\n\nExcusez-moi de vous écrire à la va-vite, mais nous n'avons pas le luxe du temps.\n\nL'équipe de forage a fait des progrès significatifs, exhumant d'importants artefacts des Titans. Mais nous avons également trouvé d'autres objets antiques, en particulier des ossements de grande taille.", "Peu après l'exhumation des ossements, nous avons été attaqués par des raptors. Les hommes du régiment de Longbraid ont combattu vaillamment, mais ils ont été submergés. Presque tout le monde a péri. Nous ne sommes que trois à avoir survécu. Un ouvrier du nom d'Ormer s'est montré fort héroïque, en nous protégeant, le Prospecteur Whelgar et moi-même.", "Nous nous sommes réfugiés dans une caverne, apparemment hors de danger. Mais nous sommes piégés ici jusqu'à ce qu'une force puisse être envoyée pour reconnaître la position des raptors. Whelgar essaie de continuer le travail mais je suspecte qu'il est toujours bien effrayé. Telle est notre situation, Tarrel. Veuillez presser Longbraid de nous dépêcher immédiatement un contingent de secours.\n\nMon amour vous reste acquis, même en ces heures difficiles.\n\n--Merrin" } } },
    ["Message from Emily"] = { { ids = { "i209029" }, first = "thegetawayplanisagowelea", pages = { "Le plan d'évasion est prêt. Nous partons ce soir.\n\nIl y a juste une dernière chose. J'ai caché une réserve d'équipement aux collines de la Dague, à l'entrée de derrière des Mortemines. La clé est dans cette enveloppe. J'espère que nous n'en aurons pas besoin, mais on ne sait jamais.\n\nQuel soulagement que nous puissions enfin laisser cette histoire des Défias derrière nous. Demain, à la même heure, nous nous reposerons sur les plages de Strangleronce.\n\nAvec toute mon affection,\n Émilie" } } },
    ["Metzen's Letters and Notes"] = { { ids = { "i21314" }, first = "onbehalfofsmokywoodpastu", pages = { "Au nom des Gourmandises Fumebois, nous vous remercions d'avoir accepté d'enquêter. Nous ne savons pas avec certitude quel groupe détient Metzen. Vous pouvez donc commencer par l'un ou par l'autre, à votre guise.\n\nLe temps, c'est de l'argent, mais dans ce cas précis, nous en manquons. Soyez rapide, car ces deux bandes sont capables du pire.\n\nVoici les deux demandes de rançon que nous avons reçues. Bonne chance.", "Si vous voulez retrouver le renne vivant, dépêchez-vous de payer la rançon. Les pirates des Mers du sud n'aiment pas les retards de paiement, et nous savons que l'animal vous rend de grands services dans VOTRE forme de piraterie.\n\nApportez 1000 pièces d'or à l'entrée de la crique des Gréements, à Tanaris. Toute tentative pour libérer le renne nous obligera à lui faire subir le supplice de la planche, avec une toute petite planche suivie d'une très longue chute.\n\nYeargh !\n\nLes pirates des Mers du sud.", "Votre animal bien-aimé supporte assez mal la chaleur incessante de la gorge des Vents brûlants… vous avez intérêt à payer la rançon sans tarder.\n\nNous demandons 700 pièces d'or et cinq rubis stellaires. Vous les placerez dans une boîte dépourvue de signes distinctifs que vous laisserez à l'entrée du passage de Formepierre d'ici une semaine.\n\nSi vous n'obtempérez pas, Metzen deviendra le plat principal du traditionnel festin sombrefer du Voile d'hiver.\n\nMmmm… du renne….", "Plus rapide que des aigles sont ses coursiers,\n\nEt il siffle, et il crie, et il les encourage :\n\n« Hue, Mercer ! Hue, Chilton ! Hue, Jordan et Kaplan !\n\nAllons, Nagle ! Allons, Pardo ! Allons, Goodman et Metzen !\n\nEn haut des murailles ! En haut des toits !\n\nEn avant ! En avant ! En avant, tous ! »" } } },
    ["Military Ranks of the Horde & Alliance"] = { { ids = { "o179707", "i18675" }, first = "militaryranksofthehordea", pages = { "GRADES MILITAIRES DE LA HORDE & DE L'ALLIANCE\n\nThrom'ka!  Vous\n\ntrouverez dans ce\n\n livre la liste détaillée\n\ndes grades militaires\n\nde la Horde et de la\n\nmisérable Alliance.\n\nNous traiterons d'abord\n\nde la Horde, puis de\n\n l'Alliance, en indiquant chaque fois les grades d'officiers et de les grades d'hommes de troupe. Comme il se doit, les plus forts sont en haut, et les faibles en bas.", "GRADES D'OFFICIER DE LA HORDE\n\nPart 1\n\n Grand seigneur de guerre\n\n Seigneur de guerre\n\nGénéral\n\nLieutenant-général\n\nChampion", "GRADES D'OFFICIER DE LA HORDE\n\nPart 2\n\nCenturion\n\nLégionnaire\n\nGarde de sang\n\nGarde de pierre", "GRADES DES RECRUES DE LA HORDE\n\nAdjudant\n\n Sergent-chef\n\nSergent\n\nGrunt\n\nEclaireur", "GRADES D'OFFICIER DE L'ALLIANCE\n\nPart 1\n\nConnétable\n\nGrand maréchal\n\nMaréchal\n\nCommandant\n\nLieutenant-commandant", "GRADES D'OFFICIER DE L'ALLIANCE\n\nPart 2\n\nChevalier-champion\n\n Chevalier-capitaine\n\n Chevalier-lieutenant\n\nChevalier", "GRADES DES RECRUES DE L'ALLIANCE\n\nSergent-major\n\n Sergent-chef\n\nSergent\n\nCaporal\n\nSoldat" } } },
    ["Missing: Corporal Keeshan"] = { { ids = { "o1726" }, first = "missingcorporalkeeshanla", pages = { "Porté disparu : caporal Keeshan\n\nPorté disparu depuis la sanglante bataille du donjon de Guet-de-pierre, le caporal Keeshan semble avoir été emporté par les orcs Blackrock.\n\nOn pense que le caporal Keeshan est prisonnier au camp Blackrock situé au nord de Lakeshire, à l'ouest du col menant aux Steppes ardentes.\n\nPar mandat du Magistrat Solomon, quiconque aidera à retrouver le caporal Keeshan sera récompensé par le maréchal Marris." } } },
    ["Mists of Dawn"] = { { ids = { "o177207" }, first = "beforetheageofmemorytheg", pages = { "Avant l'Age de la Mémoire, la douce Terre-mère respirait dans les brumes dorées de l'aube. Lorsque les nuages d'ambre se posèrent pour le repos, d'innombrables champs de blé et d'orge apparurent. Telle fut la mer primordiale de son travail, la grande vasque de la vie et de l'espoir.", "Les yeux de la Terre-mère s'abaissèrent sur les terres dont son souffle avait suscité l'émergence. Son oeil droit, An'she (le soleil), donna chaleur et lumière à la terre. Son oeil gauche, Mu'sha (la lune), donna la paix et le repos aux créatures agitées de l'aube. Telle était la puissance de son regard que la Terre-mère devait alternativement fermer l'un ou l'autre de ses yeux. Son regard tendre fit du jour la nuit et ce fut le premier jour de la terre.", "Tandis que l'oeil droit brillait sur l'aube dorée, les douces mains de la Terre-mère s'étendirent sur les plaines d'or. Partout où passait l'ombre de ses bras, un noble peuple se levait sur le sol riche. Les Shu'halo (les taurens) se dressèrent et remercièrent en priant leur aimante mère. Là, dans les champs sans fin de l'aube, les enfants de la terre jurèrent allégeance à sa grâce et promirent de bénir son nom jusqu'à l'obscurcissement final du monde." } } },
    ["Monument to Grom Hellscream"] = { { ids = { "o21004" }, first = "hereliesgrommashhellscre", pages = { "Ici repose Grommash Hellscream, Chef du clan Warsong\n\nD'une certaine manière, la malédiction de notre peuple a commencé et fini avec Grom.\nSon nom signifie \"coeur de géant\" dans notre vieille langue. Il gagna ce surnom\nde façon bien méritée en s'opposant seul au démon Mannoroth\n- et en achetant notre liberté au prix du sang.\n\nLok'Tar ogar, grand frère. Que le clan Warsong jamais ne disparaisse.\n\n-Thrall, Chef de la Horde" } } },
    ["Mor'zul's Instructions"] = { { ids = { "i18818" }, first = "tobindadreadsteedyoumust", pages = { "Pour vous lier à un Destrier de l'effroi, vous devez faire les trois choses suivantes :\n\nCréer un Cercle d'invocation supérieure.\n\nA l'intérieur du Cercle, ouvrez une porte vers Xoroth et sortez-en un Destrier de l'effroi.\n\nTriomphez du Destrier de l'effroi, puis rendez-vous maître de son esprit.\n\nLes pages suivantes vous expliqueront comment accomplir chacune de ces actions. Ce ne sera pas facile, mais vous avez prouvé votre valeur. Montrez-vous habile, et je ne doute pas que le Destrier de l'effroi vous appartiendra.\n\nPoursuivez votre lecture,\n-Mor'zul Bloodbringer", "Les instruments du Rituel\n\nAvant de commencer, il vous faut les instruments magiques suivants :\n\nLe bocal de J'eevee\nUne Magnétite noire\nGlyphes de Xoroth\n\nMon serviteur Gorzeeki vous les fournira, si vous payez. Ne tentez d'accomplir aucune des étapes du rituel si vous n'avez pas tous ces instruments. Chacun est très important.\n\nDans les pages qui suivent, j'expliquerai comment chaque instrument doit être utilisé.", "Cercle de lien supérieur\n\nVous devez créer un Cercle de lien supérieur à un endroit où la magie est forte. Un tel lieu existe loin dans les ruines d'Eldre'Thalas, que l'on appelle aussi Hache-tripes. Un être très puissant est emprisonné à Eldre'Thalas : Immol'thar. C'est sur le socle de sa prison que vous devez accomplir le rituel pour créer le Cercle.\n\nCombattez pour atteindre le Socle, puis laissez J'eevee s'échapper de son bocal.", "La Cloche, la Roue et la Chandelle\n\nQuand vous aurez libéré J'eevee, il mettra en place la Cloche, la Roue et la Chandelle et un cercle apparaîtra. C'est alors que commence le rituel. Prenez garde : les trois objets véhiculent des énergies très puissantes et peuvent cesser de fonctionner. Lorsque cela se produit, utilisez vite votre Magnétite noire pour les remettre en route avant que votre rituel n'échoue complètement.\n\nSi les objets cessent tous les trois de fonctionner avant que vous ne les ayez remis en route, le rituel est interrompu et il vous faudra tout recommencer.", "La Cloche, la Roue et la Chandelle ne véhiculent pas seulement les énergies du rituel mais possèdent aussi des propriétés spécifiques.\n\nLorsqu'elle sonne, la Cloche de Dethmoora confère vigueur et énergie aux démonistes se trouvant à l'intérieur du cercle.\n\nLorsqu'elle tourne, la Roue de la Marche noire protège ceux qui se trouvent à l'intérieur du cercle.\n\nLorsqu'elle brûle, la Chandelle de l'apocalypse projette une énergie surnaturelle sur les ennemis qui pénètrent dans le cercle.\n\nEn raison de ces bienfaits, il est très important que les trois objets fonctionnent pendant le rituel.", "Notez également que la Magnétite noire, qui permet de remettre en route la Cloche, la Roue et la Chandelle si elles cessent de fonctionner, nécessite des fragments d'âme. Chaque fois que vous remettez en route un objet du rituel à l'aide de la Magnétite, un de vos fragments d'âme sera consommé. Veillez donc à en avoir suffisamment avant de commencer le rituel.", "La fin du Rituel\n\nVous pouvez surveiller la progression du rituel à l'aide des runes magiques autour du cercle. Le rituel est terminé lorsque neuf runes ont apparu, et vous verrez l'énergie s'élever du Cercle.\n\nVous pouvez dès lors invoquer les Glyphes de Xoroth, ouvrir une porte vers Xoroth et en sortir un Destrier de l'effroi.\n\nTriomphez du Destrier de l'effroi et libérez son esprit. Affrontez l'esprit et soumettez-le, et vous serez récompensé par le secret de son invocation." } } },
    ["Mount Hyjal and Illidan's Gift"] = { { ids = { "o175729" }, first = "thefewnightelvesthatsurv", pages = { "Les quelques elfes de la nuit qui survécurent à l'horrible explosion se groupèrent sur des canots grossiers et se dirigèrent laborieusement vers le seul continent à portée de vision. Grâce à la protection d'Elune, Malfurion, Tyrande et Cénarius avaient survécu à la Grande Fracture. Les héros épuisés acceptèrent de conduire leurs compagnons survivants et de fonder une nouvelle demeure pour leur peuple.", "Tandis qu'ils progressaient en silence, ils observèrent le naufrage de leur monde et réalisèrent que leurs passions avaient conduit à cette immense destruction tout autour d'eux. Sargeras et sa Légion avaient été chassés du monde par la destruction du Puits, mais Malfurion et ses compagnons ne pouvaient que pleurer sur le terrible coût de leur victoire.", "Il restait de nombreux Bien-nés parmi les survivants qui gagnèrent les rives de la nouvelle terre avec les autres elfes de la nuit. Malfurion n'avait pas confiance en leurs intentions, mais il était rassuré par leur incapacité à causer du tort sans les énergies du Puits.", "En prenant pied sur les rivages de la nouvelle terre, le peuple fatigué des elfes de la nuit découvrit que la montagne sainte, Hyjal, se dressait toujours. Cherchant un nouveau foyer où s'établir, Malfurion et les elfes de la nuit gravirent les pentes du mont Hyjal et atteignirent ses sommets venteux. En descendant dans la vallée boisée protégée par les remparts montagneux, ils trouvèrent un petit lac paisible. A leur grande horreur, ils découvrirent que les eaux du lac étaient gorgées de magie.", "Illidan, ayant survécu à la Fracture, avait atteint le sommet du mont Hyjal bien avant Malfurion et les elfes de la nuit. Dans son désir dément de maintenir le flux de la magie dans le monde, Illidan avait versé le contenu de ses fioles, remplies des eaux précieuses du Puits d'éternité, dans le lac de la montagne.", "Les puissantes énergies enchantées se répandirent rapidement, créant une sorte de nouveau Puits d'éternité. Illidan, fou de joie, pensait que ce nouveau puits serait un don pour les générations à venir. Il fut choqué de la réaction négative de Malfurion. Ce dernier expliqua à son frère que la magie était intrinsèquement chaotique et que son utilisation conduirait inéluctablement à l'extension de la corruption et de la guerre. Pourtant, Illidan refusa de renoncer à ses pouvoirs magiques.", "Sachant pertinemment où les plans déloyaux d'Illidan pouvaient mener, Malfurion décida d'en finir une fois pour toutes avec ce frère assoiffé de pouvoir. Avec l'aide de Cénarius, Malfurion enferma Illidan dans une vaste chambre souterraine où il devait rester enchaîné, privé de sa puissance, jusqu'à la fin des temps. Pour s'assurer que son frère resterait prisonnier, Malfurion confia la surveillance du captif à Maiev Shadowsong.", "Craignant que la destruction du nouveau Puits ne déclenche une catastrophe plus terrible encore, les elfes de la nuit décidèrent de le laisser perdurer. Mais Malfurion déclara que jamais plus les arts de la magie ne devaient être pratiqués. Sous la surveillance attentive de Cénarius, les elfes commencèrent à étudier les arts anciens des druides qui leur permettraient de panser les plaies de la terre ravagée et de faire renaître leurs chères forêts au pied du mont Hyjal." } } },
    ["Mountaineer Gretchen's Report"] = { { ids = { "i280430" }, first = "areportonthestateofwendi", pages = { "Rapport sur la situation des wendigos dans les grottes proches de Kharanos\n\nRédigé par la montagnarde Gretchen sur la base des observations du montagnard Cornélius\n\nLes wendigos s'aventurent rarement hors de leurs grottes, mais des attaques de civils ont été signalées à plusieurs reprises à proximité de villages comme Kharanos et Brassetout. Les wendigos semblent de plus en plus agités lorsqu'ils se mettent en quête de nourriture. Nous avons d'ailleurs perdu l'un des nôtres en tentant d'enrayer le problème. Si l'élimination totale de ces bêtes n'est pas envisageable, les montagnards demandent", "des moyens supplémentaires afin de freiner leur propagation. Nous ne pouvons pas indéfiniment recourir à des aventuriers pour faire face au problème, et espérer que les choses finissent par s'arranger. Tôt ou tard, les wendigos viendront à manquer de nourriture et s'attaqueront directement à nos villes. Même Forgefer pourrait être touchée.\n\nJe vous prie de présenter mes condoléances à la famille du montagnard Cornélius, qui a vaillamment combattu pour protéger la population de Dun Morogh." } } },
    ["Muddy Journal Pages"] = { { ids = { "i938" }, first = "mostcertainthatsheshares", pages = { "...tout à fait certain qu'elle partage désormais mes sentiments. Elle a même posé sa main sur la mienne ce matin. Lorsqu'elle sourit, ses yeux s'illuminent comme des diamants. Nous échangeons de longues conversations d'un simple regard. Je sens sa présence dans mon coeur palpitant et dans mes veines.", "...une colère, une furie dont j'ignorais qu'elles pussent exister ! Comment ose-t-elle ! J'apprenais à Giles les merveilles de l'arithmétique lorsque Tilloa est apparue devant moi avec un chevalier servant, la main dans la main ! Un jeune homme sans raffinement ! Au lieu de me présenter comme il convient, Tilloa s'est simplement exclamée : \"Oh, et voilà mon précepteur, Oncle Stalvan. C'est un charmant vieillard.\" Vieillard ! En entendant ces mots, j'ai senti mes joues rougir. J'ai à peine quelques années de plus, et elle me trahit ainsi..." } } },
    ["Muddy Note"] = { { ids = { "i2720" }, first = "dayamtoamuppercampamtoam", pages = { "Jour 1 :\n6H - 11H - camp supérieur\n11H - 11H30 - Pause, déjeuner\n11H30 - 16H00 - passe du canyon\n16H00 - 19H30 - camp supérieur\n\nJour 2 :\nIdem jour 1\n\nJour 3 :\nIdem\n\nJour 4 :\nIdem, à une exception. Juste avant le crépuscule, Thorsen m'a demandé de le couvrir pendant qu'il s'enfonçait dans la passe du canyon. Je suppose qu'il est allé rencontrer un de nos agents.\n\nMais il est revenu une heure plus tard. Cela m'a surpris. J'espérais qu'il avait rencontré un de nos agents et rejoint Kurzen. Quelque chose ne va pas.", "Jour 5 :\nThorsen était très agité aujourd'hui. Quoi qu'il ait vu ou qui qu'il ait rencontré durant son excursion d'hier, il a eu peur.\n\nJe suppose que nos agents lui ont parlé, mais lorsque j'ai demandé à Thorsen où il était allé pendant que je le couvrais, il est resté silencieux. Il me pense son ami, et croit me protéger contre un dangereux secret.\n\nIl place mal sa loyauté, mais il est loyal. Quand il nous rejoindra, il sera un apport inestimable aux forces de Kurzen.", "Jour 6 :\nTôt ce matin, Thorsen a longuement parlé avec le sergent Yohwa. J'ai dû faire semblant de dormir et je n'ai pu m'approcher pour les écouter. Mais je pense qu'ils parlaient de l'excursion récente de Thorsen.\n\nJe l'ai attentivement observé au déjeuner et j'ai vu que Yohwa en faisait autant. Plus tard, Doren a convoqué Thorsen. Tous trois partagent un secret. Doren et Yohwa doivent savoir que Thorsen rencontre vos agents.\n\nIl espionne les rebelles.", "Nous ne devons plus donner de renseignements à Thorsen et nous devons le tuer. Il n'est plus d'aucune utilité pour notre colonel.\n\nJe m'occuperai de Thorsen si j'en ai la possibilité, mais si vous recevez cette lettre, vous saurez que je n'en ai pas encore eu l'occasion.\n\nDans ce cas, je suggère que le prochain contact de Thorsen avec nos agents soit sa dernière heure.\n\nGloire à Kurzen,\n-M" } } },
    ["Mysterious Orders"] = { { ids = { "i265782" }, first = "brotherhaalienitistimeto", pages = { "Frère Haalien,\n\nIl est temps de faire vos preuves aux Al'Aketh ! Rendez-vous dans Trombenoire et localisez le pylône. Vous avez fait part de vos réserves au sujet des druides et les autorités de l'ordre vous ont entendu.\n\nCes preux soldats vous accompagneront dans votre mission sacrée. Éliminez les druides sans tarder pour qu'ils n'entravent pas nos plans. Nos yeux et nos oreilles à Valanaar pourront nous confirmer votre réussite.\n\nL'heure de la vengeance a sonné ! Nul ne pourra faire obstacle à l'avènement !\n\n– N." } } },
    ["Mythology of the Titans"] = { { ids = { "i5536" }, first = "nooneknowsexactlyhowtheu", pages = { "Nul ne sait au juste comment l'univers est né. Selon certains, une gigantesque explosion cosmique a envoyé les mondes infinis tourbillonner dans les espaces immenses du Grand Néant. Ces mondes allaient un jour porter la vie dans une immense et impressionnante diversité. D'autres pensent que l'univers, tel qu'il existe aujourd'hui, a été créé par un être tout-puissant.", "On reste sans explication définitive quant aux origines de l'univers chaotique, mais il est certain qu'une race d'êtres puissants s'est dressée pour donner forme aux différents mondes et assurer un avenir aux êtres qui suivraient leurs traces.\n\nLes colossaux Titans, dieux à peau métallique venus des confins du cosmos, commencèrent à façonner les mondes qu'ils rencontraient. Ils élevèrent de hautes montagnes et drainèrent de vastes océans.", "Ils bâtirent des cieux et des atmosphères de leur souffle dans le but impénétrable de créer l'ordre à partir du chaos. Ils donnèrent même une certaine puissance à des races primitives pour entretenir leur travail et maintenir l'intégrité de leurs mondes respectifs.\n\nLes Titans, dirigés par une secte d'élite nommée le Panthéon, mirent en ordre une centaine de million de mondes disséminés dans le Grand Néant pendant les premiers âges de la création.", "Le bienveillant Panthéon, cherchant à sauvegarder les mondes structurés, restait vigilant face aux possibles attaques des viles créatures extra-dimensionnelles du Néant distordu. Il s'agissait d'une dimension éthérée faite de magie chaotique qui connectait les myriades de mondes de l'univers. Il abritait un nombre infini d'êtres démoniaques et maléfiques qui ne cherchaient qu'à détruire la vie et dévorer les énergies de l'univers vivant." } } },
    ["Naga Manuscript"] = { { ids = { "i211777" }, first = "", pages = { "<Le manuscrit indique l'emplacement de trois cristaux le long de la grève de Zoram. Un itinéraire numéroté est tracé entre eux, du sud vers le nord. Près de chaque cristal se trouve un petit dessin représentant une explosion de magie arcanique.>" } } },
    ["Nat Pagle's Guide to Extreme Anglin'"] = { { ids = { "i18229" }, first = "andsothatswhereyoullfind", pages = { "… et c'est là que vous trouverez Porte-cendres, l'épée légendaire du généralissime de la Croisade écarlate.\n\nC'est fou ce qu'on trouve en une journée de pêche, pas vrai ?" } } },
    ["Neeka's Report"] = { { ids = { "i6167" }, first = "helgrummycomplimentstowh", pages = { "Helgrum,\n\nMes compliments à celui qui a réussi à établir notre base de Kargath dans les Terres ingrates. C'est l'endroit idéal pour entraîner nos troupes. Le climat, la vie sauvage, les tribus natives et guerrières et l'absence totale de commodités en font un endroit de prédilection dont seuls les meilleurs guerriers et éclaireurs sortiront indemnes.\n\nExcellent travail.", "Je vais vous décrire les terres environnantes que les éclaireurs de Kargath ont explorées :\n\n-Des collines rocailleuses et rouges et de grandes étendues stériles.\n-Un soleil brûlant et des vents violents.\n-Ni lac, ni rivière. Pas même de point d'eau. Pour trouver de l'eau, les habitants doivent creuser profondément dans des puits boueux ou exploiter le peu d'humidité que l'on trouve dans les cactus.\n\nEn d'autres termes : chaud et difficile à supporter.", "Les Terres ingrates regorgent d'ennemis. Les ogres rôdent dans les sables brûlants, tendant des embuscades aux voyageurs trop confiants. Les nains Sombrefer habitent des bâtiments à l'est de Kargath et font la guerre à leurs cousins à la peau claire de Loch Modan, qui se trouvent au nord. Les troggs, brutaux et primitifs, chassent les points d'ombre et les défendent sauvagement.\n\nEt loin à l'est dans les Terres ingrates, il y a le ravin de Lethlor où vivent les dragons. Nous ne connaissons ni leur taille ni leur nombre. Les rares éclaireurs à s'en être approchés ne sont jamais revenus.", "Il faut dire que nous, les personnes en garnison à Kargath, sommes satisfaits de notre affectation. Ici, nous sommes constamment en état d'alerte et si nous relâchons notre vigilance, nous sommes morts.\n\nEt je ne voudrais pas qu'il en soit autrement.\n\nNeeka Bloodscar\nChef éclaireur, Kargath" } } },
    ["Nostro's Compendium of Dragon Slaying"] = { { ids = { "i18401" }, first = "fororscompendiumofdragon", pages = { "Le guide de Nostro du tueur de dragons est un épais volume couvert d'écriture. Malheureusement, le texte semble brouillé et reste incompréhensible." } } },
    ["Note from Ba'so"] = { { ids = { "i207098" }, first = "ivegotthegoodsillbehidin", pages = { "J'ai la marchandise. Je me cacherai à l'ouest du donjon de Tiragarde, sous un arbre aux feuilles sombres. Si vous envoyez l'un de vos agents pour la récupérer, assurez-vous qu'il ne soit pas visible !\n\n- Ba'so" } } },
    ["Of Love and Family"] = { { ids = { "i14679" }, first = "", pages = { "" } } },
    ["Old Hatreds - The Colonization of Kalimdor"] = { { ids = { "o175763" }, first = "thoughvictorywastheirsth", pages = { "Malgré leur victoire, les races mortelles se retrouvaient dans un monde que la guerre avait déchiré. Le Fléau et la Légion ardente avaient détruit les civilisations de Lordaeron et presque réussi à en faire autant dans Kalimdor. Il y avait des forêts à panser, des rancunes à enterrer, des terres à rebâtir. Chaque race avait été profondément blessée par la guerre, mais toutes se rejoignaient avec altruisme pour tenter un nouveau départ. La paix difficile entre l'Alliance et la Horde donnait l'exemple.", "Thrall mena les orcs vers le continent de Kalimdor, où ils fondèrent une nouvelle terre avec l'aide de leurs frères taurens. Ils nommèrent leur nouveau territoire Durotar, en hommage au père assassiné de Thrall, et commencèrent à rebâtir leur société naguère glorieuse.", "Maintenant que la menace démoniaque avait pris fin, la Horde cessa d'être une machine de guerre pour devenir une coalition plus souple, dédiée à la survie et à la prospérité plutôt qu'à la conquête. Aidés par les nobles taurens et les trolls rusés de la tribu Darkspear, Thrall et ses orcs cherchèrent à bâtir une nouvelle ère de paix.", "Les forces de l'Alliance restantes, menées par Jaina Proudmoore, s'installèrent dans le sud de Kalimdor. A l'écart de la rive est du marécage d'Âprefange, elles bâtirent la ville portuaire de Theramore. Là, les humains et leurs alliés nains s'employèrent à survivre sur une terre qui leur serait à jamais hostile. Bien que les défenseurs de Durotar et de Theramore s'efforcèrent de maintenir leur trêve, la fragile sérénité des colonies ne devait pas durer.", "La paix entre les humains et les orcs fut brisée par l'arrivée d'une puissante flotte de l'Alliance à Kalimdor. Commandée par le Grand amiral Daelin Proudmoore (le père de Jaina), la flotte avait quitté Lordaeron avant la destruction du royaume par Arthas. Ayant péniblement navigué pendant des mois, l'amiral Proudmoore cherchait tous les survivants de l'Alliance qu'il pouvait trouver.", "L'armada de Proudmoore constituait une sérieuse menace pour l'équilibre de la région. Héros de la Deuxième Guerre, le père de Jaina était un sérieux ennemi de la Horde, et il était décidé à détruire Durotar avant que les orcs ne puissent s'étendre.", "Le Grand amiral força Jaina à prendre une terrible décision : le soutenir au combat contre les orcs et trahir ses nouveaux alliés, ou combattre son propre père pour maintenir la paix fragile que l'Alliance et la Horde avaient enfin établie. Après bien des hésitations, Jaina choisit la dernière solution et aida Thrall à vaincre son père.", "Malheureusement, l'amiral Proudmoore mourut au combat avant que Jaina ne puisse se réconcilier avec lui ni lui prouver que les orcs n'étaient plus des monstres assoiffés de sang. En remerciement de sa loyauté, les orcs permirent à Jaina et à ses forces de revenir en toute sécurité à Theramore." } } },
    ["Orders from the Grand Crusader"] = { { ids = { "i216610" }, first = "byorderofgrandcrusaderda", pages = { "Par ordre du grand croisé Dathrohan :\n\nL'hérétique connu sous le nom d'Aeonas le Silencieux est condamné pour les crimes de commerce avec les démons et les morts-vivants, d'abandon de la Lumière, de vol et de meurtre. Cette vile créature a tué pas moins de deux de nos vaillants frères de la Lumière en dérobant des biens importants de la Croisade écarlate. Une fois retrouvé, l'hérétique devra être conduit au monastère de Tirisfal pour y être interrogé et exécuté. Tout paquet ou artefact en sa possession lors de son arrestation devra être rendu au grand croisé au plus vite, comme pièce à conviction.\n\nUne fois capturé, Aeonas devra être bâillonné, et nul autre que le grand inquisiteur ne pourra lui parler, de peur que ses mensonges insidieux ne sèment le chaos et le doute dans des cœurs par ailleurs vertueux. Soyez prudents, mes frères et sœurs, car nul ne sait quelles magies infâmes Aeonas a pu obtenir dans ses sombres tractations avec les ennemis de la Lumière." } } },
    ["Orman of Stromgarde"] = { { ids = { "o175779" }, first = "ormanofstromgardethefirs", pages = { "Orman de Stromgarde\nPremier capitaine général de la Croisade écarlate\nCitoyen de Stromgarde\nPorté disparu aux abords du glacier de la Couronne de glace" } } },
    ["Peeling the Onion"] = { { ids = { "i19483" }, first = "peelingtheonionthehowtog", pages = { "Peler l'oignon\nComment démanteler les Stormpike\n-par Drek'Thar\n\nVous trouverez dans ces pages de nombreuses informations d'ordre tactique et politique. Le soldat érudit est celui qui se penche sur l'épaule de l'expérience. Que ce livre vous serve de guide dans votre bataille pour la Vallée d'Alterac.", "Chapitre 1 - La première ligne\n\nDémanteler l'armée des Stormpike est tout à fait comparable à peler un oignon. Pour parvenir jusqu'au coeur, il faut commencer par enlever les couches extérieures.\n\nLes premières lignes, principalement constituées de Montagnards Stormpike et de Sentinelles de l'Alliance, sont liées au fortin du capitaine. C'est le capitaine Balinda Stonehearth qui commande ces unités et envoie des renforts quand les lignes sont assiégées. Frappez le capitaine et les forces de la première ligne s'effondreront.", "Chapitre 2 - Les tours jumelles\n\nNe vous y trompez pas. Vanndar Stormpike est très loin d'être stupide. Une fois que la première ligne aura été percée, il faudra encore détruire les défenses secondaires. C'est depuis les tours jumelles de Stonehearth et de l'Aile de glace que sont commandés les gardes Stormpike à l'extérieur de Dun Baldar et les patrouilles Stormpike.", "Prenez garde, soldat, car ces deux tours sont très bien gardées par des troupes sous les ordres de l'un des commandants d'élite de Vanndar. Si vos forces pénètrent dans les fortifications, assurez-vous que le commandant à l'intérieur a été... réduit au silence. Cela aussi fait partie du démantèlement des Stormpike.", "Chapitre 3 - Les quatre commandants\n\nLa troisième couche de l'oignon Stormpike est constituée par les quatre commandants. À cet égard, Vanndar a copié nos glorieuses défenses Frostwolf. Bien sûr, il vous dira le contraire... Mais je m'égare.\n\nLes quatre commandants contrôlent les mouvements des gardes Stormpike qui protègent férocement Dun Baldar. Réduisez-les au silence et les gardes Stormpike tomberont.\n\nIl ne restera alors plus qu'une couche à peler.", "Chapitre 4 - Les fortins de Dun Baldar\n\nComme vous l'avez sans doute remarqué, les couches défensives des Stormpike sont placées de sorte à empêcher qu'une puissante attaque ne détruise les défenses de l'armée entière. Inutile de demander : oui, c'est exactement comme cela que notre propres forces sont positionnées, et non, je ne changerai pas l'organisation de notre défense. Ce sont eux qui nous ont copiés, pourquoi devrions-nous changer ?", "Où en étais-je ? Ah oui, les défenseurs Stormpike - les unités d'élite les plus fidèles de Vanndar - sont commandés depuis les fortins de Dun Baldar (situés à Dun Baldar). Détruisez ces deux tours et les renforts destinés à aider Vanndar n'existeront plus.", "Epilogue\n\nQuand vous aurez fait tout cela, il vous restera le coeur de l'oignon. Vanndar Stormpike se retrouvera seul et sans défenses. Le code de conduite militaire nous oblige à lui demander sa reddition avant de procéder à toute exécution. N'oubliez pas de lui demander de se rendre quand vous le verrez... puis tuez-le." } } },
    ["Petrified Bark"] = { { ids = { "i18708" }, first = "simonetheseductressyouwi", pages = { "Simona la Séductrice :\n\nSimona empoisonne de sa présence le cratère d'Un'Goro. Ne vous laissez pas tromper par son apparence. Approchez-vous d'elle avec prudence et défiez-la.", "Klinfran l'Enragé :\n\nKlinfran erre dans les Steppes ardentes. Approchez-vous de lui avec prudence et obligez-le à se montrer sous sa vraie forme.", "Solenor le Tueur :\n\nC'est dans le paysage aride de Silithus que se tapit le démon Solenor le Tueur. Il est sans doute déguisé et il est extrêmement dangereux. Approchez-vous de lui et obligez-le à se transformer.", "Artorius le Néfaste :\n\nArtorius n'apporte que la corruption et la ruine à tout ce qu'il touche au Berceau-de-l'Hiver. Trouvez-le et tuez-le.", "Soyez prévenu, chasseur, ces démons ne se battent que s'ils le souhaitent. S'ils pensent qu'ils ne peuvent pas vous battre, ils fuient.\n\nPARTEZ SEUL." } } },
    ["Podrig's Order"] = { { ids = { "i16209" }, first = "byorderofhighexecutorhad", pages = { "Par ordre du Grand-exécuteur Hadrec, voici ci-dessous énumérés les objets jugés nécessaires pour maintenir le niveau des stocks du Sépulcre :\n\n12 Epées longues\n9 Dagues\n8 Boucliers ronds\n15 Haches\n1000 Flèches\n\nL'exécution de cet ordre doit être considéré comme un ordre venant directement de la Dame noire. Soyez assuré que les noms des responsables lui seront communiqués de même que ceux qui s'opposent à elle ou cherchent à entraver ses souhaits." } } },
    ["Prismatic Punch Card"] = { { ids = { "i9316" }, first = "thesecurityratingofthisd", pages = { "Ces données sont très secrètes, si secrètes qu'elles ne peuvent même pas être classées !", "01000011 01100001 01110011 01110100 01110000 01101001 01110000 01100101 00100000 00111010 00100000 00111000 00100000 01100011 01101000 01100101 01101101 01101001 01110011 01100101 01110011 00100000 01100101 01110100 00100000 00110011 00100000 01100011 01100001 01101100 01100101 11100111 01101111 01101110 01110011 00101100 00100000 01110011 01110101 01110000 01110000 01101100 11101001 01101101 01100101 01101110 01110100 00100000 01100001 01101101 01101001 01100100 01101111 01101110 01101110 01100001 01100111 01100101 00101110" } } },
    ["Proof of Deed"] = { { ids = { "i10022" }, first = "thisproofofdeedistoverif", pages = { "Cette preuve atteste que $N a tué Margol l'Enragée, fléau de la gorge des Vents brûlants.\n\nLe musée d'Ironforge reconnaît cet exploit, remercie le porteur de la nouvelle et se réjouit de cette généreuse contribution.\n\n-Conservateur en chef Thorius Stonetender" } } },
    ["Pteradon Skeleton"] = { { ids = { "o175685", "o177222" }, first = "thisintactpteradonskelet", pages = { "Ce squelette intact de ptéradon a été découvert dans le lointain cratère d'Un'Goro. D'après la structure du squelette, il apparaît clairement que cette espèce n'a encore jamais été rencontrée. Ce squelette pourrait avoir été préservé pendant des siècles dans le riche sol de la région." } } },
    ["Quel'Thalas Registry"] = { { ids = { "i15847" }, first = "entrydateunknownnamenath", pages = { "Date : Inconnue\n\nNom : Nathanos Marris, seigneur des Forestiers de Lordaeron.\n\nEntrée :\n\nL'opposition de Kael'thas Haut-soleil à ma décision d'accueillir Nathanos Marris dans notre ordre a été notée. Par ailleurs, rappelons-nous que Nathanos, bien qu'il soit humain, est l'un des forestiers les plus doués que j'aie jamais eu le plaisir de former.\n\n(à suivre)", "Durant des millénaires nous nous sommes isolés des étrangers. Je serai la première à admettre que nous avons fait des erreurs dans le passé. Les humains n'auraient jamais dû être exposés à la magie. Je ne le nierai pas mais je ne nous condamnerai pas non plus à une existence arriérée à cause des erreurs de nos ancêtres. Il est possible d'aller au-delà de la simple coexistence entre les Quel'dorei et les autres races de ce monde. Nous devons apprendre la tolérance.\n\n(à suivre)", "C'est en ces termes que je rejette la requête de Kael concernant Nathanos Marris. Il sera un allié de valeur. Souvenez-vous de mes propos.\n\nSigné,\n\nSylvanas Windrunner\nGénéral des Forestiers de Lune-d'argent." } } },
    ["Rabine's Letter"] = { { ids = { "i17355" }, first = "layowehavereceivedthegen", pages = { "Layo :\n\nNous avons reçu l'aide généreuse de cet aventurier. Je vous l'ai envoyé à Silithus pour vous soutenir. Notez qu'il ne doit pas être gaspillé dans vos efforts pour comprendre les secrets qui sont enfouis ici. Le Cercle attend avec impatience des progrès.\n\nQue Cénarius veille sur vous...\nRabine" } } },
    ["Ranger Captain Alleria Windrunner"] = { { ids = { "o25331" }, first = "rangercaptainalleriawind", pages = { "Général des forestiers Alleria Windrunner\n\nCélèbre chasseresse de trolls de Quel'Thalas. Chef des éclaireurs et agent de renseignement attaché à l'expédition de l'Alliance qui a marché sur le monde des orcs, Draenor. Présumée morte.\n\nTon cœur était aussi droit qu'une flèche fendant le vent, sœur. Tu fus la meilleure de notre ordre. Tu fus la meilleure des nôtres.\n\n- Sylvanas Windrunner - Général des forestiers de Quel'Thalas" } } },
    ["Raven Hill Tome"] = { { ids = { "i281046" }, first = "memoriesofvalorarecounto", pages = { "Souvenirs des Valor\nUne chronique de la famille Valor et des services qu'elle a rendus à Colline-aux-Corbeaux\n\nAucune famille des royaumes de l'Est n'est plus remarquable que la famille Valor. Les exploits accomplis par ses membres au service de la population qu'ils avaient juré de protéger tiennent du miracle, et leur disparition est un drame pour tout Colline-aux-Corbeaux.\n\nJ'écris cette chronique pour rétablir la vérité, et montrer que Grant, Ira, Silvia et Merrick étaient des êtres d'exception. Que ces mots soient source de réconfort, car leur absence me peine profondément.", "Merrick Valor, Watcher of Darkshire\n\nMerrick was the youngest son of the Valor family. As he witnessed the corruption coming to his homeland, he chose to join The Watch in a desperate bid to protect his loved ones.\n\nWhile he was the most inexperienced member of his family, he quickly made a name for himself amongst the ranks of The Watchers. He had a knack for archery, and soon became one of the most staunch defenders of Darkshire.\n\nHis personal mission was to keep the roads safe, wary of the ever more hostile creatures coming to the forests.", "Silvia Valor, garde de Colline-aux-Corbeaux\n\nSilvia Valor était déjà une héroïne locale lorsqu'elle fut invitée à rejoindre les rangs de la Garde. S'il y avait bien une chose au monde qu'elle ne pouvait tolérer, c'était les opportunistes qui profitaient du malheur des gens.\n\nBandits, escrocs, fauteurs de troubles, tous connaissaient le même sort. Silvia passait au fil de l'épée quiconque tentait de semer le chaos dans sa contrée chérie. Il n'y avait donc rien d'étonnant qu'elle accède à un poste qui allait lui conférer l'autorité nécessaire pour appliquer son idéal de justice.\n\nÀ croire les récits, ce ne serait qu'en rendant son dernier soupir qu'elle aurait abandonné les fermes et foyers du bois de la Pénombre. Et cela reste encore à prouver.", "Ira Valor, Forest Stalker\n\nWhen Ira's father grew ill, she took it upon herself to gather food and supplies from the nearby forests. While resources were not in short supply, you were as likely to find food as you were to become it.\n\nOver the years, she adapted to the forests, preferring to spend her time within the dark woods rather than in Raven Hill. Travelers who got lost in the trees would tell stories of a shadow seemingly opening the way for them back to the road. There was no confirmations of who it was, but rumors spread quickly.\n\nIt's said that Ira is still in the woods offering a guiding hand to those who fall prey to the beasts within.", "Seigneur Grant Valor, patriarche de la famille Valor\n\nLe seigneur Grant, paix à son âme, était le summum de l'exceptionnalisme de l'Alliance. Un meneur né, ses choix avisés ont contribué à mener la population de Colline-aux-Corbeaux vers la prospérité. Lorsque les ténèbres ont commencé à envahir les bois, il fut le premier à rallier notre peuple.\n\nPour le seigneur Grant, aucun adversaire n'était plus abject que les morts-vivants. Il patrouillait en personne dans les cimetières du bois de la Pénombre pour contenir les hordes chancelantes. Le jour où les monstres lui infligèrent une grave blessure, toute la ville partagea sa souffrance.\n\nGrâce au dévouement de sa famille, il put reprendre ses fonctions, mais un mal tenace sembla l'affecter jusqu'à la fin de ses jours.", "Dame Cassandra Valor, épouse et mère aimante\n\nOn sait peu de choses au sujet de Cassandra, si ce n'est qu'elle aimait sa famille. Elle prit grand soin de braves enfants et d'un mari puissant, en amenant certains à s'imaginer qu'elle était la source de la grandeur de sa famille. Des louanges qu'elle démentait toujours avec grâce.\n\nSi elle ne doit rester dans les mémoires que pour une unique raison, n'oublions jamais qu'elle a toujours œuvré pour le bien de sa famille." } } },
    ["Recruitment Letter"] = { { ids = { "i4992" }, first = "hordeconscriptionregistr", pages = { "Registre de conscription de la Horde\n\nCette personne a montré de grands talents au service de la Horde. Il faut immédiatement l'affecter à la Croisée.\n\nRespectueusement :\n\nÇa m'a l'air parfait.\n- Takrin Pathseeker" } } },
    ["Red Punch Card"] = { { ids = { "i9281" }, first = "securityratingsupersensi", pages = { "Niveau de sécurité 10^10000 données très sensibles !\n\n01000001 01110101 00100000 01110011 01100101 01100011 01101111 01110101 01110010 01110011 00100000 00100001 00100000 01001111 01101110 00100000 01101101 00100111 01100001 00100000 01100101 01101110 01100110 01100101 01110010 01101101 11101001 00100000 01100100 01100001 01101110 01110011 00100000 01110101 01101110 01100101 00100000 01110101 01110011 01101001 01101110 01100101 00100000 01100100 01100101 00100000 01100011 01100001 01110010 01110100 01100101 01110011 00100000 01110000 01100101 01110010 01100110 01101111 01110010 11101001 01100101 01110011 00100000 00100001" } } },
    ["Report on the Defias Brotherhood"] = { { ids = { "i2956" }, first = "fromthehandofbarosalexst", pages = { "De la main de Baros Alexston,\nBureau de l'Architecte de la cité\nStormwind\n\nSire,\n\nPour de nombreuses raisons, j'ai pensé qu'un rapport devait être compilé et présenté sur les affaires récentes concernant la \"Confrérie Défias\" et ses activités dans le royaume.\n\nJe commencerai par un peu d'histoire. Comme Votre Majesté le sait peut-être, mes services à la ville de Stormwind ont commencé au sein de la Guilde des Maçons. Des années de travail ont permis la reconstruction de", "Stormwind, après quoi les honoraires de la Guilde des Maçons n'ont pas été acquittés.\n\nÀ l'époque, Edwin VanCleef venait d'être élu Maître de la Guilde des Maçons et il se fit le porte-parole des doléances de ses compagnons. En réponse, la Maison des Nobles de Stormwind ordonna la dissolution de la Guilde des Maçons, ce qui, c'est compréhensible, rendit VanCleef furieux. Dans une atmosphère d'émeute, VanCleef mena les Maçons hors de la ville.\n\nAvant de continuer, voici quelques-uns des événements qui sont survenus durant", "ces temps troublés et sur lesquels j'attire l'attention de Votre Majesté.\n\nTout d'abord, c'est à cette époque que je me vis offrir le poste d'architecte de la cité à condition de ne pas rejoindre VanCleef. En raison de certains divergences d'opinion avec lui, je choisis de rester à Stormwind.\n\nPendant les émeutes, le lieutenant de VanCleef, Bazil Thredd, fut capturé et jeté en prison, où il fut presque oublié, dans l'attente d'un procès.\n\nPour en revenir à VanCleef, après avoir conduit le restant des", "Maçons hors de Stormwind, il profita des faibles défenses de la marche de l'Ouest et s'appuya sur ses troupes pour chasser nombre de fermiers avant de s'emparer des mines d'or.\n\nGrâce à ces ressources, VanCleef a préparé la vengeance contre le gouvernement de Stormwind.\n\nCette information m'est parvenue dernièrement grâce à l'aide du porteur de ce document, qui a beaucoup contribué à mettre en lumière les dessous de cette vaste conspiration." } } },
    ["Rexxar's Testament"] = { { ids = { "i16785" }, first = "thispagedocumentisblank", pages = { "Ce document de 3 pages est vierge." } } },
    ["Ripped Note"] = { { ids = { "i4101" }, first = "thatbeastthatreignsovert", pages = { "La bête qui règne sur cette île est vraiment puissante. Crins-de-ciel ou jagueros, les autres créatures tremblent devant elle. Même aujourd'hui, j'entends ses rugissements et ils me font frémir.\n\nCes créatures arrêteront à coup sûr tous ceux qui s'approcheront de l'île. Je dois avoir foi en mes ancêtres." } } },
    ["Rise of the Blood Elves"] = { { ids = { "o175760" }, first = "atthistimetheundeadscour", pages = { "A cette époque, le Fléau mort-vivant avait transformé Lordaeron et Quel'Thalas. Ces deux contrées étaient devenues les Maleterres maudites et contaminées. Il ne restait que quelques poches de résistance de l'Alliance. L'une d'elles, composée essentiellement de hauts-elfes, était menée par le dernier héritier des Haut-soleil : le prince Kael'thas.", "Kael, lui-même magicien accompli, eut vent des défaillances de l'Alliance. Les hauts-elfes pleuraient la perte de leur terre natale et décidèrent de prendre le nom d'elfes de sang en souvenir de leur peuple décimé. Tout en luttant pour repousser le Fléau, ils souffraient d'avoir été coupés du Puits qui leur avait conféré leurs pouvoirs.", "Voulant désespérément trouver un remède à l'accoutumance de son peuple à la magie, Kael fit l'impensable : il accepta l'héritage ancestral des Bien-nés et se joignit à Illidan et ses nagas dans l'espoir de trouver une nouvelle source de puissance magique. Les autres commandants de l'Alliance condamnèrent la traîtrise des elfes de sang et les rejetèrent définitivement.", "N'ayant nulle part où aller, Kael et ses elfes de sang suivirent dame Vashj en Outreterre pour s'en prendre à Maiev, qui avait mis la main sur Illidan. L'assaut combiné des nagas et des elfes de sang vint à bout de Maiev et permit de libérer Illidan. Depuis l'Outreterre, Illidan rassembla des forces pour une seconde attaque contre le roi-liche et la forteresse de la Couronne de glace." } } },
    ["Rise of the Horde"] = { { ids = { "o175742" }, first = "theorcsbecameincreasingl", pages = { "Sous le contrôle secret de Gul'dan et de son Conseil des ombres, les orcs devinrent extrêmement agressifs. Ils construisirent de grandes arènes où les guerriers s'entraînaient au combat et au meurtre. Pendant cette période, quelques chefs de clan se déclarèrent opposés à la dépravation croissante de leur race.", "Parmi eux, Durotan, du clan Frostwolf, prévint les orcs qu'ils allaient se perdre dans tant de haine et de fureur. Nul ne l'écouta, car des chefs plus puissants, tels que Grom Hellscream du clan Warsong, se faisaient les champions de ce nouvel âge de guerre et de domination.", "Kil'jaeden savait que les clans des orcs étaient presque prêts, mais il avait besoin de s'assurer de leur totale loyauté. En secret, il fit invoquer Mannoroth le Destructeur, incarnation vivante de la destruction et de la rage, par le Conseil des ombres. Gul'dan rassembla les chefs des clans et les convainquit que boire le sang bouillonnant de Mannoroth les rendrait pratiquement invincibles.", "Menés par Grom Hellscream, tous les chefs de clan à l'exception de Durotan burent le sang et scellèrent ainsi leur destin : celui d'esclaves de la Légion ardente. Renforcés par la rage de Mannoroth, les chefs étendirent leur allégeance à leurs frères.", "Consumés par la malédiction de cette soif de sang nouvelle, les orcs cherchèrent à déchaîner leur fureur sur quiconque se dressait devant eux. Sentant que l'heure était venue, Gul'dan unifia les clans guerriers en une Horde invincible.", "Cependant, sachant que divers chefs comme Hellscream et Orgrim Doomhammer rivaliseraient pour la suprématie, Gul'dan choisit un homme de paille pour en faire le meneur de la nouvelle Horde. Blackhand le Destructeur, un seigneur de guerre particulièrement dépravé et vicieux, fut choisi pour être la marionnette de Gul'dan. Sous le commandement de Blackhand, la Horde s'en prit aux draeneï.", "En quelques mois, la Horde éradiqua presque tous les draeneï de Draenor. Quelques survivants dispersés parvinrent à échapper à la colère terrible des orcs. Enivré par la victoire, Gul'dan se délecta de la puissance de la Horde. Mais il savait que sans ennemi à combattre, la Horde se désagrégerait en luttes intestines interminables dans son appétit inextinguible de gloire et de massacre.", "Kil'jaeden savait que la Horde était enfin préparée. Les orcs étaient devenus l'arme la plus puissante de la Légion ardente. Le démon rusé le fit savoir à son maître et Sargeras comprit que le temps de sa revanche était venu." } } },
    ["Roc Talon"] = { { ids = { "o175681" }, first = "thispetrifiedtalonwasfou", pages = { "Cette griffe pétrifiée a été trouvée sur les côtes sud de Strangleronce. Les écologistes pensent qu'il pourrait appartenir à un ancien Roc solaire. Bien que ces créatures apparaissent surtout dans les légendes et mythes des taurens, cette griffe suggère qu'elles pourraient avoir bel et bien existé." } } },
    ["Rock of Durotan"] = { { ids = { "o179909" }, first = "hereliesdurotanfirstchie", pages = { "Ci-gît Durotan, premier chef du clan Loup-de-Givre et père de notre vénéré chef de guerre Thrall. Il était le plus brave d'entre nous, trahi par ceux qui voulaient réduire notre peuple en esclavage. Durotan donna sa vie pour que nous puissions gagner notre liberté. Nous honorons sa mémoire et l'héritage qu'il nous a transmis par son fils.\n\nDrek'Thar, long-voyant des Loups-de-Givre" } } },
    ["Rune-Inscribed Note"] = { { ids = { "i9552" }, first = "igreetyouyoungthewindsto", pages = { "Je vous salue, jeune $C. Les vents m'ont annoncé votre arrivée. La terre loue votre force. Et désormais les esprits anciens annoncent vos futurs accomplissements. Notre peuple a besoin de chefs importants et sages. Il se tourne souvent vers nous pour ces deux vertus. Si vous le désirez, je vous instruirai.\n\nTrouvez-moi dans le Camp Narache sur la Mesa de Nuage rouge. Nous discuterons plus amplement.\n\n-Meela Dawnstrider, Maître des chamans" } } },
    ["Rune-Inscribed Parchment"] = { { ids = { "i9568" }, first = "loktarbrothersistertheel", pages = { "Lok-tar, $gfrère:soeur;. Les éléments annoncent votre venue et me demandent de vous guider sur la voie du chaman. Les esprits de nos ancêtres observent depuis l'au-delà et tremblent de fierté à l'idée que vous ayez rejoint nos rangs.\n\nQuand vous le jugerez bon, venez me voir à l'entrée de l'Antre. C'est là que je forme les nôtres. Jusque là, que les vents vous soient favorables.\n\n-Shikrik, Maître des chamans" } } },
    ["Rune-Inscribed Tablet"] = { { ids = { "i9562" }, first = "greetingstoyoubrothasist", pages = { "Salutations. Les esprits disent que vous pouvez maintenant rejoindre nos rangs. Vous avez des liens solides avec les éléments, et vous avez bien plus de puissance aujourd'hui que lorsque vous avez commencé vos leçons avec nous.\n\nJe vous envoie maintenant à Shikrik, la chaman orc de la Vallée des épreuves. Elle sait déjà que vous viendrez étudier avec elle. Remplissez nos ancêtres de fierté. Jusqu'à ce que nous nous revoyions, que la flamme vous réchauffe et que les vents vous portent.\n\n-Ishi-yo" } } },
    ["Sara Balloo's Plea"] = { { ids = { "i4514" }, first = "tomyhonorablekingtisnott", pages = { "A mon vénéré roi :\n\nCe n'est pas le rôle d'une pauvre femme de soldat de demander des comptes aux grands chefs tels que Votre Majesté. Les combats qui font rage sur nos terres ont pour but de préserver la vie que nous aimons et dont nous sommes fiers, depuis les eaux du Loch jusqu'aux pics enneigés de Dun Morogh.", "Mais quel est le prix que nous devons payer au nom de notre liberté ? Combien nous faudra-t-il perdre de soldats pour comprendre que la vie même que nous cherchons à protéger nous échappe sur le champ de bataille ?\n\nCombien de haches et d'épées nous faudra-t-il forger pour acheter notre avenir ? Sous combien de pierres tombales devrons-nous enterrer notre passé ?", "Une simple femme de soldat n'a pas à poser ces questions.\n\nPourtant j'écris à Votre Majesté, en tant que veuve de soldat. Mon mari n'était peut-être qu'un soldat parmi les milliers de votre armée. Mais pour moi il était le grand Sully Balloo, père de mes enfants et amour de ma vie.\n\nPardonnez-moi si mes questions, Sire, semblent inappropriées à Votre Majesté. Mais les morts ne peuvent poser eux-mêmes ces questions....\n\nVotre loyale servante,\nSara Balloo" } } },
    ["Sargeras and the Betrayal"] = { { ids = { "o175724" }, first = "overtimedemonicentitiesm", pages = { "Avec le temps, les entités démoniaques parvinrent aux mondes des titans depuis le Néant distordu. Le Panthéon élut le plus grand guerrier, Sargeras, et lui confia la charge de défendre le bien. Sargeras, noble géant de bronze fondu, remplit sa tâche pendant d'innombrables millénaires, cherchant et détruisant les démons partout où il pouvait les trouver. Par delà les éons, Sargeras rencontra deux races démoniaques puissantes, toutes deux régies par l'appétit de puissance et désireuses de dominer l'univers physique.", "Les érédars, race sournoise de sorciers démoniaques, utilisèrent leur magie impie pour envahir et réduire en esclavage de nombreux mondes. Les races indigènes de ces mondes furent transformées par les pouvoirs chaotiques des érédars et devinrent elles-mêmes démoniaques", "Les pouvoirs presque sans limite de Sargeras étaient bien suffisants pour détruire les ignobles érédars, mais le Titan fut troublé par la corruption de ces créatures et par le Mal qui consumait tout sur son passage. Incapable de comprendre cette dépravation et cette malveillance, le grand Titan tomba dans une dépression sans fin. En dépit de son malaise grandissant, Sargeras chercha à débarrasser l'univers des sorciers à jamais, en les enfermant dans une cellule de vide au coeur du Néant distordu.", "Alors que sa confusion et sa dépression empiraient, Sargeras dut faire face à un autre groupe décidé à perturber l'ordre des Titans : les Nathrezim. Cette race obscure de démons vampiriques (également connus sous le nom de seigneurs de l'Effroi) conquit nombre de mondes peuplés en possédant ses habitants et en les transformant en ombres.", "Les immondes comploteurs avaient dressé des nations les unes contre les autres en les manipulant par la défiance et la haine aveugle. Sargeras vainquit les Nathrezim facilement, mais il fut profondément affecté par leur corruption.", "Le noble Sargeras, incapable de lutter contre les doutes et le désespoir frénétiques qui accablaient sa raison, perdit foi non seulement en sa mission mais aussi en la vision des Titans d'un univers ordonné. Sargeras commença à croire que le concept même d'ordre était pure démence, et que le chaos et la dépravation étaient les seuls absolus dans le vaste univers sombre et solitaire.", "Les autres Titans tentèrent de le convaincre de son erreur et de mettre du baume sur son coeur meurtri, mais il repoussa leurs arguments comme de simples illusions. Sargeras quitta leurs rangs pour toujours afin de trouver sa propre place dans l'univers. Le Panthéon fut attristé de son départ mais ne pouvait imaginer ce qu'il adviendrait de lui.", "Tandis que la folie de Sargeras détruisait les derniers vestiges de son noble esprit, il commença à penser que les Titans étaient les vrais responsables de l'échec de la création. Il décida finalement de détruire leur travail à travers tout l'univers et il commença à rassembler une armée invincible qui nettoierait l'univers physique par le feu.", "Même la forme gigantesque de Sargeras fut transformée par la corruption qui gangrenait son coeur naguère noble. Ses yeux, ses cheveux et sa barbe devinrent des foyers ardents et sa peau de bronze s'ouvrit pour révéler une fournaise sans fin de fureur et de haine.", "Dans sa folie, Sargeras ouvrit la prison des érédars et des Nathrezim et libéra les infâmes démons. Rusés, les démons s'inclinèrent devant la colère sans borne et le pouvoir du Titan, s'offrirent à lui et lui promirent de le servir de toutes les manières qu'ils pourraient. Dans les rangs des puissants érédars, Sargeras choisit deux champions pour commander son armée démoniaque destinée à détruire.", "Kil'jaeden le Trompeur fut choisi pour trouver les races les plus sombres de l'univers et les attirer dans l'ombre de Sargeras. Le second champion, Archimonde le Profanateur, fut choisi pour conduire les vastes armées de Sargeras au combat contre quiconque se dresserait contre le Titan noir.", "Le premier acte de Kil'jaeden consista à placer les seigneurs de l'Effroi sous son terrible pouvoir. Les seigneurs de l'Effroi devinrent ses agents préférés et sa garde d'élite à travers l'univers. Ils prenaient plaisir à leur travail, qui consistait à trouver des races primitives susceptibles d'être corrompues par leur maître. Le premier des seigneurs de l'Effroi était Tichondrius le Sombre. Tichondrius était un soldat parfait pour Kil'jaeden. Il accepta de porter la volonté embrasée de Sargeras jusqu'aux confins de l'univers.", "Le puissant Archimonde utilisa également ses propres agents. Il fit appel aux maléfiques seigneurs des Abîmes et à leur abject dirigeant, Mannoroth le Destructeur, espérant forger une élite de combat capable de tuer toute vie dans la création.", "Sargeras, voyant que ses armées étaient rassemblées et prêtes à suivre ses ordres, lança ses forces tempétueuses dans les immenses étendues du Grand Néant. Il décida de nommer son armée sans cesse plus nombreuse la Légion ardente. On ne sait toujours pas à ce jour combien de mondes ont été consumés et brûlés dans cette croisade impie à travers l'univers." } } },
    ["Saurial Egg"] = { { ids = { "o175684" }, first = "foundintheremoterainfore", pages = { "Trouvé dans les forêts lointaines du cratère d'Un'Goro, cet œuf contenait naguère un embryon de Diablosaure. Le matériau génétique de cet animal s'est avéré d'une importance vitale pour les écologistes de la Ligue, qui sont plus près que jamais de découvrir un sérum contre le venin du Diablosaure." } } },
    ["Scarlet Crusade Documents"] = { { ids = { "i2885" }, first = "disperseinformationasyou", pages = { "Propagez l'information selon les moyens qui vous semblent appropriés.\n\nCommandement régional de Tirisfal\nCapitaine Melrose\nCapitaine Vachon\nCapitaine Perrine\n\nPar l'ordre du généralissime.\n\nCapitaine Perrine, fortifiez votre position à la tour du sud-ouest (comme indiqué). Des fournitures vous seront envoyées à une date ultérieure. En attendant, les matériaux voulus peuvent être obtenus dans les fermes voisines. De plus, des reconnaissances et des informations", "doivent impérativement nous renseigner sur l'organisation des morts-vivants à Brill.\n\nCapitaine Vachon, il semble que les morts-vivants s'agitent près de la tour du Nord. Vous devez vous occuper promptement de ces troubles.\n\nCapitaine Melrose, le niveau d'organisation des morts-vivants cause des soucis près de la frontière des Maleterres. Des troupes fraîches seront affectées à votre position dans les semaines à venir.\n\nGloire et Lumière" } } },
    ["Scribbled Letter"] = { { ids = { "i251941" }, first = "oiyougetoffyerduffandcom", pages = { "Hé, vous, $C. Bougez-vous et venez me voir derrière l'abbaye. Sans guide, $gun chasseur:une chasseresse; novice $gtel:telle; que vous n'a aucune chance de se débrouiller ni même de survivre dans les environs. Heureusement, le bon vieux Tordrin est là pour vous filer un coup de main, si vous vous sentez d'attaque !\n\nTordrin Tigelame, maître des chasseurs (et très bel homme)" } } },
    ["Scribbled Note"] = { { ids = { "i282421" }, first = "greetingsyouveshowngreat", pages = { "Salutations, $N.\n\nVos capacités de chasse sont prometteuses et j'aimerais m'assurer que vous bénéficiez d'un accompagnement et d'un entraînement adaptés.\n\nLes forestiers s'occupent de contrôler la faune locale du bosquet de Thendal, mais hors de nos frontières… c'est une tout autre histoire.\n\nVenez me retrouver au centre du village dès que possible. La nature vous appelle.\n\n– Tai'ree Doublevue, maîtresse des chasseurs" } } },
    ["Sealed Research Report"] = { { ids = { "i23008" }, first = "helloasitturnsoutiveunea", pages = { "Salut, $N. Eh bien, il semblerait que j'aie réussi à dénicher quelques informations à partir de cette note.\n\nJe crains de ne pas avoir trouvé grand-chose sur James. Cependant, j'ai fait quelques découvertes sur Amelia.\n\nNi elle ni ses enfants n'ont survécu à la guerre, mais son frère, un certain Alexander Calder, est toujours en vie. Vous pourrez le trouver dans la Caverne lugubre d'Ironforge, où il étudie la dangereuse magie de la Légion ardente.\n\nAmelia avait aussi une cousine dont elle était très proche, nommée Deze Snowbane, qui recrute pour la bataille du bassin d'Arathi à Orgrimmar.\n\nVous devriez rendre visite à l'un d'entre eux quand vous sera dans le coin. Je suis certain qu'ils seront contents d'entendre parler de leur défunte Amelia, à défaut de mieux." } }, { ids = { "i23010" }, first = "greetingsithoughtyoumigh", pages = { "Bien le bonjour, $N. Je pense que vous serez $gintéressé:intéressée; par les résultats de mes recherches.\n\nIl semblerait que des membres de la famille de Reuben et de Leagrem aient survécu... Enfin, c'est une façon de parler. Même s'ils connaissent déjà le destin des soldats tombés, leur rendre visite en vaudra la peine.\n\nVous pourrez trouver l'ex-épouse de Reuben, Joanna Whitehall, dans le Quartier de la guerre d'Undercity, où elle passe le plus clair de son temps. Je ne sais pas trop si elle appréciera vraiment de recevoir des nouvelles, mais vous verrez bien…\n\nQuant à Leagrem, sa tante est devenue la gouvernante de l'orphelinat de Stormwind, un poste admirable.\n\nQuelle que soit la voie que vous suivrez, je vous souhaite bonne chance dans votre entreprise." } }, { ids = { "i23011" }, first = "ihopethisletterfindsyouw", pages = { "$N, j'espère que cette lettre vous trouvera en bonne santé. Après avoir fouillé dans mes archives, j'ai découvert quelques informations sur les personnes qui ont écrit la note que vous avez récupérée.\n\nLe père de Samla dirige les Réprouvés et les trolls qui font le pèlerinage vers Thunder Bluff, en digne représentant de sa foi. Il se nomme Miles Welsh, et vous pourrez le trouver avec ses amis morts-vivants aux Bassins de la vision.\n\nLa cousine de Torgal, Elissa Dumas, a survécu. D'après ce que j'ai compris, elle mène une existence de recluse, et passe ses journées au Temple de la lune à Darnassus.\n\nJe vous conseille de rendre visite à l'un d'entre eux, $N. Ils n'ont peut-être jamais appris ce qui était arrivé à Torgal ou Samla." } }, { ids = { "i23012" }, first = "thekeeperpassedonthelett", pages = { "\"Le Gardien m'a transmis la lettre que vous avez découverte, $N, et j'ai pensé que vous apprécieriez peut-être quelques nouvelles.\n\nOn a retrouvé la trace du dernier survivant de la famille du \"Vargus\" mentionné dans le courrier en Silithus, au Fort cénarien. Il se nomme Garon Hutchins.\n\nVous devriez lui parler durant votre prochaine excursion dans le désert. Il sera peut-être heureux que vous lui relatiez ce que nous avons appris.\n\n\"" } }, { ids = { "i23013" }, first = "salutationsiveatlastfoun", pages = { "Salutations. J'ai enfin trouvé le temps d'examiner la missive que vous avez trouvée sur le Fléau. Bien que cela m'ait donné un peu de fil à retordre, je pense avoir découvert une parente du défunt encore en vie.\n\nLa sœur de Maxwell, une certaine Zarena Cromwind, dirige une petite affaire de vente d'armes à Baie-du-Butin. Je ne sais pas vraiment si elle était très proche de son frère, mais si vous passez dans la région, vous devriez lui rendre une petite visite. Pouvoir mettre un point final à ce genre d'affaire est une chose précieuse et rare, de nos jours." } }, { ids = { "i23016" }, first = "ivefinallyunearthedsomei", pages = { "J'ai enfin réussi à déterrer quelques informations sur l'ancien soldat que vous avez combattu. La piste était difficile à suivre, car cette branche de l'arbre généalogique de la famille n'était pas à jour. Mais je suis tout de même parvenu à trouver un de ses parents.\n\nAuriez-vous cru que le conservateur Alen, à la chapelle de l'Espoir de Lumière, est en réalité le fils de Christoph ? Recevoir des nouvelles de son père pourrait l'apaiser. Si vous vous retrouvez une nouvelle fois au service de l'Aube d'argent dans les Maleterres, je vous en prie, allez lui parler. Ce serait un acte de pure bonté." } } },
    ["Secret Note #1"] = { { ids = { "i12765" }, first = "agashamourplansmustbekep", pages = { "Agasham,\n\nnos plans doivent rester secrets à tout prix ! Il serait désastreux que les autres tribus taurens découvrent notre alliance.\n\nSigné,\n\nMessager Elm" } } },
    ["Secret Note #2"] = { { ids = { "i12766" }, first = "agashamworkingtogetherou", pages = { "Agasham,\n\nEn travaillant de concert, nos forces seront plus puissantes que toutes les tribus de taurens réunies ! Mais nous avons besoin de votre totale obéissance. Souvenez-vous, votre peuple sera récompensé lorsque nos plans auront porté leurs fruits !\n\nSigné,\n\nMessager Rex" } } },
    ["Secret Note #3"] = { { ids = { "i12768" }, first = "agashamouragentsfromlord", pages = { "Agasham,\n\nNos agents de Lordaeron rencontreront bientôt vos délégués, très bientôt. Nous vous contacterons quand nous aurons trouvé un lieu adéquat pour notre rencontre.\n\nSigné,\n\nMessager Grakus" } } },
    ["Senir's Report"] = { { ids = { "i2628" }, first = "areportonthestateofthefr", pages = { "Rapport sur les Trolls crins-de-givre dans la région de Dun Morogh\n\nPréparé par Senir Blanchebarbe, envoyé spécial du sénat\n\nLes Trolls situés dans Dun Morogh sont essentiellement concentrés dans le repaire des Crins-de-givre, un renfoncement montagneux à la frontière de l'ouest. Ils sont en nombre suffisant pour causer une grave inquiétude, mais ils ne semblent pas avoir la velléité de sortir de leur antre. Probablement ne souhaitent-ils pas encourir de nouveau la colère des Nains et risquer l'extermination totale. Leurs actions restent confinées dans leur territoire, et je", "pense qu'ils ne nous menacent pas directement, tant que nous ne mordons pas sur leur territoire. Cette situation n'est pas confortable pour la population des Nains, mais vu la dispersion des ressources militaires, il semble prudent de reléguer l'extermination des Trolls à un niveau moindre d'importance et de continuer à nous concentrer sur la menace posée par les Troggs et les Sombrefer.\n\nVous trouverez ci-joint un exemplaire du rapport de mon frère Grelin sur Courbenclume, ainsi que le rapport de l'un de nos montagnards sur le wendigo.\n\nSigné,\nSenir Blanchebarbe", "Rapport sur la situation des wendigos dans les grottes proches de Kharanos\n\nRédigé par la montagnarde Gretchen sur la base des observations du montagnard Cornélius\n\nLes wendigos s'aventurent rarement hors de leurs grottes, mais des attaques de civils ont été signalées à plusieurs reprises à proximité de villages comme Kharanos et Brassetout. Les wendigos semblent de plus en plus agités lorsqu'ils se mettent en quête de nourriture. Nous avons d'ailleurs perdu l'un des nôtres en tentant d'enrayer le problème. Si l'élimination totale de ces bêtes n'est pas envisageable, les montagnards demandent", "des moyens supplémentaires afin de freiner leur propagation. Nous ne pouvons pas indéfiniment recourir à des aventuriers pour faire face au problème, et espérer que les choses finissent par s'arranger. Tôt ou tard, les wendigos viendront à manquer de nourriture et s'attaqueront directement à nos villes. Même Forgefer pourrait être touchée.\n\nJe vous prie de présenter mes condoléances à la famille du montagnard Cornélius, qui a vaillamment combattu pour protéger la population de Dun Morogh.", "Rapport sur les trolls Frostmane dans la région de la vallée des Frigères\n\nPréparé par Grelin Whitebeard, Envoyé spécial du Sénat\n\nAprès avoir passé du temps à observer les mouvements des trolls Frostmane dans la région de la vallée des Frigères, je suis en mesure de dire qu'ils ne représentent pas une menace sérieuse pour les comptoirs des nains dans la zone. Bien plus, avec une petite aide de l'armée, la question pourrait rapidement être réglée. Avec le soutien des Montagnards déjà présents dans la", "vallée des Frigères et de mercenaires (payés par les fonds débloqués avant mon départ par le Sénat), je suis convaincu que le problème sera résolu rapidement.\n\nCette action a été autorisée par le roi Bronzebeard." } } },
    ["Sevren's Orders"] = { { ids = { "i3017" }, first = "lordbethoriceshardaspery", pages = { "Seigneur Bethor Iceshard,\n\nSuivant vos instructions, je vous envoie l'agent que vous avez demandé. C'est le porteur de ce message.\n\nCette personne s'est révélée fiable et capable d'obéir aux ordres, a su affronter les forces du Fléau, et son choix s'impose pour votre mission.\n\nQue Son règne soit éternel,\n-Magistrat Sevren" } } },
    ["Shadowsworn Note"] = { { ids = { "i227658" }, first = "weneedmorewillingsacrifi", pages = { "Il nous faut d'autres sacrifices volontaires !\n\nCet autel doit demander une manipulation spéciale. Pour l'instant, il n'a rien produit.\n\nPrésentez votre rapport aux anneaux du serpent lorsque vous découvrirez quelque chose d'utile." } } },
    ["Shaw's Report"] = { { ids = { "i1353" }, first = "lordstoutmantleledbyedwi", pages = { "Seigneur Stoutmantle--\n\nSous la direction d'Edwin VanCleef, la guilde des Maçons est devenue la plus expérimentée des associations de bâtisseurs parmi les hommes. Les maçons ont aidé à la reconstruction de la cité dévastée de Stormwind, rasée par les orcs durant la Première Guerre. VanCleef et ses hommes se sont montrés sans égaux, et leur travail élégant apparaît dans des édifices comme la cathédrale de la Lumière et le donjon de Stormwind.", "Cependant, les nobles de Stormwind se sont gravement endettés en étendant la présence militaire du royaume jusqu'à Elwynn et Strangleronce. Cette énorme dette a sapé l'économie du royaume et privé VanCleef et ses maçons de la récompense qu'ils méritaient. Après des années de labeur pour reconstruire la glorieuse cité, les maçons n'ont pas touché une pièce d'argent, oubliés par les dirigeants corrompus de la ville.", "Je connais personnellement Edwin VanCleef depuis toujours, je vous assure que l'avoir comme ennemi est une mauvaise idée. C'est un ami d'enfance, et je lui ai personnellement appris les voies des Ténèbres, au cas où il envisagerait un jour une carrière à mes côtés. Si VanCleef rejoint la Confrérie des Défias, que la Lumière ait pitié de nous.\n\nMaître Mathias Shaw\nGuilde des Assassins de Stormwind" } } },
    ["Signed Recruitment Letter"] = { { ids = { "i4995" }, first = "hordeconscriptionregistr", pages = { "Registre de conscription de la Horde\n\nCette personne a montré de grands talents au service de la Horde. Il faut immédiatement l'affecter à la Croisée.\n\nRespectueusement :\n- Kargal Battlescar\n\nÇa m'a l'air parfait.\n- Takrin Pathseeker" } } },
    ["Simple Letter"] = { { ids = { "i9542" }, first = "tellmehaveyouheardanorcs", pages = { "Dis-moi, $C, as-tu déjà entendu un orc hurler ? As-tu déjà défendu ton foyer contre des gnolls qui cherchaient à t'arracher la gorge ? Ouais, ça paraît brutal, hein ?\n\nEh bien, tu vas avoir besoin de mon aide si tu veux protéger les tiens. Tu me trouveras dans l'abbaye de Comté-du-Nord. Mon savoir n'est pas donné, mais si tu as assez d'expérience, je peux t'enseigner des techniques et des mouvements qui t'aideront à combattre les menaces qui pèsent sur Hurlevent et au-delà.\n\nLlane Beshere, maître des guerriers" } } },
    ["Simple Memorandum"] = { { ids = { "i9544" }, first = "attentionyoumustreportto", pages = { "ATTENTION :\nVous devez immédiatement vous présenter devant Thran Khorman. Il se trouve dans le bâtiment A3, également connu sous le nom d'Anvilmar chez les habitants des environs. Quand vous aurez réussi à prendre contact avec Khorman, vous commencerez à vous préparer pour la future guerre, la guerre qui vous permettra de reprendre possession de Gnomeregan !\n\nTous vos efforts et les tâches les plus importantes doivent converger vers ce but. Une fois ceci accompli, une nouvelle tâche vous sera donnée." } } },
    ["Simple Note"] = { { ids = { "i9547" }, first = "manytribesclaimthatitisa", pages = { "Bien des tribus affirment que c'est un don de savoir utiliser la magie ou de pouvoir parler avec les ancêtres. Mais sachez que vous aussi avez des dons, $C. Il est des gens qui n'ont pas le bras assez puissant pour tenir le bouclier, parer le coup d'un assassin, souffrir les douleurs infligées par un maître des arcanes. Vous, si. Vous avez cette force. Et je vous aiderai à en profiter. Vous me trouverez au Camp Narache.\n\n-Harutt Thunderhorn, Maître des guerriers" } } },
    ["Simple Parchment"] = { { ids = { "i12635" }, first = "thromkawarrioriwontfawno", pages = { "Throm-Ka, guerrier. Je ne m'attarderai pas sur votre valeur et votre force. Tout ça est connu. Vous avez tué des humains dernièrement ? Pas beaucoup, je suppose. Vous mollissez. Sans défis, vous vous embourgeoisez.\n\nJ'ai besoin d'un peu d'aide et, quoi que vous en pensiez, vous aurez l'usage des leçons que je peux vous donner. Quand vous aurez réussi à vous enfoncer ça dans le crâne, je vous attendrai sous la canopée.\n\n-Frang, Maître des guerriers" } } },
    ["Simple Rune"] = { { ids = { "i9543" }, first = "bymagnisbeardtheresmucht", pages = { "Par la barbe de Magni, nous avons beaucoup à dire, et peu de temps à y consacrer, $N. Trouvez-moi à Anvilmar, qui surplombe la vallée des Frigères, dès que vous le pourrez. Nous pourrons alors commencer.\n\nIl y a beaucoup de choses que je voudrais vous dire mais cela nous éloigne du sujet. Nous devons nous concentrer sur la manière d'empoigner une hache, sur le poids de notre armure, sur l'odeur de notre transpiration qui coule de notre front tandis que nous combattons nos ennemis. Nous débuterons avec cela.\n\n-Thran Khorman, Maître des guerriers" } } },
    ["Simple Scroll"] = { { ids = { "i9546" }, first = "manyofourkindresorttothe", pages = { "Beaucoup parmi nous ont recours aux arcanes et aux divinités pour gagner en force, mais nous savons ce qu'il en est, n'est-ce pas, $C ? Nous savons que nos armes sont nos symboles sacrés, que notre bouclier est notre livre de sorts et que nos mailles sont notre sagesse.\n\nMême dans la non-mort nous sommes forts, et nous deviendrons plus forts encore.\n\nTrouvez-moi à l'auberge du village de Glas. Je vous en dirai davantage sur tout ceci et sur d'autres choses encore.\n\n-Dannal Stern, Maître des guerriers" } } },
    ["Simple Sigil"] = { { ids = { "i9545" }, first = "ihopemysigilfindsyouwell", pages = { "J'espère que mon message vous trouvera en bonne forme, $C. Je vous écris parce que notre peuple a grand besoin de ceux qui savent manier l'épée, le glaive, toutes les armes. Il est arrivé tant de choses depuis que notre peuple a rencontré les autres races d'Azeroth que nous avons besoin de toutes sortes de protecteurs.\n\nC'est là que vous entrez en jeu. Je vous en dirai plus, mais vous devez venir en personne. Vous me trouverez dans Aldrassil... dans les niveaux inférieurs.\n\n-Alyissia, Maître des guerriers" } } },
    ["Simple Tablet"] = { { ids = { "i6488" }, first = "ayemontakedislettertofra", pages = { "Salut. Apportez cette lettre à Frang dans la Vallée des épreuves. On le trouve en général en dehors de l'Antre, formant à la dure de jeunes guerriers pour la Horde.\n\nIl a besoin de guerriers astucieux comme vous pour montrer aux orcs comment se battre avec autre chose que leurs muscles. Vous êtes plus rapide et plus habile que la plupart, mais ne vous vantez pas de ces choses-là. Les orcs prennent assez mal ce genre d'insultes. Ils sont de bons alliés et ils vous apprendront peut-être une chose ou deux.\n\n-Tar'sere" } } },
    ["Snapshot of Gammerita"] = { { ids = { "i9330" }, first = "", pages = { "" } } },
    ["Snufflenose Owner's Manual"] = { { ids = { "i5897" }, first = "congratulationsyouarethe", pages = { "FÉLICITATIONS !\n\nVous voilà l'heureux propriétaire d'un écureuil Sniffetarin ! Votre nouveau compagnon est une créature timide, mais nous sommes certains que vous craquerez pour cette boule de fourrure et ses capacités olfactives incroyables.\n\nDans les pages suivantes, vous trouverez des informations pour prendre soin de votre écureuil.\n\n1. Nourriture et soins\n2. Comportement excentrique (et adorable)\n3. Utilisation du bâton de commandement de Sniffetarin(tm)\n\nEt encore félicitations, vous ne serez pas déçu,\n\n-Marwig Rustbolt\nPropriétaire de la Sniff SARL.", "NOURRITURE ET SOINS :\n\nNous nous engageons à vous fournir tout ce dont votre familier a besoin. Nos clients savent que la Sniff SARL offre un service sans comparaison et rien n'est plus vrai !\n\nDans cette optique, nous avons créé de solides caisses pour écureuils possédant de petits trous qui apportent sécurité, confort et obscurité.\n\nÀ des fins pratiques, chaque caisse est équipée d'un distributeur de nourriture diffusant l'odeur appétissante de la racine de feuillebleue (l'aliment préféré des écureuils Sniffetarin) !", "PROMENADE DE L'ÉCUREUIL\n\nL'écureuil Sniffetarin aime les endroits sombres et reclus. Il est très timide.\n\nSi vous voulez lui parler, vous devez l'emmener dans un endroit qui lui paraisse familier. Et vous devez le mener là où il pourra sentir son odeur préférée : les feuillebleues !\n\nIl y a un tel endroit non loin : la \"tranchée\" du kraal de Tranchebauge. Si vous ouvrez la caisse près de la tranchée, votre écureuil pourra humer les plantes proches, il sortira et vous suivra.", "BÂTON DE COMMANDEMENT DE SNIFFETARIN(tm)\n\nL'écureuil Sniffetarin est un animal incroyable. Même le plus hargneux des trotteurs des plaines ne peut résister à sa gentillesse. Il peut sentir une racine de feuillebleue enterrée à cinquante mètres !\n\nSi vous voulez envoyer votre écureuil à la recherche de racines, utilisez notre bâton de commandement de sniffetarin breveté (vendu séparément).\n\nNotice d'utilisation disponible sur la page suivante...", "Tous nos écureuils sont entraînés à un niveau élevé. Il vous suffit d'agiter votre bâton de commandement pour envoyer un écureuil à proximité en \"mode recherche.\" Si l'écureuil flaire un tubercule, il se rend à l'endroit où celui-ci est supposé se trouver et creuse pour le déterrer.\n\nSi vous agitez de nouveau le bâton de commandement pendant que l'écureuil cherche le tubercule, il stoppera ses recherches et reviendra joyeusement à vos côtés.\n\nNous sommes certains que vous trouverez nos écureuils bien entraînés et très utiles à votre groupe !", "La Sniff SARL se doit malheureusement de signaler que certains chasseurs de racines mettent en danger la vie de leur adorable animal en l'envoyant rechercher des racines dans des recoins sombres et dangereux.\n\nNous ne cautionnons pas de telles attitudes, mais afin de satisfaire nos clients, nous avons inclus une garantie. Lorsque vous achetez un écureuil et que vous le perdez, vous avez la possibilité de demander un nouvel écureuil à votre point de vente.\n\nBonne chasse !" } } },
    ["Solomon's Plea to Darkshire"] = { { ids = { "i1409" }, first = "lordebonlockethetownship", pages = { "Seigneur Ebonlocke--\n\nLa ville de Lakeshire demande humblement l'aide des Veilleurs. Nous sommes assiégés à la fois par les orcs Blackrock et les gnolls Sombrepoil de Morganth. Je n'aurais pas envoyé de demande si notre situation n'était pas si délicate. Nous attendons de l'aide de Stormwind, mais avant que cette aide n'arrive, je vous supplie de bien vouloir nous accorder des renforts. Si le royaume est atteint, c'est toute l'humanité qui est menacée.\n\nMagistrat Solomon" } } },
    ["Solomon's Plea to Farholde"] = { { ids = { "i266895" }, first = "lordebonlockethetownship", pages = { "Seigneur Ebonlocke--\n\nLa ville de Lakeshire demande humblement l'aide des Veilleurs. Nous sommes assiégés à la fois par les orcs Blackrock et les gnolls Sombrepoil de Morganth. Je n'aurais pas envoyé de demande si notre situation n'était pas si délicate. Nous attendons de l'aide de Stormwind, mais avant que cette aide n'arrive, je vous supplie de bien vouloir nous accorder des renforts. Si le royaume est atteint, c'est toute l'humanité qui est menacée.\n\nMagistrat Solomon" } } },
    ["Solomon's Plea to Westfall"] = { { ids = { "i1407" }, first = "lordstoutmantlethetownsh", pages = { "Seigneur Stoutmantle --\n\nLa ville de Lakeshire sollicite humblement l'aide de votre milice. Au moment où j'écris ces lignes, nous sommes assiégés par les orcs Blackrock et les gnolls Sombrepoil de Morganth. Je n'enverrais pas cette requête si notre situation n'était très grave. Nous attendons de l'aide de Stormwind mais jusqu'à ce que ces renforts arrivent, je vous supplie de nous accorder votre assistance. Si le royaume cède, c'est toute l'humanité qui sera en péril.\n\nMagistrat Solomon" } } },
    ["Sorrow of the Earthmother"] = { { ids = { "o177204" }, first = "asthechildrenoftheearthr", pages = { "Alors que les enfants de la terre parcouraient les champs de l'aube, ils entendirent de sombres murmures venus des profondeurs du monde. Ces voix leur enseignèrent les arts de la guerre et de la tromperie. Beaucoup de Shu'halo tombèrent sous l'emprise de l'ombre et embrassèrent la malveillance et la cruauté. Ils se retournèrent contre leurs frères restés purs et abandonnèrent leur innocence aux vents des plaines.", "Le coeur lourd devant le malheur de ses enfants, la Terre-mère ne pouvait supporter de les voir ainsi déchoir. Dans son chagrin, elle s'arracha les yeux et les lança dans le ciel infini et étoilé. An'she et Mu'sha, cherchant chacun à apaiser la peine de l'autre, ne pouvaient que poursuivre leur faible lueur à travers le ciel. Les jumeaux se poursuivent encore à chaque tour du monde.", "Bien qu'aveugle, la Terre-mère ne pouvait rester longtemps éloignée du monde qu'elle aimait. Elle prêtait l'oreille aux vents et écoutait tout ce qui se passait dans les champs de l'aube. Son grand coeur demeurait toujours auprès de ses enfants, et sa sagesse aimante ne les quitta jamais." } } },
    ["Spy's Report"] = { { ids = { "i5917" }, first = "daytroopmovementnearther", pages = { "--Jour 13\nLes mouvements de troupes à côté de Theramore sont plus nombreux. Beaucoup d'humains ont quitté la cité en hâte et sont partis vers l'ouest.\n\n--Jour 14\nDe plus en plus de troupes quittent la cité. J'ai suivi un petit groupe et j'ai vu ses membres ôter leur uniforme une fois qu'ils n'étaient plus à portée de tir de Theramore. Peut-être sont-ils des déserteurs ?\n\n--Jour 15\nJ'ai entendu aujourd'hui des soldats de Theramore parlant de gardes abandonnant leur poste. Mes soupçons devaient être fondés", "--Jour 16\nUleg et Thargil sont revenus de leur mission dans les docks de Theramore. Ils ont vu un nouveau navire dans le port : le Bleeding Sparrow. Le bateau est arrivé du port de Menethil en Azeroth.\n\nDemain, Uleg et Thargil retourneront au port et se glisseront dans le navire. Ils espèrent trouver des documents politiques qui révèleraient les relations entre Theramore et l'Alliance.", "--Jour 17\nUleg est revenu de sa mission. Il a échoué et Thargil a été capturé. J'ai envoyé Uleg faire son rapport à Nazeer.\n\nJe vais rester ici. J'ai pu constater une augmentation de l'activité maritime au large de la côte de Theramore. Je vais poursuivre ma garde et rapporter personnellement les événements notables." } } },
    ["Stormpike's Request"] = { { ids = { "i5998" }, first = "masterlongbeardasyouknow", pages = { "Maître Longbeard,\n\nComme vous le savez, nous les Stormpikes avons du goût pour l'excellence et la qualité de vos boucliers n'est plus un secret pour nous.\n\nPour cette raison, j'ai été mandaté pour vous demander de réaliser un bouclier. J'ai inscrit ses caractéristiques sur la page suivante :", "Parfaitement rond, allant du poing au coude.\n\n-Des clous le long des bords. Argent.\n\n-Un grand clou au centre, de trois doigts de large. Argent.\n\n-En chêne, renforcé de fer.\n\n-Mon nom, Gringer Stormpike, gravé sur le dessus.", "Le paiement s'effectuera comme d'habitude. Donnez au porteur de cette requête un pourboire et ajoutez-le au prix du bouclier.\n\nAvec tous mes remerciements,\n--Gringer Stormpike" } } },
    ["Stormwind Armor Marker"] = { { ids = { "i748" }, first = "thisarmormarkerisgoodfor", pages = { "Ce bon permet d'obtenir un élément d'armure en cuir ou en étoffe à la demeure de Timberlain, dans le Camp de bûcherons du Val d'est" } } },
    ["Stoutmantle's Response to Solomon"] = { { ids = { "i1408" }, first = "yourhonorallofwestfallmo", pages = { "Votre Honneur--\n\nLa marche de l'Ouest pleure vos cruelles pertes, mais nous menons notre propre guerre. Les fermiers sont sous la menace de voleurs et de golems mécaniques. Stormwind a retiré ses troupes, ce qui laisse les petites gens sans défense. J'ai assemblé la Milice du Peuple au moment de l'abandon de Stormwind, pour sauver ce qui peut l'être de ces terres. Envoyer la Milice dans les Carmines soumettrait la marche de l'Ouest à un destin funeste.\n\nTous mes regrets,\nGryan Stoutmantle" } } },
    ["Strange Note"] = { { ids = { "i228144" }, first = "thecrystalhasshownmevisi", pages = { "Le cristal m'a montré des visions de son passé. Il a été arraché à un tout parfait, une chose d'une glorieuse puissance divine.\n\nLes conflits féroces entre les races d'Azeroth ne cessent de croître. Si les éclats étaient réunis maintenant, ils pourraient servir d'arme d'une terrifiante destruction.\n\nSi vous cherchez à réunir les éclats, je vous en conjure : servez-vous de leur pouvoir pour unir les enfants d'Azeroth, et non pour mener d'autres guerres." } } },
    ["Studies in Spirit Speaking"] = { { ids = { "i15790" }, first = "oooooooooooooooooooooooo", pages = { "OoOoOoO OOoOOoo OOOoOoo OOoOooO OOoOOoO OOooooO Oooooo OooOOOO OOoOOOo OOoOOoo OOoOooO OOoOOOo OOooOoO Oooooo OooOOOo OOooooO OOOoooo OOooooO Oooooo OoOoOOo OOooooO OOoOOoo OOoOOoo OOooOoO OOOOooO Oooooo OooOoOO OOoOOOo OOoOooO OOooOOO OOoOooo OOOoOoo OOOooOO Oooooo OOoOOOO OOooOOo Oooooo OooooOO OOoOooo OOooooO OOoOOOO OOOooOO" } } },
    ["Sully Balloo's Letter"] = { { ids = { "i4432" }, first = "dunmodrofthewetlandsmyde", pages = { "Dun Modr des Paluns\n\nMa chère Sara,\n\nTout porte à croire que nous allons partir dans quelques jours assurer la garde du viaduc de Thandol. Je ne pourrai plus vous écrire. Je ressens le besoin de vous écrire quelques lignes qui pourront vous atteindre lorsque je ne serai plus.", "Notre mission peut être courte et pleine de réjouissances ou apporter la mort après de rudes combats. S'il me faut tomber pour l'Alliance sur le champ de bataille, je suis prêt.\n\nJe n'ai pas le moindre doute sur la cause pour laquelle je me bats et mon courage ne connaît pas de trouble.", "Je sais à quel point le royaume d'Ironforge dépend du triomphe de l'Alliance, et la dette que nous avons envers ceux qui sont tombés avant nous dans les Grandes Guerres. Je suis prêt, vraiment prêt, à abandonner toutes les joies de l'existence pour aider à maintenir l'Alliance et pour payer cette dette.", "Sara, mon amour pour vous est éternel, j'ai l'impression d'être uni à vous par de solides liens que seule une divinité pourrait briser, et mon amour pour le royaume est comme un vent puissant qui me porte irrésistiblement, avec ces chaînes, sur le champ de bataille.", "La mémoire de tous les heureux moments que j'ai passés avec vous ne cesse de me hanter et je remercie infiniment la Lumière de les avoir connus. Il est très dur pour moi de laisser tout ceci derrière moi et de voir réduits en cendres les espoirs des années à venir que nous aurions vécues ensemble en voyant nos fils devenir d'honorables nains.", "Je sais que je ne suis rien dans les desseins de la Divine Providence, mais quelque chose me murmure (peut-être est-ce la prière de mon petit Edgar) que je reviendrai sans mal vers ceux que j'aime. Si tel n'est pas le cas, ma bien-aimée Sara, n'oubliez jamais combien je vous aime et sachez que lorsque j'exhalerai mon dernier souffle ce sera en murmurant votre nom.\n\nPardonnez mes fautes et les douleurs que je vous ai causées, pardonnez mon manque d'attention, ma stupidité.", "Avec quel bonheur je laverais de mes larmes la moindre tache sur votre bonheur et me battrais contre toutes les infortunes de ce monde pour vous protéger du mal, ainsi que mes chers enfants.\n\nMais c'est impossible.\n\nJe vous regarderai depuis le Néant distordu et je veillerai sur vous tandis que vous affronterez les tempêtes du haut de votre frêle taille, attendant que nous nous rejoignions pour toujours.", "Mais, ô ma Sara, si les morts peuvent revenir à Azeroth et entourer, invisibles, ceux qu'ils aiment, je serai toujours à vos côtés dans les jours heureux comme dans les nuits les plus sombres, partageant vos heures de joie comme vos moments de tristesse. Si jamais vous sentez une douce brise sur votre joue, ce sera mon souffle, si l'air rafraîchit vos tempes, ce sera mon esprit qui passe.\n\nSara, ne me pleurez pas, pensez que je suis parti et que je vous attends, car nous nous reverrons.\n\n--Sully" } } },
    ["Sunwell - The Fall of Quel'Thalas"] = { { ids = { "o175757" }, first = "thoughhehaddefeatedallof", pages = { "Bien qu'ayant battu tous ceux qu'il voyait désormais comme des ennemis, Arthas était toujours hanté par le fantôme de Kel'Thuzad. Ce dernier lui dit qu'il devait revivre pour la phase suivante du plan du roi-liche. Pour le ressusciter, Arthas devait apporter les restes de Kel'Thuzad vers le mystique Puits de soleil, caché dans le royaume éternel des hauts-elfes de Quel'Thalas.", "Arthas et le Fléau envahirent Quel'Thalas et assiégèrent les défenses vacillantes des elfes. Sylvanas Windrunner, général des Forestiers de Lune-d'argent, combattit vaillamment, mais Arthas finit par balayer l'armée des hauts-elfes et se fraya un passage jusqu'au Puits de soleil. Dans un geste dominateur et cruel, il releva le corps décédé de Sylvanas pour en faire une banshee, condamnée éternellement au service du conquérant de Quel'Thalas.", "Enfin, Arthas immergea les restes de Kel'Thuzad dans les eaux saintes du Puits de soleil. Bien que les puissantes eaux d'éternité aient été souillées par cet acte, Kel'Thuzad put renaître sous la forme d'une liche. Ressuscité et bien plus puissant qu'avant, Kel'Thuzad expliqua quelle était l'étape suivante du plan du roi-liche.", "Lorsque Arthas et son armée s'en allèrent vers le sud, il n'y avait plus âme qui vive dans Quel'Thalas. Le glorieux foyer des hauts-elfes, vieux de neuf mille ans, n'était plus." } } },
    ["Survivor Journal"] = { { ids = { "i227748" }, first = "undertheprotectionofthes", pages = { "Sous la protection de l'éclat de Lumière, nous avons fui vers la crypte et nous nous y sommes barricadés. Mais Wescott et Billina sont partis chercher des provisions, et ont emporté l'éclat pour se protéger. Trois jours ont passé et ils ne sont pas revenus. Sans le pouvoir de l'éclat, le Fléau sera bientôt sur nous..." } } },
    ["Syndicate Missive"] = { { ids = { "i3601" }, first = "valikguardtheslaveuntilo", pages = { "Valik,\nGardez l'esclave jusqu'à notre retour. Il est risqué de le garder ici plus longtemps. Emmenons-le plus au nord afin d'être sûr que personne ne le verra.\n\nCe sont des animaux, et des brutes qui plus est. Les connaissant, nous avons des raisons de nous inquiéter. Mieux vaut éviter toute espèce de provocation. Nous ne voulons pas leur donner une raison de se regrouper et de nous attaquer." } } },
    ["Tabetha's Instructions"] = { { ids = { "i7516" }, first = "getajadetheyhideinmanydi", pages = { "Trouvez du jade. ll y en a à différents endroits. C'est une denrée rare, mais si vous parlez avec un forgeron ou un ingénieur, ils en auront peut-être un peu en réserve.", "Trouvez un Roncier de foudre. Pour le fabriquer, récupérez 10 bâtons totem de Witherbark que l'on trouve sur les trolls Witherbark des hautes-terres d'Arathi. Emportez les bâtons au Cercle de lien extérieur, un cercle de pierres qui se trouve sur les mêmes plateaux. Placez les bâtons au centre du cercle de pierres et attendez que la foudre s'abatte sur eux. Vous obtenez alors un Roncier de foudre." } } },
    ["Tainted Letter"] = { { ids = { "i9576" }, first = "toooftenpeoplelikethefol", pages = { "Trop souvent des personnes comme les disciples du Feu sacré effraient ceux qui recherchent le vrai pouvoir en les induisant à croire qu'ils ne peuvent maîtriser aucune forme des arcanes. Toutes les choses extérieures à ce monde ne sont pas mauvaises. Toutes les entités ne cherchent pas à dominer ou à soumettre les autres. Si vous êtes assez puissant, ces mêmes entités peuvent devenir vos disciples.\n\nC'est quelque chose dont j'aimerais discuter davantage avec vous. Trouvez-moi dans le cimetière situé sur le côté droit de l'abbaye.\n\n-Drusilla La Salle, Maître des démonistes" } } },
    ["Tainted Memorandum"] = { { ids = { "i9577" }, first = "attentionremainsilentdon", pages = { "ATTENTION :\n\nNe dites rien ! Ne regardez personne ! Quelqu'un est peut-être en train de vous surveiller en ce moment même.\n\nMon nom est Alamar Grimm, $N. J'entraîne ceux qui sont à la recherche d'une connaissance et d'un pouvoir venant... de mondes lointains. On m'a demandé de me mettre en contact avec vous discrètement et de vous informer que je peux vous enseigner une forme de magie véritable.\n\nQuand vous le pourrez, venez me trouver à l'arrière d'Anvilmar.\n\n-Alamar Grimm, Maître des démonistes" } } },
    ["Tainted Parchment"] = { { ids = { "i9579" }, first = "iwritethismessageinthemo", pages = { "J'ai écrit ce message avec l'encre la plus puissante que je suis arrivé à créer, $N. Une malédiction s'abattra sur quiconque tentera de le lire à part vous. Je suis assez puissant pour cela. J'invoque des démons du Néant distordu selon mes bons plaisirs. Je tourmente mes ennemis durant leur sommeil et sur le champ de bataille. Et désormais, vous aussi connaissez la puissance qui est la mienne. Mes frères sont très contents de cela.\n\nTrouvez-moi dans les profondeurs de l'Antre une fois que vous aurez trouvé votre chemin. Je vous parlerais alors de certaines choses importantes.\n\n-Nartok, Maître des démonistes" } } },
    ["Tainted Scroll"] = { { ids = { "i9578" }, first = "anawfulpredicamenttofind", pages = { "C'est une bien terrible situation, $N, n'est-ce pas ? Tourmentés par le vil prince. Ostracisés par nos propres familles. Nous avons retrouvé notre volonté propre, grâce à la belle Sylvanas, mais qu'y avons-nous gagné ? Changer de maître ne libère pas un esclave, telle est mon opinion.\n\nMais si nous devenions les maîtres à notre tour ? Oui, vous me comprenez, j'en suis certain.\n\nNous sommes séparés du reste des Réprouvés, $N. Et c'est pourquoi nous devons parler. Vous me trouverez à l'église du Glas." } } },
    ["Tattered Note"] = { { ids = { "i272319" }, first = "guldanagreedanddecidedth", pages = { "Gul'dan accepta et décida qu'une fois que les citoyens d'Azeroth seraient battus, il trouverait la tombe légendaire et demanderait sa récompense. Désormais certain que la Horde servirait ses desseins, Sargeras ordonna le début de l'invasion.", "Ensemble, Medivh et les démonistes du Conseil des ombres ouvrirent la voie connue sous le nom de Porte des ténèbres. Cette voie menait d'Azeroth à Draenor, et elle était assez vaste pour permettre à des armées de l'emprunter. Gul'dan envoya les éclaireurs orcs par la Porte pour explorer les terres qu'il entendait conquérir. Les éclaireurs, en revenant, assurèrent au Conseil des ombres que le monde d'Azeroth était prêt à tomber entre leurs mains.", "Toujours convaincu que la corruption de Gul'dan allait détruire son peuple, Durotan se prononça une fois de plus contre les démonistes. Le brave guerrier affirma que les démonistes détruisaient la pureté de l'esprit des orcs et que cette invasion signerait leur perte. Gul'dan, ne pouvant tuer un héros si populaire, dut exiler Durotan et le clan Frostwolf dans les terres les plus reculées de ce nouveau monde.", "Lorsque les exilés du clan Frostwolf passèrent le portail, quelques clans d'orcs seulement les suivirent. Ils établirent rapidement une base d'opérations dans le Noir Marécage, une zone sombre et marécageuse à l'est du royaume de Stormwind. En se lançant à l'exploration de ces nouvelles terres, les orcs entrèrent immédiatement en conflit avec les défenseurs de Stormwind.", "Ces escarmouches ne duraient jamais longtemps, mais elles illustraient les forces et faiblesses respectives des armées en présence. Llane et Lothar ne furent jamais en mesure de rassembler des données précises sur le nombre des orcs et en furent contraints à spéculer sur les forces qu'ils auraient à affronter.", "Il fallut quelques années à la majorité de la Horde pour venir sur Azeroth, et Gul'dan décida que l'heure d'une première attaque contre l'humanité était venue. La Horde lança toute sa puissance contre le royaume de Stormwind, qui ne s'y attendait pas.", "Alors que les forces d'Azeroth et de la Horde s'affrontaient partout dans le royaume, des dissensions se firent jour au sein des deux armées. Le roi Llane, qui croyaient les orcs bestiaux incapables de conquérir Azeroth, restait avec dédain dans sa capitale de Stormwind. Mais le seigneur Lothar était convaincu que le combat devait être porté directement au coeur du territoire ennemi, et il eut à choisir entre ses convictions et sa loyauté envers le roi.", "Choisissant de suivre son instinct, Lothar mit à sac la forteresse de Medivh à Karazhan avec l'aide du jeune apprenti sorcier Khadgar. Khadgar et Lothar parvinrent à vaincre le Gardien possédé, qui était sans doute possible la source du conflit.", "En détruisant le corps de Medivh, Lothar et le jeune apprenti bannirent sans le vouloir l'esprit de Sargeras dans les abîmes. En conséquence, le pur et vertueux esprit de Medivh put survivre et continua d'errer dans le plan astral pendant des années.", "En dépit de la défaite de Medivh, la Horde continua à prendre l'avantage sur les défenseurs de Stormwind. Alors que la victoire de la Horde semblait inéluctable, Orgrim Doomhammer, l'un des plus grands chefs des orcs, eut la révélation de la corruption et de la dépravation qui se répandaient dans les clans.", "Son vieux camarade Durotan revint d'exil et l'avertit une fois encore de la trahison de Gul'dan. Les assassins de Gul'dan tuèrent immédiatement Durotan et sa famille, ne laissant en vie qu'un enfant en bas âge. Doomhammer ignorait que le fils de Durotan avait été trouvé par un officier humain, Aedelas Blackmoore, et réduit en esclavage.\n\nCe petit orc allait un jour devenir le plus grand chef que son peuple ait jamais connu.", "Enragé par la mort de Durotan, Orgrim libéra la Horde de la corruption démoniaque et se mit à la tête des orcs en tuant l'homme de paille de Gul'dan, Blackhand. Sous son commandement vigoureux, la Horde vint finalement assiéger le donjon de Stormwind.", "Le roi Llane avait nettement sous-estimé la puissance de la Horde, et il regarda impuissant son royaume s'effondrer sous l'assaut des envahisseurs à la peau verte. Il finit par être tué par un des plus subtils assassins du Conseil des ombres, la demi-orc Garona.", "Lothar et ses guerriers, en revenant de Karazhan, espéraient endiguer les massacres et sauver leur terre naguère glorieuse. Mais ils revinrent trop tard et trouvèrent leur bien-aimé royaume en ruines. La Horde continuait de ravager la région et s'emparait de toutes les terres. Forcés de se cacher, Lothar et ses compagnons jurèrent de reprendre leur royaume à n'importe quel prix." } } },
    ["Teronis' Journal"] = { { ids = { "i5505" }, first = "istartedthisjournalsoico", pages = { "J'ai commencé ce journal pour garder une trace de ma quête au service d'Ashenvale. Certains événements survenus il y a peu restent mystérieux, et j'ai bon espoir d'en apprendre davantage dans le but d'aider mon peuple.\n\nCommençons par rédiger les faits afin que je m'en souvienne toujours.\n\nJ'ai récemment découvert qu'il y avait du vrai dans les rumeurs concernant le sorcier Dartol.", "J'ai cru naguère grotesque l'idée qu'un humain vienne dans nos terres apprendre nos moeurs, mais ce sorcier, cet homme maléfique, est venu jusqu'à nous. Il a survécu et appris une partie de notre savoir. Je ne suis pas certain de savoir comment...\n\nJe n'ai pas compris ses objectifs lors de mon enquête, mais son plan semblait simple : en utilisant la magie druidique, il voulait se lier avec les furbolgs puis les contrôler. J'espère apprendre avant que mon heure vienne si c'est pour s'en prendre à mon espèce ou pour quelque autre dessein maléfique.", "Malgré cela, il a apparemment réussi à mener ses plans à bien. A-t-il essayé ses machinations sur les furbolgs avant de les tenter sur mon peuple ? Est-ce que les furbolgs possédaient quelque chose qu'il convoitait ? Qui sait ?\n\nEn utilisant un objet qu'il a conçu (un genre de bâton ou de bâtonnet), il a essayé d'infiltrer les tribus de furbolgs à Ashenvale. A un certain moment, et tous les points ne sont pas encore très clairs, il fut démasqué par les furbolgs alors qu'il essayait de les monter", "les uns contre les autres. Tout comme les elfes l'auraient été, les furbolgs ont été pris de rage. Mais ils ont réagi de façon plus primaire et ont tué Dartol.\n\nLes furbolgs, à cette époque du moins, n'étaient pas les créatures corrompues qu'elles sont devenues. Ils étaient rationnels et intelligents, leurs relations avec notre peuple restaient amicales.\n\nJ'espère qu'en recréant le bâtonnet avec l'aide d'une dryade nommée Shael'dryn, je pourrai utiliser sa puissance pour aider notre peuple... et les furbolgs.", "Tous les furbolgs n'ont pas été corrompus. Certains vivent encore et tentent de protéger la forêt. Sous l'effet de la corruption, certains des furbolgs ont fui, beaucoup ont été tués, d'autres ont été chassés de leurs tribus.\n\nJ'ai trouvé un vénérable furbolg de la tribu Vile-sylve qui vit au-dessus du lac Mystral. Il s'appelle Krolg.\n\nJe l'ai observé des jours durant, et je pense que si je pouvais l'approcher sous le déguisement d'un furbolg, je pourrais l'aider et découvrir un moyen de recréer un lien entre nos deux peuples.", "En plus de tuer Dartol, les furbolgs ont brisé le bâtonnet en trois parties pour qu'on ne puisse plus l'utiliser contre eux. Ce fut difficile, mais je crois que je sais maintenant où se trouvent les trois fragments.\n\nLa Gemme\nLa première partie du bâtonnet, une gemme luminescente, a été cachée dans un autel au nord-ouest d'Ashenvale. Je pense que cet autel est dans les ruines au centre du lac Falathim. Les Sentinelles m'ont dit que des murlocs y habitent désormais.", "Si je ne peux trouver la gemme cachée dans le sanctuaire, c'est qu'elle est sûrement en possession d'un des murlocs.\n\nLa Hampe\nCe morceau du bâtonnet a été donné aux tréants près de ce qui s'appelle maintenant Gangrebois. Ni les furbolgs ni mon peuple n'auraient pu imaginer que de si magnifiques créatures pourraient succomber à la corruption qui s'est emparée de nos terres.\n\nMes recherches me disent que les gardiens conservent ce morceau dans une petite clairière, à l'intérieur d'un coffre. Pour en savoir plus, il faudra que je parle à Shael'dryn.", "Shael'dryn est une dryade qui protège le puits de lune au nord-est du lac Iris. Elle refuse de quitter la forêt ou de l'abandonner à la corruption. Je sais qu'elle a la puissance et la connaissance nécessaires pour réparer le bâtonnet ou au moins pour me dire comment procéder.\n\nLe Pommeau\nLe Pommeau du bâtonnet a été donné aux druides de Dor'danil. Un problème : les druides sont morts.\n\nLeurs esprits habitent maintenant la région et ne sont pas hospitaliers.", "Cela mérite une enquête plus approfondie. Je ne suis pas sûr d'être assez puissant pour pouvoir combattre les esprits de mon peuple... encore moins pour m'enfoncer dans les profondeurs de Dor'danil et trouver le pommeau.\n\n(Remarque : durant mes préparatifs à Astranaar, j'ai récemment rencontré un chasseur nain qui a passé une bonne partie de son temps à Ashenvale pour tenter d'y aider mon peuple. Il vient d'un lieu nommé Stormwind.\n\nNous avons parlé autour de quelques bières une nuit, et ce qu'il m'a dit m'a donné un nouvel espoir de pouvoir retrouver le pommeau.", "Il m'a dit qu'il avait traversé tout Dor'danil, et qu'il n'a jamais vu de coffre susceptible de contenir le pommeau.\n\nIlo m'a dit également que des gelées pourrissantes avaient vécu dans la région, dévorant tout ce qui était plus petit qu'elles. Il les a vues manger des tables, des sculptures, des ours, et même des gnomes !\n\nLes gelées semblent affectionner tout particulièrement ce qui est magique. Si le coffre contenant le pommeau a été enchanté, il est possible que les gelées l'aient dévoré.", "C'est un pari, mais je n'ai pas plus d'informations à cette heure...\n\nQuand j'en saurai plus, je le noterai ici. Mais en attendant, je dois me mettre à la recherche des morceaux du bâtonnet pour aider Ashenvale." } } },
    ["The Alliance of Lordaeron"] = { { ids = { "o175746" }, first = "lordlotharralliedtheremn", pages = { "Lothar rallia les restes des armées d'Azeroth après leur défaite de Stormwind et lança un exode massif, par mer, jusqu'au royaume septentrional de Lordaeron. Convaincus que la Horde submergerait toute l'humanité si rien n'était fait, les chefs des sept nations humaines se rencontrèrent et décidèrent de s'unifier pour former l'Alliance de Lordaeron.", "Pour la première fois en presque trois mille ans, les nations disparates d'Arathor s'unifiaient de nouveau sous une bannière unique. Nommé commandant suprême des forces de l'Alliance, Lothar prépara ses armées à la venue de la Horde.", "Aidé par ses lieutenants Uther Lightbringer - dit le Porteur de Lumière -, l'amiral Daelin Proudmoore et Turalyon, Lothar parvint à convaincre les races demi-humaines de Lordaeron de la menace qui pointait à l'horizon. L'Alliance parvint à obtenir l'aide des nains stoïques d'Ironforge et d'un petit nombre de hauts-elfes de Quel'Thalas.", "Les elfes, dont le chef était alors Anasterian Haut-soleil, se désintéressaient profondément du conflit en cours. Mais le sens du devoir les liait à Lothar, descendant de la lignée des Arathi qui les avait sauvés des siècles plus tôt.", "La Horde, menée désormais par le chef Doomhammer, fit venir des ogres de Draenor et enrôla les trolls des forêts d'Amani. Elle lança ensuite une vaste campagne pour s'emparer du royaume nain de Khaz Modan et des rivages méridionaux de Lordaeron. Toute opposition était anéantie.", "Les combats épiques de la Deuxième Guerre incluaient des engagements aériens aussi bien que de vastes batailles navales. La Horde était parvenue à déterrer un puissant artefact nommé l'Âme du démon et l'avait utilisé pour réduire en esclavage la reine des dragons, Alexstrasza. Menaçant de détruire ses précieux oeufs, la Horde força Alexstrasza à envoyer sa progéniture adulte au combat. Les nobles dragons rouges furent contraints de se battre pour la Horde, et ils le firent bien.", "La guerre faisait rage sur les continents de Khaz Modan, Lordaeron et Azeroth. Au nord, la Horde parvint à ravager les terres frontalières de Quel'Thalas, ce qui renforça la décision des elfes de rejoindre l'Alliance. Les grandes villes et les cités de Lordaeron furent rasées et dévastées par le conflit. Malgré l'absence de renforts et bien que les chances ne fussent pas de leur côté, Lothar et ses alliés parvinrent à arrêter la progression de l'ennemi.", "Lors des derniers jours de la Deuxième Guerre, quand la victoire de la Horde sur l'Alliance semblait inéluctable, deux des plus puissants orcs d'Azeroth s'affrontèrent. Tandis que Doomhammer préparait l'assaut final contre Lordaeron, une bataille qui aurait écrasé les derniers restes de l'Alliance, Gul'dan et les clans renégats abandonnèrent leurs postes et prirent la mer.", "Doomhammer, ayant perdu près de la moitié de ses forces en raison de la trahison de Gul'dan, fut contraint de battre en retraite et laissa passer sa chance d'écraser l'Alliance.", "Gul'dan, assoiffé de puissance et obsédé par l'obtention de la divinité, partit à la recherche de la tombe sous-marine de Sargeras, dont il pensait qu'elle détenait les secrets de la puissance ultime. Ayant déjà condamné ses frères orcs à devenir les esclaves de la Légion ardente, Gul'dan ne se voyait aucun devoir à remplir auprès de Doomhammer.", "Soutenu par les puissants clans Stormreaver et Twilight's Hammer, Gul'dan parvint à découvrir la Tombe de Sargeras au fond des mers. Mais quand il ouvrit la crypte immergée, il n'y trouva que des démons enragés qui l'attendaient.", "Ivre de vengeance, Doomhammer envoya ses forces tuer Gul'dan et ramener les renégats dans son armée. Mais Gul'dan avait déjà payé sa témérité de sa vie, déchiqueté par les démons qu'il avait libérés. Leur chef mort, les clans renégats tombèrent rapidement sous les coups des légions de Doomhammer.", "La rébellion avait été étouffée, mais la Horde ne pouvait se remettre des terribles pertes qu'elle venait de subir. La trahison de Gul'dan avait donné à l'Alliance non seulement un nouvel espoir, mais aussi le temps de se regrouper et de riposter.", "Le seigneur Lothar, voyant que la Horde était divisée, rassembla toutes ses troupes et repoussa Doomhammer vers le sud, jusqu'au coeur dévasté de la patrie de Stormwind. A leur tour, les forces de l'Alliance avaient piégé la Horde, dans la forteresse volcanique du pic Blackrock. Le seigneur Lothar fut tué lors de la bataille qui s'ensuivit, mais son lieutenant, Turalyon, parvint à rallier les troupes de l'Alliance au dernier moment et repoussa les dernières forces de la Horde dans le marais des Chagrins.", "Les troupes de Turalyon parvinrent également à détruire la Porte des ténèbres, qui reliait les orcs à leur monde natal, Draenor. Sans renforts de Draenor et décimée par les combats, la Horde fut finalement encerclée et écrasée par l'Alliance.", "Les clans décimés et éparpillés furent rassemblés et placés dans des camps gardés, sortes de réserves dont ils ne pouvaient sortir. La Horde semblait définitivement vaincue, mais beaucoup pensaient que la paix ne durerait pas. Khadgar, archimage désormais renommé, parvint à convaincre le haut commandement de l'Alliance de bâtir la forteresse de Rempart-du-Néant pour surveiller les ruines de la Porte des ténèbres et s'assurer que plus aucune invasion ne pourrait provenir de Draenor." } } },
    ["The Armor of Mannoroth"] = { { ids = { "o175658" }, first = "thesedemonplateswereworn", pages = { "Ces plaques démoniaques ont été portées par la créature qui a la première plongé notre peuple dans la folie sanguinaire. Grâce à l'action héroïque d'un seul orc brave, il fut battu. Mannoroth le Destructeur n'est plus. Que ces plaques nous rappellent toujours jusqu'où nous nous sommes égarés et combien il nous fallut combattre pour recouvrer notre honneur.\n\n- Thrall, Chef de la Horde" } } },
    ["The Battle of Grim Batol"] = { { ids = { "o175750" }, first = "meanwhileinthewartornlan", pages = { "Pendant ce temps, dans les terres dévastées du sud, les restes éparpillés de la Horde luttaient pour leur survie. Grom Hellscream et le clan Warsong parvinrent à éviter la capture, mais Deadeye et le clan Orbite-sanglante furent pris et placés dans les camps d'internement de Lordaeron. Leurs gardiens, malgré le lourd tribut payé à la révolte, finirent par reprendre le contrôle des camps.", "L'Alliance ne savait pas qu'une importante force d'orcs restait en liberté dans les terres septentrionales dévastées de Khaz Modan. Le clan Dragonmaw, conduit par l'infâme démoniste Nekros, avait conservé le contrôle de la reine-dragon Alexstrasza et de ses congénères en utilisant un puissant objet magique, l'Âme du démon. La reine-dragon en son pouvoir, Nekros construisit dans le plus grand secret une nouvelle armée dans la forteresse naine abandonnée de Grim Batol.", "Nekros espérait qu'en lâchant ses forces et les puissants dragons rouges sur l'Alliance, il pourrait réunifier la Horde et poursuivre la conquête d'Azeroth. Mais il échoua : un petit groupe de combattants, mené par le mage humain Rhonin, parvint à détruire l'Âme du démon, libérant ainsi la reine-dragon de la domination de Nekros.", "Emplis de fureur, les dragons d'Alexstrasza détruisirent Grim Batol et la majeure partie du clan Dragonmaw. Les espoirs de Nekros de réunifier les orcs furent définitivement écrasés lorsque les troupes de l'Alliance rassemblèrent les survivants et les placèrent dans des réserves. La défaite du clan Dragonmaw sonna le glas de la Horde et la fin de la menace représentée par les orcs." } } },
    ["The Betrayer Ascendant"] = { { ids = { "o175759" }, first = "duringthelegionsinvasion", pages = { "Durant l'invasion d'Ashenvale par la Légion, Illidan fut libéré de sa prison souterraine après dix mille ans de captivité. Bien qu'il cherchât à rassurer ses compagnons, il renoua bientôt avec ses anciens travers et absorba les énergies d'un puissant artefact de démoniste connu sous le nom de crâne de Gul'dan.", "Illidan acquit ainsi des traits démoniaques et des pouvoirs considérablement accrus. Il reçut aussi certains des anciens souvenirs de Gul'dan, notamment ceux du tombeau de Sargeras, un donjon insulaire qui, disait-on, abritait la dépouille du Titan noir Sargeras.", "Débordant de puissance et libre de parcourir à nouveau le monde, Illidan entreprit de trouver sa place dans le grand ordre des choses. Mais Kil'jaeden vint à sa rencontre et lui fit une offre qu'il ne pouvait refuser. La défaite d'Archimonde au mont Hyjal avait mis Kil'jaeden en colère, mais il avait de plus grandes préoccupations que la vengeance.", "Sentant que sa création, le roi-liche, devenait trop puissante pour rester sous son contrôle, Kil'jaeden ordonna à Illidan de détruire Ner'zhul et d'en finir une fois pour toutes avec le Fléau mort-vivant. En échange, Illidan recevrait une puissance sans pareille et une véritable place parmi les derniers seigneurs de la Légion ardente.", "Illidan accepta et entreprit aussitôt de détruire le Trône de glace, le cercueil de cristal gelé qui abritait l'esprit du roi-liche. Il savait qu'il lui faudrait un artefact puissant pour y parvenir. Grâce aux connaissances tirées des souvenirs de Gul'dan, il décida de chercher le tombeau de Sargeras et de s'emparer de la dépouille du Titan noir.", "Il réclama le paiement d'anciennes dettes aux Bien-nés et attira les nagas serpentins hors de leurs sombres repaires sous-marins. Menés par la rusée sorcière dame Vashj, les nagas aidèrent Illidan à atteindre les îles Brisées, où devait se trouver le tombeau de Sargeras.", "Tandis qu'Illidan partait avec les nagas, la Gardienne Maiev Shadowsong se lança à sa poursuite. Maiev avait été sa geôlière pendant dix mille ans et se réjouissait à l'idée de le capturer de nouveau. Mais Illidan déjoua ses plans et ceux de ses Guetteuses, et réussit malgré leurs efforts à s'emparer de l'OEil de Sargeras. Muni de ce puissant artefact, il se rendit à Dalaran, l'ancienne cité des mages.", "Renforcé par les lignes telluriques de la cité, Illidan utilisa l'OEil pour lancer un sort dévastateur contre la citadelle du roi-liche, à la Couronne de glace, dans le lointain Northrend. Son attaque brisa les défenses du roi-liche et fendit le toit même du monde. Au dernier instant, son frère Malfurion et la prêtresse Tyrande arrivèrent au secours de Maiev et interrompirent le sort destructeur d'Illidan.", "Sachant que Kil'jaeden ne lui pardonnerait pas son échec à détruire le Trône de glace, Illidan s'enfuit vers la dimension désolée appelée Outreterre, dernier vestige de Draenor, l'ancien monde des orcs. Il comptait y échapper à la colère de Kil'jaeden et préparer ses prochaines actions.", "Après avoir réussi à arrêter Illidan, Malfurion et Tyrande regagnèrent la forêt d'Ashenvale pour veiller sur leur peuple. Maiev, elle, ne renonça pas si facilement. Elle suivit Illidan en Outreterre, déterminée à le traduire en justice." } } },
    ["The Birth of the Lich King"] = { { ids = { "o175748" }, first = "nerzhulandhisfollowersen", pages = { "Ner'zhul et ses serviteurs entrèrent dans le Néant distordu, un plan éthéré qui reliait tous les mondes éparpillés dans le Grand Au-delà. Malheureusement, Kil'jaeden et ses serviteurs démoniaques les attendaient. Kil'jaeden, qui avait juré de se venger de Ner'zhul et de sa fière indépendance, déchiqueta le vieux chaman morceau par morceau.", "Kil'jaeden garda l'esprit du chaman vivant et intact, pour que Ner'zhul éprouve jusqu'au bout la douleur physique de son démembrement. Ner'zhul implora le démon de libérer son esprit et de lui procurer la paix de la mort, mais le démon répliqua que le Pacte de sang qu'ils avaient conclu il y a longtemps n'était pas abrogé. Il avait l'intention d'utiliser encore son pion dans l'avenir.", "L'incapacité des orcs à conquérir le monde pour le compte de la Légion ardente força Kil'jaeden à créer une nouvelle armée pour jeter le chaos dans les royaumes d'Azeroth. Cette nouvelle armée ne devait pas être l'objet des mêmes rivalités mesquines dont la Horde avait souffert. Il lui faudrait être sans merci et focalisée sur sa mission. Cette fois, Kil'jaeden ne pouvait se permettre d'échouer.", "Tout en maintenant Ner'zhul dans l'état douloureux d'esprit immobile et sans repos, Kil'jaeden lui donna une dernière chance de servir la Légion pour échapper aux tourments éternels. Une fois encore, égoïste, Ner'zhul accepta la proposition du démon. L'esprit de Ner'zhul fut insufflé à un bloc taillé dans la glace dure comme du diamant que l'on trouve aux confins du Néant distordu.", "Enchâssé dans son carcan glacial, Ner'zhul sentit sa conscience se développer et s'étendre comme jamais. Entouré par les pouvoirs chaotiques du démon, Ner'zhul devint une créature spectrale d'un pouvoir incommensurable. A cette époque, les orcs tels que Ner'zhul les avait connus étaient dispersés pour toujours. Le roi-liche était né.", "Les fidèles chevaliers de la mort et les démonistes de Ner'zhul furent également transformés par les énergies chaotiques du démon. Les lanceurs de sort maudits furent décomposés et recréés sous forme de liches squelettiques. Les démons s'étaient assurés que même dans la mort, les serviteurs de Ner'zhul le serviraient sans poser de question.", "Lorsque l'heure fut venue, Kil'jaeden expliqua patiemment la mission pour laquelle il avait créé le roi-liche : Ner'zhul allait devoir répandre une peste de mort et de terreur à travers Azeroth pour y faire disparaître à jamais la civilisation humaine. Tous ceux qui mourraient se joindraient à l'armée des morts-vivants… et leur esprit serait soumis à la volonté de fer de Ner'zhul, à jamais.", "Kil'jaeden promis que si Ner'zhul accomplissait cette abjecte mission de destruction de l'humanité, il serait libéré de la malédiction et recevrait un nouveau corps sain dans lequel habiter.", "Ner'zhul ne protesta pas et semblait désireux de bien remplir son rôle, mais Kil'jaeden restait sceptique quant à sa loyauté. Il garda le roi-liche loin de tout corps, enfermé dans sa gangue de cristal, pour s'assurer de sa docilité à court terme, mais le démon savait qu'il lui fallait garder un oeil vigilant sur le roi-liche. Pour ce faire, Kil'jaeden appela l'élite de ses gardes démoniaques, les seigneurs de l'effroi vampiriques, à surveiller Ner'zhul et à s'assurer qu'il remplissait sa terrible mission.", "Tichondrius, le plus puissant et le plus avisé des seigneurs de l'effroi, releva le gant, fasciné par la brutalité de la peste et par le pouvoir du roi-liche à accomplir un vrai génocide." } } },
    ["The Book of Ur"] = { { ids = { "i6283" }, first = "thelandofazerothishostto", pages = { "Les terres d'Azeroth recèlent d'innombrables merveilles. La flore, la faune, les cultures et la magie cohabitent à sa surface. En effet, les curieux trouveront une diversité sans borne dans ce monde. Il n'y a qu'à regarder.\n\nMais si vous observez plus attentivement, vous noterez des fenêtres conduisant vers de nouveaux mondes qui accueillent chacun leur lot de merveilles.\n\nDe même, chacun de ces mondes possède son lot d'horreurs.", "C'est le sujet de mon livre : cataloguer ces êtres, ces démons de l'autre monde qui souhaitent détruire nos terres. Ce récit servira aux explorateurs qui se retrouveront face à eux.\n\nSi vous vous considérez comme un gardien d'Azeroth, lisez-le et apprenez à connaître votre ennemi.\n\n-Ur\nMage de Dalaran", "Le démon dont je parle est un worgen.\n\nLe vieux folklore rural mentionne ces créatures. En effet, quel enfant de paysan n'a pas entendu ces histoires d'hommes-loups qui rôdent dans les bois et les marais, à l'extérieur du village ?\n\nLa vérité se cache souvent dans de tels récits. Peut-être s'agit-il d'avertissements contre les worgens déguisés en légendes pour nous faire peur.", "Mais avant que de telles histoires soient réfutées, laissez-moi vous assurer que les worgens existent. Peut-être ne sont-ils pas de notre monde, mais des passages existent entre nos univers et une puissante magie leur permet d'accéder chez nous.\n\nIl est préférable que ces chants ne soient pas prononcés, car où que les worgens aillent, ils apportent terreur et désolation.", "Vous reconnaîtrez un worgen à ses traits qui sont très proches de ceux des loups de notre monde. Ceux qui ont aperçu un worgen vous diront à quel point son poil rêche, ses oreilles en pointe et son long museau rappellent ceux des loups.\n\nMais vous vous rendrez compte rapidement de certaines différences : son poil dissimule un corps puissant juché sur deux jambes et doté de dents longues et de griffes acérées comme des poignards. Derrière ses hurlements, on perçoit une aura maléfique qu'aucun animal du règne de la nature ne peut engendrer.", "La patrie des worgens est un endroit ténébreux et cauchemardesque. Si ce monde recélait des lieux libres de la malédiction worgen, mes recherches ne m'ont pas permis de découvrir ces bastions.\n\nEt si l'on considère la férocité et la cruauté des worgens, cela semble normal.\n\nOn pense que les worgens sont satisfaits de leur monde, car bien que certains d'entre eux possèdent de puissants pouvoirs magiques, ils n'ont pas essayé d'atteindre Azeroth.\n\nEt de ce point de vue, nous pouvons nous estimer chanceux.", "Comme mentionné plus haut, certains worgens possèdent des dons mystiques et leur magie est imprégnée des ténèbres et de la corruption.\n\nLes malédictions et les poisons surnaturels sont courants. Veillez à vous protéger contre les ténèbres si vous comptez affronter des worgens.", "J'espère qu'aucun sorcier de Dalaran, même guidé par de bonnes intentions, n'a essayé de trouver les worgens. Aucun pacte ne peut être passé avec eux, aucun de leurs secrets ne peut être appris, et l'on ne peut rien obtenir de bon à les côtoyer.\n\nIls sont bien dans leur monde et si d'aventure nous en croisions dans le nôtre, alors nous serions en grand péril..." } } },
    ["The Collector's Schedule"] = { { ids = { "i2223" }, first = "belowistheprocessandsche", pages = { "Voici la procédure et l'organisation de la collecte d'or dans les mines d'Elwynn par les Défias, pour le bénéfice de notre quartier général de la marche de l'Ouest.\n\nDélais :\n\nDimanche : 12h30\nMercredi : 12h30\n\nChaque jour spécifié, l'or obtenu dans les mines d'Elwynn sera rassemblé au champ de potirons des Brackwell. L'agent en charge de ces collectes, nommé \"le Collecteur\", s'identifiera par l'anneau gravé que je lui ai donné.", "Un représentant du quartier général des Défias va contacter le Collecteur, après quoi il transférera l'or collecté.\n\nAssurez-vous que cela se fait avec efficacité et discrétion. Le Collecteur est responsable du transfert de l'or, mais au bout du compte il appartient à chaque membre de la Confrérie de s'assurer qu'il remplit son rôle avec attention et discipline.", "Souvenez-vous, mes frères, nous avons été naguère de fiers artisans. Nous accomplirons nos tâches actuelles avec la même précision que dans nos anciennes activités.\n\n-EVC" } } },
    ["The Dark Portal and the Fall of Stormwind"] = { { ids = { "o175745" }, first = "askiljaedenpreparedtheho", pages = { "Tandis que Kil'jaeden préparait la Horde pour l'invasion d'Azeroth, Medivh continuait à disputer son âme à Sargeras. Le roi Llane, noble monarque de Stormwind, se rendit compte des ténèbres qui semblaient souiller l'esprit de son ancien ami.", "Le roi Llane fit part de ses inquiétudes à Anduin Lothar, le dernier descendant de la lignée Arathi, qu'il avait désigné comme son lieutenant. Aucun d'entre eux n'imaginait pourtant quelles horreurs allait déclencher la lente descente de Medivh vers la folie.", "Comme ultime incitation, Sargeras promit un grand pouvoir à Gul'dan s'il acceptait de mener la Horde jusqu'à Azeroth. À travers Medivh, Sargeras dit au démoniste qu'il pourrait devenir un dieu vivant s'il découvrait la tombe sous-marine où la Gardienne Aegwynn avait placé le corps désarticulé de Sargeras presque mille ans plus tôt.", "Gul'dan accepta et décida qu'une fois que les citoyens d'Azeroth seraient battus, il trouverait la tombe légendaire et demanderait sa récompense. Désormais certain que la Horde servirait ses desseins, Sargeras ordonna le début de l'invasion.", "Ensemble, Medivh et les démonistes du Conseil des ombres ouvrirent la voie connue sous le nom de Porte des ténèbres. Cette voie menait d'Azeroth à Draenor, et elle était assez vaste pour permettre à des armées de l'emprunter. Gul'dan envoya les éclaireurs orcs par la Porte pour explorer les terres qu'il entendait conquérir. Les éclaireurs, en revenant, assurèrent au Conseil des ombres que le monde d'Azeroth était prêt à tomber entre leurs mains.", "Toujours convaincu que la corruption de Gul'dan allait détruire son peuple, Durotan se prononça une fois de plus contre les démonistes. Le brave guerrier affirma que les démonistes détruisaient la pureté de l'esprit des orcs et que cette invasion signerait leur perte. Gul'dan, ne pouvant tuer un héros si populaire, dut exiler Durotan et le clan Frostwolf dans les terres les plus reculées de ce nouveau monde.", "Lorsque les exilés du clan Frostwolf passèrent le portail, quelques clans d'orcs seulement les suivirent. Ils établirent rapidement une base d'opérations dans le Noir Marécage, une zone sombre et marécageuse à l'est du royaume de Stormwind. En se lançant à l'exploration de ces nouvelles terres, les orcs entrèrent immédiatement en conflit avec les défenseurs de Stormwind.", "Ces escarmouches ne duraient jamais longtemps, mais elles illustraient les forces et faiblesses respectives des armées en présence. Llane et Lothar ne furent jamais en mesure de rassembler des données précises sur le nombre des orcs et en furent contraints à spéculer sur les forces qu'ils auraient à affronter.", "Il fallut quelques années à la majorité de la Horde pour venir sur Azeroth, et Gul'dan décida que l'heure d'une première attaque contre l'humanité était venue. La Horde lança toute sa puissance contre le royaume de Stormwind, qui ne s'y attendait pas.", "Alors que les forces d'Azeroth et de la Horde s'affrontaient partout dans le royaume, des dissensions se firent jour au sein des deux armées. Le roi Llane, qui croyaient les orcs bestiaux incapables de conquérir Azeroth, restait avec dédain dans sa capitale de Stormwind. Mais le seigneur Lothar était convaincu que le combat devait être porté directement au coeur du territoire ennemi, et il eut à choisir entre ses convictions et sa loyauté envers le roi.", "Choisissant de suivre son instinct, Lothar mit à sac la forteresse de Medivh à Karazhan avec l'aide du jeune apprenti sorcier Khadgar. Khadgar et Lothar parvinrent à vaincre le Gardien possédé, qui était sans doute possible la source du conflit.", "En détruisant le corps de Medivh, Lothar et le jeune apprenti bannirent sans le vouloir l'esprit de Sargeras dans les abîmes. En conséquence, le pur et vertueux esprit de Medivh put survivre et continua d'errer dans le plan astral pendant des années.", "En dépit de la défaite de Medivh, la Horde continua à prendre l'avantage sur les défenseurs de Stormwind. Alors que la victoire de la Horde semblait inéluctable, Orgrim Doomhammer, l'un des plus grands chefs des orcs, eut la révélation de la corruption et de la dépravation qui se répandaient dans les clans.", "Son vieux camarade Durotan revint d'exil et l'avertit une fois encore de la trahison de Gul'dan. Les assassins de Gul'dan tuèrent immédiatement Durotan et sa famille, ne laissant en vie qu'un enfant en bas âge. Doomhammer ignorait que le fils de Durotan avait été trouvé par un officier humain, Aedelas Blackmoore, et réduit en esclavage.\n\nCe petit orc allait un jour devenir le plus grand chef que son peuple ait jamais connu.", "Enragé par la mort de Durotan, Orgrim libéra la Horde de la corruption démoniaque et se mit à la tête des orcs en tuant l'homme de paille de Gul'dan, Blackhand. Sous son commandement vigoureux, la Horde vint finalement assiéger le donjon de Stormwind.", "Le roi Llane avait nettement sous-estimé la puissance de la Horde, et il regarda impuissant son royaume s'effondrer sous l'assaut des envahisseurs à la peau verte. Il finit par être tué par un des plus subtils assassins du Conseil des ombres, la demi-orc Garona.", "Lothar et ses guerriers, en revenant de Karazhan, espéraient endiguer les massacres et sauver leur terre naguère glorieuse. Mais ils revinrent trop tard et trouvèrent leur bien-aimé royaume en ruines. La Horde continuait de ravager la région et s'emparait de toutes les terres. Forcés de se cacher, Lothar et ses compagnons jurèrent de reprendre leur royaume à n'importe quel prix." } } },
    ["The Eye of Divinity"] = { { ids = { "i18646" }, first = "whenyoupeerintotheeyeima", pages = { "Quand vous regardez dans l'Oeil, les images d'une grande bataille emplissent votre esprit.\n\nOn dirait que cet effroyable affrontement se déroule quelque part à Lordaeron.\n\nVous distinguez à peine une silhouette féminine, seule parmi des milliers de cadavres, repoussant une vague de morts-vivants du Fléau. Ils vont l'écraser sous leur nombre.\n\nDes filaments de lumière jaillissent de ses mains, lacérant des centaines de morts-vivants.", "En vain, semble-t-il. Quelques instants plus tard, la prêtresse est submergée par les cadavres des paysans qui l'entouraient… Les morts se sont levés." } } },
    ["The Feast of Winter Veil"] = { { ids = { "i17735" }, first = "thefeastofwinterveilthel", pages = { "La Fête du Voile d'hiver\n\nLes dernières saisons d'Azeroth sont une période de changement dans de nombreuses cultures. Les nains et les taurens, plus particulièrement, célèbrent la légende du Voile d'hiver : la neige recouvre les terres d'un manteau pur qui annonce le renouveau. C'est une période de fête et de célébrations. Bien que les légendes que les races d'Azeroth partagent soient à peu près similaires, les manières qu'elles choisissent pour les célébrer sont aussi diverses que le nombre de races.", "La Légende de Grand-père Hiver\n\nL'expression \"Voile d'hiver\" viendrait d'un être surnaturel, souvent appelé Grand-père Hiver, qui existe dans de nombreuses cultures. On dit que l'hiver le dissimule lorsqu'il se déplace dans le pays à la fin des saisons. À sa suite, le pays se recouvre de neige. La légende dit que Grand-père Hiver a jeté son voile d'hiver sur les terres. Bien que de nombreuses parties d'Azeroth restent sous la neige, cela laisse le temps à la terre de renaître.", "Les nains\n\nLes nains sont obsédés par la recherche de leurs origines. Les nains ont choisi de célébrer la saison comme une reconnaissance de Grand-père Hiver lui-même. Ils considèrent qu'il est la personnification d'un membre des anciens d'Azeroth : les Titans. Bien qu'ils revendiquent une descendance plus ou moins éloignée avec ces êtres mystiques, ils considèrent que Dun Morogh est le meilleur exemple des bienfaits de Grand-père Hiver.", "Les taurens\n\nLa légende du Voile de l'hiver s'accommode parfaitement de la vision chamaniste de l'hiver des taurens et de leurs intérêt récent pour le druidisme. Ils se focalisent presque entièrement sur les aspects de la tradition relatifs à la renaissance, laissant toute la partie cultuelle aux races qui, selon eux, sont moins en accord avec la nature des choses. De nombreux taurens considèrent cette époque comme le bon moment pour rendre grâce pour leur nouveau foyer à Mulgore.", "Fête\n\nL'idée de fête durant cette époque de l'année est intimement liée à la légende elle-même. Tandis que Grand-père Hiver traverse Azeroth et apporte l'hiver, la légende dit qu'il est généreux avec ceux qui fêtent sa présence. En tant que telle, l'idée de fête durant le Voile d'hiver rapprocherait les différentes communautés car elles partagent ce qu'elles possèdent. Une seule journée de joie et de fête accueille le changement, en prévision du renouveau des terres.", "Pratiques actuelles\n\nD'autres cultures ont commencé à accepter la Fête du Voile de l'hiver comme une période de célébration, bien que dans une tradition différente de ce sur quoi repose la légende. Les coutumes ne sont désormais rien d'autre qu'un prétexte pour des festivités et des échanges de présents. Même l'image de grand-père Hiver est parfois utilisée, mais davantage comme héraut commercial que comme titan surnaturel." } } },
    ["The First Tablet of I'lalai"] = { { ids = { "i270308" }, first = "amoonoverthevaleshinesca", pages = { "Une lune brille au-dessus de la vallée\nNoyant la jungle de ses lueurs\nC'est là que de fiers Guerriers suivent l'appel\nDe notre Pays et de ses terres sacrées.\n\nUne lune brille au-dessus de la Vallée\nBien au-dessus des clameurs du combat\nOù se verse le sang\nDe l'ennemi et de nos camarades.", "Et lorsque nos frères passent\nDans le royaume dont on ne sait rien\nL'âme et l'esprit se durcissent\nLoin sous la vallée.\n\nEt lorsque nos frères passent\nDans le Temple de la montagne\nNous protégeons leur esprit immortel\nEnchâssé dans le saint cristal bleu.\n\nEt lorsque nos frères passent\nUne lune brille au-dessus de la vallée." } } },
    ["The First Troll Legend"] = { { ids = { "i2005" }, first = "amoonoverthevaleshinesca", pages = { "Une lune brille au-dessus de la vallée\nNoyant la jungle de ses lueurs\nC'est là que de fiers Guerriers suivent l'appel\nDe notre Pays et de ses terres sacrées.\n\nUne lune brille au-dessus de la Vallée\nBien au-dessus des clameurs du combat\nOù se verse le sang\nDe l'ennemi et de nos camarades.", "Et lorsque nos frères passent\nDans le royaume dont on ne sait rien\nL'âme et l'esprit se durcissent\nLoin sous la vallée.\n\nEt lorsque nos frères passent\nDans le Temple de la montagne\nNous protégeons leur esprit immortel\nEnchâssé dans le saint cristal bleu.\n\nEt lorsque nos frères passent\nUne lune brille au-dessus de la vallée." } } },
    ["The Founding of Quel'Thalas"] = { { ids = { "o175733" }, first = "thehighelvesledbydathrem", pages = { "Les hauts-elfes, menés par Dath'Remar, quittèrent Kalimdor et affrontèrent les tempêtes du Maelström. Leur flotte erra aux bords des rivages déchiquetés pendant de longues années, et ils découvrirent bien des mystères et bien des royaumes perdus au cours de leur voyage. Dath'Remar, qui avait pris le surnom de Haut-soleil (ou \"Celui qui marche de jour\"), cherchait un endroit gorgé de puissance naturelle pour y bâtir un nouveau foyer pour son peuple.", "Sa flotte finit par s'arrêter sur les plages d'un monde que les hommes appelleraient un jour Lordaeron. En s'enfonçant dans les terres, les hauts-elfes fondèrent un campement dans les paisibles clairières de Tirisfal. Après quelques années, beaucoup d'entre eux commencèrent à devenir fous. On pensa que quelque mal inconnu dormait dans cette région du monde, mais on ne put jamais prouver ces rumeurs. Les hauts-elfes se remirent en route vers le nord, vers une autre terre convenant à leurs besoins.", "Tandis que les hauts-elfes traversaient les terres montagneuses de Lordaeron, leur voyage devint de plus en plus périlleux. Coupés des énegies vitales du Puits d'éternité, beaucoup succombèrent au climat glacial ou moururent de faim. Le changement le plus radical fut qu'ils n'étaient plus immortels ni protégés contre les éléments.", "Leur taille diminua et leur peau perdit sa teinte violette caractéristique. Ils rencontrèrent de nombreuses créatures étranges qui n'avaient jamais été vues dans Kalimdor. Ils trouvèrent également des tribus humaines primitives qui chassaient dans les anciennes forêts. Mais la plus grande menace à laquelle ils furent confrontés fut les trolls des forêts de Zul'Aman.", "Ces trolls à peau de mousse pouvaient régénérer des membres perdus et soigner de graves blessures physiques. Ils constituaient une race barbare et maléfique. L'empire Amani s'étendait sur le nord de Lordaeron, et les trolls combattirent sauvagement pour repousser les étrangers. Les elfes développèrent une haine farouche contre les méprisables trolls et les tuèrent à vue à chaque fois que ce fut possible.", "Après de longues années, les hauts-elfes trouvèrent finalement une terre qui leur rappelait Kalimdor. Au fond des forêts septentrionales du continent, ils fondèrent le royaume de Quel'Thalas et jurèrent de créer un puissant empire qui ridiculiserait celui de leurs cousins kaldorei. Malheureusement, ils apprirent rapidement que Quel'Thalas était fondée sur une ancienne cité des trolls que ces derniers considéraient comme sacrée. Immédiatement, les trolls attaquèrent les campements des elfes.", "Têtus, les elfes, qui ne voulaient pas abandonner leur nouvelle terre, utilisèrent la magie qu'ils avaient soutirée au Puits d'éternité pour tenir à distance les trolls. Sous le commandement de Dath'Remar, ils parvinrent à vaincre les forces des Amani à un contre dix. Certains elfes, attentifs aux vieux avertissements des Kaldorei, sentirent qu'une telle utilisation de la magie pouvait éveiller l'attention de la Légion ardente.", "Ils décidèrent donc de masquer leurs terres d'une barrière de protection qui leur permettrait, à couvert, de pratiquer leurs enchantements. Ils bâtirent une série de Monolithes en pierres runiques à différents endroits, autour de Quel'Thalas, marquant ainsi les frontières de la barrière magique. Non seulement les Pierres runiques cachaient la magie des elfes aux menaces extra-dimensionnelles, mais elles contribuèrent à effrayer les trolls superstitieux.", "Au fur et à mesure que le temps passait, Quel'Thalas devint un somptueux monument à la gloire des hauts-elfes et de leur habileté magique. Ses splendides palais étaient bâtis dans le même style architectural que les anciens halls de Kalimdor, mais en intégrant la topographie naturelle de la région. Quel'Thalas était devenu le joyau que les elfes avaient longtemps voulu créer.", "La Convocation de Lune-d'argent fut fondée tandis que les gouvernants de Quel'Thalas, à travers la dynastie Haut-soleil, ne conservaient qu'un minimum de pouvoir politique. Comprenant sept des principaux seigneurs hauts-elfes, la Convocation travaillait à assurer la sécurité des elfes. Entourés de leur barrière de protection, les hauts-elfes restaient inébranlables devant les vieux avertissements des Kaldorei et continuaient à utiliser la magie à chaque moment de leur existence.", "Pendant presque quatre mille ans, les hauts-elfes vécurent dans les frontières paisibles de leur royaume. Mais les trolls vindicatifs n'étaient pas si faciles à battre. Ils conspirèrent dans les profondeurs des forêts, attendant l'heure où leurs troupes seraient assez nombreuses. Enfin, une puissante armée de trolls sortit des ombres de la forêt et fit le siège de Quel'Thalas." } } },
    ["The Fourth Troll Legend"] = { { ids = { "i2008" }, first = "bymoonandfirebyfleshandb", pages = { "Par la lune et par le feu,\nPar l'os et par la chair,\nÉcrit avec le sang,\nGravé dans la pierre.\n\nAbandonnez ces lieux\nOu préparez-vous à la terreur\nLa mort monte la garde\nSur la tombe de l'empereur." } } },
    ["The Frostwolf Artichoke"] = { { ids = { "i19484" }, first = "thefrostwolfartichoketal", pages = { "L'artichaut Frostwolf : Récits glorieux des Stormpike\n-par Vanndar Stormpike\n\nQu'est-ce que les Frostwolf ? La réponse est simple : les Frostwolf sont des sauvages qui essayent de briser notre élan impérialiste et notre impératif souverain.\n\nComme un artichaut, les Frostwolf possèdent des défenses hérissées de piquants, et comme un artichaut, une fois qu'on a ôté la couche extérieure, le coeur apparaît, prêt à être mangé avec une bonne petite sauce à l'aïl.\n\nDélicieux !", "Chapitre 1 - La première ligne\n\nLes premières lignes des défenses des Frostwolf sont constituées de guerriers Frostwolf. Les guerriers sont déployés vers les premières lignes depuis la forteresse du capitaine Galvangar : la garnison de Glace-sang. Le moyen le plus efficace de briser cette couche de leurs défenses est de s'attaquer à la garnison de Glace-sang.\n\nAssiégez la forteresse et débarrassez-vous du capitaine Galvangar. Quand ce sera fait, les premières lignes s'effondreront.", "Chapitre 2 - Glace-sang et la Halte de la tour\n\nUne fois la première couche tombée, la deuxième couche de l\"artichaut\" sera à nu. Détruire les tours Frostwolf qui se dressent près des premières lignes handicapera lourdement les patrouilles et les légionnaires qui sont à l'arrière.\n\nLes tours sont très bien gardées et chacune abrite l'un des commandants d'élite de Drek'Thar. Ils doivent être tués. Cela accélérera le démantèlement des défenses des Frostwolf.", "Chapitre 3 - Les quatre commandants\n\nSi vous avez suivi les conseils de ce guide, deux des commandants de Drek'Thar sont maintenant morts. Bon travail, soldat ! Ils commencent déjà à perdre de leur détermination. Vous devez maintenant achever le démantèlement de la chaîne de commandement en tuant les deux commandants restants.\n\nQuand les quatre commandants seront tués, les légionnaires Frostwolf qui gardent le donjon Frostwolf seront éparpillés, sans personne pour les commander. Prêts à être cueillis !", "Chapitre 4 - Les tours Frostwolf occidentales et orientales\n\nIl n'y a maintenant plus qu'une couche qui vous sépare de la victoire : les unités les plus puissantes et les plus fidèles de Drek'Thar, les Gardiens Frostwolf.\n\nLes Gardiens Frostwolf viennent des sections de réserve qui se tiennent dans les tours Frostwolf occidentales et orientales. Détruisez ces tours et regardez les Gardiens Frostwolf restants fuir dans le déshonneur.", "Epilogue\n\n\"Couvrez le coeur de l'artichaut de beurre d'aïl et de mayonnaise. Accompagnez le repas d'une enivrante bière vieillie.\"\n\nDrek'Thar est maintenant seul, ses deux chiens à ses côtés. Prenez la hutte de guérison Frostwolf  pour vous aider dans votre bataille et finissez-en avec Drek'Thar. Quand le général tombera, cette terre reviendra enfin aux mains de ceux à qui elle appartient : les Stormpike." } } },
    ["The General's Response"] = { { ids = { "i1294" }, first = "honorablemagistratesolom", pages = { "Honorable magistrat Solomon :\n\nJe pleure avec vous la perte de nos braves. Je veillerai personnellement à ce que le roi soit informé de la situation et j'ai grand espoir qu'il envoie des renforts à Lakeshire. Sa Majesté s'est faite discrète ces derniers temps et ses actes sont des plus étranges. Que ceci reste entre nous.\n\nJe reste votre serviteur,\n\nGénéral Marcus Jonathan\nRoyaume de Stormwind" } } },
    ["The Green Hills of Stranglethorn"] = { { ids = { "o182203" }, first = "thegreenhillsofstranglet", pages = { "LES VERTES COLLINES DE STRANGLERONCE\n\npar Hemet Nesingwary", "Notre première journée s'est aussi bien déroulée qu'on pouvait l'espérer. Nous avons surtout oeuvré à préparer l'établissement d'un campement. J'ai repéré un emplacement idéal près d'une rivière. A en juger par les vieux quais abandonnés qui s'y trouvent, ce site a été habité naguère. Quant aux anciens habitants, le temps nous dira peut-être ce qu'ils sont devenus.", "Pour cette expédition, j'ai réuni Ajeck Rouack et sire S. J. Erlgadin, ainsi que mon fidèle serviteur Barnil Stonepot. J'ai combattu aux côtés du père d'Ajeck dans bien des batailles au service de l'Alliance. La voir grandir a été quelque chose de très particulier. Son père l'a bien formée dans les arts du maniement d'arme. Ses talents à l'arc me font demander si elle n'aurait pas du sang elfe.", "Sire S. J. Erlgadin est un aristocrate humain. Son père, le comte Erlgadin, était célèbre pour sa générosité. C'est le comte qui s'est battu pour améliorer les conditions de travail de la Guilde des Maçons pendant la reconstruction de Stormwind après la Deuxième Guerre.", "Dans les années qui suivirent, après la trahison par Stormwind de la Guilde des Maçons, sire Erlgadin devint aigri au sujet du rôle des nobles du royaume. Il ne souhaitait plus conserver la position que la lignée de son père lui réservait à la Maison des Nobles. Mais trêve de digressions. Le but de cette histoire n'est pas de jouer au traité de science politique ni à la biographie. C'est la narration de mes expériences de chasse dans les vertes vallées de Strangleronce.", "Nous nous sommes levés à l'aube. Barnil a commencé à préparer le repas du matin. J'ai constaté qu'Ajeck semblait distraite. La marche serait longue ce jour-là et la chasse s'annonçait dangereuse. Il était vital que chacun reste concentré. Mais Ajeck me semblait incapable de détacher ses yeux de Barnil qui nettoyait ses affaires dans la rivière.", "Alors que j'allais interroger Ajeck sur son manque d'intérêt pour la stratégie de ce jour de chasse, elle s'est précipitée vers son carquois, a sorti une flèche et a tiré en direction du pauvre Barnil. Mais ce n'est pas Barnil qu'Ajeck visait. Lorsque Barnil s'est écarté, bouche bée, un grand crocilisque des rivières flottait à la surface, la flèche d'Ajeck parfaitement plantée entre ses deux yeux.", "Nous sommes partis vers l'ouest, à travers la jungle épaisse. Marchant lentement et précautionneusement, nous avons cherché nos proies dans l'épaisse frondaison. La matinée s'est écoulée dans un silence frustré. Rien ne frémissait dans la vallée, pas même la brise. Au début de l'après-midi, nous étions fatigués et Barnil avait abandonné la démarche silencieuse du chasseur de proies. Il arpentait la région d'un pas lourd, faisant craquer les feuilles mortes et les brindilles.", "Au cours d'un de ces faux-pas, Erlgadin a posé lourdement la main sur l'épaule de Barnil. Ajeck et moi nous sommes lancés un regard, pensant qu'il voulait simplement tancer Barnil. Mais Erlgadin a fait un geste  lent de la tête vers un arbre mort, non loin. Deux yeux noirs nous fixaient au-dessus d'une gueule emplie de crocs acérés.", "C'était un tigre de Strangleronce, un mâle. Avant que j'aie le temps de relever mon arme, Erlgadin a pointé son arbalète vers la bête et a fait feu. Le trait a manqué la tête et a mordu la bête dans le flanc gauche. Le tigre a fait une puérile tentative pour fuir, mais la blessure était trop grave. Il a oscillé quelques secondes et Barnil l'a achevé d'un coup de hache.", "La mise à mort a créé une atmosphère joviale parmi les membres de l'expédition. Barnil a servi de l'hydromel à tous. Mais la bonne humeur n'a pas duré. Alors que nous préparions le cadavre pour le rapporter au campement, nous avons été surpris par un horrible grognement. De toute ma vie je n'ai jamais rien entendu qui soit plus de nature à glacer le sang.", "Sur un précipice rocheux découpé par le soleil couchant, j'ai aperçu le plus gros félin que l'on puisse imaginer. J'ai tiré une salve maladroite avec mon arme, mais le félin n'a pas bougé. Il a grogné à nouveau, plus fort que la première fois, et il a disparu.\n\nNous avons rassemblé nos affaires et nous sommes rentrés au campement.", "J'avais promis à l'équipe que nous passerions le jour suivant à chasser des panthères, car leur fourrure est très chère à Azeroth. Cela est juste, vu le nombre de trappeurs et de chasseurs qui ont perdu la vie au service de l'Alliance.", "Ajeck et sire Erlgadin étaient désireux d'apprendre à chasser efficacement avec un fusil nain. J'ai conseillé aux deux humains de laisser leurs armes primitives au campement. Barnil et moi leur avons fourni des armes à feu parmi les meilleures d'Ironforge.", "Ce jour-là, nous nous sommes aventurés vers le sud, à la suite de traces de panthère fraîches. Nous sommes arrivés à un ravin traversé par un immense pont de corde. Je n'ai pu m'empêcher de penser aux descriptions de Brann sur la région, quand j'ai aperçu cette merveille surplombant le vide. On pense si souvent que les trolls sont une race primitive et sans éducation, mais en observant la parfaite construction du pont je ne pus m'empêcher d'admirer l'habileté avec laquelle les bâtisseurs trolls avaient vaincu cette difficulté apparemment insurmontable.", "Bien vite, Ajeck repéra les traces d'une panthère vers le sud-ouest. Nous avons avancé rapidement, les armes prêtes, avides de rencontrer notre proie. Un craquement de branchages a attiré notre attention. Il y avait quelque chose par là. Un coup d'oeil rapide à Barnil a confirmé mes suppositions. Barnil a lentement relevé son fusil. Cette proie n'était pas pour nous, mais pour nos compagnons humains. D'innombrables panthères avaient perdu la vie au bout de nos canons. C'était au tour des humains.", "Ajeck et sire Erlgadin restaient aux aguets, canon levé vers le feulement qui provenait de la frange mouvante des arbres. Le soleil de midi tapait dur sur nos épaules. Un mince filet de sueur coulait le long des tempes d'Erlgadin lorsqu'il a relevé le chien de son arme. Au cliquetis qui a retenti, la dense végétation s'est ouverte et une panthère noire, un spécimen magnifique, est entrée dans la clairière.", "Les humains ont pointé leur arme sur la panthère qui courait le long de la ligne des arbres. Les canons se déplaçaient en parallèles parfaites. Barnil m'a lancé un coup d'oeil pressant mais j'ai fait non de la tête. Cette chasse était pour les humains, pas pour Barnil ni pour moi. Sire Erlgadin a tiré, mais a manqué la cible. Il n'était visiblement pas préparé au violent recul de l'arme.", "Son arme a failli lui échapper des mains. Le canon a dévié et est venu se placer sous le fusil d'Ajeck. Ajeck a choisi ce moment précis pour tirer. Le coup est parti avec sa détonation caractéristique, mais dans la direction de la ligne d'arbres. Des oiseaux se sont envolés dans toutes les directions avec des cris plaintifs. Un filet de fumée s'est élevé de l'arbre qui avait été touché. Stupéfaits, nous avons vu une énorme branche tomber sur la panthère en pleine course, lui brisant la colonne vertébrale.", "Au fur et à mesure que les semaines passaient, notre stock de peaux de panthère et de tigre grandissait. Je décidai qu'il était temps pour l'expédition de se concentrer sur un nouveau défi : les raptors.\n\nLes humains, tout en appréciant l'expérience de Barnil et la mienne, décidèrent de ne pas se servir d'armes à feu. Ajeck se sentait plus à l'aise avec un arc et sire Erlgadin ne quittait jamais le camp sans une solide arbalète.", "Nous avons levé le camp à l'aube et sommes partis vers le sud en traversant les ruines de Tkashi. Barnil craignait qu'on ne rencontre des membres de la tribu Bloodscalp. J'ai rappelé à Barnil que les Bloodscalp se concentraient surtout sur la destruction de leurs rivaux, les Skullsplitter. Cela, bien sûr, n'a pas rassuré Barnil le moins du monde. Mais j'avais un fusil chargé, des munitions, et trois chasseurs expérimentés pour me réconforter contre la menace d'une embuscade.", "Je me suis déjà tenu devant un immense Infernal sur le champ de bataille, tandis que l'armée de la Légion ardente avançait de toutes les directions. Une bande de trolls sans chef est aussi inoffensive qu'un lapin dans les collines de Dun Morogh.\n\nNous avons traversé les ruines de Tkashi sans incident, au grand soulagement de Barnil. Le groupe s'est ensuite dirigé vers l'ouest, en direction de la Grande Mer, longeant les ruines de Zul'Kunda au sud. C'est alors que nous montions les escarpements du rivage que nous avons repéré notre premier raptor.", "La bête ne nous a pas entendu approcher. Tout ce qu'elle a reçu, c'est une balle entre les yeux. Sire Erlgadin a laissé échapper un cri de joie tandis qu'Ajeck me lançait un coup de tête approbateur. J'ai cherché ma pipe dans mon sac, pour célébrer cette victoire. Barnil a filé vers le haut de la colline pour retrouver le cadavre du raptor. J'ai regardé la bête morte avec la satisfaction qui accompagne chaque joli tir.", "Mais je n'ai pas profité longtemps de ce moment de gloire. Quand j'ai tourné les yeux vers l'horizon, j'ai vu plusieurs silhouettes apparaître au sommet de la colline, juste au-dessus du pauvre Barnil.\n\n*Fuyez, Barnil !* ai-je hurlé. Ajeck, sire Erlgadin et moi avons envoyé une salve de balles et de flèches vers les nouveaux raptors. Dans la confusion, nous en avons abattu un autre.", "Nos tirs mal ajustés ont suffi à couvrir la fuite de Barnil. Il a dévalé la colline pour nous rejoindre. Nous nous sommes précipités dans la jungle, entraînant derrière nous une meute de raptors flagellants.\n\nLes chasseurs étaient désormais les proies.", "J'ai mené le groupe jusqu'à la mer, espérant que le rivage nous fournirait une protection contre les raptors. Dans notre hâte, nous sommes allés trop loin vers le Nord, jusqu'à un promontoire dangereusement escarpé. Erreur fatale. Ma faute. Nous nous sommes retrouvés bloqués sur une corniche, les raptors à quelques pas derrière nous.", "Je fis lentement un pas en avant, arme levée. J'avais conduit ces braves chasseurs à leur mort. J'étais prêt à mourir en tentant de les défendre. Les raptors flagellants sont particulièrement féroces, réputés pour leur inextinguible soif de sang. Ils étaient beaucoup plus nombreux que nous. Mais je n'allais pas les laisser me tuer ainsi que mes camarades sans verser d'abord un peu de leur sang.", "Ajeck et sire Erlgadin ont préparé leurs armes, un à chacun de mes côtés, nos dos tournés vers la mer. Barnil a laissé échapper un soupir et a levé sa hache. Les flagellants étaient presque sur nous. Ils avançaient moins vite. Ils traquaient leurs proies maintenant qu'ils savaient qu'ils nous avaient piégés.", "Et le miracle a eu lieu. Loin sur notre flanc, nous avons entendu le rugissement caractéristique et terrifiant du grand tigre blanc. Malgré leur nombre, les raptors ont fait demi-tour et se sont dispersés dans toutes les directions. Nous avons vu un bref éclair blanc : le tigre passait devant nous et se précipitait sur l'un des raptors. Inutile de donner des ordres : nous savions tous que l'heure de fuir avait sonné.", "Nous avons foncé jusqu'au campement, sans ralentir. Au cours de la nuit, assis silencieusement autour du feu de camp, nous avons médité sur l'étrange destin qui venait de nous sauver la vie. Tels sont les risques de la chasse. Nous jouons avec le destin. Chacun de nous, à un moment ou à un autre, rencontrera sa fin entre ses dents aiguisées. Le nain que je suis est simplement heureux que ce moment ne soit pas arrivé dans les vertes collines de Strangleronce.\n\n-- Fin --" } } },
    ["The Guardians of Tirisfal"] = { { ids = { "o175735" }, first = "withtheabsenceoftrollsin", pages = { "Les trolls chassés des terres du Nord, les elfes de Quel'Thalas consacrèrent leurs efforts à reconstruire leur glorieux foyer. Les armées victorieuses d'Arathor retournèrent au Sud, à Strom.", "La société humaine d'Arathor grandit et prospéra, mais Thoradin, craignant que le royaume ne se disloque s'il s'étendait trop, maintint Strom au centre de l'empire arathorien. Après bien des années de paix et de croissance, le puissant Thoradin mourut de vieillesse, laissant la jeune génération d'Arathor libre de s'étendre au-delà des terres de Strom.", "Les cent magi d'origine, instruits dans les arts magiques par les elfes, étendirent leurs pouvoirs et étudièrent plus profondément les disciplines mystiques. Ces magi, choisis initialement pour leur volonté de fer et leur esprit noble, avaient toujours pratiqué la magie de manière responsable, mais ils transmirent leur savoir à une génération plus jeune qui ignorait tout des rigueurs de la guerre et de la nécessité de l'auto-discipline.", "Ces jeunes magiciens commencèrent à utiliser la magie à des fins personnelles sans se soucier des besoins de leurs semblables.", "Avec la croissance de l'empire vers de nouvelles terres, les jeunes magiciens émigrèrent également vers le sud. Usant de leurs pouvoirs magiques, les magiciens protégèrent leurs frères contre les créatures sauvages et permirent à de nouvelles cités-états de s'ériger dans les terres sauvages. Mais, avec la croissance de leur puissance, les magiciens s'isolèrent de plus en plus du reste de la société.", "La seconde cité-état arathorienne, Dalaran, fut fondée dans les terres septentrionales de Strom. De nombreux sorciers quittèrent les confins restreints de Strom et se rendirent à Dalaran, où ils espéraient pouvoir utiliser leur savoir plus librement. Ces magiciens utilisèrent leurs connaissances pour construire les pics enchantés de Dalaran et poursuivre leurs études.", "Les citoyens de Dalaran tolérèrent le comportement des magiciens et érigèrent une économie florissante sous la protection des magiciens. Cependant, alors que le nombre de sorciers augmentait, le tissu de la réalité commença à s'affaiblir puis à se déchirer autour de Dalaran.", "Les sinistres agents de la Légion ardente, qui avaient été bannis à l'effondrement du Puits d'éternité, furent de nouveau attirés dans le monde par les sorts sans retenue des magiciens de Dalaran. Ces démons assez faibles n'apparurent pas en force, mais ils causèrent confusion et chaos dans les rues de Dalaran.", "La plupart des rencontres avec les démons étaient des événements isolés et les magiocrates au pouvoir firent ce qu'ils purent pour cacher au peuple ces événements. Les plus puissants magiciens furent envoyés dans l'espoir de capturer les démons, mais furent souvent incapables de maîtriser les agents solitaires de la puissante Légion.", "Après quelques mois, les paysans superstitieux commencèrent à suspecter que leurs maîtres leur cachaient quelque chose. Des rumeurs de révolution commencèrent à se répandre dans les rues de Dalaran : les citoyens rendus paranoïaques commençaient à mettre en doute les motivations et les pratiques des magiciens qu'ils admiraient naguère. Les magiocrates, effrayés par la perspective d'une révolte paysanne et d'une réaction de Strom, se tournèrent vers le seul groupe dont ils pensaient être compris : les elfes.", "Instruits par les magiocrates de l'activité démoniaque à Dalaran, les elfes envoyèrent immédiatement leurs plus puissants sorciers vers les terres humaines. Les sorciers elfiques étudièrent les courants d'énergie de Dalaran et firent des rapports détaillés sur les activités démoniaques dont ils prenaient connaissance. Ils conclurent qu'il n'y avait que quelques démons épars dans le monde, mais que la Légion elle-même resterait une menace si les humains continuaient à se servir de la magie.", "Le Conseil de Lune-d'argent, que dirigeaient les elfes de Quel'Thalas, conclut un pacte secret avec les magiocrates de Dalaran. Les elfes enseignèrent aux magiocrates l'histoire ancienne de Kalimdor et de la Légion ardente, histoire qui pouvait se répéter. Ils informèrent les humains qu'aussi longtemps qu'ils utiliseraient la magie, ils auraient à protéger leurs citoyens contre les agents de la Légion.", "Les magiocrates proposèrent de donner pouvoir à un seul champion mortel d'utiliser leur puissance pour mettre fin à l'éternelle guerre secrète contre la Légion. Ils insistèrent sur le fait que l'humanité ne devait pas être instruite de l'histoire du Gardien ou de la menace de la Légion sous peine que la peur et la paranoïa ne la plongent dans le chaos. Les elfes acceptèrent et fondèrent une société secrète dédiée à surperviser le choix du Gardien et à prévenir tout désordre dans le monde.", "La société tenait ses réunions secrètes dans les clairières de Tirisfal, où les hauts-elfes s'étaient initialement installés à Lordaeron. La secte secrète prit le nom de Gardiens de Tirisfal. Les champions mortels qui étaient choisis pour devenir Gardiens recevaient d'incroyables pouvoirs magiques, elfiques et humains. Il ne devait y avoir qu'un Gardien en même temps, mais son pouvoir était tel qu'il devait pouvoir combattre seul les agents de la Légion où qu'ils apparaissent dans le monde.", "La puissance du Gardien était telle que le Conseil de Tirisfal seul était autorisé à choisir ses successeurs potentiels. Quand un Gardien vieillissait, ou se lassait de la Guerre secrète contre le chaos, le Conseil choisissait un nouveau champion et, sous contrôle sévère, canalisait la puissance de l'ancien Gardien dans le nouveau.", "Les générations passaient et les Gardiens défendaient l'humanité contre la menace invisible de la Légion ardente sur toutes les terres d'Arathor et de Quel'Thalas. Arathor prospéra tandis que l'usage de la magie se répandait dans l'empire. Cependant, les Gardiens restaient aux aguets de tout signe d'activité démoniaque." } } },
    ["The Horde's Hellscream"] = { { ids = { "i20010" }, first = "hisnamewillnotdiehissacr", pages = { "Son nom ne mourra pas.\nSon sacrifice servira toujours\nà nous montrer la voie.\n\nLes chaînes qui autrefois\nétouffaient notre honneur\nne nous lient plus.", "Entendez-vous son cri ?\nUn hurlement de bataille pour la Horde :\nLa victoire ou la mort !\n\nN'oublions jamais\nsa force face à la mort.\nSon rêve, à présent réalité.", "Le danger est partout !\nLes ennemis cherchent à nous\nremettre dans les fers.\n\nQuand nous combattons, pensez à\ncelui qui fit son devoir.\nHellscream, pour toujours !" } } },
    ["The Invasion of Draenor"] = { { ids = { "o175747" }, first = "asthefiresofthesecondwar", pages = { "Alors que les feux de la Deuxième Guerre s'éteignaient, l'Alliance prit des mesures énergiques pour contenir la menace orque. Plusieurs grands camps d'internement furent construits dans le sud de Lordaeron pour y enfermer les orcs capturés. Gardés par les paladins et les soldats vétérans de l'Alliance, ces camps se révélèrent très efficaces.", "Bien que les orcs captifs fussent tendus et impatients de reprendre le combat, les responsables des camps, établis dans l'ancienne forteresse-prison de Fort-de-Durn, préservaient la paix et maintenaient un semblant d'ordre solide.", "Cependant, sur le monde infernal de Draenor, une nouvelle armée orque se préparait à frapper l'Alliance, qui ne se doutait de rien. Ner'zhul, l'ancien mentor de Gul'dan, rallia les clans orcs restants sous sa sombre bannière. Avec l'aide du clan Shadowmoon, le vieux chaman projetait d'ouvrir sur Draenor plusieurs portails qui conduiraient la Horde vers de nouveaux mondes encore intacts.", "Pour alimenter ses nouveaux portails, il lui fallait plusieurs artefacts enchantés d'Azeroth. Afin de se les procurer, Ner'zhul rouvrit la Porte des ténèbres et y lança ses serviteurs avides de conquête.", "La nouvelle Horde, menée par des chefs vétérans tels que Grom Hellscream et Kilrogg Deadeye, du clan Bleeding Hollow, prit les défenseurs de l'Alliance par surprise et ravagea les campagnes. Sous les ordres précis de Ner'zhul, les orcs réunirent rapidement les artefacts dont ils avaient besoin, puis regagnèrent la sécurité de Draenor.", "Le roi Terenas de Lordaeron, convaincu que les orcs préparaient une nouvelle invasion d'Azeroth, réunit ses lieutenants les plus fidèles. Il ordonna au général Turalyon et à l'archimage Khadgar de mener une expédition à travers la Porte des ténèbres pour mettre un terme définitif à la menace orque. Les forces de Turalyon et de Khadgar pénétrèrent en Draenor et affrontèrent à maintes reprises les clans de Ner'zhul sur la péninsule dévastée des Flammes infernales.", "Malgré l'aide de la haute-elfe Alleria Windrunner, du nain Kurdran Wildhammer et du soldat vétéran Danath Trollbane, Khadgar ne parvint pas à empêcher Ner'zhul d'ouvrir ses portails vers d'autres mondes.", "Ner'zhul ouvrit enfin ses portails vers d'autres mondes, sans prévoir le terrible prix qu'il allait payer. Leurs immenses énergies commencèrent à déchirer la trame même de Draenor. Tandis que les forces de Turalyon luttaient désespérément pour rentrer en Azeroth, Draenor se mit à s'effondrer sur elle-même. Grom Hellscream et Kilrogg Deadeye, comprenant que les projets insensés de Ner'zhul condamneraient toute leur race, rallièrent les orcs survivants et s'enfuirent vers la sécurité toute relative d'Azeroth.", "Sur Draenor, Turalyon et Khadgar acceptèrent le sacrifice ultime en décidant de détruire la Porte des ténèbres de leur côté. Même s'ils devaient y laisser leur vie et celle de leurs compagnons, ils savaient que c'était le seul moyen d'assurer la survie d'Azeroth. Alors que Hellscream et Deadeye se frayaient un chemin à travers les rangs humains dans une tentative désespérée pour retrouver leur liberté, la Porte des ténèbres explosa derrière eux. Pour eux et les autres orcs restés sur Azeroth, il n'y aurait plus de retour possible.", "Ner'zhul et son fidèle clan Shadowmoon franchirent le plus grand des portails nouvellement créés, tandis que de gigantesques éruptions volcaniques commençaient à disloquer les continents de Draenor. Les mers brûlantes montèrent et engloutirent les terres déchirées, jusqu'à ce que ce monde supplicié soit consumé dans une immense explosion apocalyptique." } } },
    ["The Kaldorei and the Well of Eternity"] = { { ids = { "o21583" }, first = "tenthousandyearsbeforeth", pages = { "Dix mille ans avant la première guerre entre les orcs et les humains, le monde d'Azeroth ne comprenait qu'un seul vaste continent entouré d'immenses océans déchaînés. Cette terre sans fin, nommée Kalimdor, donna naissance à des races et des créatures diverses, qui luttaient toutes pour survivre au milieu des éléments sauvages de ce monde naissant. Au centre de ce sombre continent existait un mystérieux lac d'énergies incandescentes.", "Ce lac, qui deviendrait un jour le Puits d'éternité, était le véritable coeur de la magie et des puissances naturelles du monde. Tirant ses énergies du Grand Néant par delà du monde, le Puits était comme une fontaine mystique déversant ses énergies puissantes de par le monde pour nourrir la vie dans sa multitude de formes.\n\nIl vint un temps où une tribu primitive d'humanoïdes nocturnes trouva son chemin jusqu'aux bords du fascinant lac enchanté.", "Ces humanoïdes nomades et sauvages, conduits par les étranges énergies du lac, construisirent des cabanes grossières sur ses berges paisibles. L'étrange tribu fut progressivement affectée par les pouvoirs cosmiques du Puits et y gagna la force, la sagesse et une quasi-immortalité. La tribu adopta le nom de Kaldorei, ce qui signifie \"enfants des étoiles\" dans sa langue natale. Pour célébrer leur société bourgeonnante, les Kaldorei construisirent de grands bâtiments et des temples tout autour du lac.", "Les Kaldorei, qui allaient un jour se faire connaître sous le nom d'elfes de la nuit, adoraient Elune, la déesse de la lune. Ils pensaient qu'elle dormait dans les profondeurs chatoyantes du Puits pendant la journée. Les premiers prêtres des elfes de la nuit étudièrent le Puits avec une curiosité inaltérable, cherchant à percer ses secrets et sa puissance cachés. Au fur et à mesure que leur civilisation grandissait, les elfes de la nuit explorèrent tout\nKalimdor et rencontrèrent ses myriades d'habitants.", "Les seules créatures qui arrêtèrent leur expansion furent les anciens et puissants dragons. Les grandes bêtes écailleuses vivaient volontiers recluses, mais elles défendaient leurs terres contre toute invasion. Les elfes de la nuit croyaient que les dragons étaient les protecteurs du monde et qu'il était préférable de les laisser en paix et de ne pas s'intéresser à leurs secrets.", "Plus tard, la curiosité des elfes de la nuit les conduisit à rencontrer et à se lier d'amitié avec de nombreuses entités puissantes, dont Cénarius, un impressionnant demi-dieu des forêts primitives. Cénarius, dont le coeur était grand, s'attacha aux elfes curieux et passa beaucoup de temps à leur enseigner les secrets du monde naturel. Les tranquilles Kaldorei développèrent une profonde empathie avec les forêts vivantes de Kalimdor et prirent goût à l'harmonieux équilibre de la nature.", "Au fur et à mesure que les siècles infinis s'écoulaient, la civilisation des elfes de la nuit grandit en taille et en splendeur. Leurs temples, leurs voies et leurs résidences s'étendaient sur toute la surface du continent. Azshara, la belle et douée reine des elfes de la nuit, construisit un immense et magnifique palais sur les rives du Puits afin d'y abriter ses serviteurs favoris dans des couloirs d'émeraude.", "Ses serviteurs, qu'elle nommait les Quel'dorei, ou \"Bien-nés\", lui obéissaient en tout et se pensaient supérieurs à leurs frères des castes inférieures. Bien que la reine Azshara fût aimée de tout son peuple avec la même ferveur, les Bien-nés étaient en secret jalousés et haïs par les masses.\n\nPartageant la curiosité des prêtres pour le Puits d'éternité, Azshara ordonna aux érudits bien-nés de percer ses secrets et de révéler son rôle véritable dans le monde.", "Les Bien-nés s'immergèrent dans le travail et étudièrent le Puits sans relâche. Ils finirent par développer la capacité de manipuler et de contrôler les énergies cosmiques du Puits. Au fur et à mesure que les expériences leur permettaient de progresser, les Bien-nés découvrirent qu'ils pouvaient utiliser leurs nouveaux pouvoirs pour créer ou détruire à volonté. Les malheureux Bien-nés découvraient la magie et avaient maintenant pour but d'en acquérir la maîtrise.", "Ils étaient convaincus que la magie était dangereuse si on l'utilisait de façon irresponsable, mais Azshara et ses Bien-nés s'abandonnèrent tout de même complètement au plaisir des sorts. Cénarius et de nombreux érudits elfes prévinrent que des catastrophes résulteraient nécessairement de cette manipulation infantile d'une magie volatile. Mais Azshara et ses serviteurs continuèrent, entêtés, à développer leurs pouvoirs naissants.", "Alors que leurs pouvoirs grandissaient, Azshara et les Bien-nés commencèrent visiblement à changer. La classe supérieure, distante et hautaine, devint de plus en plus cruelle et brutale envers ses frères de race. Un voile sombre noircissait désormais la beauté naguère légendaire d'Azshara. Elle s'isola de ses sujets fidèles et refusa tout contact avec qui que ce soit d'autre que ses prêtres bien-nés, en qui elle avait toute confiance.", "Un jeune érudit indépendant d'esprit nommé Furion Stormrage, qui avait passé le plus clair de sa vie à étudier les effets du Puits, commença à suspecter qu'un pouvoir terrible corrompait les Bien-nés et sa reine tant aimée. Il était incapable de deviner l'horreur à venir mais il savait que la vie des elfes de la nuit allait changer à jamais..." } } },
    ["The Last Guardian"] = { { ids = { "o175740" }, first = "theguardianaegwynngrewpo", pages = { "La Gardienne Aegwynn devint puissante au fil des ans et utilisa les énergies de Tirisfal pour grandement accroître sa vie. Croyant naïvement avoir battu Sargeras, elle continua à monter la garde contre les serviteurs du roi démon pendant neuf cents ans. Finalement, le Conseil de Tirisfal décréta que son service touchait à sa fin.", "Le Conseil ordonna à Aegwynn de retourner à Dalaran pour qu'ils puissent choisir un successeur à qui conférer les pouvoirs du gardien. Mais Aegwynn, qui n'avait jamais eu confiance dans le Conseil, décida de choisir elle-même son successeur.", "La fière Aegwynn envisagea de donner naissance à un fils à qui elle donnerait son pouvoir. Elle n'avait pas l'intention de permettre à l'Ordre de Tirisfal de manipuler ses successeurs comme il avait tenté de la manipuler. Elle se rendit dans le sud d'Azeroth, et trouva l'homme parfait pour engendrer son fils : un magicien humain expérimenté nommé Nielas Aran.", "Aran était le conjurateur de la cour et le conseiller du roi d'Azeroth. Aegwynn séduisit le magicien et conçut un fils. Les affinités naturelles de Nielas avec la magie couraient dans les veines de l'enfant à naître et allaient définir la voie que prendrait plus tard le garçon. Le pouvoir de Tirisfal fut également implanté dans l'enfant, mais il ne devait pas s'éveiller avant que l'adolescent n'atteigne la maturité physique.", "Le temps passa et Aegwynn donna naissance à son fils dans un bosquet retiré. Elle nomma l'enfant Medivh, ce qui signifie \"Gardien des secrets\" dans la langue des hauts-elfes. Aegwynn pensait qu'en mûrissant le garçon deviendrait le Gardien suivant. Mais l'esprit malin de Sargeras, qui se cachait en elle, s'était emparé dans son sein de l'enfant sans défense. Aegwynn n'imaginait pas que le nouveau Gardien du monde était déjà possédé par son principal ennemi.", "Certaine que son fils serait sain et solide, Aegwynn amena le jeune Medivh à la cour d'Azeroth et en confia l'éducation à son père mortel et à son peuple. Puis elle se mit en route vers des terres vierges et se prépara à entrer dans l'au-delà qui lui était réservé. Medivh devint un solide garçon, qui n'avait aucune idée de la puissance qui lui était promise en vertu de son héritage tirisfalin.", "Sargeras attendit son heure jusqu'à ce que la puissance du jeune homme se manifeste. Lorsque Medivh atteignit l'adolescence, il était devenu très populaire à Azeroth en raison de ses prouesses magiques et partait souvent à l'aventure avec ses deux amis : Llane, le prince d'Azeroth, et Anduin Lothar, un des derniers descendants de la lignée des Arathi. Les trois garçons faisaient toutes sortes de sottises dans le royaume, mais les citoyens les aimaient bien.", "Lorsque Medivh atteignit l'âge de 14 ans, la puissance cosmique qui sommeillait en lui s'éveilla avec l'esprit pervers de Sargeras qui rampait au fond de son âme. Medivh tomba dans un état catatonique qui dura plusieurs années.", "Lorsqu'il s'éveilla de son coma, il découvrit qu'il était devenu adulte et que ses amis Llane et Anduin étaient devenus régents d'Azeroth. Bien que désireux d'utiliser ses fabuleux pouvoirs pour la défense du pays qu'il appelait son foyer, ses pensées et ses émotions étaient distordues par l'esprit de Sargeras.", "Sargeras se révéla dans le coeur assombri de Medivh, car il savait que son plan pour la seconde invasion du monde était près d'aboutir et que le dernier Gardien y contribuerait." } } },
    ["The Lich King Triumphant"] = { { ids = { "o175762" }, first = "evenweakenedashewasartha", pages = { "Même affaibli comme il l'était, Arthas parvint à déjouer les plans d'Illidan et à atteindre le Trône de glace en premier. Avec son épée runique, Frostmourne, Arthas brisa la prison de glace du roi-liche et exhuma le casque et le plastron enchantés de Ner'zhul.", "Arthas plaça le casque d'une invraisemblable puissance sur sa tête et devint le nouveau roi-liche. Les esprits de Ner'zhul et d'Arthas fusionnèrent en une unité unique, comme Ner'zhul l'avait toujours envisagé. Illidan et ses troupes durent rebrousser chemin en toute hâte, regagnant l'Outreterre, tandis qu'Arthas devenait l'une des plus puissantes entités que le monde ait jamais connue.", "À cette heure, Arthas, le nouveau et immortel roi-liche, réside à Northrend, on dit qu'il rebâtit la citadelle de la Couronne de glace. Son fidèle lieutenant, Kel'Thuzad, commande le Fléau dans les Maleterres. Sylvanas et ses Réprouvés rebelles tiennent les clairières de Tirisfal, une petite portion du royaume déchiré par la guerre." } } },
    ["The New Horde"] = { { ids = { "o175752" }, first = "thechiefwardenoftheinter", pages = { "Le gardien des camps d'internement, Aedelas Blackmoore, surveillait les orcs captifs depuis la forteresse-prison de Durnholde. Un orc retenait plus particulièrement son attention : l'orphelin trouvé enfant dix-huit ans plus tôt. Blackmoore avait élevé le jeune mâle en tant qu'esclave et l'avait nommé Thrall. Blackmoore apprit à l'orc la tactique, la philosophie et le combat. Thrall subit même la formation des gladiateurs. Le gardien corrompu avait pour objectif de se servir de l'orc comme arme.", "En dépit de sa difficile enfance, le jeune Thrall devint un orc fort et intelligent, qui savait dans son coeur que la vie d'esclave n'était pas pour lui. En grandissant, il apprit ce qui se passait hors de la forteresse. Il découvrit que son peuple, les orcs, qu'il n'avait jamais rencontré, avait été vaincu et parqué dans des réserves. Doomhammer, le chef de son peuple, s'était échappé et se cachait. Il savait également qu'un clan rebelle était encore en activité, cherchant à tromper la vigilance de l'Alliance.", "Inexpérimenté mais plein de ressources, Thrall décida de s'échapper et de partir à la recherche de son peuple. Au cours de son périple, Thrall découvrit les réserves et vit que sa race autrefois puissante était devenue étrangement indolente. N'ayant pas trouvé les fiers guerriers qu'il espérait, Thrall se mit à la recherche du dernier chef invaincu, Grom Hellscream.", "Pourchassé en permanence par les humains, Hellscream parvenait néanmoins à maintenir l'esprit combatif de ses orcs, le clan Warsong. Il continuait à combattre pour libérer son peuple de l'oppression. Mais Hellscream ne parvint jamais à trouver un moyen de débarrasser les orcs captifs de leur étrange léthargie. Thrall, jeune et impressionnable, fut inspiré par l'idéalisme de Hellscream et développa une forte empathie pour la Horde et ses traditions guerrières.", "Cherchant à découvrir la vérité sur ses propres origines, Thrall voyagea vers le nord à la recherche du légendaire clan Frostwolf. Thrall apprit que Gul'dan avait exilé le clan Frostwolf au début de la Première Guerre. Il découvrit également qu'il était le fils et l'héritier du héros du clan, Durotan, le véritable chef du clan Frostwolf qui avait été assassiné vingt ans auparavant.", "Sous la tutelle du vénérable chaman Drek'Thar, Thrall étudia la culture chamanique que son peuple avait oubliée sous la férule de Gul'dan. Au fil du temps, Thrall devient un puissant chaman et prit la place qui lui revenait à la tête du clan Frostwolf. Grandi par les éléments eux-mêmes et avide d'accomplir son destin, Thrall décida de libérer les clans captifs et sa race de la corruption démoniaque.", "Thrall rencontra alors un chef âgé, Orgrim Doomhammer, qui vivait en ermite depuis de nombreuses années. Doomhammer, qui avait été un ami proche du père de Thrall, décida de suivre le jeune orc visionnaire et de l'aider à libérer les clans captifs. Avec le soutien de plusieurs des chefs aguerris, Thrall parvint finalement à rendre vie à la Horde et à redonner une identité spirituelle à son peuple.", "Pour symboliser la renaissance des orcs, Thrall retourna à la forteresse de Durnholde. Il mit un terme définitif aux plans de son ancien maître, Blackmoore, en assiégeant les réserves. Malheureusement, lors de la libération d'une des réserves, Doomhammer tomba au combat.", "Thrall ramassa le légendaire marteau de guerre de Doomhammer, endossa son armure noire et devint le nouveau chef de la Horde. Dans les mois qui suivirent, la petite mais vivace Horde de Thrall libéra plusieurs réserves et contra les efforts de l'Alliance visant à l'en empêcher. Encouragé par son meilleur ami et son mentor Grom Hellscream, Thrall s'assura qu'aucun orc ne serait jamais plus esclave." } } },
    ["The Old Gods and the Ordering of Azeroth"] = { { ids = { "o175725" }, first = "unawareofsargerasmission", pages = { "Ignorant apparemment que Sargeras cherchait à défaire leur gigantesque travail, les Titans continuèrent à se déplacer de monde en monde, mettant en ordre et façonnant chacun d'entre eux comme il leur paraissait convenable. Au cours de leur voyage, ils arrivèrent sur un petit monde que ses habitants appelleraient plus tard Azeroth.", "Les Titans progressèrent au travers de son paysage chaotique primordial en croisant la route de nombreux êtres élémentaires hostiles. Les élémentaires, qui adoraient les êtres maléfiques et insondables connus sous le nom de Dieux très anciens, firent le voeu de repousser les Titans et de préserver leur monde de leur main métallique.", "Le Panthéon, troublé par le penchant des Dieux très anciens pour le mal, envoya ses forces combattre les élémentaires et leurs maîtres noirs. Les armées des Dieux très anciens étaient menées par les plus puissants lieutenants élémentaires : Ragnaros le seigneur du Feu, Therazane la Mère des pierres, Al'Akir le seigneur des Vents et Neptulon le Chasseur des vagues.", "Leurs forces chaotiques firent rage sur le monde et se heurtèrent aux colossaux Titans. Bien que les élémentaires furent puissants au-delà de toute compréhension humaine, leurs forces combinées ne purent arrêter les Titans. L'un après l'autre, les seigneurs élémentaires tombèrent et leurs forces se dispersèrent.", "Le Panthéon détruisit les citadelles des Dieux très anciens et enchaîna les cinq êtres abjects loin sous la surface de la terre. Le pouvoir des Dieux très anciens n'attachant plus leurs esprits bouillonnants au monde physique, les élémentaires se dissipèrent et retournèrent à l'argile première. Une fois les élémentaires disparus, la nature s'apaisa et le monde devint paisible et harmonieux. Les Titans, s'avisant que la menace avait disparu, se mirent au travail.", "Les Titans donnèrent pouvoir à de nombreuses races de les aider à façonner le monde. Pour les aider à drainer les cavernes impénétrables sous la terre, ils créèrent les nains à partir d'une pierre magique et vivante. Pour les aider à contenir les mers et à séparer la terre de l'océan, ils créèrent d'immenses géants des mers, de tempérament doux. Pendant longtemps, les Titans transformèrent et bâtirent la terre, jusqu'à ce qu'il ne reste plus qu'un continent parfait.", "Au centre du continent, les Titans creusèrent un lac d'énergies scintillantes. Ils le nommèrent Puits d'éternité. Il devait devenir une fontaine de vie pour le monde. Ses puissantes énergies devaient nourrir la structure du monde et permettre à la vie de s'épanouir dans l'humus riche de la terre. Peu à peu, plantes, arbres, monstres et créatures diverses commencèrent à peupler le continent primordial.", "Lorsque le crépuscule tomba sur leur dernier jour de travail, les Titans nommèrent le continent Kalimdor : \"terre de l'éternelle lumière\"." } } },
    ["The Pariah's Instructions"] = { { ids = { "i17781" }, first = "setfarbackinthevalleyofs", pages = { "Le très saint temple de Maraudon se trouve très loin dans la vallée des Lances. Cela a beau être un sacrilège, je demande à un non-centaure de nous aider. Vous allez comprendre pourquoi.\n\nLà, juste derrière les portes, où seuls les esprits et nos prêtres et prêtresses les plus sacrés peuvent se rendre, réside le Prophète sans nom. Il est l'un des plus âgés de toutes les tribus, c'est notre plus haute autorité spirituelle.", "Le Prophète est puissant et communique avec les esprits de nos ancêtres. Mais c'est un fou ! Il n'a aucune idée du vrai pouvoir qu'il possède. L'Amulette des esprits se trouve sur lui. C'est de là que toute sa force provient.\n\nJ'ai appris que l'Amulette est puissante, mais elle est incomplète.", "Il manque cinq gemmes sur l'amulette. Et si ces gemmes sont retrouvées et replacées sur le symbole, le pouvoir de l'amulette excédera de loin celui qui est le sien actuellement. J'ai retrouvé les cinq gemmes, mais j'ai besoin de l'une de vos compétences pour m'aider à les rassembler. Tuer le Prophète sans nom est une hérésie, sans aucun doute, de même que dépouiller son cadavre, mais ce que je voudrais vous demander condamnerait n'importe quel centaure rien qu'en y pensant.", "Les esprits de nos premiers khans rôdent à travers les cavernes de Maraudon. Les premiers enfants de notre mère et de notre père, et nos plus grands chefs : Gelk, Kolk, Magra, Maraudos et Veng. Chacun de ces esprits détient l'une des gemmes manquantes.", "Utilisez le pouvoir de l'Amulette des esprits pour les inciter à se manifester et prenez les gemmes qu'elles ont ! Puis, placez les gemmes sur l'Amulette des esprits et rapportez-la-moi. Une fois que j'aurai l'Amulette d'union, je serai assez puissant pour reformer les tribus afin que nous puissions enfin devenir ce que nos ancêtres voulaient !" } } },
    ["The Scourge of Lordaeron"] = { { ids = { "o175756" }, first = "afterpreparingformanylon", pages = { "Arpès de longs mois de préparation, Kel'Thuzad et son Culte des damnés frappèrent finalement un premier coup en lançant les morts-vivants sur Lordaeron. Uther et ses paladins enquêtèrent dans les régions touchées, dans l'espoir de trouver le moyen d'arrêter cette infection. En dépit de leurs efforts, cette dernière continuait à se répandre et menaçait de déchirer l'Alliance.", "Tandis que les armées de morts-vivants se déversaient sur Lordaeron, le fils unique de Terenas, le prince Arthas, se porta au-devant du Fléau. Arthas parvint à tuer Kel'Thuzad, mais malgré cela les rangs des morts-vivants s'enrichissaient de chaque soldat mort au combat. Frustré et impuissant devant cette armée innombrable, Arthas prit la décision audacieuse d'en faire la conquête. Ses camarades l'avertirent qu'il risquait d'y perdre son humanité.", "La peur et la fermeté d'Arthas furent sa perte. Il remonta à la source de l'infection, Northrend, désireux de mettre fin définitivement à cette menace. Mais le prince Arthas succomba devant l'immense puissance du roi-liche. Pensant que cela sauverait son peuple, Arthas s'empara de l'épée runique maudite, Frostmourne.", "L'épée lui conféra un immense pouvoir mais lui vola son âme et fit de lui le plus grand des chevaliers de la mort du roi-liche. Son âme rejetée et sa raison détruite, Arthas mena le Fléau contre son propre royaume. Enfin, Arthas assassina son propre père, le roi Terenas, et écrasa Lordaeron sous la botte de fer du roi-liche." } } },
    ["The Second Troll Legend"] = { { ids = { "i2006" }, first = "taleofgrilekthewanderert", pages = { "Conte de Gri'lek le vagabond\n\n[...Le début est effacé et illisible. Mais la fin est lisible...]\n\nGri'lek a marché à travers la jungle. Et ses yeux crépitaient et sa poitrine était incendiée, car il avait de la colère en lui.\n\nDans sa rage, il hurla vers les cieux et leva son bras. Il leva son bras gauche, devenu fort et sûr au cours des chasses sans son frère.\n\nCar le bras droit de Gri'lek n'était plus, et ne devait plus revenir.", "Alors il a erré et cherché. Et son bras restait perdu. Alors il a rugi, maudit, marché.\n\nMais Gri'lek avait depuis longtemps détourné ses oreilles des esprits, et ils étaient furieux et n'écoutaient pas ses malédictions.\n\nGri'lek était condamné. Condamné à errer sans bras." } } },
    ["The Sentinels and the Long Vigil"] = { { ids = { "o175732" }, first = "withthedepartureoftheirw", pages = { "Après le départ de leurs cousins, les elfes de la nuit se consacrèrent de nouveau à la défense de leur terre enchantée. Les druides, sentant approcher à nouveau l'heure de l'hibernation, se préparèrent à dormir en laissant derrière eux leurs familles et leurs proches.", "Tyrande, qui était devenue grande prêtresse d'Elune, demanda à son amour de toujours, Malfurion, de ne pas la quitter pour le Rêve d'émeraude d'Ysera. Mais Malfurion, contraint par un pacte d'honneur d'entrer dans le monde onirique, dit adieu à la prêtresse et jura qu'ils ne seraient jamais séparés aussi longtemps qu'ils resteraient fidèles à leur amour.", "Tyrande, laissée seule pour protéger Kalimdor contre les dangers du nouveau monde, assembla une puissante force de combat parmi ses soeurs elfes de la nuit. Ces guerrières sans peur et bien entraînées se dévouèrent à la défense de Kalimdor et prirent le nom de Sentinelles. Bien que préférant patrouiller seules dans les forêts d'Ashenvale, elles avaient beaucoup d'alliés sur lesquels compter en cas d'urgence.", "Le demi-dieu Cénarius resta aux alentours du mont Hyjal. Ses fils, connus sous le nom de Gardiens du bosquet, continuaient à surveiller les terres des elfes de la nuit et aidèrent souvent les Sentinelles à maintenir la paix sur la contrée. Même les filles timides de Cénarius, les dryades, furent de plus en plus souvent visibles.", "Bien qu'occupée par la garde d'Ashenvale, Tyrande souffrait tout de même de l'absence de Malfurion à ses côtés. Tandis que les siècles interminables du sommeil des druides passaient, elle commença à redouter de plus en plus une nouvelle invasion démoniaque. Elle ne pouvait se débarrasser de la sensation que la Légion ardente était peut-être toujours proche, au-delà des Grandes Ténèbres du ciel, attendant l'heure de sa revanche sur les elfes de la nuit et le monde d'Azeroth." } } },
    ["The Seven Kingdoms"] = { { ids = { "o175737" }, first = "stromcontinuedtoactasthe", pages = { "Strom continua d'être le centre névralgique d'Arathor, mais, à la manière de Dalaran, beaucoup de nouvelles cités-états émergèrent sur le continent de Lordaeron. Gilnéas, Alterac, Kul Tiras furent les premières. Chacune avait ses propres coutumes et ses propres règles commerciales, mais toutes se soumettaient à l'autorité unificatrice de Strom.", "Sous la garde vigilante de l'Ordre de Tirisfal, Dalaran devint la principale ville d'apprentissage des magiciens. Les magiocrates qui dirigeaient Dalaran fondèrent le Kirin Tor, une secte spécialisée qui avait pour charge de faire l'inventaire des sorts, des artefacts et des objets magiques connus de l'humanité, et de les étudier.", "Gilnéas et Alterac devinrent d'ardents soutiens de Strom et constituèrent de puissantes armées qui explorèrent les zones montagneuses au sud de Khaz Modan. C'est à cette époque que les humains rencontrèrent pour la première fois l'ancienne race des nains et arrivèrent à leur cité souterraine d'Ironforge. Les humains et les nains partagèrent de nombreux secrets sur la forge et le travail du métal et se découvrirent un goût commun pour les combats et la narration des épopées.", "La cité-état de Kul Tiras, fondée sur une grande île au sud de Lordaeron, développa une économie prospère basée sur la pêche et la navigation. Avec le temps, Kul Tiras bâtit une flotte impressionnante de vaisseaux marchands qui firent voile vers toutes les terres connues, à la recherche de biens exotiques à échanger. Mais tandis que l'économie d'Arathor s'épanouissait, ses plus solides éléments commencèrent à se désagréger.", "Avec le temps, les seigneurs de Strom cherchèrent à déplacer leur domaine vers les terres fertiles de Lordaeron et quittèrent les terres arides du Sud. Les héritiers du roi Thoradin, les derniers descendants de la lignée d'Arathi, affirmèrent que Strom ne devait pas être abandonnée et encoururent la rancune des citoyens aisés, qui avaient également hâte de partir.", "Les seigneurs de Strom, voulant trouver la pureté et la lumière du Nord vierge, décidèrent de laisser derrière eux leur vieille cité. Loin au nord de Dalaran, les seigneurs de Strom érigèrent une nouvelle cité-état qu'ils appelèrent Lordaeron. Tout le continent allait bientôt prendre ce nom. Lordaeron devint un centre important pour les pèlerins et ceux qui cherchaient la paix et la sécurité.", "Les descendants des Arathi, abandonnés entre les murs en ruines de la vieille Strom, décidèrent d'aller vers le sud, au-delà des montagnes rocheuses de Khaz Modan. Leur voyage prit fin après de longues saisons et ils s'établirent dans le nord d'un continent qu'ils nommèrent Azeroth. Dans une vallée fertile, ils fondèrent le royaume de Stormwind, qui devint rapidement une puissance indépendante.", "Les quelques guerriers qui restaient à Strom décidèrent de demeurer entre les anciens murs de leur ville. Strom n'était plus le centre de l'empire, mais une nouvelle nation s'y développa sous le nom de Stromgarde. Chaque cité-état prospérait de son côté et Arathor, en tant qu'empire, se désintégra. Chaque nation développait ses propres coutumes, ses propres croyances, toutes se séparaient les unes des autres. Le rêve du roi Thoradin, unifier l'humanité, s'était évaporé." } } },
    ["The Skull of Tyrannistrasz"] = { { ids = { "o175679" }, first = "theremainsofthegargantua", pages = { "Les restes de l'énorme dragon rouge ont été trouvés dans les Paluns peu après la bataille de Grim Batol. Tyrannistrasz, selon les rumeurs, était le plus ancien compagnon de la reine de dragons, Alextrasza." } } },
    ["The State of Lakeshire"] = { { ids = { "i1293" }, first = "mylordwarisuponusdoomhar", pages = { "Monseigneur,\n\nLa guerre est sur nous. La malédiction frappe à nos portes.\n\nEn tant que Magistrat de la ville de Lakeshire, il est de mon devoir de vous faire savoir que des activités militaires ont lieu dans les colonies les plus à l'est de Sa Majesté.\n\nDans ces pages, vous trouverez un rapport sur Lakeshire, niché dans les Carmines.", "La perte du donjon de Guet-de-pierre est très grave. Dans les précédents rapports, je vous ai fait connaître l'alliance entre le clan Blackrock des orcs et le démoniste nommé Morganth. Les orcs Blackrock se sont battus avec une sauvagerie inouïe, probablement soutenus par la magie maléfique de Morganth. Nombre des vaillants chevaliers de Sa Majesté ont péri dans la défense du donjon, mais ce fut en vain.", "Étrangement, Morganth s'est retourné contre les cohortes des orcs aussitôt après leur ignoble victoire. Le démoniste a construit une tour des arcanes dans le nord-est et il a utilisé ses pouvoirs pour assembler une petite armée de gnolls Sombrepoil destinés à servir ses vils desseins. Les orcs comme les humains ont été les victimes des ces brutes gluantes. Les raisons de cette rupture entre Morganth et Gath'Ilzogg, le chef de guerre du clan Blackrock, restent inconnues.", "Il est regrettable de constater que les vils orcs semblent surtout intéressés par la lutte contre les citoyens de Sa Majesté. Au cours des quinze derniers jours, le clan Blackrock a tenté plusieurs offensives brutales contre Lakeshire. Beaucoup d'hommes braves y ont perdu la vie. Les orcs avancent si rapidement et avec tant de rage que le pont du lac Placide n'est plus que ruines. Nos fournitures de guerre diminuent dangereusement. Nous manquons de bandages pour panser les plaies des blessés.", "Je sollicite maintenant de Sa Majesté qu'elle aide le bon peuple de Lakeshire en ces temps de désespoir. Nous avons besoin de troupes pour défendre notre territoire et de nouveaux engins de guerre pour remplacer ceux perdus au combat. La nourriture et les matériaux de construction nous font aussi défaut. Monseigneur, par pitié, veuillez nous aider à défendre le dernier bastion entre les humains et les orcs. L'ennemi ne doit pas pénétrer dans le royaume de Stormwind.", "J'ai peur qu'un mal plus grand et plus noir ne se prépare dans ce chaudron de corruption que sont devenues les terres du Nord. Il est impératif que le royaume de Stormwind agisse à moins que nous ne désirions devenir les esclaves de l'ennemi.\n\nSigné,\n\nMagistrat Solomon\nVille de Lakeshire\nRoyaume de Stormwind" } } },
    ["The Story of Morgan Ladimore"] = { { ids = { "i2154" }, first = "morganladimorewasagreata", pages = { "Morgan Ladimore était un grand et noble chevalier qui s'est battu en défense de l'innocent, du pauvre, de l'affligé. Pendant des années, il a arpenté sans faiblir les confins d'Azeroth, apportant le réconfort à ceux qui souffraient et un prompt châtiment aux serviteurs du mal.\n\nIl avait épousé une jeune femme du nom de Lys dans l'été de sa dix-huitième année. Ils étaient fort amoureux et eurent trois enfants, un garçon et deux filles.\n\nMorgan avait trente-deux ans lorsque la guerre éclata à", "Lordaeron. Morgan fut appelé aux côtés du légendaire paladin Uther, le Porteur de Lumière, pour combattre contre les orcs et les morts-vivants. Il laissa femme et enfants en sûreté dans leur maison et partit pour la guerre.\n\nLes années passèrent et la guerre ne cessait point. Morgan fut le témoin de bien des horreurs, dont la déroute des paladins de la Main d'argent, la mort d'Uther et l'extension du Fléau. Il n'était retenu de sombrer dans la folie que par l'espoir d'être", "un jour réuni à sa femme et ses enfants.\n\nMorgan finit par rentrer au pays, mais le trouva bien différent de ce qu'il avait laissé derrière lui. Les forêts naguère verdoyantes étaient corrompues par les morts-vivants et les forces du mal. Des maisons et des fermes détruites noircissaient le paysage à perte de vue et le cimetière près de la Colline-aux-Corbeaux avait pris d'effroyables proportions. Choqué et dérouté, Morgan regagna finalement sa demeure, mais ne trouva que des ruines. Ignorant ce qui avait ravagé sa terre natale, il", "se mit en marche vers le village pour trouver des réponses et, espérait-il, sa femme et ses enfants.\n\nMorgan tenta de savoir ce qu'il était advenu des siens, mais ne trouva pas de réponse. Un prêtre de Darkshire, comme ces terres s'appelaient désormais, lui conseilla de chercher parmi les pierres tombales du cimetière de la Colline-aux-Corbeaux. Morgan refusa de croire à la mort de sa famille et continua de fouiller chaque ferme, chaque maison du bois de la Pénombre, mais sans résultat.\n\nMorgan galopa de Darkshire jusqu'à Lakeshire, pensant que sa famille s'y était peut-être réfugiée. En route,", "il décida malgré tout de faire halte au cimetière de la Colline-aux-Corbeaux. Morgan passa des heures à marcher parmi les pierres tombales. Il reconnut le nom de bien des gens qu'il avait connus et sentit sa raison défaillir. Puis il les vit : un petit espace mal entretenu avec trois pierres tombales. En approchant, il se sentit saisi d'effroi. Morgan brossa la poussière de la pierre tombale la plus grande pour en lire le nom. Les lettres grossièrement gravées sur la pierre confirmèrent", "ses pires craintes :\n\nLys Ladimore\nEpouse et mère bien-aimée\n\nLes peurs de Morgan se transformèrent en consternation puis en douleur, et il tomba à genoux pour pleurer. Il resta des heures à contempler cette tombe, implorant la pierre froide de lui pardonner. Quelque chose finit par casser à l'intérieur de lui. Il dégaina son épée et se mit à asséner des coups sur les pierres tombales avec des hurlements de douleur. Aveuglé par la rage, il se démenait sauvagement et finit par attirer l'attention", "de trois fossoyeurs. Ces derniers tentèrent de l'immobiliser, mais il se retourna contre eux, hurlant des accusations contre les innocents fossoyeurs. Puis il les tua tous les trois.\n\nPlus tard, sa rage passée, Morgan commença à réaliser ce qu'il venait de faire : son épée sanglante était encore plantée dans la poitrine de l'un des fossoyeurs. Désespéré, il dégaina son poignard et se l'enfonça dans la poitrine.\n\nLes corps de Morgan Ladimore et de ses trois victimes furent retrouvés", "le lendemain. Le paladin fut enterré rapidement, sans cérémonie, dans une tombe creusée à la hâte aux abords du cimetière. Comme Morgan avait assassiné des innocents, ce qui était contraire à sa nature et à ses convictions, et en raison de la douleur qu'il avait ressentie à n'avoir pas su protéger sa famille, Morgan n'eut pas droit à une mort paisible et fut condamné à hanter dans l'affliction.\n\nQuelques jours plus tard, on constata que son corps ne se trouvait plus dans sa tombe. L'être qui avait été Morgan erre", "maintenant dans le bois de la Pénombre, consumé par le chagrin d'avoir perdu sa famille et par la haine qu'il se porte à lui-même. Mor'Ladim (tel est désormais son nom) arpente le bois de la Pénombre, rempli de haine et d'un désir de vengeance. Il tue sans discernement." } } },
    ["The Third Troll Legend"] = { { ids = { "i2007" }, first = "risingfromtheoceanatower", pages = { "S'élevant en tour d'eau au-dessus de l'océan, Neptulon envoya les grands krakkens détruire I'lalai. Si hautes étaient leurs formes que des jungles de varech palpitaient entre leurs côtes, et les léviathans bourdonnaient sur tout leur corps.\n\nLe plus grand des krakkens leva alors ses bras et frappa puissamment la mer, envoyant des raz-de-marée autour de lui. Puis tous se mirent en route vers I'lalai.", "Les Krakkens rugirent et leurs voix éclatèrent comme des typhons :\n\n\"Nous venons.\"\n\nMin'loth, imperturbable, invoqua sa magie. Les vagues envoyées vers I'lalia se séparèrent et se perdirent dans les jungles côtières. Min'loth ordonna alors à ses serviteurs de chanter des sorts de lien et des dizaines de voix de trolls s'élevèrent.\n\nEt une voix se détacha des autres.", "Min'loth vociféra et sa magie rassembla la force des sorts de ses serviteurs, pour la diriger vers les krakkens qui approchaient.\n\nLes flots se séparèrent et le sort de Min'loth jaillit vers les soldats de Neptulon. Des éclairs déchirèrent le ciel et le sort les atteignit, faisant bouillir l'eau et creusant des cratères.\n\nMin'loth chanta sa victoire, sachant que son sort allait abattre les grandes bêtes.", "Mais les Krakkens étaient vieux, très vieux. Ils se rappelaient le temps où la terre avait pour la première fois jailli de l'eau.\n\nIls se rappelaient le règne des Anciens et leur chute face aux Voyageurs. Ils se souvenaient de la naissance de toute magie.\n\nIls étaient vieux et ils détenaient bien des secrets. Le sort de Min'loth était puissant mais, tout comme les trolls, il était mortel.\n\nC'est ainsi qu'il échoua.", "Le sort ne put lier les Krakkens, mais il les rendit furieux. Aucun mortel ne leur avait causé de douleur depuis des siècles, et le sort des trolls était douloureux.\n\nIls se débarrassèrent des liens de Minloth puis s'élancèrent pleins de rage.\n\nUn grondement s'éleva tandis que de grandes vagues s'élevaient des profondeurs et roulaient vers la terre. Quand ils atteignirent I'lalai, ils couvrirent la ville de leur ombre.\n\nMais avant de la détruire, les Krakkens firent halte.", "Les sorciers docteurs trolls tremblèrent et en appelèrent à leur maître. Min'loth regarda les montagnes de la mer, méfiant et sombre. Il se tourna vers ses adeptes et murmura, et les trolls gravèrent ses derniers mots dans la pierre. Min'loth fit alors face aux menaçants Krakkens.\n\nIl grimaça et lança violemment son bâton : son dernier acte de bravoure.\n\nLes Krakkens tournèrent alors leur rage contre Min'loth, et un océan fondit sur I'lalai.\n\nEt la ville disparut.", "Puis les eaux tombèrent sur la jungle, nettoyant tout sur leur passage. Trolls et bêtes hurlaient sous les cataractes qui les engloutissaient.\n\nNombre de Gurubashi se demandèrent pourquoi l'océan les avalait, mais ils mouraient sans réponse.\n\nEnfin, lorsque les eaux atteignirent les montagnes, elles s'arrêtèrent. Apaisées, elles revinrent au rivage, laissant derrière elles la mort et la désolation.\n\nElles s'en allèrent, mais pas au point de rendre à la terre les ruines d'I'lalai, qui restèrent à jamais englouties.", "Et le chef Var'gazul, à  l'abri dans les montagnes de Zul'Gurub, s'enfonça dans la jungle et la trouva vidée de son peuple.\n\nIl fut pris de désespoir, car ses rêves de conquête étaient anéantis.\n\nJamais ne fut trouvé Min'loth le Serpent." } } },
    ["The Twin Empires"] = { { ids = { "o175854" }, first = "aboutyearsagolongbeforet", pages = { "Il y a 16000 ans environ (bien avant que les elfes de la nuit n'attirent stupidement la colère de la Légion ardente), les trolls régnaient sur la plus grande partie de Kalimdor (qui était alors un continent unique). Il y avait deux empires trolls : les Gurubashi dans les jungles du sud-est, et les Amani dans les terres médianes.", "De plus petites tribus vivaient loin au nord (dans la région connue sous le nom de Northrend). Ces tribus ont fondé une petite nation connue sous le nom de Gundrak, mais n'ont jamais connu la prospérité des empires du sud.", "Les empires Gurubashi et Amani ne s'aimaient guère, mais se sont rarement fait la guerre. À l'époque, leur plus grand ennemi commun était un troisième empire, la civilisation d'Azj'Aqir. Les Aqir étaient des insectoïdes intelligents qui régnaient sur les terres de l'ouest lointain. Ces insectoïdes intelligents étaient expansionnistes et maléfiques. Ils étaient obsédés par la destruction des formes de vie non-insectoïdes dans Kalimdor.", "Les trolls les combattirent pendant des millénaires mais ne parvinrent jamais à obtenir une victoire décisive sur les Aqir. Finalement, en raison de la persévérance des trolls, le royaume des Aqir se divisa et ses membres fuirent dans des colonies séparées dans les régions les plus au nord et au sud du continent.", "Deux cités-états Aqir émergèrent : Azjol-Nerub dans les terres du Nord et Ahn'Qiraj dans le désert du Sud. Les trolls suspectaient l'existence d'autres colonies d'Aqir sous Kalimdor, mais leur existence ne fut jamais vérifiée.", "Une fois les insectoïdes contraints à l'exil, les deux empires des trolls reprirent le cours normal de leur existence. En dépit de leur grande victoire, aucune des deux civilisations ne s'étendit au-delà de ses frontières d'origine. Mais d'anciens textes évoquent une petite faction de trolls qui quittèrent l'empire Amani pour fonder une colonie au coeur du continent noir.", "Là, ces braves pionniers découvrirent le Puits d'éternité cosmique qui les transforma en créatures dotées d'immenses pouvoirs. Certaines légendes suggèrent que ces trolls aventureux furent les premiers elfes de la nuit, mais cette théorie n'a jamais été prouvée." } } },
    ["The War of the Ancients"] = { { ids = { "o175727" }, first = "thehighbornesrecklessuse", pages = { "L'utilisation imprudente de la magie par les Bien-nés fit déborder des spirales d'énergie hors du Puits d'éternité dans le Grand Néant extérieur. Ces traînées d'énergie envahirent le Néant Distordu et furent ressenties par d'effroyables esprits étrangers. Sargeras, le Grand Ennemi de toute vie, le Ravageur des mondes, huma les puissants effluves d'énergie et fut conduit jusqu'à leur lointain point d'origine.", "Il espionna le monde primordial d'Azeroth et sentit les énergies sans fin du Puits d'éternité. Sargeras en devint fou de désir. Le grand dieu noir du Vide sans nom décida de détruire ce monde naissant et de s'emparer de ses énergies.", "Sargeras rassembla sa vaste armée démoniaque, connue sous le nom de Légion ardente, et se mit en branle vers le monde paisible d'Azeroth. La Légion, qui comptait un million de démons hurlants rassemblés dans les lieux les plus reculés de l'univers, se mit à bouillonner à l'idée de la conquête. Les lieutenants de Sargeras, Archimonde le Profanateur et Mannoroth le Destructeur, préparèrent les serviteurs infernaux à la grande offensive.", "La reine Azshara, subjuguée par la terrible extase de sa magie, succomba à l'indéniable pouvoir de Sargeras et lui offrit le droit d'entrer dans son monde. Même ses serviteurs bien-nés furent entraînés par l'inévitable corruption de la magie et commencèrent à adorer Sargeras comme leur dieu. Pour montrer leur allégeance à la Légion, les Bien-nés aidèrent leur reine à ouvrir un grand portail tourbillonnant dans les profondeurs du Puits d'éternité.", "Une fois ses préparatifs terminés, Sargeras lança sa dramatique invasion d'Azeroth. Les guerriers démons de la Légion ardente s'engouffrèrent dans le monde à travers le Puits d'éternité et firent le siège des cités assoupies des elfes. Menée par Archimonde et Mannoroth, la Légion se répandit sur les terres de Kalimdor, ne laissant que cendres et larmes dans son sillage.", "Les sorciers démoniaques appelèrent à eux les infernaux qui s'écrasèrent comme des météorites impies sur les colonnes raffinées des temples de Kalimdor. La Garde maudite, composée d'assassins sanguinaires, traversa les champs de Kalimdor en exterminant tout le monde sur son passage. Des meutes de gangrechiens sauvages ravagèrent les campagnes sans la moindre opposition. Les braves guerriers kaldorei se précipitèrent pour tenter de défendre leur terre natale, mais ils durent rompre, pouce par pouce, devant la furie meurtrière de la Légion.", "Malfurion Stormrage décida de trouver coûte que coûte de l'aide pour son peuple assiégé. Stormrage, dont le propre frère Illidan pratiquait la magie des Bien-nés, était rendu furieux par la corruption grandissante de la classe supérieure. Il persuada Illidan de renoncer à sa dangereuse obsession et il se mit en quête de Cénarius dans le but de rassembler une force de résistance.", "La belle et jeune prêtresse Tyrande accepta d'accompagner les deux frères au nom d'Elune. Bien que Malfurion et Illidan partageassent un chaste amour pour la noble prêtresse, le coeur de Tyrande appartenait à Malfurion seul. Illidan fut blessé par l'idylle naissante de son frère avec Tyrande, mais savait que sa souffrance n'était rien en regard de sa dépendance à la magie.", "Illidan, qui était devenu captif de la fascination magique, luttait pour conserver le contrôle de lui-même, pour repousser l'envie dévorante qu'il ressentait de goûter à nouveau aux énergies du Puits. Cependant, avec l'aide patiente de Tyrande, il parvint à se contenir et il aida son frère à trouver le demi-dieu Cénarius, qui vivait en reclus.", "Cénarius, qui vivait au sein des Plaines sacrées du lointain mont Hyjal, accepta d'aider les elfes de la nuit en retrouvant les anciens dragons et en sollicitant leur appui. Les dragons, conduits par le grand léviathan rouge, Alexstrasza, acceptèrent de se porter à la rencontre des démons et de leurs maîtres infernaux.", "Cénarius, appelant tous les esprits des forêts enchantées, rallia une armée d'antiques hommes-arbres et les conduisit à l'attaque de la Légion dans une audacieuse opération au sol. Les alliés des elfes de la nuit convergèrent vers le temple d'Azshara et le Puits d'éternité et la guerre totale commença. Malgré la puissance de leurs nouveaux alliés, Malfurion et ses compagnons réalisèrent que la Légion ne pouvait être vaincue par des combattants conventionnels.", "Tandis que la bataille formidable faisait rage autour de la capitale Azshara, la reine naïve et trompée attendait l'arrivée de Sargeras. Le seigneur de la Légion se préparait à passer par le Puits d'éternité dans le monde ravagé par la guerre. Son ombre immense s'approchait toujours plus du Puits lorsque Azshara rassembla les plus puissants de ses serviteurs bien-nés. En liant leurs pouvoirs magiques dans un seul sort focalisé, ils cherchèrent à créer une porte assez vaste pour laisser passer Sargeras.", "Tandis que la bataille faisait rage sur les champs calcinés de Kalimdor, un terrible événement survint. Les détails en sont perdus, mais on sait que Neltharion, l'Aspect dragon de la Terre, devint fou durant une bataille vitale contre la Légion ardente. Il commença à se disloquer tandis que les flammes et la rage surgissaient de son côté obscur. Prenant le nom d'Aile de mort, le dragon brûlant se retourna contre ses frères et éloigna les cinq tribus de dragons du champ de bataille.", "La soudaine trahison d'Aile de mort fut si destructrice que les cinq tribus de dragons ne s'en remirent jamais complètement. Blessés et choqués, Alexstrasza et les autres dragons nobles durent abandonner leurs alliés mortels. Malfurion et ses compagnons, désormais surclassés en nombre, purent à peine survivre au massacre qui suivit.", "Malfurion, convaincu que le Puits d'éternité était le lien ombilical des démons avec le monde physique, insista pour le détruire. Ses compagnons, sachant que le Puits était la source de leur immortalité et de leurs pouvoirs, furent choqués par cette suggestion. Mais Tyrande, comprenant la sagesse des propositions de Malfurion, convainquit Cénarius et les dragons de prendre le temple d'Azshara d'assaut et de trouver un moyen pour fermer le Puits à jamais." } } },
    ["The War of the Shifting Sands"] = { { ids = { "i20415" }, first = "ithasbeennearlyathousand", pages = { "Près de mille ans se sont écoulés depuis la \"Guerre des sables changeants\". Pendant ce conflit, Fandral Staghelm a été frappé par une terrible tragédie, au cœur du désert de Silithus. Depuis, il porte un lourd fardeau. On suppose que le tempérament désagréable de l'archidruide vient en grande partie des événements décrits ici.", "À un moment donné, une ancienne race insectoïde, les Qiraji, tenta de s'emparer de presque tout Kalimdor. Il revint à Staghelm, l'impérialiste pompeux, et à son armée d'elfes de la nuit, de les affronter sur le champ de bataille.", "Père et fils se battirent vaillamment pour contenir les essaims à l'intérieur de Silithus. Un flot ininterrompu de silithides jaillissait de la forteresse d'Ahn'Qiraj pour renforcer les forces d'invasion des Qiraji. Tout Silithus était assiégé.", "Staghelm l'aîné le regretta par la suite, mais il donna l'ordre au jeune Staghelm, Valstann, de défendre l'avant-poste de Sudevent. Hélas, Valstann fut tué ce même jour, lorsque Sudevent succomba devant les armées d'Ahn'Qiraj.", "Le coeur lourd, la tête pleine de pensées de vengeance, Fandral Staghelm ne renonça pas. Une défaite en Silithus aurait représenté une perte tragique pour la nation des elfes de la nuit, et peut-être pour le monde entier.\n\nLa bataille se poursuivit pendant des mois. Les Qiraji conquirent tout Silithus. Staghelm et son armée furent repoussés jusqu'à Tanaris, et l'arrogance qui poussait Fandral Staghelm jusque-là disparut complètement.Ses troupes étaient décimées. D'innombrables innocents avaient trouvé la mort.", "Son orgueil anéanti, Staghelm ressentit, pour la seconde fois de son existence, ce frisson au centre de son être qui ne pouvait venir que de la peur. C'est en Tanaris qu'il décida d'approcher Anachronos, progéniture de Nozdormu, et de demander l'aide du Vol de bronze.", "Dans un premier temps, Anachronos refusa d'impliquer le Vol de bronze dans les affaires des races inférieures. Il fallut que les Qiraji osent attaquer les Grottes du temps pour qu'Anachronos accepte de s'allier aux elfes de la nuit.", "Anachronos ne tarda pas à réaliser que même le puissant Vol de bronze ne parvenait pas à empêcher la progression des armées des Qiraji. À chaque fois que son souffle anéantissait cinquante insectes, cent autres prenaient leur place. Les lignes des elfes de nuit se délitèrent. Confronté à la possibilité d'une retraite dans les étendues sauvages de Feralas, Anachronos décida d'avertir les enfants des Aspects.", "Il avertit d'abord le Vol draconique d'Ysera. Merithra du Rêve répondit à son appel. Ensuite, le Vol draconique d' Alexstrasza et le Vol draconique de Malygos furent informés.", "Les dragons se rencontrèrent dans la stratosphère, très loin au-dessus de Silithus et de la forteresse d'Ahn'Qiraj.\n\nEtaient présents Anachronos, enfant de Nozdormu, Aspect du Temps.\n\nDu Rêve d'Emeraude vint Merithra, enfant d'Ysera, Aspect de la Nature.\n\nCaelestrasz, enfant d' Alexstrasza, Aspect de la Vie, représentait le Vol draconique rouge.\n\nArygos, enfant de Malygos, Aspect de la Magie, représentait le Vol draconique bleu.", "Les dragons observèrent, et virent un flot incessant de silithides et de Qiraji jaillir d'Ahn'Qiraj. Il leur apparut vite que la force seule ne suffirait pas à mettre un terme à cette guerre. À l'intérieur du temple principal, des dizaines de milliers de soldats Qiraji attendaient, et d'autres naissaient sans cesse. Après une brève éducation, ils étaient prêts à être lâchés sur le monde.", "Arygos fut le premier à sentir les étranges émanations. Le temple monolithique situé au sud d'Ahn'Qiraj irradiait une magie faible, mais très différente de celle des Qiraji. En dépit de leurs efforts, aucun des dragons ne parvint à pénétrer plus avant dans le temple ou à découvrir la source de cette énergie. Seule une créature d'une puissance immense pouvait se dissimuler aussi bien. Peut-être… peut-être que quelque chose d'autre contrôlait les insectes, y compris les Qiraji.", "Les dragons comprirent qu'ils devaient réagir rapidement, sous peine de voir le monde souffrir d'une nouvelle et terrible catastrophe. Après avoir pesé leurs différents choix, ils décidèrent que la meilleure tactique sera d'arrêter l'armée ennemie près de sa source.", "Une immense barrière serait érigée en puisant à la fois dans l'essence des elfes de la nuit et dans celle des vols draconiques. Cette barrière magique retiendrait les silithides et leurs maîtres à l'intérieur des murs d'Ahn'Qiraj, évitant ainsi de futures incursions. Ahn'Qiraj deviendrait une prison." } } },
    ["The White Stag and the Moon"] = { { ids = { "o177208" }, first = "intothebraveheartsofherp", pages = { "La Terre-mère insuffla l'amour de la chasse à ses enfants innocents, au coeur vaillant. Car les créatures de la première aube étaient sauvages et farouches. Elles se cachaient de la Terre-mère, trouvant refuge dans les ombres et les lieux sauvages du monde. Les Shu'halo les chassaient partout où ils les trouvaient et les apprivoisaient avec la bénédiction de la Terre-mère.", "Un grand esprit leur échappait cependant. Apa'ro, que les elfes de la nuit appellent Malorne, était un fier cerf au pelage blanc comme neige. Ses bois frôlaient la voûte des cieux, et ses puissants sabots creusaient les profondeurs du monde. Les Shu'halo poursuivirent Apa'ro jusqu'aux confins du monde naissant et se rapprochèrent pour prendre le fier cerf au piège.", "Pour leur échapper, le grand cerf bondit dans le ciel. Mais alors qu'il se croyait sauvé, ses puissants bois s'emmêlèrent dans les étoiles, qui le retinrent prisonnier. Malgré ses ruades et ses efforts, Apa'ro ne pouvait se libérer des cieux. C'est alors que Mu'sha le découvrit, tandis qu'elle poursuivait son frère An'she vers l'aube. Elle vit le grand cerf se débattre et en tomba aussitôt amoureuse.", "L'astucieuse lune proposa un marché au grand cerf. Elle le libérerait du piège des étoiles s'il acceptait de l'aimer et de mettre fin à sa solitude.\nMu'sha aima Apa'ro et conçut un enfant de lui. L'enfant, un demi-dieu selon certains, naquit dans les forêts ombreuses de la nuit. Il porterait le nom de Cenarius et suivrait le chemin étoilé entre le monde éveillé et le royaume des cieux." } } },
    ["The World Tree and the Emerald Dream"] = { { ids = { "o175730" }, first = "formanyyearsthenightelve", pages = { "Pendant des années, les elfes de la nuit travaillèrent sans relâche à reconstruire leurs anciennes terres. Abandonnant à la poussée de la nature leurs temples détruits et leurs routes ruinées, ils construisirent de nouvelles demeures parmi les arbres verdoyants et les collines ombragées au pied du mont Hyjal. Les dragons qui avaient survécu à la Grande Fracture finirent par émerger de leurs tanières cachées.", "Alexstrasza la rouge, Ysera la verte et Nozdormu le dragon de bronze descendirent sur les terres druidiques et observèrent le fruit du travail des elfes de la nuit. Malfurion, qui était devenu un archi-druide aux pouvoirs immenses, accueillit les puissants dragons et leur parla de la création du nouveau Puits d'éternité.", "Les grands dragons furent alarmés par ces mauvaises nouvelles et en vinrent à penser que si le Puits restait actif, la Légion était susceptible de revenir un jour et de prendre à nouveau le monde d'assaut. Malfurion et les trois dragons firent un pacte pour assurer la protection du Puits et pour s'assurer qu'aucun agent de la Légion ardente ne pourrait jamais revenir dans le monde.", "Alexstrasza, la Donneuse de vie, planta un gland enchanté au coeur du Puits d'éternité. Le gland, nourri par les puissantes eaux magiques, se développa en un arbre gigantesque. Les racines de l'arbre émergèrent des eaux du Puits et son faîte verdoyant sembla atteindre la voûte des cieux.", "L'arbre immense devait devenir un symbole éternel de l'alliance des elfes de la nuit avec la nature, et ses énergies fécondes allaient se répandre pour guérir peu à peu le reste du monde. Les elfes de la nuit nommèrent leur Arbre monde Nordrassil, ce qui signifie \"couronne des cieux\" dans leur langue originale.", "Nozdormu, l'Eternel, enchanta l'Arbre monde pour s'assurer qu'aussi longtemps que l'arbre perdurerait les elfes de la nuit ne vieilliraient pas et ne seraient point victimes de la maladie.", "Ysera, la Rêveuse, enchanta l'Arbre monde à son tour pour le relier à son propre monde, une dimension éthérée connue sous le nom de Rêve d'émeraude. Le Rêve d'émeraude, un vaste monde spirituel sans cesse mouvant, existait hors des frontières du monde physique. Depuis le Rêve, Ysera régulait le flux et le reflux de la nature et l'évolution du monde lui-même.", "Les druides des elfes de la nuit, y compris Malfurion, furent reliés au Rêve à travers l'arbre-monde. Partie intégrante du pacte mystique, les druides acceptèrent de dormir pendant des siècles de façon à ce que leur esprit puisse explorer les chemins infinis du monde onirique d'Ysera. Les druides n'étaient pas enthousiastes à l'idée de perdre tant d'années de leur vie en hibernation, mais ils acceptèrent avec altruisme de remplir leur part du marché avec Ysera." } } },
    ["Thun'grim's Instructions"] = { { ids = { "i7587" }, first = "belowaretheitemsneededto", pages = { "$N, voici les objets nécessaires pour créer votre armure :\n\nLingots de fer cendré des kobolds de la mine des Cisailles des Serres-Rocheuses.\n\nAzurite en poudre des mineurs d'Hillsbrad dans Hillsbrad.\n\nBarres de fer auprès des mineurs ou des filons de fer si vous êtes un mineur.\n\nFiole de phlogiston, auprès d'un huran nommé Roogug au Kraal de Tranchebauge." } } },
    ["Thundris' Letter"] = { { ids = { "i279045" }, first = "mralexstonofstormwindimu", pages = { "M. Alexston de Hurlevent,\n\nJe dois vous féliciter pour tous vos efforts consacrés à la restauration de Hurlevent. Nombre de visiteurs de passage à Auberdine vantent sa grandeur et ses solides fondations. C'est cette réussite qui me pousse à vous écrire.\n\nAuberdine a trouvé sa place dans le monde au bord de la mer. Alors que notre cité était autrefois isolée, les vents qui balaient nos rivages sont désormais porteurs d'espoir.\n\n$gCe messager:Cette messagère; est l'une des âmes que les vents ont poussées dans ma direction. J'espère $gqu'il:qu'elle; se montrera aussi utile à votre peuple qu'elle l'a été pour le mien.\n\nEn retour, je vous saurais gré d'envoyer fournitures et main-d'œuvre à Auberdine, afin que nous puissions préparer la cité à affronter le courroux de ce monde qui nous a déjà tant pris.\n\n– Thundris Tissevent, ancien d'Auberdine" } } },
    ["Thurman's Letter"] = { { ids = { "i2837" }, first = "dearestyvetteiwillentrus", pages = { "Chère Yvette,\n\nJe vais confier cette lettre à notre plus rapide messager. Je prie qu'il trouve un passage à travers les troupes qui nous entourent. Et je prie pour que vous puissiez lire ces mots, qui sont les derniers que vous recevrez de moi.\n\nMon seul réconfort en ces jours sombres est mon soulagement à l'idée que vous ne partagerez pas mon destin.", "J'ai peur que mon père n'ait commis une grave erreur quand il a décidé de rester pour défendre notre foyer. Les forces du Fléau ravagent les clairières de Tirisfal, et bien que les fortifications et les stocks soient sûrs, la traîtrise de mon frère Devlin nous prive de la force et des troupes nécessaires pour repousser leurs assauts constants.\n\nSi vous recevez cette lettre, Yvette, sachez bien que Devlin est un traître.", "Devlin a connu le désespoir et a fui notre infortune, et par là même il a fait un pacte avec le Fléau. Je ne sais pas quelle récompense il a reçue pour prix de sa lâcheté, mais je suis sûr que tout n'était que mensonges.\n\nSi vous voyez mon frère, fuyez-le. C'est une vile créature. Il y a de cela quelques nuits, il a assassiné deux de nos veilleurs et laissé quelques membres du Fléau franchir la brèche, là où nombre d'entre nous dormaient.", "L'attaque a été brutale. Ils ont tué le tiers d'entre nous avant que nous ne puissions les abattre. Il nous reste à peine assez d'hommes pour surveiller nos frontières. Ce n'est qu'une question de temps avant que notre surveillance ne se relâche et que le Fléau n'attaque.\n\nEt bien que j'aie repéré le visage de Devlin parmi les désespérés du Fléau cette nuit-là, il s'est éclipsé avant que je ne puisse l'atteindre. Il est peut-être mort, ou peut-être est-il un agent bien vivant du Fléau.\n\nDans les deux cas, il est un monstre.", "Devlin nous a avertis que si nous tentions de nous opposer au Fléau, nous étions perdus. Il nous l'a dit quand ils sont entrés pour la première fois dans les clairières de Tirisfal, avant l'encerclement de notre foyer. Il nous implorait peut-être de partir, ou peut-être se vantait-il.\n\nIl est difficile de comprendre les motivations de Devlin. Depuis son enfance, il est un mystère pour nous tous.", "Mais il avait raison. Nous sommes perdus. La lignée de la famille Agamand va s'éteindre. Je suis toujours en vie, mais je sais que je n'en ai plus pour longtemps.\n\nJe n'ai pas peur et je ne regrette pas d'être resté avec ma famille. Mais mes dernières pensées vont vers vous.\n\nVivez, ma bien-aimée Yvette, et je trouverai la paix,\n-Thurman" } } },
    ["Tinkee's Letter"] = { { ids = { "i12438" }, first = "hifelnokmystudiesinthebu", pages = { "Salut Felnok !\n\nMes études dans les Steppes Ardentes se déroulent à merveille. Et je suis redevable à $N pour son aide ! Voici ce dont j'ai besoin pour continuer :\n\nUn bitzel en acier\nUn glaceur à 17 jauges\n12 livres de plumes de canard\nUn pot de la colle que vous fabriquez\n\nMerci beaucoup Felnok, et quand on se reverra, rappelez-moi une nouvelle fois de ne pas mettre de la colle dans vos bottes !\n\n-Tinkee" } } },
    ["Toothgnasher's Skeleton"] = { { ids = { "o175683" }, first = "thisisascalereplicaoftoo", pages = { "Voici une réplique à l'échelle du squelette de Grincedents. Le bélier légendaire était une des merveilles de Khaz Modan et peuple de sa présence le folklore des nains. À ce jour, les écologistes ont été incapables d'expliquer la taille et l'énergie impressionnantes de l'animal." } } },
    ["Torn Letter"] = { { ids = { "i216956" }, first = "duetoyourcovensstaggerin", pages = { "En raison de l'incompétence de votre groupe, ce ne sont pas un, mais deux intrus qui ont pu pénétrer vos défenses, infliger de lourdes pertes et voler ce qui nous appartenait. Je me chargerai de la Croisade écarlate, mais j'ai besoin que vos membres pathétiques retrouvent le paladin et la personne qui l'accompagnait pour récupérer…\n\n<La lettre est déchirée, il manque le reste.>" } } },
    ["Torn Note"] = { { ids = { "i4102" }, first = "imissmytribeandmyhomeiwo", pages = { "Ma tribu et mon foyer me manquent. J'accueillerais avec joie les plaines ouvertes ou le crépuscule sur Thunder Bluff au milieu de la chaleur de cette jungle.\n\nJ'aperçois l'océan non loin, mais il ne rafraîchit ni mon corps ni mon humeur. Il ne fait que me rappeler mon emprisonnement." } } },
    ["Torn Page"] = { { ids = { "i281347" }, first = "thecalmcomesbeforethesto", pages = { "Le calme avant la tempête." } } },
    ["Translated Letter"] = { { ids = { "i1656" }, first = "greetingselloebonlockema", pages = { "Salutations, Ello Ebonlocke, maire de Darkshire. Je crains d'avoir de mauvaises nouvelles pour votre ville.\n\nVoyez-vous, je suis un créateur. J'ai trompé le porteur de ce message pour qu'il m'aide à réaliser ma dernière et plus audacieuse création : une créature mêlée de chair et de métal impie ! Au moment où vous lisez ces lignes, elle est probablement à l'extérieur de mon humble demeure, aiguisant ses dents et attendant que je lui donne l'ordre de commencer le massacre.\n\nMais vous verrez cela rapidement par vous-même.\n\n-L'Embaumeur" } } },
    ["Translated Letter from The Embalmer"] = { { ids = { "i3248" }, first = "greetingselloebonlockema", pages = { "Salutations, Ello Ebonlocke, maire de Darkshire. J'ai peur d'avoir de mauvaises nouvelles pour votre ville.\n\nVoyez-vous, je suis un créateur. J'ai trompé le porteur de ce message pour qu'il m'aide à réaliser ma dernière et plus audacieuse création : une créature mêlée de chair et de métal impie ! Au moment où vous lisez ces lignes, elle est probablement à l'extérieur de mon humble demeure, aiguisant ses dents et attendant que je lui donne l'ordre de commencer le massacre.\n\nMais vous verrez cela rapidement par vous-même.\n\n-L'Embaumeur" } } },
    ["Trevan's Weapon Notes"] = { { ids = { "i267454" }, first = "oldfireeyeisamagicalcrea", pages = { "$N,\nOld Fire-Eye is a magical creature of the night, and as such, we require a magical weapon that is also of the night. We can infuse such a weapon with the light of the full moon and use it to turn the dark magic that drives this creature against itself. For this, we need a specific set of materials to craft a blade of brilliant moonsilver, capable of destroying this evil utterly.\n\nThis won't be easy, but you've shown great promise so I trust that you'll be able to get what we need.", "Enchanted Moonsilver - This is the key ingredient to our creation. Moonsilver is an incredibly rare material, made from enchanted silver infused with the raw power of the moon. A number of weapons were forged to fight off the worgen once the curse began to take hold in Silverpine. Unfortunately they are all lost now and the location of the last remaining moonsilver ingots is unknown.\n\nThere is a rumor that there was a cache of such material in Shadowfang Keep to the south. It's a longshot, but it's our best bet for now to find some of this moonsilver.", "Un peu de bon bois de chêne de blanchepierre – Il existe un endroit dans la marche de l'Ouest connu sous le nom de Ruisselune, qui contenait autrefois ce bois en abondance, les artisans de l'Alliance l'ont utilisé pour reconstruire Hurlevent après la Deuxième guerre.\n\nRuisselune n'est plus ce qu'elle était, mais j'ai entendu dire qu'une organisation de malfrats a eu recours à des sculpteurs gobelins pour entreprendre une construction dans les mines sous la ville. Je parierais ma botte gauche que les Gobelins en ont profité pour mettre la main sur les dernières réserves de ce bois rare.", "Une gemme de Kor – D'après les contes que j'ai entendus, les gemmes sont utilisées par des lanceurs de sorts pour contenir l'énergie dont leur magie a besoin, ce qui la rend plus mortelle encore. Je crois que les énergies de l'une des gemmes peut servir à la création de votre arme.\n\nJ'ai connu un mage appelé Ulric Voile-de-givre, qui pourra vous en dire plus à leur sujet. Aux dernières nouvelles, il était en Kalimdor, à l'avant-poste de Zoram'gar, du côté ouest d'Orneval." } } },
    ["Uldaman Relics"] = { { ids = { "o175687" }, first = "theseancientpiecesofeart", pages = { "Ces anciennes poteries ont été retrouvées au cours des fouilles d'Uldaman. Elles ne portent guère de runes ou de hiéroglyphes, mais elles renseignent sur l'habileté des artisans et les accessoires quotidiens des nains d'autrefois." } } },
    ["Uldaman Reliefs"] = { { ids = { "o175689" }, first = "theseetchedreliefrunners", pages = { "Ces bas-reliefs sont la découverte la plus significative des premières chambres d'Uldaman. Les gravures suggèrent clairement un lien entre le peuple nain et les terrestres, qui sont des créatures évoquant des golems. Si d'autres preuves se présentent, les théories sur notre prétendue création par les Titans mythiques pourraient s'avérer exactes !" } } },
    ["Ur's Treatise on Shadow Magic"] = { { ids = { "i7266" }, first = "theswirlingsymbolsandpic", pages = { "Les symboles et pictogrammes qui remplissent les pages de ce manuel sont parfaitement incompréhensibles." } } },
    ["Urgent Message"] = { { ids = { "i11886" }, first = "urgentmessagetocliffwatc", pages = { "Message urgent au garde-falaise Longhorn\n\nUne imposante force de centaures venu du camp E'thok a attaqué une de nos caravanes de ravitaillement. Tous les membres de la caravane sont perdus et les vivres également. Cette attaque audacieuse et sans précédent laisse craindre que d'autres surviennent dans le futur." } } },
    ["Uther the Lightbringer"] = { { ids = { "o2082" }, first = "hereliesutherthelightbri", pages = { "Ici repose Uther le Porteur de Lumière\nPremier des paladins - Fondateur de l'Ordre de la Main d'argent\n\nUther a vécu et est mort pour défendre le royaume de Lordaeron. Bien qu'il ait été trahi par son apprenti préféré, nous pensons que son esprit demeure. Il continue à veiller sur nous, même aujourd'hui que les ombres se referment sur nos terres. Sa lumière est celle de toute l'humanité, et tant que nous honorerons son exemple, il ne périra jamais.\n\n- Anonyme" } } },
    ["Valea Twinblades"] = { { ids = { "o175780" }, first = "valeatwinbladeswarriorof", pages = { "Valea Twinblades\nGuerrier de la Croisade écarlate\nCitoyen d'Alterac\nPorté disparu dans les Maleterres de l'est" } } },
    ["Valory Family Crest"] = { { ids = { "i281328" }, first = "memoriesofvalorarecounto", pages = { "Souvenirs des Valor\nUne chronique de la famille Valor et des services qu'elle a rendus à Colline-aux-Corbeaux\n\nAucune famille des royaumes de l'Est n'est plus remarquable que la famille Valor. Les exploits accomplis par ses membres au service de la population qu'ils avaient juré de protéger tiennent du miracle, et leur disparition est un drame pour tout Colline-aux-Corbeaux.\n\nJ'écris cette chronique pour rétablir la vérité, et montrer que Grant, Ira, Silvia et Merrick étaient des êtres d'exception. Que ces mots soient source de réconfort, car leur absence me peine profondément.", "Merrick Valor, Watcher of Darkshire\n\nMerrick was the youngest son of the Valor family. As he witnessed the corruption coming to his homeland, he chose to join The Watch in a desperate bid to protect his loved ones.\n\nWhile he was the most inexperienced member of his family, he quickly made a name for himself amongst the ranks of The Watchers. He had a knack for archery, and soon became one of the most staunch defenders of Darkshire.\n\nHis personal mission was to keep the roads safe, wary of the ever more hostile creatures coming to the forests.", "Silvia Valor, garde de Colline-aux-Corbeaux\n\nSilvia Valor était déjà une héroïne locale lorsqu'elle fut invitée à rejoindre les rangs de la Garde. S'il y avait bien une chose au monde qu'elle ne pouvait tolérer, c'était les opportunistes qui profitaient du malheur des gens.\n\nBandits, escrocs, fauteurs de troubles, tous connaissaient le même sort. Silvia passait au fil de l'épée quiconque tentait de semer le chaos dans sa contrée chérie. Il n'y avait donc rien d'étonnant qu'elle accède à un poste qui allait lui conférer l'autorité nécessaire pour appliquer son idéal de justice.\n\nÀ croire les récits, ce ne serait qu'en rendant son dernier soupir qu'elle aurait abandonné les fermes et foyers du bois de la Pénombre. Et cela reste encore à prouver.", "Ira Valor, Forest Stalker\n\nWhen Ira's father grew ill, she took it upon herself to gather food and supplies from the nearby forests. While resources were not in short supply, you were as likely to find food as you were to become it.\n\nOver the years, she adapted to the forests, preferring to spend her time within the dark woods rather than in Raven Hill. Travelers who got lost in the trees would tell stories of a shadow seemingly opening the way for them back to the road. There was no confirmations of who it was, but rumors spread quickly.\n\nIt's said that Ira is still in the woods offering a guiding hand to those who fall prey to the beasts within.", "Seigneur Grant Valor, patriarche de la famille Valor\n\nLe seigneur Grant, paix à son âme, était le summum de l'exceptionnalisme de l'Alliance. Un meneur né, ses choix avisés ont contribué à mener la population de Colline-aux-Corbeaux vers la prospérité. Lorsque les ténèbres ont commencé à envahir les bois, il fut le premier à rallier notre peuple.\n\nPour le seigneur Grant, aucun adversaire n'était plus abject que les morts-vivants. Il patrouillait en personne dans les cimetières du bois de la Pénombre pour contenir les hordes chancelantes. Le jour où les monstres lui infligèrent une grave blessure, toute la ville partagea sa souffrance.\n\nGrâce au dévouement de sa famille, il put reprendre ses fonctions, mais un mal tenace sembla l'affecter jusqu'à la fin de ses jours.", "Dame Cassandra Valor, épouse et mère aimante\n\nOn sait peu de choses au sujet de Cassandra, si ce n'est qu'elle aimait sa famille. Elle prit grand soin de braves enfants et d'un mari puissant, en amenant certains à s'imaginer qu'elle était la source de la grandeur de sa famille. Des louanges qu'elle démentait toujours avec grâce.\n\nSi elle ne doit rester dans les mémoires que pour une unique raison, n'oublions jamais qu'elle a toujours œuvré pour le bien de sa famille." } } },
    ["Velinde's Journal"] = { { ids = { "i5520" }, first = "elunehasgrantedmywishest", pages = { "Elune a exaucé mes voeux. Le sacrifice de mes camarades décédés n'aura pas été vain, et je vengerai leur mort en utilisant la Faux d'Elune. C'est un objet ancien, une branche de bois tordu qui pourrait bien être plus ancienne encore que les Kaldorei.\n\nJ'ai examiné cet outil offert par la déesse durant des heures. Ce n'est pas une arme ordinaire, cela est sûr, ni un simple instrument magique. Avec lui, c'est comme si les barrières du temps et de l'espace s'effaçaient.\n\nLa Faux en main,", "j'ai reçu une vision du chaos. Des hommes-loups... les worgens... en lutte contre une incroyable armée. Les worgens se battaient sauvagement, comme il convient à leur race primitive, mais l'ennemi ne cédait pas : c'étaient les seigneurs de la Flamme d'émeraude.\n\nEt c'est là que j'ai compris le vrai pouvoir de la Faux. En me concentrant sur lui, je suis devenu capable de communiquer avec les worgens. Je n'ai pas utilisé de mots pour cela, c'était quelque chose de différent... Je suis incapable de l'expliquer.\n\nL'important, c'est que les worgens m'ont entendu", "et m'ont compris. En canalisant la puissance de la Faux, j'ai pu altérer davantage encore les barrières et j'ai pu conduire les worgens dans notre monde. Belle réussite pour un premier essai. Ils m'ont suivi au combat, et fort de leur brutale puissance, nous nous sommes attaqués aux démons de Gangrebois.\n\nElune a répondu à mes prières. La forêt sera purifiée.\n\nQue les grâces d'Elune me comblent jusqu'à ce que ma tâche soit accomplie.", "Tout va bien. J'ai invoqué de grandes bandes de worgens pour combattre à mes côtés. Ils ne sont pas intelligents, mais ils ont une capacité remarquable à coordonner leurs attaques et à agir en groupe.\n\nJ'ai identifié des chefs dans leurs meutes. Je leur ai donné le commandement de petits groupes de combattants. Nous frappons au même instant à plusieurs endroits de la forêt et ma campagne contre les démons porte ses fruits.\n\nQue les grâces d'Elune me comblent jusqu'à ce que ma tâche soit accomplie.", "J'ai perdu une meute. J'ai envoyé les worgens dans la forêt pour y reconnaître les zones d'infestation démoniaque, mais ils ne sont pas revenus. Je commence à m'inquiéter au sujet des chefs à qui j'ai confié le commandement. Ils sont peu intelligents et pas nécessairement à la hauteur du peu de responsabilité que je leur ai confiée. Suis-je en train de perdre le contrôle ? Peut-être que je dois cesser d'invoquer plus de worgens pour l'heure.\n\nQue les grâces d'Elune me comblent jusqu'à ce que ma tâche soit accomplie.", "Bien que je n'aie pas invoqué de worgens supplémentaires, leur nombre ne cesse de croître. C'est comme si la Faux n'avait plus besoin de mon intervention pour poursuivre le processus d'invocation. C'est troublant. J'ai rassemblé autant de meutes que j'ai pu en trouver, et je leur ai donné l'ordre de demeurer à l'Autel de Mel'Thandris.\n\nEn attendant, j'ai fouillé dans les bibliothèques de Darnassus et consulté le Cercle des Anciens à Sombrivage. Pas la moindre information sur les worgens. J'ai entendu des rumeurs concernant", "un sorcier du Kirin Tor nommé Arugal. Apparemment, il aurait lui aussi invoqué des worgens. Je vais consulter ce sorcier, aussi déplaisant que cela soit, pour tâcher de découvrir ce qu'il sait.\n\nLes worgens sont dangereux et je dois reprendre le contrôle. A l'aube, je partirai pour le port des Tarides et me rendrai au Nouveau Monde.\n\nQue les grâces d'Elune me comblent jusqu'à ce que ma tâche soit accomplie." } } },
    ["Venture Co. Documents"] = { { ids = { "i4834" }, first = "supervisorfizsprocketple", pages = { "Superviseur Fizsprocket, vous trouverez ci-joint la liste du matériel que vous avez demandé, approuvée par le président Razdunk.\n\nIl m'a demandé de vous rappeler, en insistant sur ce point, l'intérêt que porte la KapitalRisk à l'implantation de ses activités dans tout Kalimdor. Nos postes de forage et nos mines dans les Tarides se sont révélés rentables et efficaces, mais nous attendons toujours des chiffres de production suffisants pour Mulgore, le territoire dont vous avez la charge.\n\nLe conseil d'administration comprend les difficultés que représente l'établissement", "d'une exploitation à grande échelle si près des terres taurènes, mais ne considère pas qu'elles constituent un obstacle majeur à notre stratégie commerciale dans la région.\n\nNous sommes heureux d'apprendre que l'exploitation minière a commencé dans les plaines de Mulgore, riches en minerais. Le conseil a donc approuvé votre demande de matériel. Outre les minerais, nous pensons que Mulgore a aussi beaucoup à offrir en matière de bois. Vous recevrez donc plusieurs déchiqueteurs de notre dernier modèle, ainsi que les matières premières nécessaires à la construction d'une", "scierie." } } },
    ["Verdant Note"] = { { ids = { "i9581" }, first = "thespiritscametomeinmydr", pages = { "Les esprits me sont apparus en rêve la nuit dernière. Ils m'ont annoncé votre visite et m'ont expliqué que ma tâche serait de vous aider. Nous aurons beaucoup à faire pendant le temps trop court que nous passerons ensemble : parler de la nature, des esprits, de la Terre-mère, des elfes de la nuit... Mais je vous enseignerai ces leçons à votre venue, et je ferai tout ce qui sera en mon pouvoir pour vous préparer aux épreuves à venir.\n\nQue la sagesse vous guide. J'attendrai.\n\n-Gart Mistrunner, Maître des druides" } } },
    ["Verdant Sigil"] = { { ids = { "i9580" }, first = "whenwordreachedmethatyou", pages = { "Lorsque j'ai entendu dire que l'heure pour vous était venue, j'ai immédiatement envoyé ce message. Tous les druides de Cénarius ont plaisir à voir grandir notre nombre. Les esprits semblent même avoir gagné en puissance à votre arrivée. En temps voulu, avec de la patience, nous retrouverons notre grandeur passée. Vous me trouverez au sommet d'Aldrassil quand vous le voudrez. Je serai votre guide tant que vous serez à Sombrevallon.\n\n- Mardant Strongoak, Maître des druides" } } },
    ["Verna's Westfall Stew Recipe"] = { { ids = { "i2832" }, first = "westfallstewpartsstringy", pages = { "Ragoût de la marche de l'Ouest\n\n3 morceaux de viande filandreuse de vautour\n3 groins de Broche-tripes\n3 yeux de murlocs\n3 okras\n\nMélangez et faites bouillir. Faites cuire à feu doux pendant au moins deux heures avant de servir." } } },
    ["Verner's Note"] = { { ids = { "i1283" }, first = "argusasyouknowimuptomyne", pages = { "Argus,\n\ncomme vous savez, je suis jusqu'au cou dans des demandes de réparation de l'armée. Je ne me plains pas du travail, mais il vide mes réserves de fer.\n\nJe n'en ai plus assez pour forger des fers à cheval. Je sais que vous en avez toujours un large stock. Je souhaiterais vous emprunter 50 paires de fers à cheval jusqu'à ce qu'arrive ma prochaine cargaison de fer.\n\nAvec toute ma gratitude,\n-Verner" } } },
    ["Wanted Notice"] = { { ids = { "i221314" }, first = "knowntrespasserspyinterr", pages = { "<Un portrait de nain grossier occupe l'essentiel de la feuille. Quelques lignes ont été inscrites en dessous.>\n\nIntrus connu ! Espion ! Il interroge NOS citoyens !\n\nLes tandems en visite à la ville des Ombreforges rapportent de courtes interactions avec un Nain à l'accent étrange, qui répéterait « Ce ne sont pas les deux qu'il nous faut. »\n\nSignalez tous renseignements aux officiers ragenclume !\n\nAttention, aucun groupe nombreux n'a rencontré cet importun.\nRestez sur vos gardes !" } } },
    ["War of the Spider"] = { { ids = { "o175753" }, first = "whilethrallwasliberating", pages = { "Pendant que Thrall libérait ses frères à Lordaeron, Ner'zhul continuait d'accroître sa puissance dans Northrend. Une vaste citadelle fut érigée au-dessus de la Couronne de glace, remplie de légions grandissantes de morts-vivants. Cependant, tandis que le roi-liche faisait croître son influence sur le pays, un empire oublié se dressa contre lui.", "L'antique royaume souterrain d'Azjol-Nerub, fondé par une race de sinistres araignées à forme humaine, envoya ses guerriers d'élite contre la Couronne de glace et mit un frein à la faim inextinguible de puissance du roi-liche. À sa grande frustration, Ner'zhul découvrit que les nérubiens étaient non seulement immunisés contre sa peste, mais aussi contre ses pouvoirs télépathiques.", "Les seigneurs-araignées nérubiens dirigeaient de vastes forces et disposaient d'un réseau souterrain qui s'étendait sous presque la moitié de Northrend. Leur tactique de harcèlement par raids contre les bastions du roi-liche l'empêchait de se débarrasser d'eux. Finalement, Ner'zhul gagna sa guerre contre les nérubiens par usure. Avec l'aide des seigneurs de l'effroi, déchaînés, et de l'armée innombrable de ses guerriers morts-vivants, le roi-liche envahit Azjol-Nerub et fit s'écrouler les temples souterrains des seigneurs-araignées sur leurs têtes.", "Bien que les nérubiens fussent immunisés contre la peste, les pouvoirs nécromanciens grandissants de Ner'zhul lui permirent de relever le cadavre des guerriers nérubiens morts et de les soumettre à sa volonté. En témoignage de leur ténacité et de leur courage, Ner'zhul adopta le style architectural particulier de ces êtres-araignées pour ses propres bâtiments.", "Libre de diriger son royaume sans opposition, le roi-liche commença à se préparer pour sa vraie mission dans le monde. Lançant sa vaste conscience des éléments à l'assaut des terres humaines, le roi appela toutes les âmes sombres susceptibles de l'écouter...." } } },
    ["War of the Three Hammers"] = { { ids = { "o175739" }, first = "thedwarvesofironforgemou", pages = { "Les nains d'Ironforge vivaient en paix depuis de longs siècles mais leur société devint trop vaste pour leurs cités montagnardes. Le puissant haut-roi Modimus Anvilmar régnait sur tous les nains avec justice et sagesse, mais trois puissantes factions s'étaient déclarées dans leur société.", "Le clan Bronzebeard, dirigé par le thane Madoran Bronzebeard, avait des liens solides avec le haut-roi et ses membres se considéraient comme les défenseurs traditionnels d'Ironforge. Le clan Wildhammer, dirigé par Khardros Wildhammer, habitait les collines et les rochers escarpés autour de la montagne et cherchait à prendre le contrôle de la ville.", "La troisième faction, le clan Sombrefer, était dirigé par le sorcier Thaurissan. Les Sombrefer se cachaient dans les plus obscures profondeurs de la montagne et complotaient contre leurs cousins Bronzebeard et Wildhammer.", "Pendant quelque temps, les trois factions maintinrent une paix fragile, mais des tensions éclatèrent lorsque le haut-roi Anvilmar mourut de vieillesse. Les trois principaux clans entrèrent en conflit pour le contrôle d'Ironforge. La guerre civile des nains fit rage durant des années sous la terre. Finalement, le clan Bronzebeard, qui disposait de la plus grosse armée, bannit les Sombrefer et les Wildhammer des profondeurs de la montagne.", "Khardros et ses guerriers Wildhammer partirent vers le nord à travers les barrières de Dun Algaz, et fondèrent leur propre royaume sur le lointain pic de Grim Batol. Là, les Wildhammer rebâtirent leurs réserves de trésors. Thaurissan et les Sombrefer ne réussirent pas aussi bien. Humiliés et rendus furieux par leur défaite, ils jurèrent de se venger d'Ironforge. Menant son peuple vers le sud, Thaurissan fonda une ville (à laquelle il donna son nom) dans les magnifiques montagnes Carmines.", "Ni le temps ni la prospérité ne purent calmer la rancoeur des Sombrefer envers leurs cousins. Thaurissan et sa sorcière de femme, Modgud, lancèrent une attaque sur deux fronts contre Ironforge et Grim Batol. Les Sombrefer avaient l'intention de s'emparer de Khaz Modan.", "Les armées des Sombrefer se lancèrent à l'assaut des forteresses de leurs cousins et furent près de prendre les deux royaumes. Mais Madoran Bronzebeard offrit à son clan une victoire décisive sur l'armée de Thaurissan. Thaurissan et ses serviteurs regagnèrent la sûreté de leur cité, tandis qu'à Grim Batol, l'armée de Modgud ne connaissait pas un meilleur sort contre Khardros et ses guerriers Wildhammer.", "En affrontant les guerriers ennemis, Modgud utilisa ses pouvoirs pour frapper leur coeur de terreur. Les ombres s'ébranlaient à son commandement et de sombres créatures rampaient depuis les profondeurs de la terre pour traquer les Wildhammer dans leurs propres murs. Finalement, Modgud franchit les portes et mit le siège devant la forteresse elle-même. Les Wildhammer combattirent désespérément, et Khardros se joignit aux combattants pour tuer la reine sorcière.", "Leur reine morte, les Sombrefer fuirent devant la fureur des Wildhammer. Ils se précipitèrent au sud, vers la forteresse de leur roi, mais tombèrent sur les armées d'Ironforge, qui se portaient au secours de Grim Batol. Ecrasées dans l'étau des deux armées, les dernières forces des Sombrefer furent anéanties.", "Les armées combinées d'Ironforge et de Grim Batol se tournèrent vers le sud, décidées à détruire Thaurissan et ses Sombrefer une fois pour toutes. Ils avaient à peine eu le temps de se mettre en route quand dans sa colère Thaurissan lança un sort digne d'un cataclysme. Cherchant à invoquer un serviteur surnaturel qui lui donnerait la victoire, Thaurissan réveilla les anciennes puissances qui sommeillaient dans les profondeurs du monde. La créature qui apparut était plus terrible que le pire cauchemar du renégat.", "Ragnaros le seigneur des flammes, maître immortel des élémentaires du feu, avait été banni par les Titans à l'aube du monde. Libéré par l'appel de Thaurissan, Ragnaros réapparut à la surface du globe. Sa renaissance apocalyptique dans Azeroth fissura les montagnes Carmines et fit surgir un volcan ardent au centre de la région dévastée.", "Le volcan, connu sous le nom de mont Blackrock, était flanqué par la gorge des Vents brûlants au nord et par les Steppes ardentes au sud. Thaurissan fut tué par les forces qu'il avait déchaînées et ses frères survivants furent réduits en esclavage par Ragnaros et ses élémentaires. Ils résident désormais dans les profondeurs de Blackrock.", "Observant le désastre horrible et les incendies qui se répandaient dans les montagnes du sud, le roi Madoran et le roi Khardros arrêtèrent leurs armées et revinrent vers leurs royaumes respectifs. Ils ne voulaient pas affronter la colère de Ragnaros.", "Les Bronzebeard revinrent à Ironforge et rebâtirent leur glorieuse cité. Les Wildhammer s'en retournèrent vers Grim Batol. Cependant, la mort de Modgud avait laissé une souillure maléfique dans la forteresse de la montagne et les Wildhammer découvrirent qu'ils ne pouvaient plus l'habiter.", "Leurs coeurs étaient amers d'avoir perdu leur foyer. Le roi Bronzebeard offrit aux Wildhammer un endroit où vivre à l'intérieur les frontières d'Ironforge, mais les Wildhammer refusèrent fermement. Khardros mena son peuple vers le nord, en direction de Lordaeron. Ils s'installèrent dans les forêts luxuriantes des Hinterlands, et bâtirent la ville de Nid-de-l'Aigle, où les Wildhammer se rapprochèrent de la nature et établirent des liens avec les puissants gryphons de la région.", "Cherchant à conserver des relations et à commercer avec leurs cousins, les nains d'Ironforge construisirent un pont à deux grandes arches, le Thandol, pour relier Khaz Modan et Lordaeron. Enrichis par le commerce mutuel, les deux royaumes prospérèrent. Après la mort de Madoran et de Khardros, leurs fils commandèrent de concert deux grandes statues en l'honneur de leurs pères.", "Les deux statues montaient la garde sur la passe menant au sud, qui était devenu une terre volcanique à l'éveil de Ragnaros. Elles servaient d'avertissement à quiconque voudrait attaquer les royaumes des nains et rappelaient le prix que les Sombrefer avaient payé pour leurs crimes.", "Les deux royaumes restèrent proches pendant des années, mais les Wildhammer avaient beaucoup changé devant les horreurs survenues à Grim Batol. Ils choisirent de vivre à la surface, au Nid-de-l'Aigle, au lieu de se creuser un vaste royaume dans la montagne. Les différences de moeurs entre les deux derniers clans des nains finirent par les séparer." } } },
    ["Warchief's Orders"] = { { ids = { "i8463" }, first = "commanderreturntoorgrimm", pages = { "Commandant,\n\nRetournez à Orgrimmar. Vos forces ne conviennent pas. Vous devez réévaluer notre position en fonction des nouvelles informations.\n\nNombre de liges d'ombre et d'ogres sont présents. Des démons gardent la Porte des ténèbres.\n\n-Thrall, Chef de guerre de la Horde" } } },
    ["Warosh's Scroll"] = { { ids = { "i12730" }, first = "ohiamcursedonceagreatogr", pages = { "Oh, je suis maudit ! J'étais autrefois un grand mage ogre du clan Pierre-du-pic. J'ai défié Urok Hurleruine et il m'a volé ma magie avant de me maudire. Maintenant j'arpente les couloirs de Hordemar sous cette pauvre défroque !\n\nAidez-moi ! Affrontez Urok et reprenez-lui ma magie ! Ce ne sera pas facile, car Urok reste dans les ombres et ne peut être invoqué que par un grand défi.\n\nCe défi marquera la fin de son allié le plus précieux, le généralissime Omokk.\n\nLisez, vous allez voir.", "Le généralissime Omokk règne sur les Pierres-du-pic, mais seulement grâce à la magie d'Urok. Urok a charmé Omokk avec un sort qui fait tomber raide mort tout ogre qui le défie. Il a utilisé ce sort bien souvent et garde les crânes de ses ennemis en tas, au-dessus de la chambre d'Omokk.\n\nC'est là que vous devez aller pour affronter Urok.", "Trouvez une pique de fortune dans le camp du Bouclier balafré. Les légionnaires les entassent généralement près des nattes, à côté de l'entrée du domaine des ogres Pierres-du-pic.\n\nQuand vous aurez la pique, foncez vers le généralissime Omokk. Tuez-le, placez la tête sur la pique.\n\nVous serez alors prêt pour le vrai défi.", "Rendez-vous au lieu de pouvoir au-dessus du domaine des Pierres-du-pic, par-delà les tunnels de Toile-grouillante. Là sont empilés les crânes des ennemis et rivaux d'Urok. C'est là que vous devez apporter la pique portant la tête d'Omokk !\n\nLorsque la tête sera en place, Urok viendra à coup sûr... Mais d'abord il enverra ses serviteurs contre vous. Battez-les et Urok lui-même finira par être invoqué.\n\nTuez Urok et récupérez ma magie. Quand j'aurai de nouveau mes pouvoirs, je vous récompenserai.", "Bonne chance à vous. Voici un indice qui pourra vous aider dans vos combats contre les serviteurs d'Urok :\n\nLe sort qu'utilise Omokk contre les ogres, celui qui les tue immédiatement, pourrait avoir toujours du pouvoir après la mort d'Omokk. Pendant votre combat contre les serviteurs d'Urok, invoquez la puissance de la tête d'Omokk. Avec un peu de chance, Omokk abattra les serviteurs d'Urok !\n\nQuelle ironie..." } } },
    ["White Punch Card"] = { { ids = { "i9279" }, first = "supercriticaltripleencod", pages = { "CARTE DE DONNEES SUPER CRITIQUES A TRIPLE CODE\n\n01010100 01101000 01110010 01100001 01101100 01101100 00100000 01100101 01110100 00100000 01001010 01100001 01101001 01101110 01100001 00100000 01110011 01100101 00100000 01110011 01101111 01101110 01110100 00100000 01100110 01100001 01101001 01110100 00100000 01100100 01100101 01110011 00100000 01000010 00101101 01001001 00101101 01010011 00101101 01001111 00101101 01010101 00101101 01010011 00100000 01100101 01101110 00100000 01100011 01100001 01100011 01101000 01100101 01110100 01110100 01100101" } } },
    ["Wiley's Note"] = { { ids = { "i1327" }, first = "stoutmantlesomenervesend", pages = { "Stoutmantle --\n\nQuel culot d'envoyer un étranger discuter de la bande des Défias. Vous m'avez naguère sauvé la vie, mais maintenant vous la mettez en grand péril.\n\nJe reste néanmoins votre débiteur. La Confrérie Défias est plus dangereuse que vous ne le pensez. De la marche de l'Ouest à la forêt d'Elwynn, toutes les mines sont sous leur contrôle. Des kobolds et des gnolls ont été engagés pour faire leur sale travail. Des gobelins construisent pour eux des monstres de métal pour que les habitants de la marche de l'Ouest deviennent la proie des pires superstitions.", "Ils ont construit un vaste réseau souterrain. Plus grand que vous ne le pourriez imaginer, Stoutmantle. De Baie-du-Butin jusqu'au donjon de Stormwind. Vous êtes sans nul doute un courageux paladin mais vous vous leurrez si vous pensez que vous pouvez les abattre. Ils travaillent sur une arme de destruction massive. Après tout, s'il y a quelque chose que savent faire les maçons, c'est construire des choses énormes. C'est bien autre chose que quelques saltimbanques batifolant dans les champs ! Je vous ai payé ma dette. Laissez-moi maintenant !\n\n--W" } } },
    ["William's Shipment"] = { { ids = { "i957" }, first = "hellomorganbusinessingol", pages = { "Bonjour Morgan,\n\nLes affaires sont florissantes à Goldshire, au point que je n'ai pas eu le temps de vous envoyer la moindre cargaison !\n\nJ'ai demandé au porteur de ce message de vous remettre un grand paquet de bougies (vous savez, celles que les kobolds aiment porter sur le sommet du crâne ?)\n\nRemerciez ce messager et donnez-lui le paiement qui lui revient." } } },
    ["Words of the High Chief"] = { { ids = { "i13158" }, first = "attackersfromallsidescan", pages = { "Des agresseurs... de tous les côtés.\n\nOn peut le voir dans leurs yeux. Les Grumegueules sont maléfiques. L'ennemi.\n\nOn doit protéger la tribu. On doit protéger Tombe-hiver. On doit repousser les assaillants de nos terres.", "Neige... Aveuglé...\n\nProtéger la tribu ! Les rendre forts... Etre fort...\n\nJe ne sais pas...", "Eau de feu.\n\nEn faire plus. Plus d'eau de feu.\n\nTombe-hiver plus forts avec eau de feu. Battre nos ennemis.\n\nTombe-hiver pas d'alliés. Tombe-hiver forts. Nous très puissants.", "Plus. Encore plus...\n\nTombe-hiver... pas... faible..." } } },
    ["Wrath of Soulflayer"] = { { ids = { "o175856" }, first = "thelongcenturiesfollowin", pages = { "Les siècles qui suivirent la Grande Fracture furent difficiles pour les trolls. La famine et la terreur étaient le pain quotidien des royaumes brisés. Les trolls Gurubashi, conduits au désespoir, cherchaient de l'aide auprès d'anciennes forces mystiques. Bien que les deux royaumes des trolls aient partagé une croyance commune dans le grand Panthéon des dieux primitifs, les Gurubashi tombèrent sous l'influence du plus sombre d'entre eux.", "Hakkar, l'Ecorcheur des âmes, l'esprit sanguinaire, entendit l'appel des trolls et décida de les aider. Hakkar offrit ses sanglants secrets aux Gurubashi et les aida à développer leur influence sur presque toute la Vallée de Strangleronce et certaines îles des Mers du Sud. Tout en leur apportant une grande puissance, Hakkar exigeait une rétribution de plus en plus importante.", "Le dieu assoiffé de sang exigeait que des âmes lui soient sacrifiées chaque jour. Il rêvait d'un accès au monde physique pour pouvoir s'y abreuver au sang des créatures mortelles. Les Gurubashi finirent par réaliser avec quelle créature ils s'étaient acoquinés et se retournèrent contre lui. Les tribus les plus puissantes se dressèrent contre Hakkar et ses prêtres fidèles, les Atal'ai.", "La terrible guerre qui suivit entre les disciples d'Hakkar et les autres tribus Gurubashi n'est jamais évoquée qu'à voix basse. L'empire naissant fut ravagé par la magie du dieu furieux et de ses enfants rebelles. Alors que l'issue du combat semblait sans espoir, les trolls parvinrent à détruire l'avatar d'Hakkar et à le bannir du monde.", "Même ses prêtres atal'ai furent finalement repoussés de la capitale de Zul'Gurub et contraints de survivre dans les marais inexplorés du Nord. Ils y bâtirent un grand temple à leur dieu déchu, Atal'Hakkar, pour y poursuivre les desseins de leur maître...", "Les dernières tribus Gurubashi se séparèrent après la grande guerre civile qui avait transformé leurs terres en ruines. Les Skullsplitter, les Bloodscalp et les Darkspear allèrent se tailler leurs propres territoires dans les vastes jungles de Strangleronce. Une paix fragile s'était installée sur l'empire brisé. Certains évoquaient une prophétie selon laquelle Hakkar renaîtrait en ce monde un jour et le consumerait intégralement." } } },
    ["Yana Bloodspear"] = { { ids = { "o175781" }, first = "yanabloodspearthesecondc", pages = { "Yana Bloodspear\n\nDeuxième assassine en chef de la Croisade écarlate\n\nOriginaire de Dalaran\n\nPortée disparue dans les clairières de Tirisfal" } } },
    ["Yellow Punch Card"] = { { ids = { "i9280" }, first = "ultravitaldatasecurityra", pages = { "DONNEES ESSENTIELLES ! NIVEAU DE SECURITE 5122 !\n\n01010011 01101001 00100000 01110100 01110101 00100000 01110000 01100101 01110101 01111000 00100000 01101100 01101001 01110010 01100101 00100000 11100111 01100001 00101100 00100000 01110100 01110101 00100000 01100101 01110011 00100000 01110110 01110010 01100001 01101001 01101101 01100101 01101110 01110100 00100000 01110100 01110010 01101111 01110000 00100000 01110000 01110010 11101000 01110011 00100000 00100001" } } },
    ["Yuriv's Tombstone"] = { { ids = { "o24777" }, first = "thewordbetrayeriscrudely", pages = { "Le mot TRAITRE est grossièrement gravé sur l'épitaphe finement ciselée qui dit :\n\nYuriv repose ici.\nPère, Epoux, Paladin.\nQue ses enfants soient le témoin de son entière dévotion à la Lumière.\nIl n'a rien demandé aux autres qu'il n'était prêt à faire lui-même." } } },
    ["Zamah's Note"] = { { ids = { "i5628" }, first = "apothecarylydonihopethis", pages = { "Apothicaire Lydon,\n\nJ'espère que cette lettre et son porteur arriveront jusqu'à vous dans de bonnes conditions. Un événement est survenu dans la lointaine Kalimdor et je crois que vos compétences sont requises.\n\nJe serai brève.\n\nUne crise a lieu dans les Serres-Rocheuses, non loin de Mulgore, la patrie de nos alliés taurens. Les gobelins de la KapitalRisk exploitent le minerai et le bois dans ces montagnes en rendant furieux les esprits qui y demeurent.", "Je dois reconnaître que la diversion faite par les esprits que contrôlaient les chamans et les druides taurens a eu de l'effet. Les taurens considèrent la présence de la KapitalRisk dans les Serres-Rocheuses comme une terrible menace.\n\nMenace ou non, nous devons aider nos alliés.\n\nLydon, vous êtes expert en toxines. Pourriez-vous en trouver une qui nous permettrait de contaminer les gobelins des Serres-Rocheuses ?\n\nVotre dévouée,\nP. Zamah" } } },
  },
